css:
/* LIFE Stock Dashboard - compact direct-value stylesheet */
#life-stock-root * { box-sizing: border-box; margin: 0; padding: 0; }
#life-stock-root { font-family: "Segoe UI", Arial, sans-serif; font-size: 13px; background: #f4f6fb; color: #202020; }
#life-stock-root .header { background: #0D2B4E; color: #fff; padding: 12px 20px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; }
.navbar { display: none; }
.web-footer { display: none; }
#life-stock-root .header .h1 { font-size: 17px; font-weight: 700; }
#life-stock-root .header .sub { font-size: 11px; color: rgba(255, 255, 255, .65); margin-top: 2px; }
#life-stock-root .header .right { display: flex; align-items: center; gap: 10px; }
#life-stock-root .hsel { height: 34px; border-radius: 5px; border: 1px solid #4a6a9a; background: #1a3a6e; color: #fff; font-size: 12px; padding: 0 10px; }
#life-stock-root .hsel option { background: #1a3a6e; }
#life-stock-root .gold-bar { height: 3px; background: #B8860B; }
#life-stock-root .main-nav { background: #fff; border-bottom: 2px solid #B8860B; padding: 0 12px; display: flex; gap: 0; overflow-x: auto; flex-wrap: nowrap; }
#life-stock-root .mnav { padding: 11px 16px; font-size: 12.5px; font-weight: 700; cursor: pointer; color: #595959; border-bottom: 3px solid transparent; margin-bottom: -2px; white-space: nowrap; }
#life-stock-root .mnav:hover { color: #0D2B4E; background: #f8f9fc; }
#life-stock-root .mnav.on { color: #0D2B4E; border-bottom: 3px solid #B8860B; background: #fff; }
#life-stock-root .mnav .cnt { background: #C00000; color: #fff; font-size: 9px; padding: 1px 6px; border-radius: 8px; margin-left: 5px; }
#life-stock-root .content { padding: 16px 20px; max-width: 1680px; margin: 0 auto; }
#life-stock-root .mode { display: none; }
#life-stock-root .mode.on { display: block; }
#life-stock-root label.lbl { font-size: 10.5px; font-weight: 700; color: #0D2B4E; display: block; margin-bottom: 4px; text-transform: uppercase; letter-spacing: .3px; }
#life-stock-root input, #life-stock-root select, #life-stock-root textarea { width: 100%; padding: 8px 10px; border: 1.5px solid #d0d5e0; border-radius: 5px; font-size: 12.5px; font-family: inherit; color: #202020; background: #fff; }
#life-stock-root input, #life-stock-root select { height: 34px; }
#life-stock-root textarea { min-height: 60px; resize: vertical; }
#life-stock-root input:focus, #life-stock-root select:focus, #life-stock-root textarea:focus { border-color: #0D2B4E; outline: none; }
#life-stock-root .card { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; margin-bottom: 16px; overflow: hidden; }
#life-stock-root .card-hdr { background: #0D2B4E; color: #fff; padding: 10px 14px; font-size: 13px; font-weight: 700; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 6px; }
#life-stock-root .card-hdr .badge { background: #B8860B; color: #fff; font-size: 10px; padding: 2px 10px; border-radius: 10px; }
#life-stock-root .card-body { padding: 16px; }
#life-stock-root .btn { padding: 9px 18px; border-radius: 5px; font-size: 12.5px; font-weight: 700; cursor: pointer; border: none; }
#life-stock-root .btn-n { background: #0D2B4E; color: #fff; }
#life-stock-root .btn-n:hover { background: #16396b; }
#life-stock-root .btn-g { background: #1E7A34; color: #fff; }
#life-stock-root .btn-r { background: #C00000; color: #fff; }
#life-stock-root .btn-gold { background: #B8860B; color: #fff; }
#life-stock-root .btn-gy { background: #f0f0f0; color: #595959; border: 1px solid #ddd; }
#life-stock-root .btn-sm { padding: 5px 12px; font-size: 11px; }
#life-stock-root .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 16px; }
#life-stock-root .tile { border-radius: 8px; padding: 12px 14px; border: 1px solid #e5e5e5; cursor: default; background: #fff; }
#life-stock-root .tile.clickable { cursor: pointer; transition: box-shadow .15s; }
#life-stock-root .tile.clickable:hover { box-shadow: 0 3px 10px rgba(0, 0, 0, .1); }
#life-stock-root .tile .tl { font-size: 10px; color: #8C8C8C; text-transform: uppercase; font-weight: 700; margin-bottom: 4px; }
#life-stock-root .tile .tv { font-size: 20px; font-weight: 800; line-height: 1.1; }
#life-stock-root .tile .ts { font-size: 10px; color: #8C8C8C; margin-top: 3px; }
#life-stock-root .t-pn { background: #E7ECF2; border-left: 3px solid #0D2B4E; }
#life-stock-root .t-pr { background: #FBE9E7; border-left: 3px solid #C00000; }
#life-stock-root .t-po { background: #FFF3E0; border-left: 3px solid #C96A00; }
#life-stock-root .t-pbl { background: #E3F0FA; border-left: 3px solid #2E86AB; }
#life-stock-root .t-pgr { background: #E8F5EC; border-left: 3px solid #1E7A34; }
#life-stock-root .t-pg { background: #FFF8E7; border-left: 3px solid #B8860B; }
#life-stock-root .tv-n { color: #0D2B4E; }
#life-stock-root .tv-r { color: #C00000; }
#life-stock-root .tv-o { color: #C96A00; }
#life-stock-root .tv-bl { color: #2E86AB; }
#life-stock-root .tv-gr { color: #1E7A34; }
#life-stock-root .tv-g { color: #B8860B; }
#life-stock-root .pill { display: inline-block; padding: 2px 10px; border-radius: 10px; font-size: 10px; font-weight: 700; white-space: nowrap; }
#life-stock-root .p-r { background: #FBE9E7; color: #C00000; }
#life-stock-root .p-g { background: #E8F5EC; color: #1E7A34; }
#life-stock-root .p-n { background: #E7ECF2; color: #0D2B4E; }
#life-stock-root .p-o { background: #FFF3E0; color: #C96A00; }
#life-stock-root .p-gy { background: #f0f0f0; color: #595959; }
#life-stock-root .p-go { background: #FFF8E7; color: #B8860B; }
#life-stock-root .p-bl { background: #E3F0FA; color: #1A6B8A; }
#life-stock-root .p-pu { background: #F0E9FB; color: #6A2CBF; }
#life-stock-root .p-am { background: #FCF3D9; color: #8A6D00; }
#life-stock-root .p-tl { background: #E0F5F1; color: #0F766E; }
#life-stock-root .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
@media (max-width:700px) {
  #life-stock-root .two-col { grid-template-columns: 1fr; }
}
#life-stock-root .field-block { margin-bottom: 10px; }
#life-stock-root .sec { font-size: 12.5px; font-weight: 700; color: #0D2B4E; margin: 14px 0 8px; border-left: 3px solid #B8860B; padding-left: 10px; }
#life-stock-root .notice { border-radius: 6px; padding: 10px 14px; margin: 6px 0; font-size: 11.5px; }
#life-stock-root .notice-blue { background: #E7ECF2; border-left: 3px solid #0D2B4E; }
#life-stock-root .notice-green { background: #E8F5EC; border-left: 3px solid #1E7A34; }
#life-stock-root .notice-red { background: #FBE9E7; border-left: 3px solid #C00000; }
#life-stock-root .notice-orange { background: #FFF3E0; border-left: 3px solid #C96A00; }
#life-stock-root .tbl-wrap { overflow-x: auto; max-height: 560px; overflow-y: auto; }
#life-stock-root table { width: 100%; border-collapse: collapse; font-size: 11.5px; white-space: nowrap; }
#life-stock-root th { background: #E7ECF2; color: #0D2B4E; font-weight: 700; padding: 7px 10px; border-bottom: 1.5px solid #c5d0e0; position: sticky; top: 0; z-index: 1; text-align: left; }
#life-stock-root td { padding: 6px 10px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }
#life-stock-root tr:hover td { background: #f8faff; }
#life-stock-root .modal-overlay { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(13, 43, 78, .55); z-index: 999; align-items: flex-start; justify-content: center; padding: 20px; overflow-y: auto; }
#life-stock-root .modal-overlay.show { display: flex; }
#life-stock-root .modal-box { background: #fff; border-radius: 10px; padding: 24px; max-width: 520px; text-align: center; box-shadow: 0 8px 30px rgba(0, 0, 0, .25); margin: auto; }
#life-stock-root .modal-box.wide { max-width: 1200px; text-align: left; max-height: 92vh; overflow-y: auto; width: 100%; }
#life-stock-root .modal-box .mic { font-size: 42px; margin-bottom: 8px; }
#life-stock-root .modal-box .mtt { font-size: 16px; font-weight: 700; color: #0D2B4E; margin-bottom: 6px; }
#life-stock-root .modal-box .mtx { font-size: 12px; color: #595959; margin-bottom: 14px; line-height: 1.5; text-align: left; white-space: pre-line; }
#life-stock-root .glist-item { padding: 11px 14px; border: 1.5px solid #e0e0e0; border-radius: 7px; margin-bottom: 8px; cursor: pointer; background: #fff; }
#life-stock-root .glist-item:hover { border-color: #0D2B4E; background: #f8faff; }
#life-stock-root .vendor-row-expand { background: #f8faff; padding: 10px 20px; border-top: 1px solid #e0e5ee; }
#life-stock-root .vendor-row-expand .detail-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; font-size: 11px; }
#life-stock-root .vendor-row-expand .detail-grid strong { color: #0D2B4E; }
#life-stock-root .vendor-pref { display: inline-block; padding: 1px 6px; border-radius: 4px; font-size: 9px; font-weight: 700; }
#life-stock-root .vendor-pref.pref1 { background: #E8F5EC; color: #1E7A34; }
#life-stock-root .vendor-pref.pref2 { background: #FFF3E0; color: #C96A00; }
#life-stock-root .vendor-pref.pref3 { background: #FBE9E7; color: #C00000; }
#life-stock-root .vendor-blocked { background: #FBE9E7; color: #C00000; padding: 2px 8px; border-radius: 4px; font-weight: 700; }
#life-stock-root .vendor-active { background: #E8F5EC; color: #1E7A34; padding: 2px 8px; border-radius: 4px; font-weight: 700; }
#life-stock-root .staff-query-item { padding: 6px 10px; border-bottom: 1px solid #f0f0f0; font-size: 11px; cursor: pointer; }
#life-stock-root .staff-query-item:hover { background: #f0f5ff; }
#life-stock-root .staff-query-item .qbadge { float: right; font-size: 9px; padding: 1px 6px; border-radius: 8px; }
#life-stock-root .ho-layout { display: grid; grid-template-columns: 200px 1fr 290px; gap: 14px; align-items: start; }
@media (max-width:1300px) {
  #life-stock-root .ho-layout { grid-template-columns: 1fr; }
}
#life-stock-root .ho-filter-col { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; padding: 14px; position: sticky; top: 10px; }
#life-stock-root .ho-filter-col .fgroup { margin-bottom: 14px; }
#life-stock-root .ho-sidebar { position: sticky; top: 10px; }
#life-stock-root .ho-sidebar-card { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; margin-bottom: 12px; overflow: hidden; }
#life-stock-root .ho-sidebar-hdr { background: #0D2B4E; color: #fff; padding: 8px 12px; font-size: 11px; font-weight: 700; }
#life-stock-root .ho-sidebar-body { padding: 10px 12px; max-height: 240px; overflow-y: auto; }
#life-stock-root .ho-sb-item { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid #f1f3f8; font-size: 11px; }
#life-stock-root .ho-sb-item:last-child { border-bottom: none; }
#life-stock-root .msg-send-box textarea { min-height: 50px; font-size: 11px; }
#life-stock-root .ho-msg-item { border-left: 3px solid #B8860B; background: #FFF8E7; padding: 7px 12px; border-radius: 0 5px 5px 0; margin-bottom: 6px; font-size: 11.5px; }
#life-stock-root .ho-msg-item .mt { font-size: 10px; color: #8C8C8C; margin-bottom: 2px; }
#life-stock-root .ra-layout { display: grid; grid-template-columns: 210px 1fr; gap: 14px; align-items: start; }
#life-stock-root .ra-sidebar { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; padding: 12px; position: sticky; top: 10px; }
#life-stock-root .ra-sidebar .ra-item { padding: 7px 12px; margin-bottom: 3px; border-radius: 5px; cursor: pointer; display: flex; justify-content: space-between; font-size: 12px; }
#life-stock-root .ra-sidebar .ra-item:hover { background: #f0f5ff; }
#life-stock-root .ra-sidebar .ra-item.active { background: #E7ECF2; font-weight: 700; }
#life-stock-root .ra-sidebar .ra-item .count { background: #0D2B4E; color: #fff; border-radius: 10px; padding: 0 8px; font-size: 10px; }
#life-stock-root .ra-sidebar .ra-item.pending .count { background: #C00000; }
#life-stock-root .ra-sidebar .ra-item.approved .count { background: #1E7A34; }
#life-stock-root .ra-sidebar .ra-item.rejected .count { background: #595959; }
#life-stock-root .ra-sidebar .ra-item.all .count { background: #0D2B4E; }
#life-stock-root .ra-content { min-height: 350px; }
#life-stock-root .ra-content .glist-item { cursor: default; }
#life-stock-root .ra-content .ra-actions { margin-top: 6px; display: flex; gap: 6px; flex-wrap: wrap; }
#life-stock-root .branch-container { margin-bottom: 12px; border: 1px solid #e0e5ee; border-radius: 8px; overflow: hidden; }
#life-stock-root .branch-heading { background: #0D2B4E; color: #fff; padding: 10px 16px; font-size: 13px; font-weight: 700; cursor: pointer; display: flex; justify-content: space-between; align-items: center; border-radius: 0; }
#life-stock-root .branch-heading:hover { background: #16396b; }
#life-stock-root .branch-heading .toggle-icon { font-size: 16px; }
#life-stock-root .branch-detail { padding: 0; background: #fff; }
#life-stock-root .branch-detail table { font-size: 11px; margin: 0; }
#life-stock-root .branch-detail table th { background: #f0f3f8; }
#life-stock-root .quick-date-row { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
#life-stock-root .qd-btn { padding: 5px 14px; border: 1.5px solid #ccc; border-radius: 14px; font-size: 11px; font-weight: 700; cursor: pointer; background: #fff; color: #595959; }
#life-stock-root .qd-btn:hover { border-color: #0D2B4E; }
#life-stock-root .qd-btn.sel { border-color: #B8860B; background: #FFF8E7; color: #B8860B; }
#life-stock-root .report-filter-bar { background: #0D2B4E; border-radius: 8px; padding: 14px 18px; display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end; margin-bottom: 14px; }
#life-stock-root .report-filter-bar label.lbl { color: #B8860B; }
#life-stock-root .report-filter-bar input, #life-stock-root .report-filter-bar select { background: #1a3a6e; border-color: #4a6a9a; color: #fff; height: 32px; min-width: 110px; }
#life-stock-root .report-filter-bar select option { background: #1a3a6e; }
#life-stock-root .report-filter-bar .apbtn { height: 32px; padding: 0 18px; background: #B8860B; color: #fff; border: none; border-radius: 4px; font-size: 12px; font-weight: 700; cursor: pointer; }
#life-stock-root .report-sidebar-layout { display: grid; grid-template-columns: 180px 1fr; gap: 14px; align-items: start; }
#life-stock-root .report-sidebar { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; padding: 12px; position: sticky; top: 10px; }
#life-stock-root .report-sidebar .rs-item { padding: 8px 12px; margin-bottom: 3px; border-radius: 5px; cursor: pointer; font-size: 12px; font-weight: 600; color: #595959; border-left: 3px solid transparent; }
#life-stock-root .report-sidebar .rs-item:hover { background: #f0f5ff; color: #0D2B4E; }
#life-stock-root .report-sidebar .rs-item.active { background: #E7ECF2; color: #0D2B4E; border-left-color: #B8860B; }
#life-stock-root .report-sidebar .rs-item .rs-icon { margin-right: 6px; }
#life-stock-root .action-btn-group { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
#life-stock-root .action-btn-group .btn { font-size: 10.5px; padding: 4px 10px; }
#life-stock-root .vendor-alternatives { margin-top: 8px; padding: 8px 12px; background: #f0f5ff; border-radius: 5px; border-left: 3px solid #0D2B4E; }
#life-stock-root .vendor-alternatives .alt-item { display: inline-block; padding: 2px 10px; background: #fff; border-radius: 12px; margin: 2px 4px 2px 0; font-size: 10.5px; border: 1px solid #dde3f0; }
#life-stock-root .pref-toggle-group { display: flex; gap: 6px; margin-top: 4px; }
#life-stock-root .pref-toggle-group .pt-btn { padding: 3px 12px; border-radius: 12px; font-size: 10px; font-weight: 700; cursor: pointer; border: 1.5px solid #ccc; background: #fff; color: #595959; }
#life-stock-root .pref-toggle-group .pt-btn.active-pref1 { border-color: #1E7A34; background: #E8F5EC; color: #1E7A34; }
#life-stock-root .pref-toggle-group .pt-btn.active-pref2 { border-color: #C96A00; background: #FFF3E0; color: #C96A00; }
#life-stock-root .pref-toggle-group .pt-btn.active-pref3 { border-color: #C00000; background: #FBE9E7; color: #C00000; }
#life-stock-root .block-toggle { padding: 3px 12px; border-radius: 12px; font-size: 10px; font-weight: 700; cursor: pointer; border: 1.5px solid #ccc; background: #fff; }
#life-stock-root .block-toggle.blocked { border-color: #C00000; background: #FBE9E7; color: #C00000; }
#life-stock-root .block-toggle.active { border-color: #1E7A34; background: #E8F5EC; color: #1E7A34; }
#life-stock-root .vendor-form-section { background: #f8fafc; border-radius: 6px; padding: 12px 14px; margin-bottom: 10px; border: 1px solid #e8edf5; }
#life-stock-root .vendor-form-section .vfs-title { font-weight: 700; color: #0D2B4E; font-size: 12px; margin-bottom: 8px; border-bottom: 1px solid #dde3f0; padding-bottom: 4px; }
#life-stock-root .material-checkbox-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 4px 12px; font-size: 11px; }
#life-stock-root .material-checkbox-grid label { display: flex; align-items: center; gap: 4px; cursor: pointer; }
#life-stock-root .material-checkbox-grid input[type="checkbox"] { width: 14px; height: 14px; cursor: pointer; flex-shrink: 0; }
#life-stock-root .vendor-search-wrap { position: relative; }
#life-stock-root .vendor-search-wrap .vd-dropdown { position: absolute; top: 100%; left: 0; right: 0; background: #fff; border: 1px solid #ccc; border-radius: 0 0 5px 5px; max-height: 180px; overflow-y: auto; z-index: 10; display: none; }
#life-stock-root .vendor-search-wrap .vd-dropdown .item { padding: 6px 12px; cursor: pointer; border-bottom: 1px solid #f0f0f0; font-size: 11px; }
#life-stock-root .vendor-search-wrap .vd-dropdown .item:hover { background: #E7ECF2; }
#life-stock-root .vendor-search-wrap .vd-dropdown.show { display: block; }
#life-stock-root .action-tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 16px; }
@media (max-width:800px) {
  #life-stock-root .action-tiles { grid-template-columns: 1fr 1fr; }
}
@media (max-width:500px) {
  #life-stock-root .action-tiles { grid-template-columns: 1fr; }
}
#life-stock-root .action-tile { border: 2px solid #e0e0e0; border-radius: 10px; padding: 14px 12px; text-align: center; cursor: pointer; background: #fff; transition: all .15s; }
#life-stock-root .action-tile:hover { border-color: #0D2B4E; transform: translateY(-2px); }
#life-stock-root .action-tile .ic { font-size: 26px; margin-bottom: 4px; }
#life-stock-root .action-tile .tt { font-size: 13px; font-weight: 700; color: #0D2B4E; }
#life-stock-root .action-tile .ts { font-size: 10px; color: #8C8C8C; margin-top: 2px; }
#life-stock-root .updates-row { display: grid; grid-template-columns: 1fr 1fr 2fr; gap: 12px; margin-bottom: 16px; }
@media (max-width:900px) {
  #life-stock-root .updates-row { grid-template-columns: 1fr; }
}
#life-stock-root .update-box { background: #fff; border: 1px solid #dde3f0; border-radius: 8px; padding: 12px 14px; }
#life-stock-root .update-box .uk { font-size: 10px; color: #8C8C8C; text-transform: uppercase; font-weight: 700; margin-bottom: 4px; }
#life-stock-root .update-box .uv { font-size: 14px; font-weight: 700; color: #0D2B4E; }
#life-stock-root .required-mark { color: #C00000; }
#life-stock-root .compose-modal textarea { min-height: 80px; }
#life-stock-root .req-hdr-row { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 14px; margin-bottom: 16px; background: #f8f9fc; border-radius: 8px; padding: 14px; }
#life-stock-root .req-hdr-block .rk { font-size: 10px; color: #8C8C8C; text-transform: uppercase; }
#life-stock-root .req-hdr-block .rv { font-size: 14px; font-weight: 700; color: #0D2B4E; margin-top: 2px; }
#life-stock-root .req-table input, #life-stock-root .req-table select { height: 30px; font-size: 11px; }
#life-stock-root .req-table td { padding: 4px 6px; }
#life-stock-root .req-table .rm-row { cursor: pointer; color: #C00000; font-weight: 700; text-align: center; }
#life-stock-root .autoval { font-size: 11px; color: #595959; }
#life-stock-root .upload-zone { border: 2px dashed #ccc; border-radius: 6px; padding: 12px; text-align: center; color: #8C8C8C; font-size: 11.5px; background: #fff; cursor: pointer; }
#life-stock-root .upload-zone:hover { border-color: #0D2B4E; }
#life-stock-root .upload-zone.uploaded { border-color: #1E7A34; border-style: solid; background: #E8F5EC; color: #1E7A34; font-weight: 700; }
#life-stock-root .upload-zone.missing-required { border-color: #C00000; background: #FBE9E7; }
#life-stock-root .fbar { background: #0D2B4E; border-radius: 8px; padding: 12px 16px; display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; margin-bottom: 14px; }
#life-stock-root .fbar label.lbl { color: #B8860B; }
