#life-material-request-root .ssr-client-loading {
    display: none;
    align-items: center;
    justify-content: center;
    padding: 40px 20px;
    margin: 20px 0;
    border: 1px solid #d7e7da;
    border-radius: 12px;
    background: #f8fcf8;
    min-height: 160px;
    gap: 20px;
}

#life-material-request-root .ssr-client-loading-spinner {
    width: 44px;
    height: 44px;
    border: 4px solid #e0ece2;
    border-top-color: #1e7a34;
    border-radius: 50%;
    flex: 0 0 44px;
    animation: ssr-spin 0.8s linear infinite;
}

@keyframes ssr-spin {
    to {
        transform: rotate(360deg);
    }
}

#life-material-request-root .ssr-client-loading-copy {
    display: flex;
    flex-direction: column;
    gap: 6px;
    text-align: left;
    flex: 1;
}

#life-material-request-root .ssr-client-loading-title {
    font-size: 16px;
    font-weight: 900;
    color: #174d25;
}

#life-material-request-root .ssr-client-loading-sub {
    font-size: 13px;
    color: #587161;
}

#life-material-request-root .ssr-client-loading-progress {
    width: 100%;
    height: 4px;
    border-radius: 2px;
    background: #e0ece2;
    overflow: hidden;
    margin-top: 4px;
}

#life-material-request-root .ssr-client-loading-progress span {
    display: block;
    height: 100%;
    width: 30%;
    background: #1e7a34;
    border-radius: 2px;
    animation: ssr-progressPulse 1.4s ease-in-out infinite;
}

@keyframes ssr-progressPulse {
    0% { width: 10%; }
    50% { width: 60%; }
    100% { width: 10%; }
}

/* Ensure the loading overlay is visible */
#life-material-request-root .ssr-client-loading.show {
    display: flex !important;
}

/* Hide client area while loading */
#life-material-request-root .ssr-client-area.loading {
    display: none !important;
}

