(function installLifeStockGateway(){
"use strict";

var API_METHOD="life_stock_fast_requests";

function gatewayError(error){
if(!error){
return new Error("The LIFE Stock API request failed.");
}
if(error instanceof Error){
return error;
}
if(error._server_messages){
try{
var messages=JSON.parse(error._server_messages);
var text=messages.map(function(message){
try{
var parsed=JSON.parse(message);
return parsed.message||message;
}
catch(parseError){
return message;
}
}).join("\n");
if(text){
return new Error(text);
}
}
catch(ignoreError){
}
}
if(error.responseJSON&&error.responseJSON._server_messages){
try{
var responseMessages=JSON.parse(error.responseJSON._server_messages);
var responseText=responseMessages.map(function(message){
try{
var parsed=JSON.parse(message);
return parsed.message||message;
}
catch(parseError){
return message;
}
}).join("\n");
if(responseText){return new Error(responseText);}
}
catch(ignoreResponseError){
}
}
if(error.message){
if(typeof error.message==="string"){return new Error(error.message);}
try{return new Error(JSON.stringify(error.message));}
catch(ignoreMessageError){return new Error(String(error.message));}
}
try{return new Error(JSON.stringify(error));}
catch(ignoreStringifyError){return new Error(String(error));}
}

async function action(actionName,payload,options){
options=options||{};
var response;
try{
response=await frappe.call({
method:API_METHOD,
type:"POST",
args:{
action:String(actionName||"").trim(),
payload:JSON.stringify(payload||{})
},
freeze:!!options.freeze,
freeze_message:options.freezeMessage||""
});
}
catch(error){
throw gatewayError(error);
}

var result=response&&response.message;
if(!result||result.ok!==true){
throw new Error(
result&&result.message
?String(result.message)
:"The LIFE Stock API returned an invalid response."
);
}
return result;
}

async function invoke(method,args,options){
var result=await action("invoke",{
method:String(method||"").trim(),
args:args||{}
},options||{});
return result.data;
}

function compat(options){
options=options||{};
var promise=invoke(
options.method,
options.args||{},
{
freeze:!!options.freeze,
freezeMessage:options.freeze_message||""
}
).then(function(data){
var response={
message:data
};
if(typeof options.callback==="function"){
options.callback(response);
}
return response;
}).catch(function(error){
if(typeof options.error==="function"){
options.error(error);
}
throw error;
});
return promise;
}

async function batch(operations,options){
return action("batch",{
operations:Array.isArray(operations)?operations:[]
},options||{});
}

async function upload(file,isPrivate,extraPayload){
if(!file){
throw new Error("A file is required for upload.");
}

var payload=Object.assign({
is_private:isPrivate===false?0:1,
file_name:file.name||"upload.bin"
},extraPayload||{});

var formData=new FormData();
formData.append("action","upload_file");
formData.append("payload",JSON.stringify(payload));
formData.append("file",file,file.name||"upload.bin");

var headers={};
if(frappe.csrf_token){
headers["X-Frappe-CSRF-Token"]=frappe.csrf_token;
}

var response=await fetch("/api/method/"+API_METHOD,{
method:"POST",
headers:headers,
credentials:"same-origin",
body:formData
});

var data;
try{
data=await response.json();
}
catch(parseError){
throw new Error("The upload server returned an unreadable response.");
}

if(!response.ok||data.exc){
throw gatewayError(data);
}

var result=data.message;
if(!result||result.ok!==true||!result.file_url){
throw new Error(
result&&result.message
?String(result.message)
:"The upload completed without returning a file URL."
);
}

return result.file_url;
}

async function serverScript(method,args,options){
options=options||{};
var response;
try{
response=await frappe.call({
method:String(method||"").trim(),
args:args||{},
freeze:!!options.freeze,
freeze_message:options.freezeMessage||""
});
}
catch(error){
throw gatewayError(error);
}
return response&&response.message;
}

