                        ? opts.limit
                        : 5000,
                parent: opts.parent || undefined
            },
            callback: function (response) {
                resolve(
                    (response && response.message) || []
                );
            },
            error: function (error) {
                reject(error);
            }
        });
    });
}

/* =========================================================
   SAFE DYNAMIC BRANCH / WAREHOUSE MASTER LOADER
   ========================================================= */
function lifeNormalizeBranchWarehouseKey(value){
return String(value||"")
.toLowerCase()
.replace(/&/g,"and")
.replace(/\s*-\s*lsacpl\s*$/i,"")
.replace(/\(old\)/gi,"")
.replace(/\bold\b/gi,"")
.replace(/\bmain\s+stores?\b/gi,"")
.replace(/\bsub\s+stores?\b/gi,"")
.replace(/\bstores?\s+warehouses?\b/gi,"")
.replace(/\bwarehouses?\b/gi,"")
.replace(/\bstores?\b/gi,"")
.replace(/[^a-z0-9]+/g,"")
.trim();
}
function lifeStaticBranchCodeForKey(value){
var normalized=lifeNormalizeBranchWarehouseKey(value);
if(!normalized){
return"";
}
var aliases={
chandanagar:"CN",chandhanagar:"CN",
srnagar:"SRN",srinagar:"SRN",
madhapur:"MP",
banjarahills:"BH",banjarahill:"BH",
himayathnagar:"HN",himayatnagar:"HN",
dilsukhnagar:"DN",dilshuknagar:"DN",
gachibowli:"GB",
vijayawada:"VW",
vizag:"VZ",visakhapatnam:"VZ",
nellore:"NLR",
kukatpally:"KP"
};
if(aliases[normalized]){
return aliases[normalized];
}
for(var i=0;i<LIFE_STATIC_BRANCHES.length;i++){
var branch=LIFE_STATIC_BRANCHES[i];
if(lifeNormalizeBranchWarehouseKey(branch.name)===normalized||lifeNormalizeBranchWarehouseKey(branch.code)===normalized){
return branch.code;
}
}
return"";
}
function lifeDynamicBranchDisplayNames(branchRows){
var namesByCode={};
(Array.isArray(branchRows)?branchRows:[]).forEach(function(row){
var branchLabel=String(row&&((row.branch!==undefined&&row.branch!==null)?row.branch:row.name)||"").trim();
var code=lifeStaticBranchCodeForKey(branchLabel);
if(code&&!namesByCode[code]){
namesByCode[code]=branchLabel;
}
});
return namesByCode;
}
function lifeResolveDynamicWarehouseBranchCode(warehouseRow){
warehouseRow=warehouseRow||{};
var candidates=[warehouseRow.warehouse_name,warehouseRow.name];
for(var i=0;i<candidates.length;i++){
var code=lifeStaticBranchCodeForKey(candidates[i]);
if(code){
return code;
}
}
return"";
}
function lifeIsDynamicHOWarehouse(warehouseRow){
warehouseRow=warehouseRow||{};
var raw=String(warehouseRow.warehouse_name||warehouseRow.name||"").trim();
var normalized=String(raw)
.toLowerCase()
.replace(/\s*-\s*lsacpl\s*$/i,"")
.replace(/[^a-z0-9]+/g,"");
if(!normalized){
return false;
}
var exact={
stores:true,
finishedgoods:true,
goodsintransit:true,
htwarehouse:true,
htmainstore:true,
htsubstore:true,
workinprogress:true
};
if(exact[normalized]){
return true;
}
return false;
}
function lifeUniqueWarehouseNames(rows){
var seen={};
var out=[];
(Array.isArray(rows)?rows:[]).forEach(function(value){
var name=String(value||"").trim();
if(!name||seen[name]){
return;
}
seen[name]=true;
out.push(name);
});
return out;
}
async function loadLifeDynamicBranchWarehouseMapping(){
var company="Life Slimming And Cosmetic Pvt Ltd";
try{
var results=await Promise.all([
callList("Branch",{
fields:["name","branch"],
order_by:"name asc",
limit:0
}),
callList("Warehouse",{
fields:["name","warehouse_name","parent_warehouse","company","is_group","disabled","warehouse_type"],
filters:{company:company,is_group:0,disabled:0},
order_by:"name asc",
limit:0
})
]);
var branchRows=Array.isArray(results[0])?results[0]:[];
var warehouseRows=(Array.isArray(results[1])?results[1]:[]).filter(function(row){
return row&&Number(row.is_group||0)!==1&&Number(row.disabled||0)!==1&&(!row.company||String(row.company)===company);
});
if(!warehouseRows.length){
throw new Error("No active non-group Warehouse records were returned.");
}
var displayNames=lifeDynamicBranchDisplayNames(branchRows);
var dynamicByCode={};
LIFE_STATIC_BRANCHES.forEach(function(branch){
dynamicByCode[branch.code]=[];
});
var dynamicHO=[];
var unmapped=[];
warehouseRows.forEach(function(row){
var warehouseName=String(row.name||row.warehouse_name||"").trim();
if(!warehouseName){
return;
}
var code=lifeResolveDynamicWarehouseBranchCode(row);
if(code&&dynamicByCode[code]){
dynamicByCode[code].push(warehouseName);
return;
}
if(lifeIsDynamicHOWarehouse(row)){
dynamicHO.push(warehouseName);
return;
}
unmapped.push(warehouseName);
});
BRANCHES=LIFE_STATIC_BRANCHES.map(function(seed){
var dynamicWarehouses=lifeUniqueWarehouseNames(dynamicByCode[seed.code]);
return{
code:seed.code,
name:displayNames[seed.code]||seed.name,
/* Never leave a known branch without warehouses because of a fetch/match issue. */
whs:dynamicWarehouses.length?dynamicWarehouses:seed.whs.slice()
};
});
var resolvedHO=lifeUniqueWarehouseNames(dynamicHO);
HO_LOCATION={
code:"HOC",
name:"HO Central (Stores)",
whs:resolvedHO.length?resolvedHO:LIFE_STATIC_HO_WAREHOUSES.slice()
};
lifeRebuildWarehouseLocationMaps();
lifePublishIntegratedBranchWarehouseMap();
LIFE_DYNAMIC_WAREHOUSE_MAPPING={
loaded:true,
usingFallback:false,
branchRows:branchRows,
warehouseRows:warehouseRows,
unmappedWarehouses:unmapped
};
if(typeof CACHE!=="undefined"&&CACHE){
CACHE.bins={};
CACHE.allBins=null;
}
void 0;
return LIFE_DYNAMIC_WAREHOUSE_MAPPING;
}
catch(error){
/* Full compatibility fallback: restore the exact original mapping. */
BRANCHES=LIFE_STATIC_BRANCHES.map(function(branch){
return{code:branch.code,name:branch.name,whs:branch.whs.slice()};
});
HO_LOCATION={code:"HOC",name:"HO Central (Stores)",whs:LIFE_STATIC_HO_WAREHOUSES.slice()};
lifeRebuildWarehouseLocationMaps();
lifePublishIntegratedBranchWarehouseMap();
LIFE_DYNAMIC_WAREHOUSE_MAPPING={
loaded:false,
usingFallback:true,
branchRows:[],
warehouseRows:[],
unmappedWarehouses:[]
};
void 0;
return LIFE_DYNAMIC_WAREHOUSE_MAPPING;
}
}

function callCount(doctype, filters) {
    return new Promise(function (resolve, reject) {
        if (typeof frappe === "undefined" || !frappe.call) {
            reject(new Error("frappe.call is unavailable."));
            return;
        }

        window.LifeStockGateway.compat({
            method: "frappe.client.get_count",
            args: {
                doctype: doctype,
                filters: filters || {}
            },
            callback: function (response) {
                resolve(
                    Math.max(
                        0,
                        Number(
                            response && response.message
                        ) || 0
                    )
                );
            },
            error: function (error) {
                reject(error);
            }
        });
    });
}

