var LIFE_PURCHASE_SUPPLIER_FILTER = {
    purchaseOrder: "",
    purchaseReceipt: "",
    purchaseInvoice: ""
};


var LIFE_PURCHASE_SUPPLIER_OPTIONS = null;

var LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE = null;


/*
 * Load Supplier master only once.
 * All three tabs reuse the same cached list.
 */
function lifeLoadPurchaseSupplierOptions() {

    if (
        Array.isArray(
            LIFE_PURCHASE_SUPPLIER_OPTIONS
        )
    ) {
        return Promise.resolve(
            LIFE_PURCHASE_SUPPLIER_OPTIONS
        );
    }


    if (
        LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE
    ) {
        return LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE;
    }


    LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE =
        callList(
            "Supplier",
            {
                fields: [
                    "name",
                    "supplier_name"
                ],

                filters: [
                    [
                        "disabled",
                        "=",
                        0
                    ]
                ],

                order_by:
                    "supplier_name asc",

                limit:
                    0
            }
        )
        .then(
            function(rows) {

                LIFE_PURCHASE_SUPPLIER_OPTIONS =
                    Array.isArray(rows)
                        ? rows
                        : [];


                return LIFE_PURCHASE_SUPPLIER_OPTIONS;
            }
        )
        .finally(
            function() {

                LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE =
                    null;
            }
        );


    return LIFE_PURCHASE_SUPPLIER_OPTIONS_PROMISE;
}


/*
 * Exact server-side Supplier filter.
 *
 * Blank = all suppliers.
 */
function lifePurchaseSupplierFilters(
    listKey
) {

    var supplier =
        String(
            LIFE_PURCHASE_SUPPLIER_FILTER[
                listKey
            ] ||
            ""
        ).trim();


    if (!supplier) {
        return {};
    }


    return {
        supplier: supplier
    };
}


/*
 * Searchable Supplier dropdown shared by PO / PR / PI.
 */
function lifeBindPurchaseSupplierDropdown(
    listKey,
    inputId,
    resultsId,
    renderFunction
) {

    var input =
        byId(
            inputId
        );


    var results =
        byId(
            resultsId
        );


    if (
        !input ||
        !results
    ) {
        return;
    }


    var selectedSupplier =
        String(
            LIFE_PURCHASE_SUPPLIER_FILTER[
                listKey
            ] ||
            ""
        ).trim();


    input.disabled =
        true;


    input.placeholder =
        "Loading suppliers…";


    lifeLoadPurchaseSupplierOptions()
        .then(
            function(suppliers) {

                input.disabled =
                    false;


                input.placeholder =
                    "Search / select supplier…";


                /*
                 * Show selected supplier's readable name.
                 */
                if (selectedSupplier) {

                    var selectedRow =
                        suppliers.find(
                            function(row) {

                                return (
                                    String(
                                        row.name ||
                                        ""
                                    ) ===
                                    selectedSupplier
                                );
                            }
                        );


                    input.value =
                        selectedRow
                            ? (
                                selectedRow.supplier_name ||
                                selectedRow.name
                            )
                            : selectedSupplier;
                }
                else {

                    input.value =
                        "";
                }


                function paintOptions(
                    query
                ) {

                    query =
                        String(
                            query ||
                            ""
                        )
                        .trim()
                        .toLowerCase();


                    var matched =
                        suppliers
                        .filter(
                            function(row) {

                                if (!query) {
                                    return true;
                                }


                                return (
                                    String(
                                        row.supplier_name ||
                                        ""
                                    )
                                    .toLowerCase()
                                    .indexOf(
                                        query
                                    ) > -1 ||

                                    String(
                                        row.name ||
                                        ""
                                    )
                                    .toLowerCase()
                                    .indexOf(
                                        query
                                    ) > -1
                                );
                            }
                        )
                        .slice(
                            0,
                            40
                        );


                    var html =

                        '<div ' +
                            'class="life-purchase-supplier-option life-purchase-supplier-all" ' +
                            'data-purchase-supplier="">' +

                            '<strong>All Suppliers</strong>' +

                        '</div>';


                    html +=
                        matched
                        .map(
                            function(row) {

                                var displayName =
                                    String(
                                        row.supplier_name ||
                                        row.name ||
                                        ""
                                    );


                                return (

                                    '<div ' +
                                        'class="life-purchase-supplier-option" ' +
                                        'data-purchase-supplier="' +
                                            esc(
                                                row.name
                                            ) +
                                        '">' +

                                        '<strong>' +
                                            esc(
                                                displayName
                                            ) +
                                        '</strong>' +

                                        (
                                            displayName !==
                                            String(
                                                row.name ||
                                                ""
                                            )

                                                ? (
                                                    '<div class="life-purchase-supplier-code">' +
                                                        esc(
                                                            row.name
                                                        ) +
                                                    '</div>'
                                                )

                                                : ''
                                        ) +

                                    '</div>'
                                );
                            }
                        )
                        .join("");


                    results.innerHTML =
                        html;


                    results.style.display =
                        "block";
                }


                input.addEventListener(
                    "focus",
                    function() {

                        /*
                         * On focus, show all supplier options rather
                         * than filtering using the selected label.
                         */
                        paintOptions(
                            ""
                        );
                    }
                );


                input.addEventListener(
                    "input",
                    function() {

                        /*
                         * User typing means they are searching,
                         * but selection isn't applied until they
                         * actually click an option.
                         */
                        paintOptions(
                            input.value
                        );
                    }
                );


                input.addEventListener(
                    "keydown",
                    function(event) {

                        if (
                            event.key ===
                            "Escape"
                        ) {

                            results.style.display =
                                "none";


                            if (
                                LIFE_PURCHASE_SUPPLIER_FILTER[
                                    listKey
                                ]
                            ) {

                                var activeRow =
                                    suppliers.find(
                                        function(row) {

                                            return (
                                                row.name ===
                                                LIFE_PURCHASE_SUPPLIER_FILTER[
                                                    listKey
                                                ]
                                            );
                                        }
                                    );


                                input.value =
                                    activeRow
                                        ? (
                                            activeRow.supplier_name ||
                                            activeRow.name
                                        )
                                        : "";
                            }
                            else {

                                input.value =
                                    "";
                            }
                        }
                    }
                );


                results.addEventListener(
                    "mousedown",
                    function(event) {

                        var option =
                            event.target.closest(
                                "[data-purchase-supplier]"
                            );


                        if (!option) {
                            return;
                        }


                        event.preventDefault();


                        var supplier =
                            String(
                                option.getAttribute(
                                    "data-purchase-supplier"
                                ) ||
                                ""
                            ).trim();


                        LIFE_PURCHASE_SUPPLIER_FILTER[
                            listKey
                        ] =
                            supplier;


                        /*
                         * Filter change always returns to page 1.
                         */
                        if (
                            LIFE_REMOTE_LIST_STATE[
                                listKey
                            ]
                        ) {

                            LIFE_REMOTE_LIST_STATE[
                                listKey
                            ].page =
                                1;
                        }


                        results.style.display =
                            "none";


                        renderFunction();
                    }
                );


                input.addEventListener(
                    "blur",
                    function() {

                        window.setTimeout(
                            function() {

                                results.style.display =
                                    "none";
                            },
                            150
                        );
                    }
                );
            }
        )
        .catch(
            function(error) {

                input.disabled =
                    false;


                input.placeholder =
                    "Supplier filter unavailable";


                void 0;
            }
        );
}


