function lifeRemoteTotalPages(total) {
    return Math.max(
        1,
        Math.ceil(
            Math.max(0, Number(total) || 0) /
            LIFE_REMOTE_PAGE_SIZE
        )
    );
}

function lifeFetchRemotePage(
    listKey,
    doctype,
    options
) {

    options =
        options ||
        {};


    var pageState =
        LIFE_REMOTE_LIST_STATE[
            listKey
        ];


    if (!pageState) {

        return Promise.reject(
            new Error(
                "Unknown paged list: " +
                listKey
            )
        );
    }


    var filters =
        options.filters ||
        {};


    return callCount(
        doctype,
        filters
    )
    .then(
        function(total) {

            pageState.total =
                total;


            var totalPages =
                lifeRemoteTotalPages(
                    total
                );


            pageState.page =
                Math.min(
                    totalPages,
                    Math.max(
                        1,
                        Number(
                            pageState.page
                        ) ||
                        1
                    )
                );


            return callList(
                doctype,
                {
                    fields:
                        options.fields ||
                        ["name"],

                    filters:
                        filters,

                    order_by:
                        options.order_by ||
                        "modified desc",

                    start:
                        (
                            pageState.page -
                            1
                        ) *
                        LIFE_REMOTE_PAGE_SIZE,

                    limit:
                        LIFE_REMOTE_PAGE_SIZE
                }
            )
            .then(
                function(rows) {

                    return {

                        rows:
                            Array.isArray(rows)
                                ? rows
                                : [],

                        page:
                            pageState.page,

                        total:
                            total,

                        totalPages:
                            totalPages,

                        first:
                            total > 0
                                ? (
                                    (
                                        pageState.page -
                                        1
                                    ) *
                                    LIFE_REMOTE_PAGE_SIZE
                                ) + 1
                                : 0,

                        last:
                            total > 0
                                ? Math.min(
                                    pageState.page *
                                    LIFE_REMOTE_PAGE_SIZE,
                                    total
                                )
                                : 0
                    };
                }
            );
        }
    );
}

function lifeBuildRemotePagination(listKey, pageData) {
    if (!pageData) {
        return "";
    }

    var page = pageData.page;
    var totalPages = pageData.totalPages;
    var startPage = Math.max(1, page - 2);
    var endPage = Math.min(
        totalPages,
        startPage + 4
    );

    startPage = Math.max(
        1,
        endPage - 4
    );

    var pageButtons = "";

    for (
        var currentPage = startPage;
        currentPage <= endPage;
        currentPage += 1
    ) {
        pageButtons +=
            '<button type="button" ' +
                'class="life-remote-page-button' +
                (
                    currentPage === page
                        ? " active"
                        : ""
                ) +
                '" data-remote-list-page="1" ' +
                'data-list-key="' +
                    esc(listKey) +
                '" data-page="' +
                    currentPage +
                '">' +
                currentPage +
            "</button>";
    }

    return (
        '<div class="life-remote-pagination">' +
            '<div class="life-remote-pagination__summary">' +
                "Showing " +
                pageData.first +
                "–" +
                pageData.last +
                " of " +
                pageData.total +
            "</div>" +

            '<div class="life-remote-pagination__buttons">' +
                '<button type="button" ' +
                    'class="life-remote-page-button" ' +
                    'data-remote-list-page="1" ' +
                    'data-list-key="' +
                        esc(listKey) +
                    '" data-page="' +
                        (page - 1) +
                    '" ' +
                    (
                        page <= 1
                            ? "disabled"
                            : ""
                    ) +
                ">‹ Previous</button>" +

                pageButtons +

                '<button type="button" ' +
                    'class="life-remote-page-button" ' +
                    'data-remote-list-page="1" ' +
                    'data-list-key="' +
                        esc(listKey) +
                    '" data-page="' +
                        (page + 1) +
                    '" ' +
                    (
                        page >= totalPages
                            ? "disabled"
                            : ""
                    ) +
                ">Next ›</button>" +
            "</div>" +
        "</div>"
    );
}

function lifeChangeRemoteListPage(listKey, requestedPage) {
    var pageState =
        LIFE_REMOTE_LIST_STATE[listKey];

    if (!pageState) {
        return;
    }

    var totalPages =
        lifeRemoteTotalPages(pageState.total);

    pageState.page = Math.min(
        totalPages,
        Math.max(
            1,
            Number(requestedPage) || 1
        )
    );

    if (listKey === "stockRequest") {
        renderBranchReqList();
    } else if (listKey === "purchaseOrder") {
        renderPurchaseOrder();
    } else if (listKey === "purchaseReceipt") {
        renderPurchaseReceipt();
