function lifeEnsureViewModalPrintButton() {
    var existingButton = byId("ls-view-modal-print");

    if (existingButton) {
        return existingButton;
    }

    var pdfButton = byId("ls-view-modal-pdf");
    var closeButton = byId("ls-view-modal-close");
    var parent =
        (pdfButton && pdfButton.parentNode) ||
        (closeButton && closeButton.parentNode);

    if (!parent) {
        return null;
    }

    var printButton = document.createElement("button");
    printButton.type = "button";
    printButton.id = "ls-view-modal-print";
    printButton.className = pdfButton
        ? pdfButton.className
        : "btn btn-g";
    printButton.textContent = "🖨 Print";
    printButton.style.display = "none";
    printButton.addEventListener(
        "click",
        printCurrentViewModalData
    );

    if (
        closeButton &&
        closeButton.parentNode === parent
    ) {
        parent.insertBefore(
            printButton,
            closeButton
        );
    } else if (
        pdfButton &&
        pdfButton.parentNode === parent
    ) {
        parent.insertBefore(
            printButton,
            pdfButton.nextSibling
        );
    } else {
        parent.appendChild(printButton);
    }

    return printButton;
}

