     * opened popup.
     */
    modal.classList.remove(
        "ls-system-manager-branch-picker-modal",
        "life-procurement-detail-modal",
        "life-supplier-detail-modal",
        "life-checklist-form-modal",
        "life-stock-issue-host-modal"
    );

    if (options && options.modalClass) {
        String(options.modalClass)
            .split(/\s+/)
            .filter(Boolean)
            .forEach(function (className) {
                modal.classList.add(className);
            });
    }

    LIFE_VIEW_MODAL_PDF_STATE =
        options && options.pdf
            ? options.pdf
            : null;

    if (pdfButton) {
        pdfButton.style.display =
