    if (printButton) {
        printButton.style.display =
            LIFE_VIEW_MODAL_PDF_STATE
                ? "inline-flex"
                : "none";
        printButton.disabled = false;
        printButton.textContent = "🖨 Print";
    }

    if (options && options.fixedDetailLayout) {
        modal.classList.add("life-procurement-detail-modal");

        content.innerHTML =
            '<div class="life-procurement-detail-shell">' +
                '<div class="life-procurement-detail-header">' +
                    '<div class="mtt">' + title + '</div>' +
