                '<div class="life-procurement-detail-footer">' +
                    (options.footerHtml || "") +
                '</div>' +
            '</div>';
    } else {
        content.innerHTML =
            '<div class="mtt" style="margin-bottom:10px">' +
                title +
            "</div>" +
            html;
    }

    modal.classList.add("show");
