function lifePdfCleanText(value) {
    return String(
        value === null || value === undefined
            ? ""
            : value
    )
        .replace(/\u2264/g, "<=")
        .replace(/[\u2013\u2014]/g, "-")
        .replace(/\u2022/g, "-")
        .replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g, "")
        .trim();
}

function lifePdfSafeFileName(value) {
    var cleaned = lifePdfCleanText(value)
        .replace(/[^a-zA-Z0-9._-]+/g, "_")
        .replace(/^_+|_+$/g, "");

    return cleaned || "life-stock-report";
}

function lifeLoadExternalScript(scriptId, sourceUrl, readyCheck) {
    return new Promise(function (resolve, reject) {
        if (readyCheck()) {
            resolve();
            return;
        }

        var existing = document.getElementById(scriptId);

        if (existing) {
            var attempts = 0;
            var timer = window.setInterval(function () {
                attempts += 1;

                if (readyCheck()) {
                    window.clearInterval(timer);
                    resolve();
                } else if (attempts >= 100) {
                    window.clearInterval(timer);
                    reject(
                        new Error(
                            "PDF library did not finish loading."
                        )
                    );
                }
            }, 100);

            return;
        }

        var script = document.createElement("script");
        script.id = scriptId;
        script.src = sourceUrl;
        script.async = true;

        script.onload = function () {
            if (readyCheck()) {
                resolve();
            } else {
                reject(
                    new Error(
                        "PDF library loaded, but its API is unavailable."
                    )
                );
            }
        };

        script.onerror = function () {
            reject(
                new Error(
                    "Could not load the PDF library. " +
                    "Check the site internet access or Content Security Policy."
                )
            );
        };

        (document.head || document.documentElement)
            .appendChild(script);
    });
}

function lifeLoadPdfLibraries() {
    if (
        window.jspdf &&
        window.jspdf.jsPDF &&
        window.jspdf.jsPDF.API &&
        window.jspdf.jsPDF.API.autoTable
    ) {
        return Promise.resolve(
            window.jspdf.jsPDF
        );
    }

    if (LIFE_PDF_LIBRARY_PROMISE) {
        return LIFE_PDF_LIBRARY_PROMISE;
    }

    LIFE_PDF_LIBRARY_PROMISE =
        lifeLoadExternalScript(
            "life-jspdf-library",
            "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js",
            function () {
                return !!(
                    window.jspdf &&
                    window.jspdf.jsPDF
                );
            }
        )
        .then(function () {
            return lifeLoadExternalScript(
                "life-jspdf-autotable-library",
                "https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.5.31/jspdf.plugin.autotable.min.js",
                function () {
                    return !!(
                        window.jspdf &&
                        window.jspdf.jsPDF &&
                        window.jspdf.jsPDF.API &&
                        window.jspdf.jsPDF.API.autoTable
                    );
                }
            );
        })
        .then(function () {
            return window.jspdf.jsPDF;
        })
        .catch(function (error) {
            LIFE_PDF_LIBRARY_PROMISE = null;
            throw error;
        });

    return LIFE_PDF_LIBRARY_PROMISE;
}

