return[];
});

return Promise.all([binPromise,stockBalancePromise]).then(function(results){
var binRows=Array.isArray(results[0])?results[0]:[];
var reportRows=Array.isArray(results[1])?results[1]:[];
var allowedWarehouseMap={};
var reportByKey={};
var merged=[];
var mergedKeyMap={};

whs.forEach(function(warehouse){
allowedWarehouseMap[String(warehouse||'').trim()]=true;
});

reportRows.forEach(function(row){
if(!row||!row.item_code||!row.warehouse){
return;
}

var warehouse=String(row.warehouse||'').trim();
if(!allowedWarehouseMap[warehouse]){
return;
}

var itemCode=String(row.item_code||'').trim();
var key=itemCode+'||'+warehouse;
var quantity=Number(row.bal_qty);
var reserved=Number(row.reserved_stock);
var valuationRate=Number(row.val_rate);
var balanceValue=Number(row.bal_val);

if(!isFinite(quantity))quantity=0;
if(!isFinite(reserved))reserved=0;
if(!isFinite(valuationRate))valuationRate=0;
if(!isFinite(balanceValue))balanceValue=0;

if(!reportByKey[key]){
reportByKey[key]={
item_code:itemCode,
warehouse:warehouse,
actual_qty:0,
balance_qty:0,
reserved_qty:0,
projected_qty:0,
valuation_rate:0,
balance_value:0
};
}

reportByKey[key].actual_qty+=quantity;
reportByKey[key].balance_qty+=quantity;
reportByKey[key].reserved_qty+=reserved;
reportByKey[key].projected_qty=
reportByKey[key].actual_qty-reportByKey[key].reserved_qty;
reportByKey[key].balance_value+=balanceValue;

if(valuationRate>0){
reportByKey[key].valuation_rate=valuationRate;
}
});

binRows.forEach(function(binRow){
if(!binRow||!binRow.item_code||!binRow.warehouse){
return;
}

var itemCode=String(binRow.item_code||'').trim();
var warehouse=String(binRow.warehouse||'').trim();
var key=itemCode+'||'+warehouse;
var liveRow=reportByKey[key];
var output={};

Object.keys(binRow).forEach(function(fieldname){
output[fieldname]=binRow[fieldname];
});

if(liveRow){
output.actual_qty=liveRow.actual_qty;
output.balance_qty=liveRow.balance_qty;
output.reserved_qty=liveRow.reserved_qty;
output.projected_qty=liveRow.projected_qty;
output.balance_value=liveRow.balance_value;

if(Number(liveRow.valuation_rate)>0){
output.valuation_rate=liveRow.valuation_rate;
}
}
else{
output.actual_qty=Number(binRow.actual_qty)||0;
output.balance_qty=output.actual_qty;
output.reserved_qty=Number(binRow.reserved_qty)||0;
output.projected_qty=Number(binRow.projected_qty)||
(output.actual_qty-output.reserved_qty);
output.valuation_rate=Number(binRow.valuation_rate)||0;
}

merged.push(output);
mergedKeyMap[key]=true;
});

Object.keys(reportByKey).forEach(function(key){
if(mergedKeyMap[key]){
return;
}
merged.push(reportByKey[key]);
});

merged.sort(function(left,right){
var quantityDifference=(Number(right.actual_qty)||0)-(Number(left.actual_qty)||0);
if(quantityDifference!==0){
return quantityDifference;
}
var itemDifference=String(left.item_code||'').localeCompare(
String(right.item_code||''),
undefined,
{numeric:true,sensitivity:'base'}
);
if(itemDifference!==0){
return itemDifference;
}
return String(left.warehouse||'').localeCompare(String(right.warehouse||''));
});

CACHE.bins[branchCode]=merged;
return merged;
});
}
