function attachPagination(rows,tbodyEl,rowHtmlFn,pageSize,countEl){
pageSize=pageSize||10;
var shown=0;
var wrap=tbodyEl.closest?tbodyEl.closest('.tbl-wrap'):null;
function renderChunk(){
var next=rows.slice(shown,shown+pageSize);
var html=next.map(rowHtmlFn).join('');
var old=tbodyEl.querySelector('tr[data-sentinel]');
if(old)old.parentNode.removeChild(old);
tbodyEl.insertAdjacentHTML('beforeend',html);
shown+=next.length;
if(countEl)countEl.textContent=shown+' / '+rows.length;
if(shown<rows.length){
var colspan=tbodyEl.querySelectorAll('tr:last-child td').length||6;
tbodyEl.insertAdjacentHTML('beforeend','<tr data-sentinel="1"><td colspan="'+colspan+'" style="text-align:center;color:#8C8C8C;padding:10px;cursor:pointer" class="ls-load-more">▼ Loading more… (scroll)</td></tr>');
}
}
renderChunk();
if(wrap){
wrap.addEventListener('scroll',function(){
if(shown>=rows.length)return;
if(wrap.scrollTop+wrap.clientHeight>=wrap.scrollHeight-40)renderChunk();
}
);
}
tbodyEl.addEventListener('click',function(e){
if(e.target&&e.target.classList&&e.target.classList.contains('ls-load-more'))renderChunk();
}
);
}
