function lifeFormRecalcTotals() {
    var showRate = (FORM_CTX === 'po' || FORM_CTX === 'pr' || FORM_CTX === 'pi');
    var formRoot = currentCreationFormRoot();
    if (!formRoot) return;

    // Pull current qty/rate from DOM into FORM_ROWS
    syncActiveFormRowsFromDom();
    syncFormTaxRowsFromDom();

    // ----- Net Total -----
    var netTotal = 0;
    var totalQty = 0;

    FORM_ROWS.forEach(function (row) {
        if (!row.item_code) return;
        var qty = Number(row.qty) || 0;
        var rate = showRate ? (Number(row.rate) || 0) : 0;
        totalQty += qty;
        netTotal += qty * rate;
    });

    // ----- Taxes (sequential — each row may depend on previous rows) -----
    var totalTax = 0;

    for (var i = 0; i < FORM_TAX_ROWS.length; i++) {
        var tax = FORM_TAX_ROWS[i];
        var chargeType = String(tax.charge_type || "On Net Total");
        var category = String(tax.category || "Total");
        var addDeduct = String(tax.add_deduct_tax || "Add");
        var rate = Number(tax.rate) || 0;

        var base = 0;

        if (chargeType === "On Net Total") {
            base = netTotal;
        } else if (chargeType === "Actual") {
            tax.tax_amount = rate;
            tax.total = netTotal + (addDeduct === "Deduct" ? -rate : rate);
            totalTax += (addDeduct === "Deduct" ? -rate : rate);
            continue;
        } else if (chargeType === "On Previous Row Amount") {
            var refRowIdx = Number(tax.row_id) - 1;
            if (refRowIdx >= 0 && FORM_TAX_ROWS[refRowIdx]) {
                base = Number(FORM_TAX_ROWS[refRowIdx].tax_amount) || 0;
            }
        } else if (chargeType === "On Previous Row Total") {
            var refRowIdx2 = Number(tax.row_id) - 1;
            if (refRowIdx2 >= 0 && FORM_TAX_ROWS[refRowIdx2]) {
                base = netTotal;
                for (var k = 0; k <= refRowIdx2; k++) {
                    var rk = FORM_TAX_ROWS[k];
                    var rkAdd = String(rk.add_deduct_tax || "Add");
                    var rkAmt = Number(rk.tax_amount) || 0;
                    base += (rkAdd === "Deduct" ? -rkAmt : rkAmt);
                }
            }
        } else if (chargeType === "On Item Quantity") {
            base = totalQty;
        }

        var amount = base * rate / 100;
        tax.tax_amount = amount;

        var signedAmount = (addDeduct === "Deduct" ? -amount : amount);
        totalTax += signedAmount;

        tax.total = netTotal + totalTax;
    }

    // ----- Grand Total -----
    var grandTotal = netTotal + totalTax;

    // ----- Update DOM -----
    var netEl = formRoot.querySelector('#ls-form-net-total');
    var taxEl = formRoot.querySelector('#ls-form-tax-total');
    var grandEl = formRoot.querySelector('#ls-form-grand-total');
    var qtyEl = formRoot.querySelector('#ls-form-total-qty');

    if (netEl) netEl.textContent = money(netTotal);
    if (taxEl) taxEl.textContent = money(totalTax);
    if (grandEl) grandEl.textContent = money(grandTotal);
    if (qtyEl) qtyEl.textContent = num(totalQty);

    // Persist on the form state so submit can read it
    formRoot.__lifeTotals = {
        net_total: netTotal,
        total_taxes_and_charges: totalTax,
        grand_total: grandTotal,
        total_qty: totalQty
    };

    // *** THE FIX ***
    // Instead of repainting the whole table (which kills focus),
    // surgically update only the calculated cells that need to change.
    lifeFormUpdateTaxRowCalculatedCells();
}

function lifeFormUpdateTaxRowCalculatedCells() {
    var tbody = formById('ls-tax-rows');
    if (!tbody) return;

    FORM_TAX_ROWS.forEach(function (tax, idx) {
        var rowEl = tbody.querySelector('tr[data-taxrow="' + idx + '"]');
        if (!rowEl) return;

        // 1. Update the "Amount" cell
        var amountCell = rowEl.querySelector('.life-tax-row-amount');
        if (amountCell) {
            amountCell.textContent = money(Number(tax.tax_amount) || 0);
        }

        // 2. Update the "Total" cell
        var totalCell = rowEl.querySelector('.life-tax-row-total');
        if (totalCell) {
            totalCell.textContent = money(Number(tax.total) || 0);
        }

        // 3. Update the "Ref Row #" input, but only if it's not the currently focused element
        var refRowInput = rowEl.querySelector('[data-taxrow-field="row_id"]');
        if (refRowInput && document.activeElement !== refRowInput) {
            refRowInput.value = tax.row_id || '';
        }
    });
}

