var LIFE_TAX_ACCOUNT_CACHE = null;
var LIFE_TAX_ACCOUNT_PROMISE = null;

function lifeLoadTaxAccounts() {
    if (LIFE_TAX_ACCOUNT_CACHE) {
        return Promise.resolve(LIFE_TAX_ACCOUNT_CACHE);
    }
    if (LIFE_TAX_ACCOUNT_PROMISE) {
        return LIFE_TAX_ACCOUNT_PROMISE;
    }

    LIFE_TAX_ACCOUNT_PROMISE = window.LifeStockGateway.compat({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Account',
            fields: ['name', 'account_name', 'account_number', 'root_type', 'is_group', 'company'],
            filters: {
                company: COMPANY,
                is_group: 0,
                disabled: 0
            },
            order_by: 'name asc',
            limit_page_length: 0
        }
    }).then(function (response) {
        var rows = (response && Array.isArray(response.message))
            ? response.message
            : [];
        LIFE_TAX_ACCOUNT_CACHE = rows;
        LIFE_TAX_ACCOUNT_PROMISE = null;
        return rows;
    }).catch(function (error) {
        LIFE_TAX_ACCOUNT_PROMISE = null;
        throw error;
    });

    return LIFE_TAX_ACCOUNT_PROMISE;
}

function lifeRenderTaxAccountMenu(idx, term) {
    var menu = document.querySelector(
        '#ls-tax-account-menu-' + idx
    );
    if (!menu) return;

    var input = document.querySelector(
        '.ls-tax-account-input[data-taxrow-index="' + idx + '"]'
    );

    menu.innerHTML = '<div class="ls-ss-empty">Loading accounts…</div>';
    menu.classList.add('show');

    lifeLoadTaxAccounts().then(function (rows) {
        var needle = String(term || '').trim().toLowerCase();
        var matches = needle
            ? rows.filter(function (row) {
                var label = String(row.account_name || '').toLowerCase();
                var name = String(row.name || '').toLowerCase();
                return label.indexOf(needle) !== -1 ||
                       name.indexOf(needle) !== -1;
            })
            : rows;

        matches = matches.slice(0, 200);

        if (!matches.length) {
            menu.innerHTML = '<div class="ls-ss-empty">No matching accounts</div>';
            return;
        }

        menu.innerHTML = matches.map(function (row) {
            return '<div class="ls-ss-opt" ' +
                'data-tax-account-pick="' + esc(String(row.name)) + '" ' +
                'data-tax-account-idx="' + idx + '">' +
                '<strong>' + esc(row.account_name || row.name) + '</strong>' +
