                    esc(row.name) +
                    (row.root_type ? ' · ' + esc(row.root_type) : '') +
                '</div>' +
            '</div>';
        }).join('');
    }).catch(function (error) {
        void 0;
        menu.innerHTML = '<div class="ls-ss-empty">Unable to load accounts</div>';
    });
}

