async function lifeFetchAndApplyItemRate(ssId, itemCode) {
    if (!FORM_CTX || !['po', 'pr', 'pi'].includes(FORM_CTX)) {
        return;
    }

    var ridMatch = ssId.match(/-item-(\d+)$/);
    if (!ridMatch || !ridMatch[1]) {
        void 0;
        return;
    }

    var rid = Number(ridMatch[1]);
    var formRow = FORM_ROWS.find(function (r) { return r.rid === rid; });
    if (!formRow) {
        void 0;
        return;
    }

    var formRoot = currentCreationFormRoot();
    if (!formRoot) return;

    var rateInput = formRoot.querySelector('[data-frow-rate="' + rid + '"]');
    if (!rateInput) return;

    rateInput.placeholder = '...';
    rateInput.disabled = true;

    var supplier = '';
    if (FORM_CTX === 'po') supplier = SS.value('ss-po-supplier');
    else if (FORM_CTX === 'pr') supplier = SS.value('ss-pr-supplier');
    else if (FORM_CTX === 'pi') supplier = SS.value('ss-pi-supplier');

    try {
        // STEP 1: Fetch the buying prices from Item Price
        var priceResponse = await window.LifeStockGateway.compat({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Item Price',
                filters: { item_code: itemCode, buying: 1 },
                fields: ['supplier', 'price_list_rate', 'currency'],
                order_by: 'price_list_rate asc',
                limit_page_length: 100
            }
        });
        var priceRows = (priceResponse && Array.isArray(priceResponse.message)) ? priceResponse.message : [];

        var chosen = null;
        if (supplier) {
            chosen = priceRows.find(function (row) {
                return String(row.supplier || '').trim() === supplier;
            });
        }
        if (!chosen && priceRows.length) {
            chosen = priceRows[0];
        }
        var newRate = chosen ? Number(chosen.price_list_rate) : 0;

        // STEP 2: Fallback to last_purchase_rate
        if (!newRate) {
            var args = {
                item_code: itemCode, company: COMPANY,
                doctype: FORM_CTX === 'po' ? 'Purchase Order' : FORM_CTX === 'pr' ? 'Purchase Receipt' : 'Purchase Invoice',
                supplier: supplier, currency: 'INR', conversion_rate: 1,
                price_list: 'Standard Buying', price_list_currency: 'INR', plc_conversion_rate: 1,
                qty: Number(formRow.qty) || 1, stock_qty: Number(formRow.qty) || 1,
            };
            var detailResponse = await window.LifeStockGateway.compat({
                method: 'erpnext.stock.get_item_details.get_item_details',
                args: { args: args, doc: Object.assign({ doctype: args.doctype, supplier: supplier, company: COMPANY, currency: 'INR', price_list: 'Standard Buying', price_list_currency: 'INR', conversion_rate: 1, plc_conversion_rate: 1 }, args) }
            });
            var itemDetails = detailResponse && detailResponse.message ? detailResponse.message : {};
            if (itemDetails.last_purchase_rate > 0) {
                newRate = itemDetails.last_purchase_rate;
            }
        }

        formRow.rate = newRate;
        rateInput.value = newRate;

        // STEP 3: Item-level tax template (unchanged, but now safely wrapped)
        try {
            var taxCategoryField = formById('ls-tax-category');
            var taxCategory = taxCategoryField ? String(taxCategoryField.value || '').trim() : '';

            var taxResponse = await window.LifeStockGateway.compat({
                method: 'erpnext.stock.get_item_details.get_item_tax_template',
                args: { args: { item_code: itemCode, company: COMPANY, base_net_rate: newRate, tax_category: taxCategory, transaction_date: isoToday() } }
            });
            var taxTemplateName = taxResponse && taxResponse.message ? taxResponse.message : '';
            if (taxTemplateName && typeof taxTemplateName === 'object') {
                taxTemplateName = taxTemplateName.name || '';
            }
            taxTemplateName = String(taxTemplateName || '').trim();

            if (taxTemplateName) {
                var taxTemplateField = formById('ls-tax-template');
                if (taxTemplateField) {
                    taxTemplateField.value = taxTemplateName;
                    FORM_TAX_TEMPLATE = taxTemplateName;

                    // FIX: This function now handles the "not found" case gracefully.
                    await lifeFormLoadTaxTemplate(FORM_TAX_TEMPLATE);
                }
            }
        } catch (taxError) {
            void 0;
        }

        lifeFormRecalcTotals();
    } catch (e) {
        void 0;
        showModal('⚠️', 'Rate Fetch Failed',
            'Could not fetch the rate for ' + itemCode + '. Please enter it manually.');
    } finally {
        rateInput.placeholder = '0.00';
        rateInput.disabled = false;
    }
}

async function lifeFormLoadTaxTemplate(templateName) {
    var formRoot = currentCreationFormRoot();
    if (!formRoot) return;

    // Normalize: templateName may be an object with a "name" field
    if (templateName && typeof templateName === 'object') {
        templateName = templateName.name || '';
    }
    templateName = String(templateName || '').trim();

    if (!templateName) {
        // No template to load — clear tax rows but do not error.
        FORM_TAX_ROWS = [];
        lifeFormRepaintTaxRows();
        lifeFormRecalcTotals();
        return;
    }

    // Verify the template exists before trying to load it.
    // This prevents the "not found" error from surfacing as a modal.
    try {
        var existsResponse = await window.LifeStockGateway.compat({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Purchase Taxes and Charges Template',
                filters: { name: templateName },
                fieldname: 'name'
            }
        });

        var exists = existsResponse &&
                     existsResponse.message &&
                     existsResponse.message.name;

        if (!exists) {
            void 0;
            FORM_TAX_ROWS = [];
            lifeFormRepaintTaxRows();
            lifeFormRecalcTotals();

            var msg = formById('ls-tax-msg');
            if (msg) {
                msg.innerHTML =
                    '<div class="notice notice-orange">' +
                    'Tax template "' + esc(templateName) + '" was not found. ' +
                    'You can select one manually.' +
                    '</div>';
            }
            return;
        }
    } catch (checkError) {
        void 0;
        // Fall through and let the main call surface its own error.
    }

    var msg = formById('ls-tax-msg');
    if (msg) msg.innerHTML = '<div class="notice notice-blue">⏳ Loading tax template…</div>';

    try {
        var doc = await callGet("Purchase Taxes and Charges Template", templateName);
        FORM_TAX_ROWS = (doc && Array.isArray(doc.taxes) ? doc.taxes : []).map(function (tax) {
            return {
                charge_type: tax.charge_type || "On Net Total",
                account_head: tax.account_head || "",
                description: tax.description || tax.account_head || "",
                rate: Number(tax.rate) || 0,
                tax_amount: 0,
                total: 0,
                category: tax.category || "Total",
                add_deduct_tax: tax.add_deduct_tax || "Add",
                cost_center: tax.cost_center || ""
            };
        });

        // copy tax_category from template if present
        if (doc && doc.tax_category) {
            FORM_TAX_CATEGORY = doc.tax_category;
            var catField = formById('ls-tax-category');
            if (catField) catField.value = FORM_TAX_CATEGORY;
        }

    if (msg) msg.innerHTML = '<div class="notice notice-green">✓ ' + FORM_TAX_ROWS.length + ' tax row(s) loaded from ' + esc(templateName) + '</div>';
        lifeFormRepaintTaxRows(); // <-- FIX: Create the DOM rows for the new template
        lifeFormRecalcTotals();   // <-- Now, calculate their values
    } catch (error) {
        void 0;
        if (msg) msg.innerHTML = '<div class="notice notice-red">✕ Could not load template: ' + esc(error.message || error) + '</div>';
    }
}

/**
 * Load the default Purchase Taxes and Charges Template for the
 * currently selected supplier. Mirrors ERPNext's behaviour where
 * the parent-level tax template is set from the supplier's tax
 * category / company defaults.
 */
async function lifeFormApplyDefaultSupplierTaxTemplate() {
    if (!FORM_CTX || !['po', 'pr', 'pi'].includes(FORM_CTX)) {
        return;
    }

    var supplier = '';
    if (FORM_CTX === 'po') supplier = SS.value('ss-po-supplier');
    else if (FORM_CTX === 'pr') supplier = SS.value('ss-pr-supplier');
    else if (FORM_CTX === 'pi') supplier = SS.value('ss-pi-supplier');

    if (!supplier) return;

    // If the user has already chosen a template, leave it alone.
    if (FORM_TAX_TEMPLATE) return;

    try {
        // Resolve the supplier's tax category (if any)
        var supplierResponse = await window.LifeStockGateway.compat({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Supplier',
                filters: { name: supplier },
                fieldname: ['tax_category', 'gst_category']
            }
        });

        var supplierData =
            supplierResponse && supplierResponse.message
                ? supplierResponse.message
                : {};

        var taxCategory =
            supplierData.tax_category ||
            supplierData.gst_category ||
            '';

        // Ask ERPNext for the default Purchase Taxes and Charges Template
        var defaultResponse = await window.LifeStockGateway.compat({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Purchase Taxes and Charges Template',
                filters: {
                    company: COMPANY,
                    disabled: 0
                },
                or_filters: taxCategory
                    ? [
                        ['tax_category', '=', taxCategory],
                        ['tax_category', '=', '']
                      ]
                    : [['tax_category', '=', '']],
                fields: ['name', 'title', 'tax_category'],
                order_by: 'is_default desc, modified desc',
                limit_page_length: 1
            }
        });

        var templates =
            defaultResponse && Array.isArray(defaultResponse.message)
                ? defaultResponse.message
                : [];

        if (!templates.length) {
            void 0;
            return;
        }

        var chosen = templates[0].name;

        var taxTemplateField = formById('ls-tax-template');
        if (taxTemplateField) {
            taxTemplateField.value = chosen;
        }
        FORM_TAX_TEMPLATE = chosen;

        await lifeFormLoadTaxTemplate(chosen);
    } catch (error) {
        void 0;
    }
}

var LIFE_TAX_TEMPLATE_SEARCH_TIMER = null;

async function lifeFormSearchTaxTemplate(term) {
    term = String(term || "").trim();
    var drop = byId('ls-tax-template-drop');
    if (!drop) return;

    // Clear any existing timer to debounce the search
    if (LIFE_TAX_TEMPLATE_SEARCH_TIMER) {
        clearTimeout(LIFE_TAX_TEMPLATE_SEARCH_TIMER);
    }

    // Show a loading indicator immediately
    drop.innerHTML = '<div class="ls-ss-empty">Searching…</div>';
    drop.classList.add('show');

    // Debounce the actual API call
    LIFE_TAX_TEMPLATE_SEARCH_TIMER = setTimeout(async () => {
        try {
            // When term is empty, fetch all available templates.
            // When term is present, apply the or_filters.
            var orFilters = term
                ? [["name", "like", "%" + term + "%"], ["title", "like", "%" + term + "%"]]
                : undefined;

            var rows = await callList("Purchase Taxes and Charges Template", {
                fields: ["name", "title", "company", "tax_category"],
                filters: { company: COMPANY, disabled: 0 },
                or_filters: orFilters,
                order_by: "title asc",
                limit: 40
            });
            drop._rows = rows;
            drop.innerHTML = rows.length
                ? rows.map(function (r, i) {
                    return '<div class="ls-ss-opt" data-tax-tmpl-idx="' + i + '">' +
                        '<strong>' + esc(r.title || r.name) + '</strong>' +
                        '<div class="ls-ss-sub">' + esc(r.name) + ' · ' + esc(r.tax_category || "No category") + '</div>' +
                    '</div>';
                }).join("")
                : '<div class="ls-ss-empty">No tax templates found for this company.</div>';
        } catch (error) {
            void 0;
            drop.innerHTML = '<div class="ls-ss-empty">Search failed. Please try again.</div>';
        }
    }, 250); // 250ms debounce delay
}

