function loadPrItemsIntoInvoiceForm(prName, supplierSSId) {
    var msg =
        formById("ls-form-msg");

    if (msg) {
        msg.innerHTML =
            '<div class="notice notice-blue">' +
            "⏳ Loading billable items from " +
            esc(prName) +
            "…" +
            "</div>";
    }

    return callGet(
        "Purchase Receipt",
        prName
    )
        .then(function (doc) {
            if (!doc) {
                throw new Error(
                    "Purchase Receipt " +
                    prName +
                    " could not be loaded."
                );
            }

            var statusKey =
                String(
                    doc.status || ""
                )
                    .trim()
                    .toLowerCase()
                    .replace(
                        /[^a-z0-9]+/g,
                        ""
                    );

            if (
                Number(doc.docstatus) !== 1 ||
                statusKey !== "tobill"
            ) {
                throw new Error(
                    "Purchase Receipt " +
                    prName +
                    " is " +
                    String(
                        doc.status ||
                        "not billable"
                    ) +
                    ". Only To Bill Purchase Receipts can create a Purchase Invoice."
                );
            }

            var items =
                Array.isArray(doc.items)
                    ? doc.items
                    : [];

            items = items.filter(
                function (item) {
                    return (
                        Number(
                            item.qty ||
                            item.received_qty ||
                            0
                        ) > 0
                    );
                }
            );

            if (!items.length) {
                throw new Error(
                    "Purchase Receipt " +
                    prName +
                    " has no billable item rows."
                );
            }

            /*
             * Supplier
             */
            if (
                supplierSSId &&
                doc.supplier
            ) {
                SS.pick(
                    supplierSSId,
                    doc.supplier
                );
            }

            /*
             * Exact Purchase Receipt item rows.
             */
            FORM_ROWS = [];
            FORM_SEQ = 0;

            items.forEach(
                function (item) {
                    FORM_ROWS.push({
                        rid:
                            FORM_SEQ++,

                        item_code:
                            item.item_code,

                        qty:
                            Number(
                                item.qty ||
                                item.received_qty
                            ) || 1,

                        rate:
                            Number(
                                item.rate
                            ) || 0,

                        purchase_receipt:
                            prName,

                        purchase_receipt_item:
                            item.name,

                        warehouse:
                            item.warehouse ||
                            doc.set_warehouse ||
                            "",

                        expense_account:
                            item.expense_account ||
                            "",

                        cost_center:
                            item.cost_center ||
                            ""
                    });
                }
            );

            // --- FIX: Load taxes from the source Purchase Receipt ---
            // Populate tax state first, then defer the repaint so the
            // #ls-tax-rows tbody exists in the DOM before it is used.
            FORM_TAX_ROWS = (doc.taxes && Array.isArray(doc.taxes)) ? doc.taxes.map(function(tax) {
                return {
                    charge_type: tax.charge_type || "On Net Total",
                    account_head: tax.account_head || "",
                    description: tax.description || tax.account_head || "",
                    rate: Number(tax.rate) || 0,
                    tax_amount: Number(tax.tax_amount) || 0,
                    total: Number(tax.total) || 0,
                    category: tax.category || "Total",
                    add_deduct_tax: tax.add_deduct_tax || "Add",
                    cost_center: tax.cost_center || ""
                };
            }) : [];
            FORM_TAX_TEMPLATE = doc.taxes_and_charges || "";
            FORM_TAX_CATEGORY = doc.tax_category || "";

            // Repaint the items table immediately (its tbody may already exist)
            paintFormRows();

            // Defer tax repaint until the browser has finished injecting
            // the form shell HTML so #ls-tax-rows actually exists.
            setTimeout(function () {
                lifeFormRepaintTaxRows();
                lifeFormRecalcTotals();
            }, 0);
            // --- END FIX ---

            if (msg) {
                msg.innerHTML =
                    '<div class="notice notice-green">' +
                    "✓ Loaded " +
                    items.length +
                    " item(s) and " +
                    FORM_TAX_ROWS.length +
                    " tax rule(s) from " +
                    esc(prName) +
                    ". Supplier and received item details were fetched from the Purchase Receipt." +
                    "</div>";
            }

            return doc;
        })
        .catch(function (error) {
            if (msg) {
                errorBox(
                    msg,
                    error
                );
            }

            throw error;
        });
}

