        return;
    }

    var warehouseRegistry=SS.reg('ss-pr-wh');
    if(!warehouseRegistry||!warehouseRegistry.options.some(function(option){return option&&option.value===wh;})){
        if(msg)msg.innerHTML='<div class="notice notice-red">Select a valid Accepting Warehouse from the search results.</div>';
        return;
    }

    var pdfInput=formById('ls-pr-receipt-pdf');
    var receiptPdf=pdfInput&&pdfInput.files&&pdfInput.files[0]?pdfInput.files[0]:null;
    if(!receiptPdf){
        if(msg)msg.innerHTML='<div class="notice notice-red">Receipt PDF Upload is mandatory.</div>';
        return;
    }

    var pdfName=String(receiptPdf.name||'').toLowerCase();
    var pdfType=String(receiptPdf.type||'').toLowerCase();
    var receiptFileIsPdf=pdfType==='application/pdf'||pdfName.endsWith('.pdf');
    var receiptFileIsImage=pdfType.indexOf('image/')===0||/\.(png|jpe?g|webp|heic|heif)$/i.test(pdfName);
    if(!receiptFileIsPdf&&!receiptFileIsImage){
        if(msg)msg.innerHTML='<div class="notice notice-red">Upload a valid file for Receipt PDF Upload.</div>';
        return;
    }

    var postingDate=(formById('ls-pr-date')||{}).value||isoToday();

    var items=formRowsToItems(function(it){
        it.warehouse=wh;
    });

    if(!items.length){
        if(msg)msg.innerHTML='<div class="notice notice-red">Add at least one item with a received quantity greater than zero.</div>';
        return;
    }

    /* Rate validation */
    var nonPositiveRateIndex=-1;
    items.some(function(item,index){
        var rowRate=Number(item.rate);
        if(!Number.isFinite(rowRate)||rowRate<=0){
            nonPositiveRateIndex=index;
            return true;
        }
        return false;
    });

    if(nonPositiveRateIndex>-1){
        if(msg)msg.innerHTML=
            '<div class="notice notice-red">'+
            'Rate must be greater than zero in item row '+
            (nonPositiveRateIndex+1)+
            '. A positive rate is required for the normal Purchase Receipt → To Bill → Purchase Invoice flow.'+
            '</div>';
        return;
    }

    /* Build tax lines BEFORE the try block */
    lifeFormRecalcTotals();
    var totals = (currentCreationFormRoot() || {}).__lifeTotals || {};

    var taxLines = FORM_TAX_ROWS.map(function (tx, idx) {
        return {
            doctype: "Purchase Taxes and Charges",
            category: tx.category || "Total",
            add_deduct_tax: tx.add_deduct_tax || "Add",
            charge_type: tx.charge_type || "On Net Total",
            account_head: tx.account_head || "",
            description: tx.description || tx.account_head || "",
            row_id: tx.row_id ? Number(tx.row_id) : null,
            included_in_print_rate: tx.included_in_print_rate ? 1 : 0,
            is_included_in_paid_amount: tx.is_included_in_paid_amount ? 1 : 0,
            is_tax_withholding_account: tx.is_tax_withholding_account ? 1 : 0,
            rate: Number(tx.rate) || 0,
            tax_amount: Number(tx.tax_amount) || 0,
            total: Number(tx.total) || Number(tx.tax_amount) || 0,
            cost_center: tx.cost_center || "",
            idx: idx + 1
        };
    });

    try{
        if(btn)btn.disabled=true;
        if(msg)msg.innerHTML='<div class="notice notice-blue">⏳ Uploading Receipt PDF…</div>';

        var uploadApi=window.LifeStockAPI;
        if(!uploadApi||typeof uploadApi.uploadTemporaryFile!=="function"){
            throw new Error("Receipt upload service is not available. Refresh the page and try again.");
        }

        var receiptPdfUrl=await uploadApi.uploadTemporaryFile(receiptPdf,true);

        /* SINGLE doc object — includes tax fields */
        var doc = {
            docstatus: 0,
            doctype: 'Purchase Receipt',
            supplier: supplier,
            company: COMPANY,
            posting_date: postingDate,
            currency: 'INR',
            conversion_rate: 1,
            set_warehouse: wh,
            supplier_delivery_note: deliveryNote,
            custom_receipt_pdf_upload: receiptPdfUrl,
            tax_category: FORM_TAX_CATEGORY || "",
            taxes_and_charges: FORM_TAX_TEMPLATE || "",
            taxes: taxLines,
            items: items
        };

        if(msg)msg.innerHTML='<div class="notice notice-blue">⏳ Creating Purchase Receipt…</div>';
        insertDoc(doc,'Purchase Receipt',renderPurchaseReceipt);

    }catch(error){
        if(btn)btn.disabled=false;
        if(msg)msg.innerHTML='<div class="notice notice-red">✕ '+esc((error&&error.message)||'Receipt PDF upload failed.')+'</div>';
    }
}

/*
 * Purchase Receipt -> Purchase Invoice shortcut.
 *
 * Used by the "Create Purchase Invoice" button in a submitted
 * To Bill Purchase Receipt detail modal.
 */
async function lifeCreateInvoiceFromPurchaseReceipt(purchaseReceiptName) {
    var receiptName = String(
        purchaseReceiptName || ""
    ).trim();

    if (!receiptName) {
        return;
    }

    /*
     * Re-read the exact Purchase Receipt before navigating.
     * This protects against stale modals and status changes.
     */
    var receiptDoc;

    try {
        receiptDoc = await callGet(
            "Purchase Receipt",
            receiptName
        );
    }
    catch (error) {
        showError(
            new Error(
                "Could not load Purchase Receipt " +
                receiptName +
                "."
            )
        );
        return;
    }

    if (!receiptDoc) {
        showError(
            new Error(
                "Purchase Receipt " +
                receiptName +
                " could not be found."
            )
        );
        return;
    }

    var statusKey = String(
        receiptDoc.status || ""
    )
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "");

    if (
        Number(receiptDoc.docstatus) !== 1 ||
        statusKey !== "tobill"
    ) {
        if (typeof toast === "function") {
            toast(
                "Purchase Receipt " +
                receiptName +
                " is now " +
                String(receiptDoc.status || "not billable") +
                ". A Purchase Invoice can be created only while it is To Bill.",
                "o"
            );
        }

        /*
         * Refresh the PR tab so a stale Create Invoice button disappears.
         */
        if (typeof renderPurchaseReceipt === "function") {
            renderPurchaseReceipt();
        }

        return;
    }

    if (typeof closeViewModal === "function") {
        closeViewModal();
    }
    else if (typeof closeModal === "function") {
        closeModal();
    }

    if (typeof showHoMode !== "function") {
        showError(
            new Error(
                "Purchase Invoice tab is not available."
            )
        );
        return;
    }

    showHoMode(6);

    var attempts = 0;
    var maxAttempts = 50;

    function waitForPurchaseInvoiceTab() {
        attempts += 1;

        var invoiceArea =
            byId("ls-ho-pi-area");

        var newInvoiceButton =
            byId("ls-new-pi");

        if (
            invoiceArea &&
            newInvoiceButton
        ) {
            openNewPurchaseInvoice(
                "PR::" + receiptName,
                receiptDoc
            );
            return;
        }

        if (attempts < maxAttempts) {
            window.setTimeout(
                waitForPurchaseInvoiceTab,
                100
            );
            return;
        }

        if (invoiceArea) {
            openNewPurchaseInvoice(
                "PR::" + receiptName,
                receiptDoc
            );
            return;
        }

        showError(
            new Error(
                "Purchase Invoice area could not be opened."
            )
        );
    }

    window.setTimeout(
        waitForPurchaseInvoiceTab,
        100
    );
}


