async function lifeCreateInvoiceFromPurchaseOrder(purchaseOrderName) {
    var orderName =
        String(
            purchaseOrderName || ""
        ).trim();

    if (!orderName) {
        return;
    }

    var orderDoc;

    try {
        orderDoc =
            await callGet(
                "Purchase Order",
                orderName
            );
    }
    catch (error) {
        showError(
            new Error(
                "Could not load Purchase Order " +
                orderName +
                "."
            )
        );
        return;
    }

    if (!orderDoc) {
        showError(
            new Error(
                "Purchase Order " +
