            )
        );
        return;
    }

    showHoMode(6);

    var attempts = 0;
    var maxAttempts = 50;

    function waitForPurchaseInvoiceTab() {
        attempts += 1;

        var invoiceArea =
            byId(
                "ls-ho-pi-area"
            );

        var newInvoiceButton =
            byId(
                "ls-new-pi"
            );

        if (
            invoiceArea &&
