var systemManagerBranchCode = "";

/* =========================================================
   RELIABLE LOGGED-IN USER ROLE DETECTION
   ========================================================= */

var loggedInUserRoleCache = null;
var loggedInUserRoleLoadPromise = null;

function normalizeRoleName(value) {
    return String(value || "")
        .trim()
        .toLowerCase();
}

function extractRoleName(value) {
    if (typeof value === "string") {
        return value;
    }

    if (value && typeof value === "object") {
        return (
            value.role ||
            value.role_name ||
            value.name ||
            ""
        );
    }

    return "";
}

function appendUniqueRoles(target, values) {
    target = Array.isArray(target)
        ? target
        : [];

    values = Array.isArray(values)
        ? values
        : [];

    values.forEach(function (value) {
        var roleName =
            String(
                extractRoleName(value) || ""
            ).trim();

        if (!roleName) {
            return;
        }

        var normalizedRole =
            normalizeRoleName(roleName);

        var alreadyExists =
            target.some(function (existingRole) {
                return (
                    normalizeRoleName(existingRole) ===
                    normalizedRole
                );
            });

        if (!alreadyExists) {
            target.push(roleName);
        }
    });

    return target;
}

function getClientAvailableRoles() {
    var roles = [];

    try {
        if (
            window.frappe &&
            Array.isArray(frappe.user_roles)
        ) {
            appendUniqueRoles(
                roles,
                frappe.user_roles
            );
        }
    } catch (error) {
        void 0;
    }

    try {
        if (
            window.frappe &&
            frappe.boot &&
            frappe.boot.user &&
            Array.isArray(
                frappe.boot.user.roles
            )
        ) {
            appendUniqueRoles(
                roles,
                frappe.boot.user.roles
            );
        }
    } catch (error) {
        void 0;
    }

    try {
        if (
            Array.isArray(
                window.user_roles
            )
        ) {
            appendUniqueRoles(
                roles,
                window.user_roles
            );
        }
    } catch (error) {
        void 0;
    }

    return roles;
}

async function loadLoggedInUserRoles() {
    if (
        Array.isArray(
            loggedInUserRoleCache
        )
    ) {
        return loggedInUserRoleCache.slice();
    }

    if (loggedInUserRoleLoadPromise) {
        return loggedInUserRoleLoadPromise;
    }

    loggedInUserRoleLoadPromise =
        (async function () {
            var roles =
                getClientAvailableRoles();

            var sessionUser =
                String(
                    window.frappe &&
                    frappe.session &&
                    frappe.session.user
                        ? frappe.session.user
                        : ""
                ).trim();

            /*
             * Administrator always has System Manager access.
             */
            if (
                normalizeUserId(sessionUser) ===
                "administrator"
            ) {
                appendUniqueRoles(
                    roles,
                    ["System Manager"]
                );
            }

            /*
             * Website routes may not expose effective roles through
             * frappe.user_roles / frappe.boot. Use the LIFE Stock
             * server context first because it resolves the logged-in
             * user's effective ERP roles without requiring browser-side
             * Read permission on the User DocType.
             */
            var rolesLoadedFromServerContext = false;

            try {
                if (
                    window.LifeStockGateway &&
                    typeof window.LifeStockGateway.action === "function"
                ) {
                    var roleContext =
                        await window.LifeStockGateway.action(
                            "get_context",
                            {}
                        );

                    if (
                        roleContext &&
                        Array.isArray(roleContext.roles)
                    ) {
                        appendUniqueRoles(
                            roles,
                            roleContext.roles
                        );

                        rolesLoadedFromServerContext = true;

                        window.__lifeStockRoleContext = {
                            user: roleContext.user || sessionUser,
                            roles: roles.slice(),
                            branch: roleContext.branch || "",
                            is_ho: !!roleContext.is_ho
                        };
                    }
                }
            } catch (roleContextError) {
                void 0;
            }

            /*
             * Compatibility / completeness fallback.
             *
             * Some website-route contexts can return a roles array
             * without every effective role. If neither Stock Manager
             * nor System Manager has been found yet, read the logged-in
             * User document when permission allows and merge User.roles.
             *
             * Access remains based on effective ERP roles only.
             */
            if (
                sessionUser &&
                (
                    !rolesLoadedFromServerContext ||
                    !lifeRoleListHasManagerToggleAccess(
                        roles
                    )
                )
            ) {
                try {
                    var userDocument =
                        await callGet(
                            "User",
                            sessionUser
                        );

                    if (
                        userDocument &&
                        Array.isArray(
                            userDocument.roles
                        )
                    ) {
                        appendUniqueRoles(
                            roles,
                            userDocument.roles
                        );
                    }
                } catch (userRoleError) {
                    void 0;
                }
            }

            loggedInUserRoleCache =
                roles.slice();

            return loggedInUserRoleCache.slice();
        })();

    return loggedInUserRoleLoadPromise;
}


function lifeRoleListHasManagerToggleAccess(roles) {
    roles = Array.isArray(roles)
        ? roles
        : [];

    return roles.some(function (role) {
        var normalized =
            normalizeRoleName(
                extractRoleName(role)
            );

        return (
            normalized === "stock manager" ||
            normalized === "system manager"
        );
    });
}

function loggedInUserHasRole(roleName) {
    var requiredRole =
        normalizeRoleName(roleName);

    if (!requiredRole) {
        return false;
    }

    if (
        loggedInUserId() ===
        "administrator"
    ) {
        return (
            requiredRole ===
            "system manager"
        );
    }

    /*
     * Use the server-loaded cache when available.
     */
    var availableRoles =
        Array.isArray(
            loggedInUserRoleCache
        )
            ? loggedInUserRoleCache
            : getClientAvailableRoles();

    return availableRoles.some(
        function (role) {
            return (
                normalizeRoleName(role) ===
                requiredRole
            );
        }
    );
}

function loggedInUserIsSystemManager() {
    return loggedInUserHasRole(
        "System Manager"
    );
}

/*
 * Stock Manager View access:
 * ERP User.roles must contain either Stock Manager or System Manager.
