function syncSystemManagerViewSwitch(view) {
    var switchElement = byId("ls-header-view-switch");

    if (!switchElement || switchElement.hidden) {
        return;
    }

    var normalizedView =
        String(view || "").trim() === "HO"
            ? "ho"
            : "branch";

    var activeBranchCode =
        normalizedView === "branch"
            ? String(
                view ||
                systemManagerBranchCode ||
                window.__lifeIntegratedStockBranchCode ||
                ""
            ).trim()
            : "";

    var activeBranchName =
        activeBranchCode
            ? (
                branchName(activeBranchCode) ||
                window.__lifeIntegratedStockBranchName ||
                activeBranchCode
            )
            : "";

    var branchButton = switchElement.querySelector(
        '[data-stock-view="branch"]'
    );

    var locationLabel = byId(
        "ls-header-location-label"
    );

    var locationCard = byId(
        "ls-header-location-card"
    );

    if (branchButton) {
        branchButton.textContent =
            normalizedView === "branch" && activeBranchName
                ? "Branch · " + activeBranchName
                : "Branch";

        branchButton.title =
            normalizedView === "branch" && activeBranchName
                ? "Current Branch: " + activeBranchName
                : "Select and open Branch View";
    }

    if (locationLabel) {
        locationLabel.textContent =
            normalizedView === "branch" && activeBranchName
                ? "DASHBOARD VIEW · " + activeBranchName.toUpperCase()
                : "DASHBOARD VIEW";
    }

    if (locationCard) {
        locationCard.style.minWidth =
            normalizedView === "branch" && activeBranchName
                ? "285px"
                : "218px";
    }

    Array.prototype.forEach.call(
        switchElement.querySelectorAll("[data-stock-view]"),
        function (button) {
            var buttonView = button.getAttribute("data-stock-view");
            var active = buttonView === normalizedView;

            button.classList.toggle(
                "life-stock-view-switch__button--active",
                active
            );

            button.setAttribute(
                "aria-pressed",
                active ? "true" : "false"
            );
        }
    );
}

async function switchSystemManagerStockView(
    requestedView
) {

    if (
        !loggedInUserHasStockManagerViewAccess()
    ) {
        return;
    }


    var requested =
        String(
            requestedView || ""
        )
        .trim()
        .toLowerCase();


    if (requested === "ho") {

        applyResolvedView(
            "HO"
        );

        return;
    }


    if (requested === "branch") {

        /*
         * System Manager always allowed.
         */
        if (
            loggedInUserIsSystemManager()
        ) {

            openSystemManagerBranchPicker();

            return;
        }


        /*
         * Stock Manager controlled by feature flag.
         */
        if (
            loggedInUserIsStockManager()
        ) {

            if (
                LIFE_STOCK_MANAGER_ALLOW_BRANCH_VIEW_SWITCH !== true
            ) {

                return;
            }


            openSystemManagerBranchPicker();

            return;
        }
    }
}


function normalizeBranchLookup(value){
return String(value||"").toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g,"");
}
function branchCodeFromName(value){
var normalized=normalizeBranchLookup(value);
if(!normalized){
return"";
}
var aliases={
chandanagar:"CN",chandhanagar:"CN",srnagar:"SRN",srinagar:"SRN",madhapur:"MP",banjarahills:"BH",banjarahill:"BH",himayathnagar:"HN",himayatnagar:"HN",dilsukhnagar:"DN",dilshuknagar:"DN",gachibowli:"GB",vijayawada:"VW",vizag:"VZ",visakhapatnam:"VZ",nellore:"NLR",kukatpally:"KP"}
;
if(aliases[normalized]){
return aliases[normalized];
}
for(var index=0;
index<BRANCHES.length;
index++){
var branch=BRANCHES[index];
if(normalizeBranchLookup(branch.name)===normalized||normalizeBranchLookup(branch.code)===normalized){
return branch.code;
}
for(var warehouseIndex=0;
warehouseIndex<branch.whs.length;
warehouseIndex++){
if(normalizeBranchLookup(branch.whs[warehouseIndex]).indexOf(normalized)===0){
return branch.code;
}
}
}
return"";
}
