/*
 * Material Request embedded-module mount generation.
 *
 * Every real Branch/HO mount gets a new token. Any delayed retry
 * from an older tab/view is ignored, preventing stale Branch
 * content from overriding Stock Manager Requests & Approvals.
 */
var LIFE_MATERIAL_MODULE_MOUNT_TOKEN = 0;

function lifeMaterialRequestPageAllowedForMode(moduleRoot, mode) {
    if (!moduleRoot) {
        return false;
    }

    var normalized =
        mode === "ho"
            ? "ho"
            : "branch";

    var activePage =
        moduleRoot.querySelector(
            ".page.active"
        );

    if (!activePage) {
        return false;
    }

    var activeId =
        String(
            activePage.id ||
            ""
        ).trim();

    if (normalized === "ho") {
        return activeId ===
            "page-ho-approval";
    }

    return [
        "page-home",
        "page-monthly-indent",
        "page-ssr",
        "page-asbr",
        "page-report"
    ].indexOf(activeId) !== -1;
}

function lifePrepareMaterialRequestModuleView(moduleRoot, mode, preserveActivePage) {
    if (!moduleRoot) {
        return;
    }

    var normalized =
        mode === "ho"
            ? "ho"
            : "branch";

    moduleRoot.dataset.forcedView =
        normalized;

    moduleRoot.classList.toggle(
        "life-integrated-forced-ho",
        normalized === "ho"
    );

    moduleRoot.classList.toggle(
        "life-integrated-forced-branch",
        normalized === "branch"
    );

    /*
     * A Material Request form can already be open while the host is
     * finishing an asynchronous module mount / context refresh.
     * In that case, do NOT force the Branch module back to Home.
     * Only a real view/branch change is allowed to reset the page.
     */
    if (
        preserveActivePage === true &&
        lifeMaterialRequestPageAllowedForMode(
            moduleRoot,
            normalized
        )
    ) {
        return;
    }

    /*
     * Remove every previous active page BEFORE the root is made
     * visible or moved into its destination slot.
     */
    Array.prototype.forEach.call(
        moduleRoot.querySelectorAll(
            ".page"
        ),
        function (page) {
            page.classList.remove(
                "active"
            );
        }
    );

    var targetPage =
        moduleRoot.querySelector(
            normalized === "ho"
                ? "#page-ho-approval"
                : "#page-home"
        );

    if (targetPage) {
        targetPage.classList.add(
            "active"
        );
    }
}

function lifeRevealMaterialRequestModule(moduleRoot, mountToken) {
    if (
        !moduleRoot ||
        mountToken !==
            LIFE_MATERIAL_MODULE_MOUNT_TOKEN
    ) {
        return;
    }

    moduleRoot.classList.remove(
        "life-material-module-switching"
    );

    moduleRoot.style.display =
        "block";

    moduleRoot.style.visibility =
        "visible";

    moduleRoot.style.pointerEvents =
        "";
}

function mountMaterialRequestModule(mode, existingMountToken){
var normalized=mode==="ho"?"ho":"branch";

var mountToken=
existingMountToken===undefined||
existingMountToken===null
?++LIFE_MATERIAL_MODULE_MOUNT_TOKEN
:Number(existingMountToken);

if(
mountToken!==
LIFE_MATERIAL_MODULE_MOUNT_TOKEN
){
return;
}

var moduleRoot=byId("life-material-request-root");
var targetSlot=byId(
normalized==="ho"
?"ls-ho-material-module-slot"
:"ls-branch-material-module-slot"
);

/*
 * The host DOM and the embedded module are created by the same
 * Web Page but may become available a few milliseconds apart.
 */
if(!moduleRoot||!targetSlot){
window.setTimeout(function(){
if(
mountToken===
LIFE_MATERIAL_MODULE_MOUNT_TOKEN
){
mountMaterialRequestModule(
normalized,
mountToken
);
}
},40);
return;
}

/*
 * Prevent one-frame cross-view content while moving the module.
 */
moduleRoot.classList.add(
"life-material-module-switching"
);

moduleRoot.style.display="none";
moduleRoot.style.visibility="hidden";
moduleRoot.style.pointerEvents="none";

/*
 * IMPORTANT:
 * Set the authoritative Branch / HO mode before moving the module.
 * If this is merely a re-mount of the SAME mode, preserve an already
 * open request form instead of forcing the user back to Home.
 */
var previousMountedMode=
String(
moduleRoot.dataset.forcedView||
""
).trim().toLowerCase();

var preserveMountedPage=
previousMountedMode===normalized&&
lifeMaterialRequestPageAllowedForMode(
moduleRoot,
normalized
);

lifePrepareMaterialRequestModuleView(
moduleRoot,
normalized,
preserveMountedPage
);

if(moduleRoot.parentNode!==targetSlot){
targetSlot.appendChild(moduleRoot);
}

/*
 * Reveal immediately.
 *
 * Do NOT wait for loadContext(), loadRequests(), Monthly Indent
 * settings, or any other asynchronous embedded-module work.
 * Those operations may legitimately take time and must not leave
 * the whole host tab blank.
 *
 * The CSS hard-separation rules already guarantee that:
 *   HO     -> only #page-ho-approval can render
 *   Branch -> HO approval page cannot render
 */
lifeRevealMaterialRequestModule(
moduleRoot,
mountToken
);

/*
 * Now synchronize the embedded runtime in the background.
 */
if(
window.LifeMaterialRequestModule&&
typeof window.LifeMaterialRequestModule.setView==="function"
){
Promise.resolve(
window.LifeMaterialRequestModule.setView(
normalized
)
).then(function(){

if(
mountToken!==
LIFE_MATERIAL_MODULE_MOUNT_TOKEN
){
return;
}

/*
 * Async initialization can finish AFTER the user has already opened
 * Monthly Indent, Consumable Request, or Advance Material Request.
 * Preserve that valid page. This is the race that previously caused
 * the form to jump back to the request-type Home screen after 1–2 s.
 */
var preserveAfterAsyncSync=
lifeMaterialRequestPageAllowedForMode(
moduleRoot,
normalized
);

lifePrepareMaterialRequestModuleView(
moduleRoot,
normalized,
preserveAfterAsyncSync
);

if(
!preserveAfterAsyncSync&&
window.LifeMaterialRequestModule&&
typeof window.LifeMaterialRequestModule.showPage==="function"
){
window.LifeMaterialRequestModule.showPage(
normalized==="ho"
?"ho-approval"
:"home"
);
}

if(normalized==="ho"){
window.setTimeout(function(){
if(
mountToken===
LIFE_MATERIAL_MODULE_MOUNT_TOKEN&&
window.lifeEnsureSRManagerPanel
){
window.lifeEnsureSRManagerPanel(0);
}
},0);
}

}).catch(function(error){

if(
mountToken!==
LIFE_MATERIAL_MODULE_MOUNT_TOKEN
){
return;
}

/*
 * Keep the correct page visible even if a background data request
 * fails. If the user is already inside a valid request form, preserve
 * that form rather than treating the failure as a reason to go Home.
 */
lifePrepareMaterialRequestModuleView(
moduleRoot,
normalized,
lifeMaterialRequestPageAllowedForMode(
moduleRoot,
normalized
)
);

moduleRoot.style.display="block";
moduleRoot.style.visibility="visible";
moduleRoot.style.pointerEvents="";

void 0;
});

return;
}

/*
 * If the embedded runtime has not been exported yet, keep the
 * already-correct page visible and retry runtime synchronization.
 */
window.setTimeout(function(){
if(
mountToken===
LIFE_MATERIAL_MODULE_MOUNT_TOKEN
){
mountMaterialRequestModule(
normalized,
mountToken
);
}
},40);
}
function showBranchMode(i) {
    i = parseInt(i, 10);

    if (isNaN(i)) {
        i = 0;
    }

    /*
     * Standalone Stock Request mode was removed.
     * Redirect any stale/direct request for mode 1 to Dashboard.
     */
    if (i === 1) {
        i = 0;
    }

    removeStandaloneBranchStockRequest();

    /*
     * Highlight by data-bmode instead of
     * navigation position.
     */
    $all(
        "#ls-branch-nav .mnav"
    ).forEach(function (node) {
        var nodeMode =
            parseInt(
                node.getAttribute(
                    "data-bmode"
                ),
                10
            );

        var isActive =
            nodeMode === i;

        node.classList.toggle(
            "on",
            isActive
        );

        node.setAttribute(
            "aria-current",
            isActive
                ? "page"
                : "false"
        );
    });

    /*
     * Display the page whose ID matches the mode.
     */
    $all(
        "#ls-branch-modes .mode"
    ).forEach(function (page) {
        var isActive =
            page.id ===
            "ls-bmode-" + i;

        page.classList.toggle(
            "on",
            isActive
        );

        page.hidden =
            !isActive;
    });

    if (i === 0) {
        renderBranchDash();
    } else if (i === 1) {
        renderBranchReqList();
    } else if (i === 2) {
        renderStockBalance();
    } else if (i === 3) {
        renderChecklist();
    } else if (i === 4) {
        renderBranchReports();
    } else if (i === 5) {
        renderBranchQueries();
    } else if (i === 6) {
        mountMaterialRequestModule(
            "branch"
        );
    }
}

function showHoMode(i) {
    i = parseInt(i, 10);

    if (isNaN(i)) {
        i = 0;
    }

    /*
     * Important:
     * Use data-hmode, not the navigation
     * element's array index.
     *
     * Queries mode 3 has been removed from
     * the navigation, so array indexes are
     * no longer equal to mode numbers.
     */
    $all(
        "#ls-ho-nav .mnav"
    ).forEach(function (node) {
        var nodeMode =
            parseInt(
                node.getAttribute(
                    "data-hmode"
                ),
                10
            );

        var isActive =
            nodeMode === i;

        node.classList.toggle(
            "on",
            isActive
        );

        node.setAttribute(
            "aria-current",
            isActive
                ? "page"
                : "false"
        );
    });

    /*
     * Display the correct mode using its ID.
     */
    $all(
        "#ls-ho-modes .mode"
    ).forEach(function (page) {
        var isActive =
            page.id ===
            "ls-hmode-" + i;

        page.classList.toggle(
            "on",
            isActive
        );

        page.hidden =
            !isActive;
    });

    if (i === 0) {
        renderHoDashboard();
    } else if (i === 1) {
        mountMaterialRequestModule(
            "ho"
        );
    } else if (i === 2) {
        renderHoReports();
    } else if (i === 3) {
        /*
         * Kept only for compatibility.
         * The Queries navigation tab is removed.
         */
        renderHoQueries();
    } else if (i === 4) {
        renderPurchaseOrder();
    } else if (i === 5) {
        renderPurchaseReceipt();
    } else if (i === 6) {
        renderPurchaseInvoice();
    } else if (i === 7) {
        renderSuppliers();
    } else if (i === 8) {
        /*
         * Stock & Asset Intelligence is intentionally lazy-loaded.
         * Initialising after the tab becomes visible ensures Chart.js
         * receives the correct canvas dimensions.
         */
        window.setTimeout(function () {
            if (
                window.LifeStockIntelligence &&
                typeof window.LifeStockIntelligence.init === "function"
            ) {
                window.LifeStockIntelligence.init();
            }
        }, 0);
    }
}

