var LIFE_STOCK_BALANCE_ROWS = [];
var LIFE_STOCK_BALANCE_SEARCH = "";
var LIFE_STOCK_BALANCE_EXPANDED = {};


function lifeStockBalanceMatches(
    row,
    searchText
) {
    if (!searchText) {
        return true;
    }

    var quantity =
        Number(row.actual_qty) || 0;

    var status =
        quantity <= 0
            ? "zero"
            : quantity <= 5
                ? "low"
                : "ok";

    var searchableText = [
        row.item_code,
        itemName(row.item_code),
        itemGroup(row.item_code),
        itemUom(row.item_code),
        row.warehouse,
        status
    ].join(" ").toLowerCase();

    return (
        searchableText.indexOf(
            searchText
        ) !== -1
    );
}


function lifeToggleStockCategory(
    encodedCategory
) {
    var category = "";

    try {
        category = decodeURIComponent(
            String(
                encodedCategory || ""
            )
        );
    } catch (error) {
        category =
            String(
                encodedCategory || ""
            );
    }

    if (!category) {
        return;
    }

    LIFE_STOCK_BALANCE_EXPANDED[
        category
    ] =
        !LIFE_STOCK_BALANCE_EXPANDED[
            category
        ];

    lifePaintStockBalance();
}


function lifeFilterStockBalance(value) {
    /*
     * Preserve the exact typed value, including spaces.
     * Normalization will be done only while filtering.
     */
    LIFE_STOCK_BALANCE_SEARCH =
        String(value || "");

    lifePaintStockBalance();
}


function lifePaintStockBalance() {
    var box =
        byId(
            "ls-balance-body-container"
        );

    if (!box) {
        return;
    }

    var rawSearchText =
    String(
        LIFE_STOCK_BALANCE_SEARCH || ""
    );

    var searchText =
        rawSearchText
            .trim()
            .toLowerCase();

    var filteredRows =
        LIFE_STOCK_BALANCE_ROWS.filter(
            function (row) {
                return lifeStockBalanceMatches(
                    row,
                    searchText
                );
            }
        );

    var groupedRows = {};

    filteredRows.forEach(
        function (row) {
            var category =
                itemGroup(
                    row.item_code
                ) ||
                "Uncategorised";

            if (!groupedRows[category]) {
                groupedRows[category] = [];
            }

            groupedRows[category].push(
                row
            );
        }
    );

    var categoriesHtml = "";

    Object.keys(groupedRows)
        .sort()
        .forEach(function (category) {
            var rows =
                groupedRows[category];

            var encodedCategory =
                encodeURIComponent(
                    category
                );

            /*
             * Categories remain closed by default.
             * Searching automatically opens matches.
             */
            var expanded =
                !!searchText ||
                !!LIFE_STOCK_BALANCE_EXPANDED[
                    category
                ];

            var rowsHtml =
                rows.map(function (row) {
                    var quantity =
                        Number(
                            row.actual_qty
                        ) || 0;

                    var statusHtml =
                        quantity <= 0
                            ? '<span class="pill p-r">Zero</span>'
                            : quantity <= 5
                                ? '<span class="pill p-o">Low</span>'
                                : '<span class="pill p-g">OK</span>';

                    return (
                        "<tr>" +

                            "<td>" +
                                esc(
                                    itemName(
                                        row.item_code
                                    )
                                ) +
                                '<div class="life-stock-item-code">' +
                                    esc(
                                        row.item_code
                                    ) +
                                "</div>" +
                            "</td>" +

                            '<td class="life-stock-small-text">' +
                                esc(
                                    String(
                                        row.warehouse ||
                                        ""
                                    ).replace(
                                        " - LSACPL",
                                        ""
                                    )
                                ) +
                            "</td>" +

                            "<td>" +
                                esc(
                                    itemUom(
                                        row.item_code
                                    )
                                ) +
                            "</td>" +

                            '<td style="text-align:right">' +
                                "<strong>" +
                                    quantity +
                                "</strong>" +
                            "</td>" +

                            "<td>" +
                                statusHtml +
                            "</td>" +

                        "</tr>"
                    );
                }).join("");

            categoriesHtml +=
                '<div class="life-stock-category">' +

                    '<button type="button" ' +
                        'class="life-stock-category__toggle" ' +
                        'data-stock-category="' +
                            esc(
                                encodedCategory
                            ) +
                        '" aria-expanded="' +
                            (
                                expanded
                                    ? "true"
                                    : "false"
                            ) +
                        '">' +

                        "<span>" +
                            "📦 " +
                            esc(category) +
                            " " +
                            "<small>(" +
                                rows.length +
                            ")</small>" +
                        "</span>" +

                        '<span class="life-stock-category__chevron">' +
                            (
                                expanded
                                    ? "▾"
                                    : "▸"
                            ) +
                        "</span>" +

                    "</button>" +

                    '<div class="life-stock-category__content"' +
                        (
                            expanded
                                ? ""
                                : " hidden"
                        ) +
                    ">" +

                        '<div class="tbl-wrap">' +
                            "<table>" +

                                "<thead>" +
                                    "<tr>" +
                                        "<th>Item</th>" +
                                        "<th>Warehouse</th>" +
                                        "<th>Unit</th>" +
                                        '<th style="text-align:right">On Hand</th>' +
                                        "<th>Status</th>" +
                                    "</tr>" +
                                "</thead>" +

                                "<tbody>" +
                                    rowsHtml +
                                "</tbody>" +

                            "</table>" +
                        "</div>" +

                    "</div>" +

                "</div>";
        });

    box.innerHTML =
        '<div class="card">' +

            '<div class="card-hdr life-list-header">' +

                "<span>" +
                    "📋 Stock Balance — " +
                    esc(
                        branchName(
                            currentView
                        )
                    ) +
                "</span>" +

                '<span class="badge">' +
                    filteredRows.length +
                    " / " +
                    LIFE_STOCK_BALANCE_ROWS.length +
                    " items" +
                "</span>" +

                '<span class="life-list-header__spacer"></span>' +

                '<input type="search" ' +
                    'id="ls-stock-balance-search" ' +
                    'class="life-tab-search" ' +
                    'placeholder="Search item, category, warehouse or status…" ' +
                    'value="' +
                        esc(
                            rawSearchText
                        ) +
                '">' +

            "</div>" +

            '<div class="card-body">' +

                (
                    categoriesHtml ||
                    '<div class="notice notice-blue">' +
                        (
                            LIFE_STOCK_BALANCE_ROWS.length
                                ? "No stock items match the search."
                                : "No stock records for this branch."
                        ) +
                    "</div>"
                ) +

            "</div>" +

        "</div>";

    var searchInput =
        byId(
            "ls-stock-balance-search"
        );

    if (searchInput) {
        searchInput.focus();

        var cursorPosition =
            searchInput.value.length;

        try {
            searchInput.setSelectionRange(
                cursorPosition,
                cursorPosition
            );
        } catch (cursorError) {
            /*
             * Some browsers may not support selection
             * handling for every input state.
             */
        }
    }
}

