function runApproval(doctype,name,action){
var msg=byId('ls-appr-msg');
if(msg)msg.innerHTML='<div class="notice notice-blue">⏳ Running "'+esc(action)+'"…</div>';
if(typeof frappe==='undefined'||!frappe.call){
if(msg)msg.innerHTML='<div class="notice notice-red">Workflow actions only work inside the portal desk.</div>';
return;
}
window.LifeStockGateway.compat({
method:'frappe.model.workflow.apply_workflow',args:{
doc:{
doctype:doctype,name:name}
,action:action}
,callback:function(r){
var newState=(r&&r.message&&(r.message.workflow_state||r.message.status))||action;
if(msg)msg.innerHTML='<div class="notice notice-green">✓ "'+esc(action)+'" done. New state: <strong>'+esc(newState)+'</strong></div>';
var bar=byId('ls-appr-actions');
if(bar)Array.prototype.forEach.call(bar.querySelectorAll('button[data-appr-do]'),function(b){
b.disabled=true;
}
);
SUPPLIER_PAY_CACHE=null;
setTimeout(function(){
closeViewModal();
if(currentView==='HO'){
renderPendingApprovalsSidebar();
}
}
,1300);
}
,error:function(e){
var m=(e&&(e.message||e._server_messages))||'Action failed. You may not have permission for this transition.';
if(msg)msg.innerHTML='<div class="notice notice-red">✕ '+esc(m)+'</div>';
}
}
);
}
