function onChecklistInput(key,value){
var st=CHECKLIST_STATE[key];
if(!st)return;
var raw=(value===null||value===undefined)?'':String(value);
var v=raw.trim()===''?null:Number(raw);
st.physical=(v===null||isNaN(v))?null:v;
var diffCell=document.querySelector('[data-chk-diff="'+cssEscape(key)+'"]');
if(!diffCell)return;
if(st.physical===null){diffCell.textContent='—';diffCell.style.color='';return;}
var diff=Number(st.physical)-(Number(st.system)||0);
diffCell.textContent=(diff>0?'+':'')+diff;
diffCell.style.color=diff===0?'#1E7A34':(diff<0?'#C00000':'#C96A00');
}
function cssEscape(s){return String(s).replace(/["\\\]]/g,'\\$&');}
function saveChecklist(){
if(LIFE_CHECKLIST_SUBMITTING)return;
var msg=byId('ls-chk-msg'),items=[];
if(!msg)return;
Object.keys(CHECKLIST_STATE).forEach(function(key){
var st=CHECKLIST_STATE[key];
if(st.physical!==null&&st.physical!==undefined&&!isNaN(st.physical)){
items.push({item_code:st.item_code,warehouse:st.warehouse,qty:Number(st.physical),valuation_rate:Number(st.valuation_rate)||0});
}
});
if(!items.length){msg.innerHTML='<div class="notice notice-red">Enter at least one physical count before submitting.</div>';return;}
var negative=items.find(function(x){return x.qty<0;});
if(negative){msg.innerHTML='<div class="notice notice-red">Physical quantity cannot be negative for '+esc(negative.item_code)+'.</div>';return;}
var missingRate=items.find(function(x){return x.qty>0&&x.valuation_rate<=0;});
if(missingRate){msg.innerHTML='<div class="notice notice-red">Valuation Rate is missing for '+esc(missingRate.item_code)+' in '+esc(missingRate.warehouse)+'. Set a valid valuation rate before submitting.</div>';return;}
var warehouses=items.map(function(x){return x.warehouse;}).filter(Boolean);
var wh=warehouses[0]||branchWh(currentView);
var currentUser=(window.frappe&&frappe.session&&frappe.session.user)||'';
var knownRequestNames={};
msg.innerHTML='<div class="notice notice-blue">⏳ Creating the Stock Reconciliation and sending it for approval…</div>';
lifeChecklistSetSubmitting(true);
var doc={doctype:'Stock Reconciliation',purpose:'Stock Reconciliation',company:'Life Slimming And Cosmetic Pvt Ltd',set_warehouse:wh,posting_date:isoToday(),items:items};
function completeSubmission(done){
var name=done&&done.name?done.name:'Stock Reconciliation';
var state=done&&done.workflow_state?done.workflow_state:'Pending Stock Manager Approval';
LIFE_CHECKLIST_LAST_SUBMISSION={name:name,workflow_state:state,item_count:items.length,submitted_at:new Date()};
lifeChecklistSetSubmitting(false);
lifeChecklistResetForm(true);
closeViewModal();
lifeChecklistRenderSubmissionResult();
lifeSRLoadList('branch');
showModal('✅','Physical Stock Request Submitted','Request '+name+' was submitted successfully. Status: '+state+'. Stock has not been adjusted.');
}
function matchingNewRequest(rows){
rows=Array.isArray(rows)?rows:[];
for(var index=0;index<rows.length;index+=1){
var row=rows[index]||{};
var name=String(row.name||'').trim();
var owner=String(row.owner||'').trim();
var warehouse=String(row.set_warehouse||'').trim();
var state=lifeSREffectiveState(row);
if(!name||knownRequestNames[name])continue;
if(currentUser&&owner&&owner!==currentUser)continue;
if(wh&&warehouse&&warehouse!==wh)continue;
if(state!=='Pending Stock Manager Approval')continue;
return row;
}
return null;
}
lifeSRGetList('branch',500).catch(function(){return[];}).then(function(existingRows){
(Array.isArray(existingRows)?existingRows:[]).forEach(function(row){if(row&&row.name)knownRequestNames[String(row.name)]=true;});
return lifeSRAction('create_stock_reconciliation_request',{doc:doc}).then(function(result){return result&&result.doc?result.doc:null;}).catch(function(error){
var message=error&&error.message?String(error.message):String(error||'');
if(message.indexOf('The LIFE Stock API returned an invalid response')===-1)throw error;
return lifeSRGetList('branch',500).then(function(rows){
var recovered=matchingNewRequest(rows);
if(!recovered)throw error;
void 0;
return recovered;
});
});
}).then(function(done){
if(!done||!done.name)throw new Error('The request could not be confirmed after submission. Refresh the request history before trying again.');
completeSubmission(done);
}).catch(function(error){
lifeChecklistSetSubmitting(false);
msg.innerHTML='<div class="notice notice-red">✕ Submission failed. '+esc(error&&error.message?error.message:String(error))+'</div>';
});
}

