var backButton=overlay.querySelector('.life-sr-action-confirm-back');

if(iconNode)iconNode.textContent=meta.icon;
if(titleNode)titleNode.textContent=meta.title;
if(subtitleNode)subtitleNode.textContent=meta.subtitle;
if(messageNode)messageNode.textContent=meta.message;
if(nameNode)nameNode.textContent=name;
if(warningNode)warningNode.innerHTML='<strong>Result:</strong> '+esc(meta.warning);

if(confirmButton){
confirmButton.disabled=false;
confirmButton.textContent=meta.confirm_label;
confirmButton.onclick=function(event){
event.preventDefault();
event.stopPropagation();
if(confirmButton.disabled||LIFE_SR_ACTION_RUNNING)return;
confirmButton.disabled=true;
if(backButton)backButton.disabled=true;
confirmButton.textContent='⏳ Please wait…';
lifeSRCloseActionConfirmation();
lifeSRApplyAction(name,action);
};
}
if(backButton)backButton.disabled=false;

LIFE_SR_ACTION_CONFIRM_OPEN=true;
overlay.classList.add('is-open');
overlay.setAttribute('aria-hidden','false');

window.setTimeout(function(){
if(confirmButton)confirmButton.focus();
},0);

return false;
}

