function lifeSRValidateActionResult(doc,meta){
if(!doc)throw new Error('ERPNext did not return the updated Stock Reconciliation.');

var actualState=lifeSREffectiveState(doc);
var actualDocstatus=Number(doc.docstatus);

if(meta.expected_state&&actualState!==meta.expected_state){
throw new Error(
'ERPNext returned workflow state "'+actualState+
'" instead of the expected "'+meta.expected_state+'".'
);
}

if(meta.expected_docstatus!==null&&actualDocstatus!==Number(meta.expected_docstatus)){
throw new Error(
'ERPNext returned document status '+actualDocstatus+
' instead of the expected '+meta.expected_docstatus+'.'
);
}

return doc;
}

