function lifeSRApplyAction(name,action){
name=String(name||'').trim();
action=String(action||'').trim();

if(!name||!action)return Promise.reject(new Error('Stock Reconciliation action is incomplete.'));
if(LIFE_SR_ACTION_RUNNING)return Promise.reject(new Error('Another Stock Reconciliation action is already running.'));

var meta=lifeSRActionMeta(action,name);
var msg=byId('life-sr-action-msg');
var overlay=document.getElementById('life-sr-dedicated-modal');
var buttons=overlay?Array.prototype.slice.call(overlay.querySelectorAll('[data-sr-modal-action]')):[];
var closeButtons=overlay?Array.prototype.slice.call(overlay.querySelectorAll('.life-sr-dedicated-close,.life-sr-actions .btn-gy')):[];

LIFE_SR_ACTION_RUNNING=true;
buttons.forEach(function(button){button.disabled=true;});
closeButtons.forEach(function(button){button.disabled=true;});

if(msg){
msg.innerHTML='<div class="notice notice-blue">⏳ <strong>'+esc(meta.progress)+'</strong><br>Please keep this window open until ERPNext confirms the final status.</div>';
}

return lifeSRAction('apply_stock_reconciliation_workflow',{
name:name,
workflow_action:action
}).then(function(result){
if(result&&result.doc)return result.doc;
return lifeSRGetDoc(name);
}).then(function(updated){
return lifeSRValidateActionResult(updated,meta);
}).then(function(updated){
LIFE_SR_MANAGER_LAST_ACTION={
name:updated.name||name,
state:lifeSREffectiveState(updated),
title:meta.success_title,
list_message:meta.moved_text,
completed_at:new Date().toISOString()
};

return Promise.all([
lifeSRLoadList('manager'),
lifeSRLoadList('branch')
]).then(function(){
lifeSRRenderManagerActionResult();
lifeSRRenderActionSuccess(updated,action);
return updated;
});
}).catch(function(error){
buttons.forEach(function(button){button.disabled=false;});
closeButtons.forEach(function(button){button.disabled=false;});

var message=error&&error.message?error.message:String(error);
if(msg){
msg.innerHTML=
'<div class="notice notice-red">'+
'<strong>✕ '+esc(action)+' was not confirmed as completed.</strong><br>'+
esc(message)+
'<br>The request has not been removed from the current list. Refresh and review its latest state before trying again.'+
'</div>';
}

lifeSRLoadList('manager');
lifeSRLoadList('branch');
throw error;
}).finally(function(){
LIFE_SR_ACTION_RUNNING=false;
});
}

var LIFE_BRANCH_REPORT_ROWS = [];
var LIFE_BRANCH_REPORT_SEARCH = "";


function lifeFilterBranchReports(value) {
