function lifePaintBranchReportRows() {
    var tbody =
        byId(
            "ls-branch-report-tbody"
        );

    var count =
        byId(
            "ls-branch-report-count"
        );

    if (!tbody) {
        return;
    }

    var filteredRows =
        LIFE_BRANCH_REPORT_ROWS.filter(
            function (row) {
                if (
                    !LIFE_BRANCH_REPORT_SEARCH
                ) {
                    return true;
                }

                var searchableText = [
                    row.item_code,
                    itemName(row.item_code),
                    row.posting_date,
                    row.voucher_type,
                    row.voucher_no,
                    row.actual_qty,
                    row.qty_after_transaction
                ].join(" ").toLowerCase();

                return (
                    searchableText.indexOf(
                        LIFE_BRANCH_REPORT_SEARCH
                    ) !== -1
                );
            }
        );

    if (count) {
        count.textContent =
            filteredRows.length +
            " / " +
            LIFE_BRANCH_REPORT_ROWS.length;
    }

    if (!filteredRows.length) {
        tbody.innerHTML =
            '<tr>' +
                '<td colspan="5" ' +
                    'style="text-align:center;padding:18px;color:#8C8C8C">' +
                    "No stock movements match the search." +
                "</td>" +
            "</tr>";

        return;
    }

    tbody.innerHTML =
        filteredRows.map(
            function (row) {
                var change =
                    Number(
                        row.actual_qty
                    ) || 0;

                return (
                    "<tr>" +

                        "<td>" +
                            displayDate(
                                row.posting_date
                            ) +
                        "</td>" +

                        "<td>" +
                            esc(
                                itemName(
                                    row.item_code
                                )
                            ) +
                            '<div class="life-stock-item-code">' +
                                esc(
                                    row.item_code
                                ) +
                            "</div>" +
                        "</td>" +

                        '<td style="text-align:right;color:' +
                            (
                                change < 0
                                    ? "#C00000"
                                    : "#1E7A34"
                            ) +
                            ';font-weight:700">' +
                            (
                                change > 0
                                    ? "+"
                                    : ""
                            ) +
                            change +
                        "</td>" +

                        '<td style="text-align:right">' +
                            (
                                Number(
                                    row.qty_after_transaction
                                ) || 0
                            ) +
                        "</td>" +

                        '<td style="font-size:10px">' +
                            esc(
                                row.voucher_type
                            ) +
                            "<br>" +
                            esc(
                                row.voucher_no
                            ) +
                        "</td>" +

                    "</tr>"
                );
            }
        ).join("");
}

