function normalizeSortValue(value){
if(value===null||value===undefined){
return"";
}
if(typeof value==="number"&&isFinite(value)){
return value;
}
var numberValue=Number(value);
if(value!==""&&isFinite(numberValue)&&String(value).trim()!==""){
return numberValue;
}
return String(value).toLowerCase().trim();
}

function compareValues(leftValue,rightValue){
var left=normalizeSortValue(leftValue);
var right=normalizeSortValue(rightValue);
var leftIsNumber=typeof left==="number";
var rightIsNumber=typeof right==="number";
if(leftIsNumber&&rightIsNumber){
return left-right;
}
if(leftIsNumber&&!rightIsNumber){
return-1;
}
if(!leftIsNumber&&rightIsNumber){
return 1;
}
return String(left).localeCompare(String(right),undefined,{numeric:true,sensitivity:"base"});
}

function applyCurrentSort(){
if(!currentSortKey||typeof sorters[currentSortKey]!=="function"){
return;
}
var sorter=sorters[currentSortKey];
var direction=currentSortDir==="desc"?-1:1;
filteredRows=filteredRows.map(function(row,index){
return{row:row,index:index};
}).sort(function(a,b){
var result=compareValues(sorter(a.row),sorter(b.row));
if(result===0){
result=a.index-b.index;
}
return result*direction;
}).map(function(entry){
return entry.row;
});
}

function updateSortHeaders(){
