function renderChunk(reset){
if(reset){
tbody.innerHTML="";
shown=0;
}
var oldSentinel=tbody.querySelector('tr[data-sentinel="1"]');
if(oldSentinel&&oldSentinel.parentNode){
oldSentinel.parentNode.removeChild(oldSentinel);
}
if(!filteredRows.length){
showEmptyMessage();
return;
}
var next=filteredRows.slice(shown,shown+pageSize);
if(next.length){
tbody.insertAdjacentHTML("beforeend",next.map(rowHtmlFn).join(""));
shown+=next.length;
}
updateCount();
if(shown<filteredRows.length){
tbody.insertAdjacentHTML(
"beforeend",
'<tr data-sentinel="1"><td colspan="'+String(columnCount)+'" style="text-align:center;color:#8C8C8C;padding:10px;cursor:pointer" class="ls-load-more">▼ Load more ('+String(shown)+' / '+String(filteredRows.length)+')</td></tr>'
);
}
}

function applySearch(){
currentQuery=lifeNormalizeHoCardModalSearch(input.value);
if(clearButton){
clearButton.hidden=!currentQuery;
}
filteredRows=currentQuery?allRows.filter(function(row){
return lifeNormalizeHoCardModalSearch(searchTextFn(row)).indexOf(currentQuery)!==-1;
}
):allRows.slice();
applyCurrentSort();
updatePdfRows();
renderChunk(true);
updateSortHeaders();
if(tableWrap){
tableWrap.scrollTop=0;
}
}

function applySort(key){
if(!key||typeof sorters[key]!=="function"){
return;
}
if(currentSortKey===key){
currentSortDir=currentSortDir==="asc"?"desc":"asc";
}
else{
currentSortKey=key;
currentSortDir="asc";
}
applySearch();
}

sortHeaders.forEach(function(header){
var key=header.getAttribute("data-sort-key")||"";
if(!key||typeof sorters[key]!=="function"){
return;
}
header.classList.add("life-ho-card-sortable");
header.setAttribute("tabindex","0");
header.setAttribute("role","button");
header.setAttribute("title","Sort by "+String(sortLabels[key]||header.textContent||key));
header.addEventListener("click",function(){
applySort(key);
});
header.addEventListener("keydown",function(event){
if(event.key==="Enter"||event.key===" "){
event.preventDefault();
applySort(key);
}
});
});

input.addEventListener("input",applySearch);
input.addEventListener("search",applySearch);
input.addEventListener("keydown",function(event){
if(event.key==="Escape"){
input.value="";
applySearch();
input.focus();
}
}
);
if(clearButton){
clearButton.addEventListener("click",function(){
input.value="";
applySearch();
input.focus();
}
);
}
