function lifeDirectChildUnder(ancestor, node) {
    if (!ancestor || !node) {
        return null;
    }

    var current = node;

    while (
        current &&
        current.parentElement &&
        current.parentElement !== ancestor
    ) {
        current = current.parentElement;
    }

    return current && current.parentElement === ancestor
        ? current
        : null;
}

function lifeFindDashboardCard(node) {
    if (!node) {
        return null;
    }

    var exactCard = node.closest
        ? node.closest(".card")
        : null;

    if (exactCard) {
        return exactCard;
    }

    var current = node;
    var steps = 0;

    while (
        current &&
        current !== ROOT &&
        steps < 8
    ) {
        var className = String(
            current.className || ""
        );

        if (
            /(^|\\s)(?:ho-[^\\s]*card|sidebar-card|filter-card|master-filter)(?:\\s|$)/i.test(
                className
            )
        ) {
            return current;
        }

        current = current.parentElement;
        steps += 1;
    }

    return node.parentElement &&
        node.parentElement.parentElement
        ? node.parentElement.parentElement
        : node.parentElement;
}

function lifeFindHoDashboardGrid(
    masterCard,
    mainNode,
    zeroCard,
    highestCard
) {
    var current = mainNode;

    while (current && current !== ROOT) {
        if (
            current.contains(masterCard) &&
            current.contains(zeroCard) &&
            current.contains(highestCard)
        ) {
            var directChildren = [
                lifeDirectChildUnder(current, masterCard),
                lifeDirectChildUnder(current, mainNode),
                lifeDirectChildUnder(current, zeroCard),
                lifeDirectChildUnder(current, highestCard)
            ].filter(Boolean);
            var uniqueChildren = [];

            directChildren.forEach(function (child) {
                if (uniqueChildren.indexOf(child) === -1) {
                    uniqueChildren.push(child);
                }
            });

            if (uniqueChildren.length >= 3) {
                return current;
            }
        }

        current = current.parentElement;
    }

    return null;
}

