function lifeArrangeHoDashboardSidebar() {
    lifeInstallHoDashboardSidebarStyles();

    var masterSelect = byId("ls-ho-master-branch");
    var zeroContent = byId("ls-ho-sb-deadstock");
    var highestContent = byId("ls-ho-sb-excess");
    var mainNode = byId("ls-ho-branch-detail-container");

    if (
        !masterSelect ||
        !zeroContent ||
        !highestContent ||
        !mainNode
    ) {
        return;
    }

    var masterCard = lifeFindDashboardCard(masterSelect);
    var zeroCard = lifeFindDashboardCard(zeroContent);
    var highestCard = lifeFindDashboardCard(highestContent);

    if (
        !masterCard ||
        !zeroCard ||
        !highestCard
    ) {
        return;
    }

    masterCard.classList.add(
        "life-ho-dashboard-master-card"
    );
    zeroCard.classList.add(
        "life-ho-dashboard-sidebar-card"
    );
    highestCard.classList.add(
        "life-ho-dashboard-sidebar-card"
    );

    var detailCard = lifeFindDashboardCard(mainNode);
    if (detailCard) {
        detailCard.classList.add(
            "life-ho-dashboard-detail-card"
        );
    }

    var existingStack = byId(
        "life-ho-dashboard-sidebar-stack"
    );

    if (existingStack) {
        [masterCard, zeroCard, highestCard].forEach(
            function (card) {
                if (card.parentElement !== existingStack) {
                    existingStack.appendChild(card);
                }
            }
        );

        var existingGrid = existingStack.parentElement;
        if (existingGrid) {
            existingGrid.classList.add(
                "life-ho-dashboard-two-column"
            );

            var existingMainColumn =
                lifeDirectChildUnder(
                    existingGrid,
                    mainNode
                );

            if (existingMainColumn) {
                existingMainColumn.classList.add(
                    "life-ho-dashboard-main-column"
                );
            }
        }
        return;
    }

    var dashboardGrid = lifeFindHoDashboardGrid(
        masterCard,
        mainNode,
        zeroCard,
        highestCard
    );

    if (!dashboardGrid) {
        return;
    }

    var masterColumn = lifeDirectChildUnder(
        dashboardGrid,
        masterCard
    );
    var mainColumn = lifeDirectChildUnder(
        dashboardGrid,
        mainNode
    );
    var zeroColumn = lifeDirectChildUnder(
        dashboardGrid,
        zeroCard
    );
    var highestColumn = lifeDirectChildUnder(
        dashboardGrid,
        highestCard
    );

    if (!mainColumn) {
        return;
    }

    var stack = document.createElement("aside");
    stack.id = "life-ho-dashboard-sidebar-stack";
    stack.className = "life-ho-dashboard-sidebar-stack";

    dashboardGrid.insertBefore(
        stack,
        mainColumn
    );

    [masterCard, zeroCard, highestCard].forEach(
        function (card) {
            stack.appendChild(card);
        }
    );

    [masterColumn, zeroColumn, highestColumn].forEach(
        function (oldColumn) {
            if (
                oldColumn &&
                oldColumn !== mainColumn &&
                oldColumn !== stack &&
                !oldColumn.contains(masterCard) &&
                !oldColumn.contains(zeroCard) &&
                !oldColumn.contains(highestCard)
            ) {
                oldColumn.classList.add(
                    "life-ho-dashboard-old-column-empty"
                );
            }
        }
    );

    dashboardGrid.classList.add(
        "life-ho-dashboard-two-column"
    );
    mainColumn.classList.add(
        "life-ho-dashboard-main-column"
    );
}

