function paintReport(content,title,headers,rows,rowFn,sorters,sortIndex,sortDir){
sorters=Array.isArray(sorters)?sorters:[];
sortIndex=Number.isInteger(sortIndex)?sortIndex:-1;
sortDir=sortDir==='desc'?'desc':'asc';
var workingRows=Array.isArray(rows)?rows.slice():[];
function reportCompareValues(a,b){
if(a===null||a===undefined)a='';
if(b===null||b===undefined)b='';
if(typeof a==='number'&&typeof b==='number'){
return a-b;
}
return String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'});
}
if(sortIndex>=0&&typeof sorters[sortIndex]==='function'){
var getter=sorters[sortIndex];
var direction=sortDir==='desc'?-1:1;
workingRows=workingRows.map(function(row,index){return{row:row,index:index};}).sort(function(a,b){
var result=reportCompareValues(getter(a.row),getter(b.row));
return result===0?a.index-b.index:result*direction;
}).map(function(entry){return entry.row;});
}
var headerHtml=headers.map(function(h,index){
if(typeof sorters[index]!=='function'){
return'<th>'+esc(h)+'</th>';
}
var active=index===sortIndex;
var icon=active?(sortDir==='desc'?'↓':'↑'):'⇅';
var titleText=active?('Sorted '+(sortDir==='desc'?'descending':'ascending')+'. Click to reverse.'):'Click to sort by '+String(h)+'.';
return'<th class="life-report-sortable '+(active?'is-sorted':'')+'" data-report-sort-index="'+index+'" title="'+esc(titleText)+'" aria-sort="'+(active?(sortDir==='desc'?'descending':'ascending'):'none')+'">'+esc(h)+' <span class="life-report-sort-icon">'+icon+'</span></th>';
}).join('');
content.innerHTML='<div class="sec" style="margin-top:0">'+esc(title)+' <span style="font-weight:400;color:#8C8C8C" id="ls-rep-count">0 / '+workingRows.length+'</span></div>'+'<div class="tbl-wrap"><table><thead><tr>'+headerHtml+'</tr></thead><tbody id="ls-rep-tbody"></tbody></table></div>'+'<div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid #e0e5ee;padding-top:10px">'+'<button class="btn btn-gy btn-sm" id="ls-rep-csv">📊 Download CSV</button>'+'<button class="btn btn-gy btn-sm" id="ls-rep-print">🖨️ Print</button>'+'</div>';
var tbody=byId('ls-rep-tbody');
var countEl=byId('ls-rep-count');
if(!document.getElementById('life-report-sort-styles')){
var reportSortStyle=document.createElement('style');
reportSortStyle.id='life-report-sort-styles';
reportSortStyle.textContent='#life-stock-root th.life-report-sortable{cursor:pointer;user-select:none;white-space:nowrap;transition:background .12s ease,color .12s ease;}#life-stock-root th.life-report-sortable:hover{background:#E8F4EA!important;color:#135A25!important;}#life-stock-root th.life-report-sortable.is-sorted{background:#DDF0E1!important;color:#0F5D25!important;}#life-stock-root .life-report-sort-icon{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;margin-left:5px;padding:0 4px;border:1px solid #AFCFB6;border-radius:5px;background:#F7FBF8;color:#3D7450;font-size:11px;font-weight:800;line-height:1;vertical-align:middle;}#life-stock-root th.life-report-sortable.is-sorted .life-report-sort-icon{background:#1E7A34;border-color:#1E7A34;color:#fff;}';
(document.head||document.documentElement).appendChild(reportSortStyle);
}
if(!workingRows.length){
tbody.innerHTML='<tr><td colspan="'+headers.length+'" style="text-align:center;color:#8C8C8C;padding:16px">No records found.</td></tr>';
return;
}
attachPagination(workingRows,tbody,rowFn,10,countEl);
Array.prototype.forEach.call(content.querySelectorAll('th[data-report-sort-index]'),function(header){
header.addEventListener('click',function(){
var index=Number(header.getAttribute('data-report-sort-index'));
var nextDir=index===sortIndex?(sortDir==='asc'?'desc':'asc'):'asc';
paintReport(content,title,headers,rows,rowFn,sorters,index,nextDir);
});
header.setAttribute('tabindex','0');
header.setAttribute('role','button');
header.addEventListener('keydown',function(event){
if(event.key==='Enter'||event.key===' '){
event.preventDefault();
header.click();
}
});
});
byId('ls-rep-csv').addEventListener('click',function(){
downloadCsv(title,headers,workingRows,rowFn);
}
);
byId('ls-rep-print').addEventListener('click',function(){
window.print();
}
);
}
function downloadCsv(title,headers,rows,rowFn){
var tmp=document.createElement('tbody');
tmp.innerHTML=rows.map(rowFn).join('');
var lines=[headers.join(',')];
Array.prototype.forEach.call(tmp.querySelectorAll('tr'),function(tr){
var cells=Array.prototype.map.call(tr.querySelectorAll('td'),function(td){
var txt=(td.textContent||'').replace(/\s+/g,' ').trim().replace(/"/g,'""');
return'"'+txt+'"';
}
);
lines.push(cells.join(','));
}
);
var blob=new Blob([lines.join('\n')],{
type:'text/csv;charset=utf-8;'}
);
var url=URL.createObjectURL(blob);
var a=document.createElement('a');
a.href=url;
a.download=title.replace(/[^\w]+/g,'_')+'_'+isoToday()+'.csv';
document.body.appendChild(a);
a.click();
document.body.removeChild(a);
URL.revokeObjectURL(url);
}
