async function lifeSendPurchaseOrderForApproval(name) {
    if (LIFE_PURCHASE_ORDER_ACTION_BUSY) {
        return;
    }

    var orderName =
        String(
            name || ""
        ).trim();

    if (!orderName) {
        return;
    }

    if (
        !window.confirm(
            "Send Purchase Order " +
            orderName +
            " for approval?"
        )
    ) {
        return;
    }

    LIFE_PURCHASE_ORDER_ACTION_BUSY =
        true;

    lifePurchaseOrderActionButtonsDisabled(
        true
    );

    lifePurchaseOrderActionStatus(
        "Sending Purchase Order for approval…",
        "loading"
    );

    try {
        /*
         * Always fetch the latest Purchase Order first.
         * We never set workflow_state manually.
         */
        var orderDoc =
            await callGet(
                "Purchase Order",
                orderName
            );

        if (!orderDoc) {
            throw new Error(
                "Purchase Order could not be loaded."
            );
        }

        if (
            Number(
                orderDoc.docstatus
            ) !== 0
        ) {
            throw new Error(
                "Only a Draft Purchase Order can be sent for approval."
            );
        }

        var currentWorkflowState =
            String(
                orderDoc.workflow_state ||
                "Draft"
            ).trim();

        if (
            currentWorkflowState
                .toLowerCase() !==
            "draft"
        ) {
            throw new Error(
                "This Purchase Order is already in workflow state: " +
                currentWorkflowState +
                "."
            );
        }

        /*
         * Ask ERPNext which workflow actions are actually
         * available for this exact Purchase Order and user.
         */
        var transitions =
            await lifePurchaseInvoiceServerCall(
                "frappe.model.workflow.get_transitions",
                {
                    doc:
                        orderDoc
                }
            );

        transitions =
            Array.isArray(
                transitions
            )
                ? transitions
                : [];

        var sendTransition =
            transitions.find(
                function (transition) {
                    return (
                        String(
                            transition &&
                            transition.action ||
                            ""
                        )
                            .trim()
                            .toLowerCase() ===
                        "send for approval"
                    );
                }
            );

        if (!sendTransition) {
            throw new Error(
                'The "Send for Approval" workflow action is not available for this Purchase Order or your current ERPNext role.'
            );
        }

        /*
         * Use ERPNext's real workflow action:
         *
         * Draft
         *   -> Send for Approval
         *   -> Pending Ops Approval
         */
        await lifePurchaseInvoiceServerCall(
            "frappe.model.workflow.apply_workflow",
            {
                doc:
                    orderDoc,

                action:
                    "Send for Approval"
            }
        );

        /*
         * Re-fetch so the dashboard displays the state ERPNext
         * actually assigned.
         */
        var freshOrder =
            await callGet(
                "Purchase Order",
                orderName
            );

        if (!freshOrder) {
            throw new Error(
                "Purchase Order was sent for approval, but the updated workflow state could not be refreshed."
            );
        }

        var freshWorkflowState =
            String(
                freshOrder.workflow_state ||
                freshOrder.status ||
                ""
            ).trim();

        lifePurchaseOrderActionStatus(
            "✓ Sent for approval. Workflow State: " +
            freshWorkflowState +
            ".",
            "success"
        );

        if (
            typeof toast ===
            "function"
        ) {
            toast(
                "Purchase Order " +
                orderName +
                " → " +
                freshWorkflowState,
                "g"
            );
        }

        if (
            typeof renderPurchaseOrder ===
            "function"
        ) {
            renderPurchaseOrder();
        }

        /*
         * Re-open the same Purchase Order so the new workflow
         * state is visible immediately.
         */
        window.setTimeout(
            function () {
                openPoDetail(
                    orderName
                );
            },
            120
        );
    }
    catch (error) {
        lifePurchaseOrderActionStatus(
            "✕ " +
            lifePurchaseInvoiceErrorMessage(
                error
            ),
            "error"
        );

        lifePurchaseOrderActionButtonsDisabled(
            false
        );
    }
    finally {
        LIFE_PURCHASE_ORDER_ACTION_BUSY =
            false;
    }
}

async function lifeSubmitPurchaseOrder(name) {
    if (LIFE_PURCHASE_ORDER_ACTION_BUSY) return;

    var orderName = String(name || "").trim();
    if (!orderName) return;

    if (!window.confirm("Submit Purchase Order " + orderName + "?")) return;

    LIFE_PURCHASE_ORDER_ACTION_BUSY = true;
    lifePurchaseOrderActionButtonsDisabled(true);
    lifePurchaseOrderActionStatus("Submitting Purchase Order…", "loading");

    try {
        var orderDoc = await callGet("Purchase Order", orderName);

        if (!orderDoc) {
            throw new Error("Purchase Order could not be loaded.");
        }

        if (Number(orderDoc.docstatus) !== 0) {
            throw new Error("Only a Draft Purchase Order can be submitted.");
        }

        var submittedDoc = await lifePurchaseInvoiceServerCall(
            "frappe.client.submit",
            { doc: orderDoc }
        );

        var submittedName = submittedDoc && submittedDoc.name
            ? submittedDoc.name
            : orderName;

        lifePurchaseOrderActionStatus(
            "✓ Purchase Order submitted successfully.",
            "success"
        );

        if (typeof toast === "function") {
            toast("Purchase Order " + submittedName + " submitted.", "g");
        }

        renderPurchaseOrder();

        window.setTimeout(function () {
            openPoDetail(submittedName);
        }, 350);
    } catch (error) {
        lifePurchaseOrderActionStatus(
            "✕ " + lifePurchaseInvoiceErrorMessage(error),
            "error"
        );
        lifePurchaseOrderActionButtonsDisabled(false);
    } finally {
        LIFE_PURCHASE_ORDER_ACTION_BUSY = false;
    }
}

async function lifeCancelPurchaseOrder(name) {
    if (LIFE_PURCHASE_ORDER_ACTION_BUSY) return;

    var orderName = String(name || "").trim();
    if (!orderName) return;

    if (!window.confirm(
        "Cancel submitted Purchase Order " + orderName +
        "? This will run ERPNext linked-document and purchasing validations."
    )) return;

    LIFE_PURCHASE_ORDER_ACTION_BUSY = true;
    lifePurchaseOrderActionButtonsDisabled(true);
    lifePurchaseOrderActionStatus("Cancelling Purchase Order…", "loading");

    try {
        var orderDoc = await callGet("Purchase Order", orderName);

        if (!orderDoc) {
            throw new Error("Purchase Order could not be loaded.");
        }

        if (Number(orderDoc.docstatus) !== 1) {
            throw new Error("Only a Submitted Purchase Order can be cancelled.");
        }

        await lifePurchaseInvoiceServerCall(
            "frappe.client.cancel",
            { doctype: "Purchase Order", name: orderName }
        );

        lifePurchaseOrderActionStatus(
            "✓ Purchase Order cancelled successfully.",
            "success"
        );

        if (typeof toast === "function") {
            toast("Purchase Order " + orderName + " cancelled.", "g");
        }

        renderPurchaseOrder();

        window.setTimeout(function () {
            openPoDetail(orderName);
        }, 350);
    } catch (error) {
        lifePurchaseOrderActionStatus(
            "✕ " + lifePurchaseInvoiceErrorMessage(error),
            "error"
        );
        lifePurchaseOrderActionButtonsDisabled(false);
    } finally {
        LIFE_PURCHASE_ORDER_ACTION_BUSY = false;
    }
}


async function lifeApprovePurchaseOrder(name, action) {
 if (LIFE_PURCHASE_ORDER_ACTION_BUSY) return;
 if (!window.confirm(action + " Purchase Order " + name + "?")) { lifePurchaseOrderActionStatus("Action canceled. Purchase Order unchanged.", "success"); return; }
 LIFE_PURCHASE_ORDER_ACTION_BUSY = true;
 lifePurchaseOrderActionButtonsDisabled(true);
 lifePurchaseOrderActionStatus("Processing approval…", "loading");
 try {
