  var transitions = await lifePurchaseInvoiceServerCall("frappe.model.workflow.get_transitions", {doc:doc});
  if (!Array.isArray(transitions) || !transitions.some(function(t){return t.action === action;})) throw new Error("This approval is no longer available for your role or the current order state.");
  var result = await lifePurchaseInvoiceServerCall("frappe.model.workflow.apply_workflow", {doc:doc,action:action});
  var state = result && result.workflow_state || "Updated";
  lifePurchaseOrderActionStatus("✓ Successfully approved. Status: " + state, "success");
