 finally { LIFE_PURCHASE_ORDER_ACTION_BUSY = false; }
}

function lifeBuildPurchaseOrderActions(doc) {
    var docstatus =
        Number(
            doc &&
            doc.docstatus
        );

    var name =
        String(
            doc &&
            doc.name ||
            ""
        ).trim();

    var workflowState =
        String(
            doc &&
            doc.workflow_state ||
            (
                docstatus === 0
                    ? "Draft"
                    : ""
            )
        ).trim();

    var workflowKey =
        workflowState
            .toLowerCase();

    var statusKey =
        String(
            doc &&
            doc.status ||
            ""
        )
            .trim()
            .toLowerCase();

    var perBilled =
        Number(
            doc &&
            doc.per_billed ||
            0
        );

    var isOpen =
        statusKey !== "cancelled" &&
        statusKey !== "closed" &&
        statusKey !== "completed";

    /*
     * Invoice creation stays restricted to an actual submitted,
     * Approved and still-billable Purchase Order.
     */
    var canCreatePurchaseInvoice =
        docstatus === 1 &&
        workflowKey === "approved" &&
        isOpen &&
        perBilled < 100;

    /*
     * Send for Approval is shown only while the PO is still
     * Draft in ERPNext's workflow.
     */
    var canSendForApproval =
        docstatus === 0 &&
        workflowKey === "draft";

    var actionButtons = [];
    (doc.__lifeApprovalTransitions || []).forEach(function(t) { actionButtons.push('<button type="button" class="btn btn-g btn-sm" data-po-action="approve" data-po-name="' + esc(name) + '" data-po-workflow-action="' + esc(t.action) + '">✓ ' + esc(t.action) + '</button>'); });

    if (docstatus !== 2) {
        actionButtons.push(
            '<button type="button" class="btn btn-gold btn-sm" ' +
                'data-po-action="print" data-po-name="' +
                    esc(name) +
                '">' +
                '🖨 View / Print Purchase Order' +
            '</button>'
        );
    }

    if (canSendForApproval) {
        actionButtons.push(
            '<button type="button" class="btn btn-g btn-sm" ' +
                'data-po-action="send-for-approval" data-po-name="' +
                    esc(name) +
                '">' +
                '📨 Send for Approval' +
            '</button>'
        );
    }

    /*
     * Once the workflow reaches Approved, ERPNext has submitted
     * the PO (docstatus = 1). Only then expose cancellation and
     * Purchase Invoice creation.
     */
    if (docstatus === 1) {
        actionButtons.push(
            '<button type="button" class="btn btn-r btn-sm" ' +
                'data-po-action="cancel" data-po-name="' +
                    esc(name) +
                '">' +
                '✕ Cancel Purchase Order' +
            '</button>'
        );

        if (
            canCreatePurchaseInvoice
        ) {
            actionButtons.push(
                '<button type="button" class="btn btn-g btn-sm" ' +
                    'data-po-action="create-invoice" data-po-name="' +
                        esc(name) +
                    '">' +
                    '🧾 Create Purchase Invoice' +
                '</button>'
            );
        }
    }

    return (
        '<div id="life-po-action-status" ' +
            'role="status" aria-live="polite" style="display:none;margin-top:14px;padding:9px 12px;border-left:3px solid #B8860B;border-radius:6px;font-size:12px;font-weight:700"></div>' +

        '<div class="btn-row" ' +
            'style="display:flex;justify-content:center;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px">' +
            actionButtons.join("") +
        '</div>'
    );
}
