var LIFE_PURCHASE_RECEIPT_ACTION_BUSY = false;

/*
 * Prevent duplicate Purchase Invoice workflow actions while a
 * Send for Approval request is running.
 */
var LIFE_PURCHASE_INVOICE_ACTION_BUSY = false;

function lifePurchaseReceiptState(doc) {
    var docstatus = Number(doc && doc.docstatus);

    if (docstatus === 2) {
        return { label: "Cancelled", cssClass: "p-r" };
    }

    if (docstatus === 1) {
        return {
            label: doc.status || "Submitted",
            cssClass: statusPillClass(doc.status || "Submitted")
        };
    }

    return {
        label: doc && doc.status ? doc.status : "Draft",
        cssClass: statusPillClass(doc && doc.status ? doc.status : "Draft")
    };
}

function lifePurchaseReceiptActionStatus(message, type) {
    var statusLine = byId("life-pr-action-status");

    if (!statusLine) {
        return;
    }

    if (!message) {
        statusLine.style.display = "none";
        statusLine.textContent = "";
        return;
    }

    statusLine.style.display = "block";
    statusLine.style.borderLeftColor =
        type === "error" ? "#C00000" : type === "success" ? "#1E7A34" : "#B8860B";
    statusLine.style.background =
        type === "error" ? "#FFF0F0" : type === "success" ? "#EEF9F0" : "#FFF8E5";
    statusLine.style.color = type === "error" ? "#8B0000" : "#173B20";
    statusLine.textContent = message;
}

function lifePurchaseReceiptActionButtonsDisabled(disabled) {
    $all("[data-pr-action]").forEach(function (button) {
        button.disabled = !!disabled;
        button.setAttribute("aria-busy", disabled ? "true" : "false");
    });
}

function lifeOpenPurchaseReceiptPrint(name) {
    var receiptName = String(name || "").trim();
    if (!receiptName) return;

    window.open(
        "/app/print/Purchase%20Receipt/" + encodeURIComponent(receiptName),
        "_blank",
        "noopener"
    );
}

async function lifeSubmitPurchaseReceipt(name) {
    if (LIFE_PURCHASE_RECEIPT_ACTION_BUSY) {
        return;
    }

    var receiptName =
        String(
            name || ""
        ).trim();

    if (!receiptName) {
        return;
    }

    if (
        !window.confirm(
            "Submit Purchase Receipt " +
            receiptName +
            "?"
        )
    ) {
        return;
    }

    LIFE_PURCHASE_RECEIPT_ACTION_BUSY =
        true;

    lifePurchaseReceiptActionButtonsDisabled(
        true
    );

    lifePurchaseReceiptActionStatus(
        "Submitting Purchase Receipt through ERPNext…",
        "loading"
    );

    try {
        /*
         * Always read the current Draft from ERPNext first.
         */
        var receiptDoc =
            await callGet(
                "Purchase Receipt",
                receiptName
            );

        if (!receiptDoc) {
            throw new Error(
                "Purchase Receipt could not be loaded."
            );
        }

        if (
            Number(
                receiptDoc.docstatus
            ) !== 0
        ) {
            throw new Error(
                "Only a Draft Purchase Receipt can be submitted."
            );
        }

        /*
         * Submit using ERPNext itself.
         * We DO NOT set status / per_billed manually.
         */
        var submittedDoc =
            await lifePurchaseInvoiceServerCall(
                "frappe.client.submit",
                {
                    doc: receiptDoc
                }
            );

        var submittedName =
            submittedDoc &&
            submittedDoc.name
                ? submittedDoc.name
                : receiptName;

        /*
         * Critical step:
         * re-fetch the document AFTER submission so the custom
         * page uses the status calculated by ERPNext.
         */
        var freshReceipt =
            await callGet(
                "Purchase Receipt",
                submittedName
            );

        if (!freshReceipt) {
            throw new Error(
                "Purchase Receipt was submitted, but its updated status could not be refreshed."
            );
        }

        var freshStatus =
            String(
                freshReceipt.status ||
                "Submitted"
            ).trim();

        var statusKey =
            freshStatus
                .toLowerCase()
                .replace(
                    /[^a-z0-9]+/g,
                    ""
                );

        var successMessage =
            "✓ Purchase Receipt submitted. ERPNext status: " +
            freshStatus +
            ".";

        if (statusKey === "tobill") {
            successMessage +=
                " It is ready for Purchase Invoice creation.";
        }

        lifePurchaseReceiptActionStatus(
            successMessage,
            "success"
        );

        if (
            typeof toast ===
            "function"
        ) {
            if (statusKey === "tobill") {
                toast(
                    "Purchase Receipt " +
                    submittedName +
                    " is now To Bill.",
                    "g"
                );
            }
            else {
                toast(
                    "Purchase Receipt " +
                    submittedName +
                    " submitted. Status: " +
                    freshStatus +
                    ".",
                    "g"
                );
            }
        }

        /*
         * Refresh the Purchase Receipt table.
         */
        if (
            typeof renderPurchaseReceipt ===
            "function"
        ) {
            renderPurchaseReceipt();
        }

        /*
         * Re-open the exact PR after the server-generated status
         * is available. The detail footer will automatically show
         * Create Purchase Invoice only when status is To Bill.
         */
        window.setTimeout(
            function () {
                openPrDetail(
                    submittedName
                );
            },
            120
        );
    }
    catch (error) {
        lifePurchaseReceiptActionStatus(
            "✕ " +
            lifePurchaseInvoiceErrorMessage(
                error
            ),
            "error"
        );

        lifePurchaseReceiptActionButtonsDisabled(
            false
        );
    }
    finally {
        LIFE_PURCHASE_RECEIPT_ACTION_BUSY =
            false;
    }
}
async function lifeCancelPurchaseReceipt(name) {
    if (LIFE_PURCHASE_RECEIPT_ACTION_BUSY) {
        return;
    }

    var receiptName =
        String(
            name || ""
        ).trim();

    if (!receiptName) {
        return;
    }

    if (
        !window.confirm(
            "Cancel submitted Purchase Receipt " +
            receiptName +
            "? This will run ERPNext stock and linked-document validations."
        )
    ) {
        return;
    }

    LIFE_PURCHASE_RECEIPT_ACTION_BUSY =
        true;

    lifePurchaseReceiptActionButtonsDisabled(
        true
    );

    lifePurchaseReceiptActionStatus(
        "Cancelling Purchase Receipt through ERPNext…",
        "loading"
    );

    try {
        var receiptDoc =
            await callGet(
                "Purchase Receipt",
                receiptName
            );

        if (!receiptDoc) {
            throw new Error(
                "Purchase Receipt could not be loaded."
            );
        }

        if (
            Number(
                receiptDoc.docstatus
            ) !== 1
        ) {
            throw new Error(
                "Only a Submitted Purchase Receipt can be cancelled."
            );
        }

        await lifePurchaseInvoiceServerCall(
            "frappe.client.cancel",
            {
                doctype:
                    "Purchase Receipt",

                name:
                    receiptName
            }
        );

        var freshReceipt = null;

        try {
            freshReceipt =
                await callGet(
                    "Purchase Receipt",
                    receiptName
                );
        }
        catch (ignoreRefreshError) {
            freshReceipt = null;
        }

        var freshStatus =
            String(
                freshReceipt &&
                freshReceipt.status ||
                "Cancelled"
            ).trim();

        lifePurchaseReceiptActionStatus(
            "✓ Purchase Receipt cancelled. ERPNext status: " +
            freshStatus +
            ".",
            "success"
        );

        if (
            typeof toast ===
            "function"
        ) {
            toast(
                "Purchase Receipt " +
                receiptName +
                " status: " +
                freshStatus +
                ".",
                "g"
            );
        }

        if (
            typeof renderPurchaseReceipt ===
            "function"
        ) {
            renderPurchaseReceipt();
        }

        window.setTimeout(
            function () {
                openPrDetail(
                    receiptName
                );
            },
            120
        );
    }
    catch (error) {
        lifePurchaseReceiptActionStatus(
            "✕ " +
            lifePurchaseInvoiceErrorMessage(
                error
            ),
            "error"
        );

        lifePurchaseReceiptActionButtonsDisabled(
            false
        );
    }
    finally {
        LIFE_PURCHASE_RECEIPT_ACTION_BUSY =
            false;
    }
}
function lifeBuildPurchaseReceiptActions(doc) {
    var docstatus =
        Number(
            doc &&
            doc.docstatus
        );

    var name =
        String(
            doc &&
            doc.name ||
            ""
        ).trim();

    /*
     * ERPNext is the authority for Purchase Receipt status.
     * We only expose Create Purchase Invoice when the refreshed
     * submitted receipt is actually in To Bill state.
     */
    var statusKey =
        String(
            doc &&
            doc.status ||
            ""
        )
            .trim()
            .toLowerCase()
            .replace(
                /[^a-z0-9]+/g,
                ""
            );

    var canCreatePurchaseInvoice =
        docstatus === 1 &&
        statusKey === "tobill";

    var actionButtons = [];

    if (docstatus !== 2) {
        actionButtons.push(
            '<button type="button" class="btn btn-gold btn-sm" ' +
                'data-pr-action="print" data-pr-name="' +
                    esc(name) +
                '">' +
                '🖨 View / Print Receipt' +
            '</button>'
        );
    }

    if (docstatus === 0) {
        actionButtons.push(
            '<button type="button" class="btn btn-g btn-sm" ' +
                'data-pr-action="submit" data-pr-name="' +
                    esc(name) +
                '">' +
                '✓ Submit Purchase Receipt' +
            '</button>'
        );
    }
    else if (docstatus === 1) {
        actionButtons.push(
            '<button type="button" class="btn btn-r btn-sm" ' +
                'data-pr-action="cancel" data-pr-name="' +
                    esc(name) +
                '">' +
                '✕ Cancel Purchase Receipt' +
            '</button>'
        );

        if (canCreatePurchaseInvoice) {
            actionButtons.push(
                '<button type="button" class="btn btn-g btn-sm" ' +
                    'data-pr-action="create-invoice" data-pr-name="' +
                        esc(name) +
                    '">' +
                    '🧾 Create Purchase Invoice' +
                '</button>'
            );
        }
    }

    return (
        '<div id="life-pr-action-status" ' +
            'style="display:none;margin-top:14px;padding:9px 12px;border-left:3px solid #B8860B;border-radius:6px;font-size:12px;font-weight:700"></div>' +

        '<div class="btn-row" ' +
            'style="display:flex;justify-content:flex-end;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px">' +
            actionButtons.join("") +
        '</div>'
    );
}
