/* =========================================================
   PURCHASE INVOICE — WORKFLOW DISPLAY HELPERS
   ========================================================= */

function lifePurchaseInvoiceWorkflowState(doc) {
    doc = doc || {};

    var workflowState = String(
        doc.workflow_state || ""
    ).trim();

    if (workflowState) {
        return workflowState;
    }

    var docstatus = Number(
        doc.docstatus
    );

    if (docstatus === 2) {
        return "Cancelled";
    }

    if (docstatus === 1) {
        return "Approved";
    }

    return "Draft";
}

function lifePurchaseInvoiceWorkflowPillClass(state) {
    var key = String(
        state || ""
    )
        .trim()
        .toLowerCase();

    if (
        key === "approved" ||
        key === "completed"
    ) {
        return "p-g";
    }

    if (
        key === "rejected" ||
        key === "cancelled"
    ) {
        return "p-r";
    }

    if (
        key === "pending ops approval" ||
        key === "pending from ceo"
    ) {
        return "p-o";
    }

    if (key === "draft") {
        return "p-b";
    }

    return statusPillClass(
        state || "Draft"
    );
}

function renderPurchaseInvoice() {

    var box =
        byId(
            "ls-ho-pi-area"
        );


    loading(
        box,
        "Loading purchase invoices…"
