                lifePurchaseSupplierFilters(
                    "purchaseInvoice"
                ),

            order_by:
                "posting_date desc"
        }
    )
    .then(
        function(pageData) {

            var selectedSupplier =
                LIFE_PURCHASE_SUPPLIER_FILTER
                    .purchaseInvoice;


