function lifePurchaseInvoiceServerCall(method, args) {
    return new Promise(function (resolve, reject) {
        window.LifeStockGateway.compat({
            method: method,
            args: args || {},
            callback: function (response) {
                resolve(response && response.message ? response.message : null);
            },
            error: function (error) {
                reject(error);
            }
        });
    });
}

function lifePurchaseInvoiceErrorMessage(error) {
    if (!error) {
        return "The operation could not be completed.";
    }

    if (error.message) {
        return String(error.message);
    }

    if (error._server_messages) {
        try {
            var serverMessages = JSON.parse(error._server_messages);
            var messages = serverMessages.map(function (entry) {
                try {
                    var parsed = JSON.parse(entry);
                    return parsed.message || entry;
                } catch (innerError) {
                    return entry;
                }
            });

            if (messages.length) {
                return messages.join(" ");
            }
        } catch (parseError) {
            return String(error._server_messages);
        }
    }

    return "The operation could not be completed.";
}

