/* =========================================================
   PURCHASE INVOICE -> PURCHASE RECEIPT STATUS REFRESH
   ---------------------------------------------------------
   ERPNext owns the actual status transition:
   - PR stays To Bill while PI is Draft.
   - PR becomes Completed when linked PI submission makes
     per_billed reach 100%.
   - PR may return to To Bill when the linked submitted PI
     is cancelled.

   This helper only reloads the affected Purchase Receipts
   so the custom web page immediately reflects ERPNext's
   recalculated state.
   ========================================================= */
async function lifeRefreshLinkedPurchaseReceipts(invoiceDoc) {
    invoiceDoc = invoiceDoc || {};

    var receiptNames = [];

    (
        Array.isArray(invoiceDoc.items)
            ? invoiceDoc.items
            : []
    ).forEach(function (item) {
        var receiptName = String(
            item &&
            item.purchase_receipt ||
            ""
        ).trim();

        if (
            receiptName &&
            receiptNames.indexOf(receiptName) === -1
        ) {
            receiptNames.push(receiptName);
        }
    });

    var updatedReceipts = [];

    for (
        var index = 0;
        index < receiptNames.length;
        index++
    ) {
        try {
            var receiptDoc = await callGet(
                "Purchase Receipt",
                receiptNames[index]
            );

            if (receiptDoc) {
                updatedReceipts.push(
                    receiptDoc
                );
            }
        }
        catch (error) {
            void 0;
        }
    }

    /*
     * Reset any remote-list pagination state if present.
     * This prevents an old cached page from continuing to show
     * the previous PR status after ERPNext recalculates it.
     */
    try {
        if (
            typeof LIFE_REMOTE_LIST_STATE !== "undefined" &&
            LIFE_REMOTE_LIST_STATE &&
            LIFE_REMOTE_LIST_STATE.purchaseReceipt
        ) {
            LIFE_REMOTE_LIST_STATE.purchaseReceipt.page = 1;
        }
    }
    catch (ignoreRemoteStateError) {
    }

    return updatedReceipts;
}

function lifePurchaseReceiptStatusSummary(receipts) {
    receipts = Array.isArray(receipts)
        ? receipts
        : [];

    return receipts.map(function (receipt) {
        return {
            name: String(
                receipt &&
                receipt.name ||
                ""
            ).trim(),

            status: String(
                receipt &&
                receipt.status ||
                ""
            ).trim(),

            per_billed: Number(
                receipt &&
                receipt.per_billed
            ) || 0
        };
    });
}

async function lifeSubmitPurchaseInvoice(name) {
    if (LIFE_PURCHASE_INVOICE_ACTION_BUSY) {
        return;
    }

    var invoiceName = String(
        name || ""
    ).trim();

    if (!invoiceName) {
        return;
    }

    if (
        !window.confirm(
            "Submit Purchase Invoice " +
            invoiceName +
            "?"
        )
    ) {
        return;
    }

    LIFE_PURCHASE_INVOICE_ACTION_BUSY =
        true;

    lifePurchaseInvoiceActionButtonsDisabled(
        true
    );

    lifePurchaseInvoiceActionStatus(
        "Submitting Purchase Invoice…",
        "loading"
    );

    try {
        /*
         * Load the Draft PI first so we retain all linked
         * Purchase Receipt references even if the submit response
         * is minimal.
         */
        var invoiceDoc = await callGet(
            "Purchase Invoice",
            invoiceName
        );

        if (!invoiceDoc) {
            throw new Error(
                "Purchase Invoice could not be loaded."
            );
        }

        if (
            Number(
                invoiceDoc.docstatus
            ) !== 0
        ) {
            throw new Error(
                "Only a Draft Purchase Invoice can be submitted."
            );
        }

        /*
         * Submit through ERPNext.
         *
         * IMPORTANT:
         * The PI document contains
         * update_billed_amount_in_purchase_receipt = 1
         * and its child rows contain purchase_receipt + pr_detail.
         * ERPNext therefore recalculates Purchase Receipt
         * billed amounts/status during submit.
         */
        var submittedDoc =
            await lifePurchaseInvoiceServerCall(
                "frappe.client.submit",
                {
                    doc: invoiceDoc
                }
            );

        var submittedName =
            submittedDoc &&
            submittedDoc.name
                ? submittedDoc.name
                : invoiceName;

        /*
         * Reload PI after submit, then re-read every linked
         * Purchase Receipt after ERPNext has updated them.
         */
        var freshInvoice = null;

        try {
            freshInvoice = await callGet(
                "Purchase Invoice",
                submittedName
            );
        }
        catch (ignoreFreshInvoiceError) {
            freshInvoice = null;
        }

        var refreshedReceipts =
            await lifeRefreshLinkedPurchaseReceipts(
                freshInvoice ||
                invoiceDoc
            );

        var completedReceipts =
            refreshedReceipts.filter(
                function (receipt) {
                    return (
                        String(
                            receipt &&
                            receipt.status ||
                            ""
                        )
                            .trim()
                            .toLowerCase()
                        === "completed"
                    );
                }
            );

        lifePurchaseInvoiceActionStatus(
            "✓ Purchase Invoice submitted successfully.",
            "success"
        );

        if (
            completedReceipts.length &&
            typeof toast === "function"
        ) {
            toast(
                "Purchase Invoice " +
                submittedName +
                " submitted. " +
                completedReceipts
                    .map(function (receipt) {
                        return receipt.name;
                    })
                    .join(", ") +
                " is now Completed.",
                "g"
            );
        }
        else if (
            typeof toast === "function"
        ) {
            toast(
                "Purchase Invoice " +
                submittedName +
                " submitted successfully.",
                "g"
            );
        }

        void 0;

        /*
         * Refresh both tabs so the UI matches ERPNext immediately.
         */
        renderPurchaseInvoice();

        if (
            typeof renderPurchaseReceipt ===
            "function"
        ) {
            renderPurchaseReceipt();
        }

        /*
         * Re-open the submitted PI detail.
         */
        window.setTimeout(
            function () {
                openPiDetail(
                    submittedName
                );
            },
            350
        );
    }
    catch (error) {
        lifePurchaseInvoiceActionStatus(
            "✕ " +
            lifePurchaseInvoiceErrorMessage(
                error
            ),
            "error"
        );

        lifePurchaseInvoiceActionButtonsDisabled(
            false
        );
    }
    finally {
        LIFE_PURCHASE_INVOICE_ACTION_BUSY =
            false;
    }
}

