    );

    lifePurchaseInvoiceActionStatus(
        "Cancelling Purchase Invoice…",
        "loading"
    );

    try {
        /*
         * Load the submitted PI before cancellation.
         * Keep this copy because it contains the linked PR names
         * and pr_detail references needed for refresh afterwards.
         */
        var invoiceDoc = await callGet(
            "Purchase Invoice",
            invoiceName
        );

        if (!invoiceDoc) {
