async function lifeSendPurchaseInvoiceForApproval(name) {
    if (LIFE_PURCHASE_INVOICE_ACTION_BUSY) {
        return;
    }

    var invoiceName =
        String(
            name || ""
        ).trim();

    if (!invoiceName) {
        return;
    }

    LIFE_PURCHASE_INVOICE_ACTION_BUSY =
        true;

    lifePurchaseInvoiceActionButtonsDisabled(
        true
    );

    lifePurchaseInvoiceActionStatus(
        "Sending Purchase Invoice for approval…",
        "loading"
    );

    try {
        /*
         * Always fetch the latest document first.
         * We never directly set workflow_state.
         */
        var invoiceDoc =
            await callGet(
                "Purchase Invoice",
                invoiceName
            );

        if (!invoiceDoc) {
            throw new Error(
                "Purchase Invoice could not be loaded."
            );
        }

        if (
            Number(
                invoiceDoc.docstatus
            ) !== 0
        ) {
            throw new Error(
                "Only a Draft Purchase Invoice can be sent for approval."
            );
        }

        var currentWorkflowState =
            String(
                invoiceDoc.workflow_state ||
                lifePurchaseInvoiceWorkflowState(
                    invoiceDoc
                ) ||
                "Draft"
            ).trim();

        if (
            currentWorkflowState
                .toLowerCase() !==
            "draft"
        ) {
            throw new Error(
                "This Purchase Invoice is already in workflow state: " +
                currentWorkflowState +
                "."
            );
        }

        /*
         * Ask ERPNext for the transitions currently allowed
         * for this exact Purchase Invoice and logged-in user.
         */
        var transitions =
            await lifePurchaseInvoiceServerCall(
                "frappe.model.workflow.get_transitions",
                {
                    doc:
                        invoiceDoc
                }
            );

        transitions =
            Array.isArray(
                transitions
            )
                ? transitions
                : [];

        var sendTransition =
            transitions.find(
                function (transition) {
                    return (
                        String(
                            transition &&
                            transition.action ||
                            ""
                        )
                            .trim()
                            .toLowerCase() ===
                        "send for approval"
                    );
                }
            );

        if (!sendTransition) {
            throw new Error(
                'The "Send for Approval" workflow action is not available for this Purchase Invoice or your current ERPNext role.'
            );
        }

        /*
         * Run ERPNext's actual workflow action.
         *
         * Draft
         *   -> Send for Approval
         *   -> Pending Ops Approval
         */
        await lifePurchaseInvoiceServerCall(
            "frappe.model.workflow.apply_workflow",
            {
                doc:
                    invoiceDoc,

                action:
                    "Send for Approval"
            }
        );

        /*
         * Re-fetch after workflow application so the dashboard
         * displays ERPNext's actual resulting state.
         */
        var freshInvoice =
            await callGet(
                "Purchase Invoice",
                invoiceName
            );

        if (!freshInvoice) {
            throw new Error(
                "Purchase Invoice was sent for approval, but the updated workflow state could not be refreshed."
            );
        }

        var freshWorkflowState =
            String(
                freshInvoice.workflow_state ||
                lifePurchaseInvoiceWorkflowState(
                    freshInvoice
                ) ||
                ""
            ).trim();

        lifePurchaseInvoiceActionStatus(
            "✓ Sent for approval. Workflow State: " +
            freshWorkflowState +
            ".",
            "success"
        );

        if (
            typeof toast ===
            "function"
        ) {
            toast(
                "Purchase Invoice " +
                invoiceName +
                " → " +
                freshWorkflowState,
                "g"
            );
        }

        /*
         * Refresh the Purchase Invoice list and re-open this
         * exact invoice so Pending Ops Approval is immediately
         * visible in both places.
         */
        renderPurchaseInvoice();

        window.setTimeout(
            function () {
                openPiDetail(
                    invoiceName
                );
            },
            120
        );
    }
    catch (error) {
        lifePurchaseInvoiceActionStatus(
            "✕ " +
            lifePurchaseInvoiceErrorMessage(
                error
            ),
            "error"
        );

        lifePurchaseInvoiceActionButtonsDisabled(
            false
        );
    }
    finally {
        LIFE_PURCHASE_INVOICE_ACTION_BUSY =
            false;
    }
}

