async function loadSupplierVendorMobileMap(
    supplierRows
){

    supplierRows =
        Array.isArray(
            supplierRows
        )
            ? supplierRows
            : [];


    var result = {};


    /*
     * Start with Supplier.mobile_no as last fallback.
     */
    supplierRows.forEach(
        function(supplier){

            var supplierName =
                String(
                    supplier.name ||
                    ''
                ).trim();


            if(!supplierName){
                return;
            }


            result[supplierName] = {
                mobile:
                    String(
                        supplier.mobile_no ||
                        ''
                    ).trim(),

                source:
                    supplier.mobile_no
                        ? 'Supplier'
                        : '',

                contact_name:
                    ''
            };
        }
    );


    /*
     * Load contacts supplier-by-supplier.
     *
     * We already have loadSupplierLinkedRecords(), which
     * correctly resolves Contact records linked through
     * Dynamic Link.
     *
     * Run in small batches so we do not hit ERP with
     * hundreds of simultaneous calls.
     */
    var batchSize = 8;


    for(
        var start = 0;
        start < supplierRows.length;
        start += batchSize
    ){

        var batch =
            supplierRows.slice(
                start,
                start + batchSize
            );


        var batchResults =
            await Promise.all(
                batch.map(
                    async function(supplier){

                        var supplierName =
                            String(
                                supplier.name ||
                                ''
                            ).trim();


                        if(!supplierName){

                            return {
                                supplier:'',
                                contacts:[]
                            };
                        }


                        try{

                            var linked =
                                await loadSupplierLinkedRecords(
                                    supplierName
                                );


                            return {
                                supplier:
                                    supplierName,

                                contacts:
                                    Array.isArray(
                                        linked.contacts
                                    )
                                        ? linked.contacts
                                        : []
                            };

                        }
                        catch(error){

                            void 0;


                            return {
                                supplier:
                                    supplierName,

                                contacts:[]
                            };
                        }
                    }
                )
            );


        batchResults.forEach(
            function(entry){

                var supplierName =
                    entry.supplier;


                if(!supplierName){
                    return;
                }


                var contacts =
                    entry.contacts.slice();


                if(!contacts.length){
                    return;
                }


                /*
                 * Newest first.
                 */
                contacts.sort(
                    function(a,b){

                        var left =
                            String(
                                a.modified ||
                                a.creation ||
                                ''
                            );


                        var right =
                            String(
                                b.modified ||
                                b.creation ||
                                ''
                            );


                        return right.localeCompare(
                            left
                        );
                    }
                );


                /*
                 * Prefer Primary Contact.
                 */
                var selected =
                    contacts.find(
                        function(contact){

                            return (
                                Number(
                                    contact.is_primary_contact ||
                                    0
                                ) === 1 &&
                                supplierContactPreferredMobile(
                                    contact
                                )
                            );
                        }
                    );


                /*
                 * Otherwise latest Contact having a number.
                 */
                if(!selected){

                    selected =
                        contacts.find(
                            function(contact){

                                return !!supplierContactPreferredMobile(
                                    contact
                                );
                            }
                        );
                }


                if(!selected){
                    return;
                }


                var mobile =
                    supplierContactPreferredMobile(
                        selected
                    );


                if(!mobile){
                    return;
                }


                result[supplierName] = {
                    mobile:
                        mobile,

                    source:
                        Number(
                            selected.is_primary_contact ||
                            0
                        ) === 1
                            ? 'Primary Contact'
                            : 'Latest Contact',

                    contact_name:
                        supplierContactName(
                            selected
                        )
                };
            }
        );
    }


    return result;
}

function supplierContactPreferredMobile(
    contact
){

    contact =
        contact ||
        {};


    /*
     * First prefer Contact.mobile_no.
     */
    var mobile =
        String(
            contact.mobile_no ||
            ''
        ).trim();


    if(mobile){
        return mobile;
    }


    /*
     * Then inspect Contact Phone child rows and prefer
     * is_primary_mobile_no.
     */
    var phoneRows =
        Array.isArray(
            contact.phone_nos
        )
            ? contact.phone_nos
            : [];


    var primaryMobileRow =
        phoneRows.find(
            function(row){

                return (
                    Number(
                        row.is_primary_mobile_no ||
                        0
                    ) === 1 &&
                    String(
                        row.phone ||
                        ''
                    ).trim()
                );
            }
        );


    if(primaryMobileRow){

        return String(
            primaryMobileRow.phone ||
            ''
        ).trim();
    }


    /*
     * Any child phone.
     */
    var anyPhoneRow =
        phoneRows.find(
            function(row){

                return !!String(
                    row.phone ||
                    ''
                ).trim();
            }
        );


    if(anyPhoneRow){

        return String(
            anyPhoneRow.phone ||
            ''
        ).trim();
    }


    /*
     * Final Contact-level fallback.
     */
    return String(
        contact.phone ||
        ''
    ).trim();
}

