async function loadNextSupplierPage(
    reset
){

    if(
        SUPPLIER_LIST_STATE.loading
    ){
        return;
    }


    if(
        !reset &&
        SUPPLIER_LIST_STATE.exhausted
    ){
        return;
    }


    if(reset){

        SUPPLIER_ROWS =
            [];

        SUPPLIER_PAY =
            {};

        SUPPLIER_MOBILE_MAP =
            {};

        SUPPLIER_PAY_READY =
            {};

        SUPPLIER_MOBILE_READY =
            {};


        SUPPLIER_LIST_STATE.start =
            0;

        SUPPLIER_LIST_STATE.exhausted =
            false;

        SUPPLIER_LIST_STATE.request_seq +=
            1;
    }


    var requestSeq =
        SUPPLIER_LIST_STATE.request_seq;


    SUPPLIER_LIST_STATE.loading =
        true;


    paintSupplierRows();


    var search =
        String(
            SUPPLIER_CURRENT_SEARCH ||
            ''
        ).trim();


    var options = {

        fields:[
            'name',
            'supplier_name',
            'supplier_group',
            'supplier_type',
            'disabled',
            'on_hold',
            'country',
            'mobile_no',
            'email_id',
            'gstin',
            'gst_category',
            'pan',
            'website',
            'workflow_state'
        ],

        order_by:
            'supplier_name asc',

        start:
            SUPPLIER_LIST_STATE.start,

        limit:
            SUPPLIER_PAGE_SIZE
    };


    /*
     * Server-side search.
     *
     * We do NOT fetch every Supplier and filter in JavaScript.
     */
    if(search){

        var safeSearch =
            search
            .replace(
                /[%_]/g,
                ''
            );


        if(safeSearch){

            options.or_filters = [

                [
                    'supplier_name',
                    'like',
                    '%' +
                    safeSearch +
                    '%'
                ],

                [
                    'name',
                    'like',
                    '%' +
                    safeSearch +
                    '%'
                ],

                [
                    'supplier_group',
                    'like',
                    '%' +
                    safeSearch +
                    '%'
                ],

                [
                    'gstin',
                    'like',
                    '%' +
                    safeSearch +
                    '%'
                ],

                [
                    'mobile_no',
                    'like',
                    '%' +
                    safeSearch +
                    '%'
                ]
            ];
        }
    }


    try{

        var rows =
            await callList(
                'Supplier',
                options
            );


        /*
         * User may have typed another search while this
         * request was running.
         */
        if(
            requestSeq !==
            SUPPLIER_LIST_STATE.request_seq
        ){
            return;
        }


        rows =
            Array.isArray(
                rows
            )
                ? rows
                : [];


        /*
         * Less than page size means the server has no
         * more records for this search.
         */
        if(
            rows.length <
            SUPPLIER_PAGE_SIZE
        ){

            SUPPLIER_LIST_STATE.exhausted =
                true;
        }


        /*
         * Initialize display state only for newly fetched
         * Suppliers.
         */
        rows.forEach(
            function(row){

                var name =
                    String(
                        row.name ||
                        ''
                    ).trim();


                if(!name){
                    return;
                }


                SUPPLIER_MOBILE_MAP[
                    name
                ] = {

                    mobile:
                        String(
                            row.mobile_no ||
                            ''
                        ).trim(),

                    source:
                        row.mobile_no
                            ? 'Supplier'
                            : '',

                    contact_name:
                        ''
                };


                SUPPLIER_MOBILE_READY[
                    name
                ] =
                    false;


                SUPPLIER_PAY_READY[
                    name
                ] =
                    false;
            }
        );


        SUPPLIER_ROWS =
            SUPPLIER_ROWS.concat(
                rows
            );


        SUPPLIER_LIST_STATE.start +=
            rows.length;


        /*
         * IMPORTANT:
         * Display Supplier rows immediately.
         */
        paintSupplierRows();


        var status =
            byId(
                'ls-supplier-mobile-status'
            );


        if(status){

            status.innerHTML =

                'Showing <strong>' +
                SUPPLIER_ROWS.length +
                '</strong> vendor' +

                (
                    SUPPLIER_ROWS.length === 1
                        ? ''
                        : 's'
                ) +

                '. Contact mobile numbers and payment totals ' +
                'for the visible records are updating in the background.';
        }


        /*
         * Enrich ONLY the newly fetched page.
         *
         * Do not block rendering.
         */
        if(rows.length){

            window.setTimeout(
                function(){

                    hydrateSupplierPage(
                        rows,
                        requestSeq
                    );

                },
                0
            );
        }

    }
    catch(error){

        if(
            requestSeq ===
            SUPPLIER_LIST_STATE.request_seq
        ){

            void 0;


            var tbody =
                byId(
                    'ls-sup-tbody'
                );


            if(
                tbody &&
                !SUPPLIER_ROWS.length
            ){

                tbody.innerHTML =

                    '<tr>' +

                        '<td colspan="6" ' +
                            'style="' +
                                'text-align:center;' +
                                'padding:18px;' +
                                'color:#a11' +
                            '">' +

                            'Unable to load vendors: ' +

                            esc(
                                (
                                    error &&
                                    error.message
                                ) ||
                                'Unknown error'
                            ) +

                        '</td>' +

                    '</tr>';
            }
        }
    }
    finally{

        if(
            requestSeq ===
            SUPPLIER_LIST_STATE.request_seq
        ){

            SUPPLIER_LIST_STATE.loading =
                false;


            paintSupplierRows();
        }
    }
}

async function hydrateSupplierPage(
    rows,
    requestSeq
){

    rows =
        Array.isArray(
            rows
        )
            ? rows
            : [];


    if(!rows.length){
        return;
    }


    await Promise.allSettled([

        loadSupplierMobilesForPage(
            rows,
            requestSeq
        ),

        loadSupplierPaymentsForPage(
            rows,
            requestSeq
        )
    ]);


    scheduleSupplierListRepaint();
}

async function loadSupplierMobilesForPage(
    rows,
    requestSeq
){

    var queue =
        rows.slice();


    /*
     * Only a few concurrent Supplier reads.
     *
     * 3 is enough for speed without hammering Frappe.
     */
    var concurrency =
        Math.min(
            3,
            queue.length
        );


    async function worker(){

        while(queue.length){

            if(
                requestSeq !==
                SUPPLIER_LIST_STATE.request_seq
            ){
                return;
            }


            var row =
                queue.shift();


            if(!row){
                continue;
            }


            var supplierName =
                String(
                    row.name ||
                    ''
                ).trim();


            if(!supplierName){
                continue;
            }


            try{

                var supplier =
                    await callGet(
                        'Supplier',
                        supplierName
                    );


                if(
                    requestSeq !==
                    SUPPLIER_LIST_STATE.request_seq
                ){
                    return;
                }


                var onload =
                    (
                        supplier &&
                        supplier.__onload
                    ) ||
                    {};


                var contacts =
                    Array.isArray(
                        onload.contact_list
                    )
                        ? onload.contact_list.slice()
                        : [];


                /*
                 * Contacts having a usable mobile/phone only.
                 */
                contacts =
                    contacts.filter(
                        function(contact){

                            return !!supplierContactPreferredMobile(
                                contact
                            );
                        }
                    );


                /*
                 * Primary Contact first.
                 * Otherwise latest modified Contact.
                 */
                contacts.sort(
                    function(a,b){

                        var aPrimary =
                            Number(
                                a &&
                                a.is_primary_contact ||
                                0
                            ) === 1;


                        var bPrimary =
                            Number(
                                b &&
                                b.is_primary_contact ||
                                0
                            ) === 1;


                        if(
                            aPrimary !==
                            bPrimary
                        ){

                            return aPrimary
                                ? -1
                                : 1;
                        }


                        var aDate =
                            String(
                                a &&
                                (
                                    a.modified ||
                                    a.creation
                                ) ||
                                ''
                            );


                        var bDate =
                            String(
                                b &&
                                (
                                    b.modified ||
                                    b.creation
                                ) ||
                                ''
                            );


                        return bDate.localeCompare(
                            aDate
                        );
                    }
                );


                var selected =
                    contacts[0];


                if(selected){

                    var mobile =
                        supplierContactPreferredMobile(
                            selected
                        );


                    if(mobile){

                        SUPPLIER_MOBILE_MAP[
                            supplierName
                        ] = {

                            mobile:
                                mobile,

                            source:
                                Number(
                                    selected.is_primary_contact ||
                                    0
                                ) === 1
                                    ? 'Primary Contact'
                                    : 'Latest Contact',

                            contact_name:
                                supplierContactName(
                                    selected
                                )
                        };
                    }
                }

            }
            catch(error){

                /*
                 * Supplier.mobile_no remains as fallback.
                 */
                void 0;
            }
            finally{

                SUPPLIER_MOBILE_READY[
                    supplierName
                ] =
                    true;


                scheduleSupplierListRepaint();
            }
        }
    }


    var workers =
        [];


    for(
        var index = 0;
        index < concurrency;
        index += 1
    ){

        workers.push(
            worker()
        );
    }


    await Promise.all(
        workers
    );
}

async function loadSupplierPaymentsForPage(
    rows,
    requestSeq
){

    var supplierNames =
        rows
        .map(
            function(row){

                return String(
                    row &&
                    row.name ||
                    ''
                ).trim();
            }
        )
        .filter(Boolean);


    if(!supplierNames.length){
        return;
    }


    try{

        var invoices =
            await callList(
                'Purchase Invoice',
                {
                    fields:[
                        'supplier',
                        'grand_total',
                        'outstanding_amount'
                    ],

                    filters:[
                        [
                            'docstatus',
                            '<',
                            2
                        ],
                        [
                            'supplier',
                            'in',
                            supplierNames
                        ]
                    ],

                    order_by:
                        'posting_date desc',

                    limit:
                        0
                }
            );


        if(
            requestSeq !==
            SUPPLIER_LIST_STATE.request_seq
        ){
            return;
        }


        var pageMap =
            {};


        (
            Array.isArray(
                invoices
            )
                ? invoices
                : []
        )
        .forEach(
            function(invoice){

                var supplier =
                    String(
                        invoice.supplier ||
                        ''
                    ).trim();


                if(!supplier){
                    return;
                }


                if(!pageMap[supplier]){

                    pageMap[supplier] = {
                        billed:0,
                        paid:0,
                        pending:0,
                        invoices:0
                    };
                }


                var grandTotal =
                    Number(
                        invoice.grand_total ||
                        0
                    );


                var outstanding =
                    Number(
                        invoice.outstanding_amount ||
                        0
                    );


                pageMap[supplier].billed +=
                    grandTotal;


                pageMap[supplier].paid +=
                    (
                        grandTotal -
                        outstanding
                    );


                pageMap[supplier].pending +=
                    outstanding;


                pageMap[supplier].invoices +=
                    1;
            }
        );


        supplierNames.forEach(
            function(name){

                SUPPLIER_PAY[
                    name
                ] =

                    pageMap[name] ||
                    {
                        billed:0,
                        paid:0,
                        pending:0,
                        invoices:0
                    };


                SUPPLIER_PAY_READY[
                    name
                ] =
                    true;
            }
        );

    }
    catch(error){

        void 0;


        /*
         * Mark them done so the UI stops showing loading dots.
         */
        supplierNames.forEach(
            function(name){

                SUPPLIER_PAY_READY[
                    name
                ] =
                    true;
            }
        );
    }


    scheduleSupplierListRepaint();
}

function scheduleSupplierListRepaint(){

    if(
        SUPPLIER_REPAINT_TIMER
    ){
        return;
    }


    SUPPLIER_REPAINT_TIMER =
        window.setTimeout(
            function(){

                SUPPLIER_REPAINT_TIMER =
                    null;


                paintSupplierRows();

            },
            180
        );
}



async function loadSupplierVendorMobileMapFast(
    supplierRows
){

    supplierRows =
        Array.isArray(
            supplierRows
        )
            ? supplierRows
            : [];


    var result = {};


    /*
     * ------------------------------------------------------
     * Initial fallback:
     * Supplier.mobile_no
     * ------------------------------------------------------
     */

    supplierRows.forEach(
        function(supplier){

            if(
                !supplier ||
                !supplier.name
            ){
                return;
            }


            result[
                supplier.name
            ] = {

                mobile:
                    String(
                        supplier.mobile_no ||
                        ''
                    ).trim(),

                source:
                    supplier.mobile_no
                        ? 'Supplier'
                        : '',

                contact_name:
                    ''
            };
        }
    );


    /*
     * Do NOT query Dynamic Link directly.
     *
     * Dynamic Link is a child DocType and the current user
     * cannot use frappe.get_list against it through the gateway.
     *
     * Instead resolve each Supplier's normal linked Contacts.
     *
     * This happens in BACKGROUND, so the vendor list itself
     * remains instant.
     */

    var queue =
        supplierRows.slice();


    var concurrency =
        5;


    async function worker(){

        while(queue.length){

            var supplier =
                queue.shift();


            if(
                !supplier ||
                !supplier.name
            ){
                continue;
            }


            var supplierName =
                String(
                    supplier.name ||
                    ''
                ).trim();


            if(!supplierName){
                continue;
            }


            try{

                var linked =
                    await loadSupplierLinkedRecords(
                        supplierName
                    );


                var contacts =
                    (
                        linked &&
                        Array.isArray(
                            linked.contacts
                        )
                    )
                        ? linked.contacts.slice()
                        : [];


                if(!contacts.length){
                    continue;
                }


                /*
                 * Latest first.
                 */
                contacts.sort(
                    function(a,b){

                        var left =
                            String(
                                a.modified ||
                                a.creation ||
                                ''
                            );


                        var right =
                            String(
                                b.modified ||
                                b.creation ||
                                ''
                            );


                        return right.localeCompare(
                            left
                        );
                    }
                );


                /*
                 * RULE 1:
                 * Primary Contact having a number.
                 */
                var selected =
                    contacts.find(
                        function(contact){

                            return (
                                Number(
                                    contact.is_primary_contact ||
                                    0
                                ) === 1 &&
                                !!supplierContactPreferredMobile(
                                    contact
                                )
                            );
                        }
                    );


                /*
                 * RULE 2:
                 * Latest Contact having a number.
                 */
                if(!selected){

                    selected =
                        contacts.find(
                            function(contact){

                                return !!supplierContactPreferredMobile(
                                    contact
                                );
                            }
                        );
                }


                if(!selected){
                    continue;
                }


                var mobile =
                    supplierContactPreferredMobile(
                        selected
                    );


                if(!mobile){
                    continue;
                }


                result[
                    supplierName
                ] = {

                    mobile:
                        mobile,

                    source:
                        Number(
                            selected.is_primary_contact ||
                            0
                        ) === 1
                            ? 'Primary Contact'
                            : 'Latest Contact',

                    contact_name:
                        supplierContactName(
                            selected
                        )
                };


                /*
                 * Update global map immediately so numbers
                 * start appearing while remaining vendors load.
                 */
                SUPPLIER_MOBILE_MAP[
                    supplierName
                ] = result[
                    supplierName
                ];


                scheduleSupplierMobileRepaint();

            }
            catch(error){

                /*
                 * One bad/permission-blocked Supplier must not
                 * stop the entire vendor list.
                 */
                void 0;
            }
        }
    }


    var workers = [];


    for(
        var index = 0;
        index < concurrency;
        index += 1
    ){

        workers.push(
            worker()
        );
    }


    await Promise.all(
        workers
    );


    return result;
}

var SUPPLIER_MOBILE_REPAINT_TIMER = null;


function scheduleSupplierMobileRepaint(){

    if(
        SUPPLIER_MOBILE_REPAINT_TIMER
    ){
        return;
    }


    SUPPLIER_MOBILE_REPAINT_TIMER =
        window.setTimeout(
            function(){

                SUPPLIER_MOBILE_REPAINT_TIMER =
                    null;


                repaintCurrentSupplierRows();

