        );
}

function repaintCurrentSupplierRows(){

    var term =
        String(
            SUPPLIER_CURRENT_SEARCH ||
            ''
        )
        .toLowerCase()
        .trim();


    var rows =
        !term

        ? SUPPLIER_ROWS

        : SUPPLIER_ROWS.filter(
            function(r){

                var mobileInfo =
                    SUPPLIER_MOBILE_MAP[
                        r.name
                    ] ||
                    {};


                var displayMobile =
                    String(
                        mobileInfo.mobile ||
                        r.mobile_no ||
                        ''
                    )
                    .toLowerCase();


                return (

                    String(
                        r.supplier_name ||
                        ''
                    )
                    .toLowerCase()
                    .indexOf(
                        term
                    ) > -1 ||

                    String(
                        r.name ||
                        ''
                    )
                    .toLowerCase()
                    .indexOf(
                        term
                    ) > -1 ||

                    String(
                        r.supplier_group ||
                        ''
                    )
                    .toLowerCase()
                    .indexOf(
                        term
                    ) > -1 ||

                    displayMobile.indexOf(
                        term
                    ) > -1 ||

                    String(
                        r.gstin ||
                        ''
                    )
                    .toLowerCase()
                    .indexOf(
                        term
                    ) > -1
                );
            }
        );


    paintSupplierRows(
        rows,
        SUPPLIER_PAY || {}
    );
}
var SUPPLIER_ROWS = [];

