function paintSupplierRows(){

    var tbody =
        byId(
            'ls-sup-tbody'
        );


    if(!tbody){
        return;
    }


    var rows =
        Array.isArray(
            SUPPLIER_ROWS
        )
            ? SUPPLIER_ROWS
            : [];


    var html =
        '';


    if(!rows.length){

        if(
            SUPPLIER_LIST_STATE.loading
        ){

            html =

                '<tr>' +

                    '<td colspan="6" ' +
                        'style="' +
                            'text-align:center;' +
                            'padding:18px;' +
                            'color:#657268' +
                        '">' +

                        '⏳ Loading vendors…' +

                    '</td>' +

                '</tr>';
        }
        else{

            html =

                '<tr>' +

                    '<td colspan="6" ' +
                        'style="' +
                            'text-align:center;' +
                            'padding:18px;' +
                            'color:#8C8C8C' +
