                    '</td>' +

                '</tr>';
        }
    }
    else{

        html =
            rows
            .map(
                function(r){

                    var name =
                        String(
                            r.name ||
                            ''
                        );


                    var paymentReady =
                        !!SUPPLIER_PAY_READY[
                            name
                        ];


                    var payment =
                        SUPPLIER_PAY[
                            name
                        ] ||
                        {
                            paid:0,
                            pending:0
                        };


                    var mobileReady =
                        !!SUPPLIER_MOBILE_READY[
                            name
                        ];


                    var mobileInfo =
                        SUPPLIER_MOBILE_MAP[
                            name
                        ] ||
                        {};


                    var mobile =
                        String(
                            mobileInfo.mobile ||
                            r.mobile_no ||
                            ''
                        ).trim();


                    /*
                     * While Contact lookup is happening:
                     * - show Supplier.mobile_no immediately
                     * - otherwise show small loading dots.
                     */
                    var mobileText =
                        mobile
                            ? mobile
                            : (
                                mobileReady
                                    ? '—'
                                    : '…'
                            );


                    var paidText =
                        paymentReady
                            ? money(
                                payment.paid
                            )
                            : '…';


                    var pendingText =
                        paymentReady
                            ? money(
                                payment.pending
                            )
                            : '…';


                    var pendingColor =
                        paymentReady &&
                        Number(
                            payment.pending ||
                            0
                        ) > 0

                            ? '#C00000'
                            : '#1E7A34';


                    var status =

                        r.disabled

                        ? (
                            '<span class="pill p-r">' +
                                'Blocked' +
                            '</span>'
                        )

                        : (
                            r.on_hold

                            ? (
                                '<span class="pill p-o">' +
                                    'On Hold' +
                                '</span>'
                            )

                            : (
                                '<span class="pill p-g">' +
                                    'Active' +
                                '</span>'
                            )
                        );


                    var mobileTitle =
                        mobileInfo.source

                        ? (
                            mobileInfo.source +
                            (
                                mobileInfo.contact_name

                                ? (
                                    ' — ' +
                                    mobileInfo.contact_name
                                )

                                : ''
                            )
                        )

                        : '';


                    return (

                        '<tr ' +
                            'class="ls-sup-row" ' +
                            'data-sup="' +
                                esc(name) +
                            '" ' +
                            'style="cursor:pointer" ' +
                            'tabindex="0">' +


                            '<td>' +

                                '<strong>' +

                                    esc(
                                        r.supplier_name ||
                                        name
                                    ) +

                                '</strong>' +

                            '</td>' +


                            '<td>' +

                                esc(
                                    r.supplier_group ||
                                    '—'
                                ) +

                            '</td>' +


                            '<td title="' +
                                esc(
                                    mobileTitle
                                ) +
                            '">' +

                                esc(
                                    mobileText
                                ) +

                            '</td>' +


                            '<td style="' +
                                'text-align:right;' +
                                'color:#1E7A34;' +
                                'font-weight:700' +
                            '">' +

                                paidText +

                            '</td>' +


                            '<td style="' +
                                'text-align:right;' +
                                'color:' +
                                    pendingColor +
                                ';' +
                                'font-weight:700' +
                            '">' +

                                pendingText +

                            '</td>' +


                            '<td>' +

                                status +

                            '</td>' +


                        '</tr>'
                    );
                }
            )
            .join('');


        /*
         * Server-side Load More control.
         */
        if(
            !SUPPLIER_LIST_STATE.exhausted
        ){

            html +=

                '<tr ' +
                    'data-supplier-load-more="1">' +

                    '<td colspan="6" ' +
                        'class="ls-load-more" ' +
                        'style="' +
                            'text-align:center;' +
                            'padding:12px;' +
                            'cursor:pointer;' +
                            'font-weight:700;' +
                            'color:#1E7A34;' +
                            'background:#F3F9F4' +
                        '">' +

                        (
                            SUPPLIER_LIST_STATE.loading

                            ? '⏳ Loading more vendors…'

                            : (
                                '▼ Load next ' +
                                SUPPLIER_PAGE_SIZE +
                                ' vendors'
                            )
                        ) +

                    '</td>' +

                '</tr>';
        }
    }


    tbody.innerHTML =
        html;


    var count =
        byId(
            'ls-sup-count'
        );


    if(count){

        count.textContent =
            rows.length +
            ' loaded';
    }


    /*
     * Direct Load More click.
     */
    tbody.onclick =
        function(event){

            var target =
                event.target &&
                event.target.closest
                    ? event.target.closest(
                        '[data-supplier-load-more]'
                    )
                    : null;


            if(!target){
                return;
            }


            event.preventDefault();

            event.stopPropagation();


            loadNextSupplierPage(
                false
            );
        };
}
