async function loadSupplierLinkedRecords(
    supplierName
){

    supplierName =
        String(
            supplierName ||
            ''
        ).trim();


    if(!supplierName){

        return {
            supplier:null,
            contacts:[],
            addresses:[]
        };
    }


    /*
     * ==========================================================
     * LOAD SUPPLIER
     * ==========================================================
     */

    var supplier =
        await callGet(
            'Supplier',
            supplierName
        );


    if(!supplier){

        throw new Error(
            'Supplier ' +
            supplierName +
            ' was not found.'
        );
    }


    var onload =
        supplier.__onload ||
        {};


    var contacts = [];
    var addresses = [];


    /*
     * ==========================================================
     * CONTACTS
     * ==========================================================
     *
     * First preference:
     * Supplier.__onload.contact_list
     *
     * Fallback:
     * Query Contact through Dynamic Link.
     *
     * IMPORTANT:
     * The Dynamic Link join makes plain "modified"
     * ambiguous, so order_by must qualify tabContact.modified.
     * ==========================================================
     */

    var onloadContacts =
        Array.isArray(
            onload.contact_list
        )
            ? onload.contact_list
            : [];


    /*
     * Use Supplier onload contacts first.
     */
    onloadContacts.forEach(
        function(row){

            if(!row){
                return;
            }


            /*
             * Sometimes ERP may return only the Contact name.
             */
            if(
                typeof row ===
                'string'
            ){

                contacts.push({
                    name:
                        row,

                    full_name:
                        row
                });

                return;
            }


            /*
             * Normal Supplier onload returns a summary object.
             */
            contacts.push(
                Object.assign(
                    {},
                    row
                )
            );
        }
    );


    /*
     * If Supplier onload did not return contacts,
     * query Contact through Dynamic Link.
     */
    if(!contacts.length){

        try{

            var contactRows =
                await callList(
                    'Contact',
                    {
                        fields:[
                            'name',
                            'first_name',
                            'middle_name',
                            'last_name',
                            'full_name',
                            'designation',
                            'phone',
                            'mobile_no',
                            'email_id',
                            'is_primary_contact',
                            'company_name',
                            'status',
                            'modified'
                        ],

                        filters:[
                            [
                                'Dynamic Link',
                                'link_doctype',
                                '=',
                                'Supplier'
                            ],
                            [
                                'Dynamic Link',
                                'link_name',
                                '=',
                                supplierName
                            ]
                        ],

                        /*
                         * Do NOT use:
                         * modified desc
                         *
                         * Dynamic Link also has modified,
                         * so MariaDB reports:
                         * Column 'modified' in ORDER BY is ambiguous
                         */
                        order_by:
                            '`tabContact`.`modified` desc',

                        limit:
                            100
                    }
                );


            contacts =
                Array.isArray(
                    contactRows
                )
                    ? contactRows
                    : [];

        }
        catch(error){

            void 0;
        }
    }


    /*
     * Enrich each Contact by loading its full document.
     *
     * This gives phone_nos / email_ids child tables.
     *
     * IMPORTANT:
     * If full Contact loading fails, keep the summary row.
     */
    contacts =
        await Promise.all(
            contacts.map(
                async function(contact){

                    contact =
                        Object.assign(
                            {},
                            contact ||
                            {}
                        );


                    var contactName =
                        String(
                            contact.name ||
                            ''
                        ).trim();


                    if(!contactName){

                        return contact;
                    }


                    try{

                        var fullContact =
                            await callGet(
                                'Contact',
                                contactName
                            );


                        if(fullContact){

                            return Object.assign(
                                {},
                                contact,
                                fullContact
                            );
                        }

                    }
                    catch(error){

                        void 0;
                    }


                    return contact;
                }
            )
        );


    /*
     * Remove duplicate Contacts.
     */
    var seenContacts = {};


    contacts =
        contacts.filter(
            function(contact){

                if(!contact){
                    return false;
                }


                var key =
                    String(
                        contact.name ||
                        contact.full_name ||
                        contact.phone ||
                        contact.mobile_no ||
                        contact.email_id ||
                        ''
                    ).trim();


                if(!key){
                    return false;
                }


                if(seenContacts[key]){
                    return false;
                }


                seenContacts[key] =
                    true;


                return true;
            }
        );


    /*
     * ==========================================================
     * ADDRESSES
     * ==========================================================
     *
     * First preference:
     * Supplier.__onload.addr_list
     *
     * Fallback:
     * Query Address through Dynamic Link.
     *
     * IMPORTANT:
     * Qualify Address fields in ORDER BY because Dynamic Link
     * introduces another "modified" column.
     * ==========================================================
     */

    var onloadAddresses =
        Array.isArray(
            onload.addr_list
        )
            ? onload.addr_list
            : [];


    /*
     * Use Supplier onload addresses first.
     */
    onloadAddresses.forEach(
        function(row){

            if(!row){
                return;
            }


            if(
                typeof row ===
                'string'
            ){

                addresses.push({
                    name:
                        row,

                    address_title:
                        row
                });

                return;
            }


            addresses.push(
                Object.assign(
                    {},
                    row
                )
            );
        }
    );


    /*
     * If Supplier onload did not return addresses,
     * query Address through Dynamic Link.
     */
    if(!addresses.length){

        try{

            var addressRows =
                await callList(
                    'Address',
                    {
                        fields:[
                            'name',
                            'address_title',
                            'address_type',
                            'address_line1',
                            'address_line2',
                            'city',
                            'county',
                            'state',
                            'pincode',
                            'country',
                            'gstin',
                            'phone',
                            'email_id',
                            'is_primary_address',
                            'is_shipping_address',
                            'modified'
                        ],

                        filters:[
                            [
                                'Dynamic Link',
                                'link_doctype',
                                '=',
                                'Supplier'
                            ],
                            [
                                'Dynamic Link',
                                'link_name',
                                '=',
                                supplierName
                            ]
                        ],

                        /*
                         * Fully qualify both fields.
                         */
                        order_by:
                            '`tabAddress`.`is_primary_address` desc, ' +
                            '`tabAddress`.`modified` desc',

                        limit:
                            100
                    }
                );


            addresses =
                Array.isArray(
                    addressRows
                )
                    ? addressRows
                    : [];

        }
        catch(error){

            void 0;
        }
    }


    /*
     * Enrich each Address with its full ERP document.
     *
     * If full Address loading fails, keep the summary row.
     */
    addresses =
        await Promise.all(
            addresses.map(
                async function(address){

                    address =
                        Object.assign(
                            {},
                            address ||
                            {}
                        );


                    var addressName =
                        String(
                            address.name ||
                            ''
                        ).trim();


                    if(!addressName){

                        return address;
                    }


                    try{

                        var fullAddress =
                            await callGet(
                                'Address',
                                addressName
                            );


                        if(fullAddress){

                            return Object.assign(
                                {},
                                address,
                                fullAddress
                            );
                        }

                    }
                    catch(error){

                        void 0;
                    }


                    return address;
                }
            )
        );


    /*
     * Remove duplicate Addresses.
     */
    var seenAddresses = {};


    addresses =
        addresses.filter(
            function(address){

                if(!address){
                    return false;
                }


                var key =
                    String(
                        address.name ||
                        [
                            address.address_title,
                            address.address_line1,
                            address.city
                        ]
                        .filter(Boolean)
                        .join('|')
                    ).trim();


                if(!key){
                    return false;
                }


                if(seenAddresses[key]){
                    return false;
                }


                seenAddresses[key] =
                    true;


                return true;
            }
        );


    /*
     * ==========================================================
     * DEBUG
     * ==========================================================
     */

    void 0;


    /*
     * ==========================================================
     * RETURN
     * ==========================================================
     */

    return {
        supplier:
            supplier,

        contacts:
            contacts,

        addresses:
            addresses
    };
}

function supplierContactName(
    contact
){

    contact =
        contact ||
        {};


    var name =
        String(
            contact.full_name ||
            ''
        ).trim();


    if(name){

        return name;

    }


    return [
        contact.first_name,
        contact.middle_name,
        contact.last_name
    ]
    .map(function(value){

        return String(
            value ||
            ''
        ).trim();

    })
    .filter(Boolean)
    .join(' ') ||
    contact.name ||
    'Contact';
}


function supplierContactPhones(
    contact
){

    contact =
        contact ||
        {};


    var phones = [];


    [
        contact.mobile_no,
        contact.phone,
        contact.phone_no
    ]
    .forEach(function(value){

        value =
            String(
                value ||
                ''
            ).trim();


        if(
            value &&
            phones.indexOf(value) === -1
        ){

            phones.push(
                value
            );
        }
    });


    var rows =
        Array.isArray(
            contact.phone_nos
        )
            ? contact.phone_nos
            : [];


    rows.forEach(function(row){

        var value =
            String(
                row.phone ||
                row.mobile_no ||
                ''
            ).trim();


        if(
            value &&
            phones.indexOf(value) === -1
        ){

            phones.push(
                value
            );
        }
    });


    return phones;
}


function supplierContactEmails(
    contact
){

    contact =
        contact ||
        {};


    var emails = [];


    var directEmail =
        String(
            contact.email_id ||
            ''
        ).trim();


    if(directEmail){

        emails.push(
            directEmail
        );
    }


    var rows =
        Array.isArray(
            contact.email_ids
        )
            ? contact.email_ids
            : [];


    rows.forEach(function(row){

        var email =
            String(
                row.email_id ||
                ''
            ).trim();


        if(
            email &&
            emails.indexOf(email) === -1
        ){

            emails.push(
                email
            );
        }
    });


    return emails;
}

