                    '</div>' +


                    (
                        gstin

                        ? (
                            '<div style="margin-top:4px">' +

                                '<strong>GSTIN:</strong> ' +

                                esc(
                                    gstin
                                ) +

                            '</div>'
                        )

                        : ''
                    ) +


                '</div>'

            );

        })
        .join('');


    return (
        header +
        body
    );
}

function wireSupplierContactAddressButtons(
