async function loadSupplierContactAddressPanels(
    supplierName
){

    supplierName =
        String(
            supplierName ||
            ''
        ).trim();


    var contactContainer =
        document.getElementById(
            'ls-supplier-contact-list'
        );


    var addressContainer =
        document.getElementById(
            'ls-supplier-address-list'
        );


    if(contactContainer){

        contactContainer.innerHTML =
            '<div class="notice notice-blue">' +
                '⏳ Loading Contacts…' +
            '</div>';
    }


    if(addressContainer){

        addressContainer.innerHTML =
            '<div class="notice notice-blue">' +
                '⏳ Loading Addresses…' +
            '</div>';
    }


    try{

        var linked =
            await loadSupplierLinkedRecords(
                supplierName
            );


        if(contactContainer){

            contactContainer.innerHTML =
                supplierContactsHtml(
                    linked.contacts,
                    supplierName
                );
        }


        if(addressContainer){

            addressContainer.innerHTML =
                supplierAddressesHtml(
                    linked.addresses,
                    supplierName
                );
        }


        if(linked.supplier){

            ACTIVE_SUPPLIER_DETAIL_DOC =
                linked.supplier;
        }


        /*
         * IMPORTANT:
         * Directly attach handlers after HTML is rendered.
         */
        wireSupplierContactAddressButtons(
            supplierName
        );


        void 0;

    }
    catch(error){

        void 0;


        var message =
            (
                error &&
                error.message
            ) ||
            'Unable to load linked records.';


        if(contactContainer){

            contactContainer.innerHTML =
                supplierContactsHtml(
                    [],
                    supplierName
                );
        }


        if(addressContainer){

            addressContainer.innerHTML =
                supplierAddressesHtml(
                    [],
                    supplierName
                );
        }


        /*
         * Even if data loading fails,
         * Add Contact / Add Address must still work.
         */
        wireSupplierContactAddressButtons(
            supplierName
        );


        if(
            contactContainer &&
            message
        ){

            void 0;
        }


        if(
            addressContainer &&
            message
        ){

            void 0;
        }
    }
}

