        );


    if(modal){

        /*
         * Re-attach to body if another render moved it.
         */
        if(
            modal.parentNode !==
            document.body
        ){

            document.body.appendChild(
                modal
            );
        }


        return modal;
    }


    modal =
        document.createElement(
            'div'
        );


    modal.id =
