            'important'
        );
    }


    var closeButton =
        document.getElementById(
            'life-supplier-master-modal-close'
        );


    if(closeButton){

        closeButton.onclick =
            function(event){

                if(event){

                    event.preventDefault();
                    event.stopPropagation();
                }


                closeSupplierMasterModal();
            };
    }


    modal.onclick =
        function(event){

            if(
                event.target ===
                modal
            ){

                closeSupplierMasterModal();
            }
        };


    if(
        !window.__lifeSupplierMasterEscapeBound
    ){

        window.__lifeSupplierMasterEscapeBound =
            true;


        document.addEventListener(
            'keydown',
            function(event){

                if(
                    event.key !==
                    'Escape'
                ){
                    return;
                }


                var current =
                    document.getElementById(
                        'life-supplier-master-modal'
                    );


                if(
                    current &&
                    current.style.display !==
                    'none'
                ){

                    closeSupplierMasterModal();
                }
            }
        );
    }


    void 0;


    return modal;
}


function openSupplierMasterModal(
    title,
    bodyHtml,
    footerHtml
){

    var modal =
        ensureSupplierMasterModal();


    if(!modal){

        void 0;

        return null;
    }


    var titleNode =
        document.getElementById(
            'life-supplier-master-modal-title'
        );


    var bodyNode =
        document.getElementById(
            'life-supplier-master-modal-body'
        );


    var footerNode =
        document.getElementById(
            'life-supplier-master-modal-footer'
        );


    if(
        !titleNode ||
        !bodyNode ||
        !footerNode
    ){

        void 0;

        return null;
    }


    titleNode.textContent =
        title ||
        'Vendor';


    bodyNode.innerHTML =
        bodyHtml ||
        '';


    footerNode.innerHTML =
        footerHtml ||
        '';


    /*
     * Do not depend only on .show CSS.
     */
    modal.classList.add(
        'show'
    );


    modal.style.setProperty(
        'display',
        'flex',
        'important'
    );

    modal.style.setProperty(
        'visibility',
        'visible',
        'important'
    );

    modal.style.setProperty(
        'opacity',
        '1',
        'important'
    );

    modal.style.setProperty(
        'pointer-events',
        'auto',
        'important'
    );

    modal.style.setProperty(
        'z-index',
        '2147483600',
        'important'
    );


    document.body.style.overflow =
        'hidden';


    /*
     * Force the modal to the end of BODY.
     * This also helps with stacking contexts.
     */
    if(
        modal.parentNode ===
        document.body
    ){

        document.body.appendChild(
            modal
        );
    }


    void 0;


    return modal;
}


function closeSupplierMasterModal(){

    var modal =
        document.getElementById(
            'life-supplier-master-modal'
        );


    if(modal){

        modal.classList.remove(
            'show'
        );


        modal.style.setProperty(
            'display',
            'none',
            'important'
        );

        modal.style.setProperty(
            'visibility',
            'hidden',
            'important'
        );

        modal.style.setProperty(
            'pointer-events',
            'none',
            'important'
        );
    }


    document.body.style.overflow =
        '';


    void 0;
}


function supplierMasterValue(id){

    var field =
        document.getElementById(
            id
        );


    return field
        ? String(
            field.value ||
            ''
        ).trim()
        : '';
}


function supplierMasterChecked(id){

    var field =
        document.getElementById(
            id
        );


    return !!(
        field &&
        field.checked
    );
}


function supplierMasterShowError(
    message
){

    var errorBox =
        document.getElementById(
            'life-supplier-master-error'
        );


    if(!errorBox){

        if(
            window.frappe &&
            typeof frappe.msgprint ===
            'function'
        ){

            frappe.msgprint(
                message
            );

        }

        return;
    }


    errorBox.textContent =
        String(
            message ||
            'Unable to continue.'
        );


    errorBox.style.display =
        'block';


    var body =
        document.getElementById(
            'life-supplier-master-modal-body'
        );


    if(body){

        body.scrollTop =
            0;

    }
}


function supplierMasterClearError(){

    var errorBox =
        document.getElementById(
            'life-supplier-master-error'
        );


    if(errorBox){

        errorBox.style.display =
            'none';

        errorBox.textContent =
            '';

    }
}

