        '</button>' +

        '<button ' +
            'type="button" ' +
            'class="life-btn life-btn-primary" ' +
            'id="life-contact-save">' +

            'Save Contact' +

        '</button>';


    openSupplierMasterModal(
        '📞 Add Contact',
        bodyHtml,
        footerHtml
    );


    var cancelButton =
        document.getElementById(
            'life-contact-cancel'
        );


    var saveButton =
        document.getElementById(
            'life-contact-save'
        );


    var firstNameField =
        document.getElementById(
            'life-contact-first-name'
        );


    /*
     * ============================================================
     * CANCEL
     * ============================================================
     */

    if(cancelButton){

        cancelButton.onclick =
            function(event){

                if(event){

                    event.preventDefault();
                    event.stopPropagation();
                }


                closeSupplierMasterModal();
            };
    }


    /*
     * ============================================================
     * SAVE CONTACT
     * ============================================================
     */

    if(saveButton){

        saveButton.onclick =
            async function(event){

                if(event){

                    event.preventDefault();
                    event.stopPropagation();
                }


                supplierMasterClearError();


                var firstName =
                    supplierMasterValue(
                        'life-contact-first-name'
                    );


                var designation =
                    supplierMasterValue(
                        'life-contact-designation'
                    );


                var mobile =
                    supplierMasterValue(
                        'life-contact-mobile'
                    );


                var email =
                    supplierMasterValue(
                        'life-contact-email'
                    );


                var isPrimary =
                    supplierMasterChecked(
                        'life-contact-primary'
                    );


                /*
                 * ==================================================
                 * VALIDATION
                 * ==================================================
                 */

                if(!firstName){

                    supplierMasterShowError(
                        'First Name is mandatory.'
                    );

                    return;
                }


                if(!mobile){

                    supplierMasterShowError(
                        'Mobile Number is mandatory.'
                    );

                    return;
                }


                var cleanedMobile =
                    String(
                        mobile ||
                        ''
                    )
                    .replace(
                        /[\s\-()]/g,
                        ''
                    );


                if(
                    !/^\+?[0-9]{7,15}$/.test(
                        cleanedMobile
                    )
                ){

                    supplierMasterShowError(
                        'Enter a valid Mobile Number.'
                    );

                    return;
                }


                if(
                    email &&
                    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
                        email
                    )
                ){

                    supplierMasterShowError(
                        'Enter a valid Email address.'
                    );

                    return;
                }


                saveButton.disabled =
                    true;


                saveButton.textContent =
                    'Saving…';


                try{

                    /*
                     * ==================================================
                     * PHONE CHILD ROW
                     * ==================================================
                     */

                    var phoneRows = [
                        {
                            phone:
                                cleanedMobile,

                            is_primary_mobile_no:
                                1,

                            is_primary_phone:
                                1
                        }
                    ];


                    /*
                     * ==================================================
                     * EMAIL CHILD ROW
                     * ==================================================
                     */

                    var emailRows =
                        [];


                    if(email){

                        emailRows.push({
                            email_id:
                                email,

                            is_primary:
                                1
                        });
                    }


                    /*
                     * ==================================================
                     * CREATE CONTACT
                     * ==================================================
                     */

                    var contactDoc = {

                        doctype:
                            'Contact',

                        first_name:
                            firstName,

                        designation:
                            designation,

                        mobile_no:
                            cleanedMobile,

                        phone:
                            cleanedMobile,

                        email_id:
                            email,

                        is_primary_contact:
                            isPrimary
                                ? 1
                                : 0,

                        links:[
                            {
                                link_doctype:
                                    'Supplier',

                                link_name:
                                    supplierName
                            }
                        ],

                        phone_nos:
                            phoneRows,

                        email_ids:
                            emailRows
                    };


                    var created =
                        await window
                        .LifeStockGateway
                        .invoke(
                            'frappe.client.insert',
                            {
                                doc:
                                    contactDoc
                            }
                        );


                    if(
                        !created ||
                        !created.name
                    ){

                        throw new Error(
                            'ERPNext did not return the created Contact.'
                        );
                    }


                    closeSupplierMasterModal();


                    if(
                        window.frappe &&
                        typeof frappe.show_alert ===
                        'function'
                    ){

                        frappe.show_alert({
                            message:
                                (
                                    isPrimary
                                        ? 'Primary contact added successfully.'
                                        : 'Contact added successfully.'
                                ),
                            indicator:
                                'green'
                        });
                    }


                    /*
                     * Refresh Vendor Contact / Address panel.
                     */
                    await loadSupplierContactAddressPanels(
                        supplierName
                    );

                }
                catch(error){

                    void 0;


                    supplierMasterShowError(
                        (
                            error &&
                            error.message
                        ) ||
                        'Unable to create Contact.'
                    );
                }
                finally{

                    saveButton.disabled =
                        false;


                    saveButton.textContent =
                        'Save Contact';
                }
            };
    }


    /*
     * ============================================================
     * INITIAL FOCUS
     * ============================================================
     */

    if(firstNameField){

        setTimeout(
            function(){

                firstNameField.focus();

            },
            50
        );
    }
}

