    /*
     * ============================================================
     * COUNTRY / STATE RULE
     *
     * ERP Address says State becomes mandatory when Country=India.
     * ============================================================
     */

    function refreshAddressStateRule(){

        var country =
            supplierMasterValue(
                'life-address-country'
            );


        var stateField =
            document.getElementById(
                'life-address-state'
            );


        var requiredMark =
            document.getElementById(
                'life-address-state-required'
            );


        var isIndia =
            String(
                country ||
                ''
            )
            .trim()
            .toLowerCase() ===
            'india';


        if(requiredMark){

            requiredMark.style.display =
                isIndia
                    ? ''
                    : 'none';
        }


        if(
            stateField &&
            !isIndia
        ){

            /*
             * For a non-India address we won't enforce the
             * Indian GST State list.
             */
            stateField.value =
                '';
        }
    }


    if(countryField){

        countryField.addEventListener(
            'change',
            refreshAddressStateRule
        );


        countryField.addEventListener(
            'input',
            refreshAddressStateRule
        );
    }


    refreshAddressStateRule();


    /*
     * ============================================================
     * SAVE
     * ============================================================
     */

    if(saveButton){

        saveButton.onclick =
            async function(event){

                if(event){

                    event.preventDefault();
                    event.stopPropagation();
                }


                supplierMasterClearError();


                var addressTitle =
                    supplierMasterValue(
                        'life-address-title'
                    ) ||
                    supplierName;


                var addressType =
                    supplierMasterValue(
                        'life-address-type'
                    );


                var line1 =
                    supplierMasterValue(
                        'life-address-line1'
                    );


                var line2 =
                    supplierMasterValue(
                        'life-address-line2'
                    );


                var city =
                    supplierMasterValue(
                        'life-address-city'
                    );


                var state =
                    supplierMasterValue(
                        'life-address-state'
                    );


                var country =
                    supplierMasterValue(
                        'life-address-country'
                    );


                var pincode =
                    supplierMasterValue(
                        'life-address-pincode'
                    );


                var gstCategory =
                    supplierMasterValue(
                        'life-address-gst-category'
                    );


                var gstin =
                    supplierMasterValue(
                        'life-address-gstin'
                    )
                    .toUpperCase();


                var email =
                    supplierMasterValue(
                        'life-address-email'
                    );


                var phone =
                    supplierMasterValue(
                        'life-address-phone'
                    );


                var isPrimary =
                    supplierMasterChecked(
                        'life-address-primary'
                    );


                var isShipping =
                    supplierMasterChecked(
                        'life-address-shipping'
                    );


                /*
                 * ----------------------------------------------------
                 * REQUIRED FIELDS
                 * ----------------------------------------------------
                 */

                if(!addressType){

                    supplierMasterShowError(
                        'Address Type is mandatory.'
                    );

                    return;
                }


                if(!line1){

                    supplierMasterShowError(
                        'Address Line 1 is mandatory.'
                    );

                    return;
                }


                if(!city){

                    supplierMasterShowError(
                        'City / Town is mandatory.'
                    );

                    return;
                }


                if(!country){

                    supplierMasterShowError(
                        'Country is mandatory.'
                    );

                    return;
                }


                if(
                    String(country)
                    .toLowerCase() ===
                    'india' &&
                    !state
                ){

                    supplierMasterShowError(
                        'State / Province is mandatory for India.'
                    );

                    return;
                }


                if(!gstCategory){

                    supplierMasterShowError(
                        'GST Category is mandatory.'
                    );

                    return;
                }


                /*
                 * ----------------------------------------------------
                 * EMAIL
                 * ----------------------------------------------------
                 */

                if(
                    email &&
                    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
                        email
                    )
                ){

                    supplierMasterShowError(
                        'Enter a valid Email Address.'
                    );

                    return;
                }


                /*
                 * ----------------------------------------------------
                 * GSTIN
                 * ----------------------------------------------------
                 */

                if(
                    gstin &&
                    gstin.length !== 15
                ){

                    supplierMasterShowError(
                        'GSTIN / UIN must contain exactly 15 characters.'
                    );

                    return;
                }


                /*
                 * Registered supplier should normally have GSTIN.
                 */
                if(
                    (
                        gstCategory ===
                        'Registered Regular' ||

                        gstCategory ===
                        'Registered Composition'
                    ) &&
                    !gstin
                ){

                    supplierMasterShowError(
                        'GSTIN / UIN is required for a registered GST category.'
                    );

                    return;
                }


                saveButton.disabled =
                    true;


                saveButton.textContent =
                    'Saving…';


                try{

                    /*
                     * ==================================================
                     * CREATE ADDRESS
                     * ==================================================
                     */

                    var addressDoc = {

                        doctype:
                            'Address',

                        address_title:
                            addressTitle,

                        address_type:
                            addressType,

                        address_line1:
                            line1,

                        address_line2:
                            line2,

                        city:
                            city,

                        state:
                            state,

                        country:
                            country,

                        pincode:
                            pincode,

                        gst_category:
                            gstCategory,

                        gstin:
                            gstin,

                        email_id:
                            email,

                        phone:
                            phone,

                        is_primary_address:
                            isPrimary
                                ? 1
                                : 0,

                        is_shipping_address:
                            isShipping
                                ? 1
                                : 0,

                        /*
                         * Link Address to this Supplier automatically.
                         */
                        links:[
                            {
                                link_doctype:
                                    'Supplier',

                                link_name:
                                    supplierName
                            }
                        ]
                    };


                    var created =
                        await window
                        .LifeStockGateway
                        .invoke(
                            'frappe.client.insert',
                            {
                                doc:
                                    addressDoc
                            }
                        );


                    if(
                        !created ||
                        !created.name
                    ){

                        throw new Error(
                            'ERPNext did not return the created Address.'
                        );
                    }


                    closeSupplierMasterModal();


                    if(
                        window.frappe &&
                        typeof frappe.show_alert ===
                        'function'
                    ){

                        frappe.show_alert({
                            message:
                                'Address added successfully.',
                            indicator:
                                'green'
                        });
                    }


                    /*
                     * Reload Contact + Address section.
                     */
                    await loadSupplierContactAddressPanels(
                        supplierName
                    );

                }
                catch(error){

                    void 0;


                    supplierMasterShowError(
                        (
                            error &&
                            error.message
                        ) ||
                        'Unable to create Address.'
                    );

                }
                finally{

                    saveButton.disabled =
                        false;


                    saveButton.textContent =
                        'Save Address';
                }
            };
    }


    /*
     * Initial focus.
     */
    if(line1Field){

        setTimeout(
            function(){

                line1Field.focus();

            },
            50
        );
    }
}


function openSupplierLedger(name){
showViewModal('📊 Ledger — '+esc(name),'<div class="notice notice-blue">⏳ Loading ledger…</div>');
callList('GL Entry',{
fields:['posting_date','account','debit','credit','voucher_type','voucher_no','against','remarks'],filters:{
party_type:'Supplier',party:name,is_cancelled:0}
,order_by:'posting_date asc, creation asc',limit:0}
).then(function(rows){
var bal=0,totDr=0,totCr=0;
rows.forEach(function(r){
bal+=(Number(r.credit)||0)-(Number(r.debit)||0);
}
);
var running=0;
var body=rows.map(function(r){
var dr=Number(r.debit)||0,cr=Number(r.credit)||0;
totDr+=dr;
totCr+=cr;
running+=(cr-dr);
return'<tr><td>'+displayDate(r.posting_date)+'</td>'+'<td style="font-size:10px">'+esc(r.voucher_type)+'<br>'+'<a href="/app/'+esc((r.voucher_type||'').toLowerCase().replace(/ /g,'-'))+'/'+encodeURIComponent(r.voucher_no)+'" target="_blank" rel="noopener">'+esc(r.voucher_no)+'</a></td>'+'<td style="text-align:right">'+(dr?money(dr):'')+'</td>'+'<td style="text-align:right">'+(cr?money(cr):'')+'</td>'+'<td style="text-align:right;font-weight:700;color:'+(running>=0?'#C00000':'#1E7A34')+'">'+money(Math.abs(running))+(running>=0?' Cr':' Dr')+'</td></tr>';
}
).join('');
var payable=bal;
var html='<div class="tiles" style="margin-bottom:12px">'+'<div class="tile t-pn"><div class="tl">Total Debit (paid/adj)</div><div class="tv tv-n">'+money(totDr)+'</div></div>'+'<div class="tile t-pn"><div class="tl">Total Credit (billed)</div><div class="tv tv-n">'+money(totCr)+'</div></div>'+'<div class="tile '+(payable>0?'t-pr':'t-pgr')+'"><div class="tl">Closing Balance</div><div class="tv" style="color:'+(payable>0?'#C00000':'#1E7A34')+'">'+money(Math.abs(payable))+(payable>=0?' Cr':' Dr')+'</div><div class="ts">'+(payable>0?'payable to vendor':'no dues')+'</div></div>'+'</div>'+(rows.length?'<div class="tbl-wrap" style="max-height:52vh;overflow:auto"><table><thead><tr><th>Date</th><th>Voucher</th><th style="text-align:right">Debit</th><th style="text-align:right">Credit</th><th style="text-align:right">Balance</th></tr></thead><tbody>'+body+'</tbody></table></div>':'<div class="notice notice-blue">No ledger entries for this supplier.</div>')+'<div style="margin-top:10px"><a class="btn btn-gy btn-sm" href="/app/query-report/General Ledger?party_type=Supplier&party='+encodeURIComponent(name)+'&company='+encodeURIComponent(COMPANY)+'" target="_blank" rel="noopener">Open full General Ledger on portal →</a></div>';
byId('ls-view-modal-content').innerHTML='<div class="mtt" style="margin-bottom:10px">📊 Ledger — '+esc(name)+'</div>'+html;
}
).catch(function(e){
byId('ls-view-modal-content').innerHTML='<div class="notice notice-red"><strong>Error:</strong> '+esc((e&&e.message)||'Failed to load ledger.')+'</div>';
}
);
}
var MATERIAL_OPTIONS=['General','Skin','Hair','Machinery','Surgicals','Electronics','Stationery','Gadgets','IT Equipment','Printing','Courier Service','Machinery Service','AMC','CCTV Service','Interior Works'];
function setVendorFormValue(id,value){
var field=byId(id);
if(!field){
return;
}
var normalized=value===undefined||value===null?'':String(value);
if(field.tagName==='SELECT'&&normalized){
var exists=Array.prototype.some.call(field.options,function(option){
return String(option.value)===normalized;
});
if(!exists){
var option=document.createElement('option');
option.value=normalized;
option.textContent=normalized;
field.appendChild(option);
}
}
field.value=normalized;
}
