        doc.custom_with_life_from
            ? String(
                doc.custom_with_life_from
            ).slice(0,10)
            : ''
    );


    setVendorFormValue(
        'ls-v-payment',
        doc.custom_payment_methods ||
        ''
    );


    setVendorFormValue(
        'ls-v-altvendors',
        doc.custom_alternative_vendors ||
        ''
    );


    var selectedMaterials =
        String(
            doc.custom_materials_provided ||
            ''
        )
        .split(',')
        .map(function(value){

            return value.trim();

        })
        .filter(Boolean);


    var normalizedOptions =
        MATERIAL_OPTIONS.map(
            function(value){

                return value.toLowerCase();

            }
        );


    VENDOR_FORM_EXTRA_MATERIALS =
        selectedMaterials.filter(
            function(value){

                return (
                    normalizedOptions.indexOf(
                        value.toLowerCase()
                    ) === -1
                );

            }
        );


    var selectedLookup =
        selectedMaterials.reduce(
            function(map,value){

                map[
                    value.toLowerCase()
                ] = true;

                return map;

            },
            {}
        );


    $all(
        '.ls-v-material'
    )
    .forEach(function(checkbox){

        checkbox.checked =
            !!selectedLookup[
                String(
                    checkbox.value ||
                    ''
                ).toLowerCase()
            ];

    });


    var extraNote =
        byId(
            'ls-v-material-extra-note'
        );


    if(extraNote){

        extraNote.innerHTML =
            VENDOR_FORM_EXTRA_MATERIALS.length

            ? (
                '<div class="notice notice-blue">' +
                    'Other saved material values will be preserved: ' +
                    '<strong>' +
                        esc(
                            VENDOR_FORM_EXTRA_MATERIALS.join(
                                ', '
                            )
                        ) +
                    '</strong>' +
                '</div>'
            )

            : '';

    }
}
