function saveNewVendor(){

    var msg =
        byId(
            'ls-vendor-msg'
        );


    var nameField =
        byId(
            'ls-v-name'
        );


    var nm =
        nameField
            ? String(
                nameField.value ||
                ''
            )
            : '';


    if(!nm.trim()){

        if(msg){

            msg.innerHTML =
                '<div class="notice notice-red">' +
                    'Vendor name is required.' +
                '</div>';

        }

        return;
    }


    var checkedMaterials =
        $all(
            '.ls-v-material'
        )
        .filter(function(c){

            return c.checked;

        })
        .map(function(c){

            return c.value;

        });


    var materials =
        checkedMaterials
        .concat(
            VENDOR_FORM_EXTRA_MATERIALS ||
            []
        )
        .filter(
            function(
                value,
                index,
                array
            ){

                var normalized =
                    String(
                        value ||
                        ''
                    )
                    .trim()
                    .toLowerCase();


                if(!normalized){

                    return false;

                }


                return (
                    array.findIndex(
                        function(other){

                            return (
                                String(
                                    other ||
                                    ''
                                )
                                .trim()
                                .toLowerCase() ===
                                normalized
                            );

                        }
                    ) ===
                    index
                );

            }
        )
        .join(', ');


    function v(id){

        var el =
            byId(id);

        return el
            ? String(
                el.value ||
                ''
            ).trim()
            : '';

    }


    var isEdit =
        !!(
            VENDOR_FORM_EDIT_DOC &&
            VENDOR_FORM_EDIT_DOC.name
        );


    var doc =
        isEdit
            ? VENDOR_FORM_EDIT_DOC
            : {
                doctype:
                    'Supplier'
            };


    /*
     * Supplier MASTER fields only.
     *
     * Contact numbers, emails and physical addresses
     * are NOT stored from this form anymore.
     */
    var values = {

        supplier_name:
            nm.trim(),

        supplier_type:
            v(
                'ls-v-type'
            ) ||
            'Company',

        supplier_group:
            v(
                'ls-v-group'
            ),

        gst_category:
            v(
                'ls-v-gstcat'
            ) ||
            'Unregistered',

        gstin:
            v(
                'ls-v-gstin'
            ),

        pan:
            v(
                'ls-v-pan'
            ),

        custom_branch:
            v(
                'ls-v-branch'
            ),

        custom_area_manager:
            v(
                'ls-v-area'
            ),

        custom_dealer_number:
            v(
                'ls-v-dealer'
            ),

        custom_relation_manager:
            v(
                'ls-v-rm'
            ),

        custom_bank_name:
            v(
                'ls-v-bank'
            ),

        custom_account_number:
            v(
                'ls-v-acct'
            ),

        custom_ifsc_code:
            v(
                'ls-v-ifsc'
            ),

        custom_bank_branch:
            v(
                'ls-v-bankbranch'
            ),

        custom_with_life_from:
            v(
                'ls-v-lifefrom'
            ),

        custom_payment_methods:
            v(
                'ls-v-payment'
            ),

        custom_materials_provided:
            materials,

        custom_alternative_vendors:
            v(
                'ls-v-altvendors'
            )
    };


    /*
     * Do not clear existing old Supplier contact fields.
     *
     * We simply stop editing them.
     */
    Object.keys(
        values
    )
    .forEach(function(fieldname){

        doc[fieldname] =
            values[fieldname];

    });


    if(!isEdit){

        doc.default_currency =
            'INR';

        doc.country =
            'India';

    }


    if(
        typeof frappe ===
        'undefined' ||
        !frappe.call
    ){

        if(msg){

            msg.innerHTML =
                '<div class="notice notice-red">' +
                    'Saving vendors only works inside the portal.' +
                '</div>';

        }

        return;
    }


    if(msg){

        msg.innerHTML =
            '<div class="notice notice-blue">' +

                '⏳ ' +

                (
                    isEdit
                        ? 'Updating'
                        : 'Creating'
                ) +

                ' vendor…' +

            '</div>';

    }


    var btn =
        byId(
            'ls-vendor-save'
        );


    if(btn){

        btn.disabled =
            true;

    }


    var vendorSaveMethod;
    var vendorSaveArgs;


    if(isEdit){

        vendorSaveMethod =
            'frappe.client.set_value';


        vendorSaveArgs = {

            doctype:
                'Supplier',

            name:
                doc.name,

            fieldname:
                values
        };

    }
    else{

        vendorSaveMethod =
            'frappe.client.insert';


        vendorSaveArgs = {
            doc:
                doc
        };

    }


    window.LifeStockGateway.compat({

        method:
            vendorSaveMethod,

        args:
            vendorSaveArgs,


        callback:
            function(r){

                if(btn){

                    btn.disabled =
                        false;

                }


                var savedDoc =
                    (
                        r &&
                        r.message
                    ) ||
                    doc;


                var savedName =
                    savedDoc.name ||
                    doc.name ||
                    nm;


                if(msg){

                    msg.innerHTML =
                        '<div class="notice notice-green">' +

                            '✓ Vendor ' +

                            (
                                isEdit
                                    ? 'updated'
                                    : 'created'
                            ) +

                            ': <strong>' +

                                esc(
                                    savedName
                                ) +

                            '</strong>' +

                        '</div>';

                }


                SUPPLIER_PAY_CACHE =
                    null;


                SUPPLIER_OPTS_CACHE =
                    null;


                ACTIVE_SUPPLIER_DETAIL_DOC =
                    savedDoc;


                showModal(
                    '✅',
                    isEdit
                        ? 'Vendor Updated'
                        : 'Vendor Created',
                    savedName +
                    (
                        isEdit
                            ? ' has been updated.'
                            : ' has been added.'
                    )
                );


                setTimeout(
                    function(){

                        var wrap =
                            byId(
                                'ls-vendor-form-wrap'
                            );


                        if(wrap){

                            wrap.remove();

                        }


                        VENDOR_FORM_EDIT_DOC =
                            null;


                        VENDOR_FORM_EXTRA_MATERIALS =
                            [];


                        renderSuppliers();

                    },
                    700
                );

            },


        error:
            function(e){

                if(btn){

                    btn.disabled =
                        false;

                }


                var fallback =
                    isEdit

                    ? (
                        'Could not update this vendor. ' +
                        'Check Supplier write permission and the configured custom fields.'
                    )

                    : (
                        'Could not create this vendor. ' +
                        'Check Supplier create permission and the configured custom fields.'
                    );


                var m =
                    (
                        e &&
                        (
                            e.message ||
                            e._server_messages
                        )
                    ) ||
                    fallback;


                if(msg){

                    msg.innerHTML =
                        '<div class="notice notice-red">' +

                            '✕ ' +

                            esc(m) +

                        '</div>';

                }

            }
    });
}
