ROOT.addEventListener(
    "input",
    function (ev) {
        var inp = ev.target;

        if (
            !inp ||
            !inp.getAttribute
        ) {
            return;
        }

        /*
         * Physical quantity entry must be handled first.
         */
        if (
            inp.getAttribute(
                "data-chk-input"
            ) !== null &&
            inp.classList.contains(
                "ls-chk-input"
            )
        ) {
            onChecklistInput(
                inp.getAttribute(
                    "data-chk-input"
                ),
                inp.value
            );

            return;
        }

        /*
         * Branch dashboard Low / Out of Stock search.
         */
        if (
            inp.id ===
            "ls-branch-low-stock-search"
        ) {
            lifeFilterBranchLowStockList(
                inp.value
            );

            return;
        }

        /*
         * Stock Balance search.
         */
        if (
            inp.id ===
            "ls-stock-balance-search"
        ) {
            lifeFilterStockBalance(
                inp.value
            );

            return;
        }

        if (inp.getAttribute("data-sr-filter") === "branch" && inp.getAttribute("data-sr-scope") === "manager") {
            LIFE_SR_MANAGER_FILTERS.branch = inp.value || "";
            lifeSRLoadList("manager");
            return;
        }

        /*
         * Physical Check List search.
         */
        if (
            inp.id ===
            "ls-checklist-search"
        ) {
            lifeFilterChecklist(
                inp.value
            );

            return;
        }

        /*
         * Branch Reports search.
         */
        if (
            inp.id ===
            "ls-branch-report-search"
        ) {
            lifeFilterBranchReports(
                inp.value
            );

            return;
        }

        if (inp.id === 'ls-tax-template') {
            lifeFormSearchTaxTemplate(inp.value);
            return;
        }

        /*
         * Existing searchable-select inputs.
         */
        if (
            inp.getAttribute(
                "data-ss-input"
            ) !== null
        ) {
            SS.onInput(
                inp.getAttribute(
                    "data-ss-input"
                ),
                inp.value
            );

            return;
        }

        /*
         * Existing Supplier search.
         */
        if (
            inp.id ===
            "ls-sup-search"
        ) {
            filterSuppliers(
                inp.value
            );
        }
    }
