async function initApp() {
    populateViewSelector();
    wireEvents();

    /*
     * Resolve the live Branch -> Warehouse mapping before any branch
     * filter, branch-view resolution, or Bin aggregation runs.
     * The loader is fail-safe and restores the original hardcoded map
     * if Branch/Warehouse fetching is unavailable for any reason.
     */
    await loadLifeDynamicBranchWarehouseMapping();
    populateHoFilters();

    /*
     * Load User.roles before deciding whether the
     * Branch / Stock Manager switch should be shown.
     */
    await loadLoggedInUserRoles();

    var noViewMessage =
        byId("ls-no-view-msg");

    var isSystemManager =
        loggedInUserIsSystemManager();

    var isStockManager =
        loggedInUserIsStockManager();

    var hasStockManagerViewAccess =
        loggedInUserHasStockManagerViewAccess();

    var branchCode = "";

    /*
     * Resolve the user's normal branch for everyone.
     *
     * Normal user:
     *   used for Branch View.
     *
     * Stock Manager:
     *   used only to allow returning to their own Branch View.
     *
     * System Manager:
     *   may use the mapped branch, and may also choose any branch
     *   from the branch picker.
     */
    if (
        noViewMessage &&
        !hasStockManagerViewAccess
    ) {
        noViewMessage.style.display = "block";
        noViewMessage.textContent =
            "Loading the branch assigned to the logged-in employee…";
    }

    branchCode =
        await resolveLoggedInBranchCode();

    /*
     * Saved arbitrary branch selection belongs only to System Manager.
     */
    if (
        isSystemManager &&
        !branchCode
    ) {
        branchCode =
            getSavedSystemManagerBranchCode();
    }

    systemManagerBranchCode =
        branchCode || "";

    configureSystemManagerViewSwitch(
        hasStockManagerViewAccess
            ? branchCode
            : ""
    );

    /*
     * Default view:
     *
     * Stock Manager role:
     *   always opens Stock Manager / HO View.
     *
     * System Manager only:
     *   opens mapped Branch View when available; otherwise HO View.
     *
     * Both roles:
     *   opens Stock Manager / HO View.
     *
     * No manager role:
     *   opens only the user's mapped Branch View.
     */
    if (isStockManager) {
        applyResolvedView("HO");
    } else if (isSystemManager) {
        if (branchCode) {
            applyResolvedView(
                branchCode
            );
        } else {
            applyResolvedView("HO");
        }
    } else if (branchCode) {
        applyResolvedView(
            branchCode
        );
    } else {
        currentView = "";

        byId("ls-branch-nav").style.display = "flex";
        byId("ls-ho-nav").style.display = "none";

        byId("ls-branch-modes").style.display = "block";
        byId("ls-ho-modes").style.display = "none";

        if (noViewMessage) {
            noViewMessage.style.display = "block";

            noViewMessage.innerHTML =
                "<strong>Branch mapping is missing.</strong> " +
                "Set an active Employee.branch or Branch User Permission for " +
                esc(loggedInUserId()) +
                ". The Material Requests tab can still use its own Employee context.";
        }

        showBranchMode(6);
    }


    /* ============================================================
       BILLING → STOCK DASHBOARD MATERIAL REQUESTS DEEP LINK
       ============================================================ */

    try {

        var lifeStockParams =
            new URLSearchParams(
                window.location.search || ""
            );

        /*
         * Billing redirects here using:
         *
         * /stock-dashboard?material_requests=1
         *
         * When present, force the branch Material Requests tab
         * AFTER the normal dashboard view has been resolved.
         */
        if (
            lifeStockParams.get(
                "material_requests"
            ) === "1"
        ) {

            var branchNav =
                byId("ls-branch-nav");

            var branchModes =
                byId("ls-branch-modes");

            /*
             * Only open branch Material Requests when the
             * logged-in user is currently in Branch View.
             */
            if (
                branchNav &&
                branchModes &&
                branchNav.style.display !== "none"
            ) {

                showBranchMode(6);

                /*
                 * Scroll to the top so Material Requests starts
                 * cleanly from the top of the screen.
                 */
                window.setTimeout(
                    function () {
                        window.scrollTo({
                            top: 0,
                            left: 0,
                            behavior: "auto"
                        });
                    },
                    100
                );
            }
        }

    } catch (lifeStockDeepLinkError) {

        void 0;
    }


    loadItems().catch(function () {
        /* Existing non-blocking preload behaviour. */
    });
}
if(document.readyState==='loading'){
document.addEventListener('DOMContentLoaded',initApp);
}
else{
initApp();
}
}
