/* =====================================================================
   LIFE SSR — ZERO-VALUATION LEGACY ITEM RESOLVER
   Build: 2026-10-02

   Some Therapy Types still point to an older Item code whose stock
   valuation is zero, even though an active replacement Item exists with
   the exact same Item Name and a real positive valuation.

   Example seen in ERP:
       CN-CFK -> "Cosmelan Full Kit" -> valuation unavailable
       D-CFK  -> "Cosmelan Full Kit" -> active replacement

   Safety rules:
   - Exact Item Name match only.
   - Replacement must be enabled.
   - Replacement must be a Stock Item.
   - Services / Assets are never used.
   - Replacement must have a positive inventory valuation.
   - Auto-map only when ONE unique valid replacement exists.
   ===================================================================== */

async function lifeResolveSSRZeroValuationItems(
    selections,
    missingItemCodes,
    valueInfo
){
    selections = Array.isArray(selections) ? selections : [];
    missingItemCodes = Array.isArray(missingItemCodes)
        ? missingItemCodes
        : [];

    if(!missingItemCodes.length){
        return {
            changed:false,
            replacements:[]
        };
    }

    var missingSet = Object.create(null);

    missingItemCodes.forEach(function(code){
        code = String(code || "").trim();
        if(code){
            missingSet[code] = true;
        }
    });

    var refs = [];

    selections.forEach(function(selection){
        (
            selection &&
            Array.isArray(selection.stocks)
                ? selection.stocks
                : []
        ).forEach(function(stock){

            var code = String(
                stock && stock.item_code || ""
            ).trim();

            if(!code || !missingSet[code]){
                return;
            }

            var itemName = String(
                stock.item_name ||
                (
                    valueInfo &&
                    valueInfo.itemNames &&
                    valueInfo.itemNames[code]
                ) ||
                ""
            ).trim();

            refs.push({
                stock:stock,
                old_code:code,
                item_name:itemName
            });
        });
    });

    if(!refs.length){
        return {
            changed:false,
            replacements:[]
        };
    }

    var replacements = [];

    for(var index=0; index<refs.length; index+=1){

        var ref = refs[index];

        if(!ref.item_name){
            void 0;
            continue;
        }

        var candidates = [];

        try{
            candidates = await safeGetList(
                "Item",
                [
                    [
                        "name",
                        "item_code",
                        "item_name",
                        "stock_uom",
                        "item_group",
                        "is_stock_item",
                        "disabled",
                        "valuation_rate",
                        "last_purchase_rate",
                        "standard_rate"
                    ],
                    [
                        "name",
                        "item_code",
                        "item_name",
                        "stock_uom",
                        "item_group",
                        "is_stock_item",
                        "disabled",
                        "valuation_rate",
                        "last_purchase_rate"
                    ],
                    [
                        "name",
                        "item_code",
                        "item_name",
                        "stock_uom",
                        "item_group",
                        "is_stock_item",
                        "disabled"
                    ]
                ],
                [
                    ["item_name","=",ref.item_name],
                    ["disabled","=",0],
                    ["is_stock_item","=",1]
                ],
                {
                    order_by:"name asc",
                    limit_page_length:50
                }
            );
        }
        catch(candidateError){
            void 0;
            continue;
        }

        candidates = (
            Array.isArray(candidates)
                ? candidates
                : []
        ).filter(function(item){

            var code = String(
                item.item_code ||
                item.name ||
                ""
            ).trim();

            return (
                code &&
                code !== ref.old_code &&
                num(item.disabled,0) !== 1 &&
                num(item.is_stock_item,0) === 1 &&
                !isExcludedRequestItemGroup(
                    item.item_group
                )
            );
        });

        if(!candidates.length){
            void 0;
            continue;
        }

        /*
         * Determine which exact-name candidates have a real positive
         * inventory valuation. This reuses the same valuation logic as
         * the final request.
         */
        var candidateCodes = candidates.map(function(item){
            return String(
                item.item_code ||
                item.name ||
                ""
            ).trim();
        }).filter(Boolean);

        var valuationResults = await Promise.all([
            loadStockBalanceRows(candidateCodes)
                .catch(function(error){
                    void 0;
                    return [];
                }),
            loadSSRItemMasterValuations(candidateCodes)
                .catch(function(error){
                    void 0;
                    return [];
                })
        ]);

        var stockRows = Array.isArray(valuationResults[0])
            ? valuationResults[0]
            : [];

        var masterRows = Array.isArray(valuationResults[1])
            ? valuationResults[1]
            : [];

        var sourceWarehouse = String(
            state.sourceWarehouse || ""
        ).trim().toLowerCase();

        var masterByCode = Object.create(null);

        masterRows.forEach(function(row){
            var code = String(
                row.item_code ||
                row.name ||
                ""
            ).trim();

            if(code){
                masterByCode[code] = row;
            }
        });

        var valuedCandidates = [];

        candidates.forEach(function(item){

            var code = String(
                item.item_code ||
                item.name ||
                ""
            ).trim();

            var rowsForItem = stockRows.filter(function(row){
                return String(
                    row.item_code || ""
                ).trim() === code;
            });

            var sourceRow = rowsForItem.find(function(row){
                return (
                    String(
                        row.warehouse || ""
                    ).trim().toLowerCase() === sourceWarehouse &&
                    ssrPositiveValuationRate(row) > 0
                );
            });

            var anyStockRow = rowsForItem.find(function(row){
                return ssrPositiveValuationRate(row) > 0;
            });

            var masterRow = masterByCode[code] || item;

            var rate = 0;
            var source = "";

            if(sourceRow){
                rate = ssrPositiveValuationRate(sourceRow);
                source = "Source Warehouse Stock Balance";
            }
            else if(anyStockRow){
                rate = ssrPositiveValuationRate(anyStockRow);
                source = "Other Warehouse Stock Balance";
            }
            else if(masterRow){
                rate = ssrPositiveValuationRate(masterRow);

                source =
                    num(masterRow.valuation_rate,0) > 0
                        ? "Item Valuation Rate"
                        : num(masterRow.last_purchase_rate,0) > 0
                        ? "Item Last Purchase Rate"
                        : num(masterRow.standard_rate,0) > 0
                        ? "Item Standard Rate"
                        : "";
            }

            if(rate > 0){
                valuedCandidates.push({
                    item:item,
                    rate:rate,
                    source:source
                });
            }
        });

        /*
         * Only one exact-name positively-valued candidate is safe to
         * auto-map. If there are multiple, leave it unresolved rather
         * than silently choosing the wrong material.
         */
        if(valuedCandidates.length !== 1){

            void 0;

            continue;
        }

        var chosen = valuedCandidates[0];
        var chosenItem = chosen.item;

        var newCode = String(
            chosenItem.item_code ||
            chosenItem.name ||
            ""
        ).trim();

        ref.stock.item_code = newCode;
        ref.stock.item_name = String(
            chosenItem.item_name ||
            newCode
        ).trim();

        ref.stock.stock_uom = String(
            chosenItem.stock_uom ||
            ref.stock.stock_uom ||
            "Nos"
        ).trim();

        ref.stock.item_group = String(
            chosenItem.item_group ||
            ref.stock.item_group ||
            ""
        ).trim();

        ref.stock.disabled = 0;
        ref.stock.is_stock_item = 1;

        replacements.push({
            old_code:ref.old_code,
            new_code:newCode,
            item_name:ref.stock.item_name,
            valuation_rate:chosen.rate,
            valuation_source:chosen.source
        });

        void 0;
    }

    return {
        changed:replacements.length > 0,
        replacements:replacements
    };
}

