);
}
);
var fallbackStockRow=itemRows.find(function(row){
return(ssrPositiveValuationRate(row)>0);
}
);
var itemMasterRow=itemMasterByCode[itemCode]||null;
var selectedRate=0;
var selectedSource="";
if(sourceRow){
selectedRate=ssrPositiveValuationRate(sourceRow);
selectedSource="Source Warehouse Stock Balance";
}
else if(fallbackStockRow){
