:num(itemMasterRow.last_purchase_rate,0)>0
?"Item Last Purchase Rate"
:num(itemMasterRow.standard_rate,0)>0
?"Item Standard Rate"
:"";
}
valuationRates[itemCode]=num(selectedRate,0);
valuationSources[itemCode]=selectedSource;
}
);
var totalAmount=requestedItems.reduce(function(total,row){
