function switchViewMode(mode) {
    var integratedForcedView =
        getIntegratedForcedView();

    if (integratedForcedView) {
        mode = integratedForcedView;
    }

    var normalizedMode =
        mode === "ho"
            ? "ho"
            : "branch";

    var previousView =
        state.currentView === "ho"
            ? "ho"
            : "branch";

    var previousPage =
        String(
            state.currentPage || "home"
        ).trim();

    var previousBranch =
        String(
            state.branch || ""
        ).trim();

    /*
     * Apply mode locally.
     */
    applyIntegratedRootMode(
        normalizedMode
    );

    /*
     * Resolve branch from host dashboard.
     */
    var hostContext =
        typeof synchronizeEmbeddedBranchFromHost ===
            "function"
            ? synchronizeEmbeddedBranchFromHost()
            : null;

    var nextBranch =
        normalizedMode === "branch"
            ? String(
                (
                    hostContext &&
                    hostContext.branch_name
                ) ||
                state.branch ||
                ""
            ).trim()
            : "";

    var branchChanged =
        normalizedMode === "branch" &&
        previousView === "branch" &&
        !!previousBranch &&
        !!nextBranch &&
        previousBranch !== nextBranch;

    var sameMode =
        previousView === normalizedMode;

    var preserveCurrentPage =
        sameMode &&
        !branchChanged &&
        (
            normalizedMode === "ho"
                ? previousPage === "ho-approval"
                : [
                    "home",
                    "monthly-indent",
                    "ssr",
                    "asbr",
                    "report"
                ].indexOf(
                    previousPage
                ) !== -1
        );

    /*
     * =====================================================
     * LOCAL REPLACEMENT FOR
     * lifePrepareMaterialRequestModuleView()
     * =====================================================
     *
     * Do not call the outer-scope helper from here.
     */
    var integratedRoot =
        resolveRoot();

    if (integratedRoot) {
        integratedRoot.dataset.forcedView =
            normalizedMode;

        integratedRoot.classList.toggle(
            "life-integrated-forced-ho",
            normalizedMode === "ho"
        );

        integratedRoot.classList.toggle(
            "life-integrated-forced-branch",
            normalizedMode === "branch"
        );

        /*
         * Only clear/change active pages when this is
         * an actual mode/branch change.
         */
        if (!preserveCurrentPage) {
            Array.prototype.forEach.call(
                integratedRoot.querySelectorAll(
                    ".page"
                ),
                function (pageElement) {
                    pageElement.classList.remove(
                        "active"
                    );
                }
            );

            var targetElement =
                integratedRoot.querySelector(
                    normalizedMode === "ho"
                        ? "#page-ho-approval"
                        : "#page-home"
                );

            if (targetElement) {
                targetElement.classList.add(
                    "active"
                );
            }
        }
    }

    /*
     * Update module state.
     */
    state.currentView =
        normalizedMode;

    if (
        normalizedMode === "branch" &&
        nextBranch
    ) {
        state.branch =
            nextBranch;
    }

    /*
     * Synchronize hidden view selector.
     */
    var selector =
