function lifeTableSortRows(rows,key,direction,valueGetter){
var sorted=Array.isArray(rows)?rows.slice():[];
var multiplier=String(direction||"desc")==="asc"?1:-1;
sorted.sort(function(left,right){
var leftValue=valueGetter(left,key);
var rightValue=valueGetter(right,key);
if(typeof leftValue==="number"||typeof rightValue==="number"){
leftValue=Number(leftValue)||0;
rightValue=Number(rightValue)||0;
if(leftValue===rightValue){
return 0;
}
return(leftValue<rightValue?-1:1)*multiplier;
}
return lifeTableTextCompare(leftValue,rightValue)*multiplier;
});
return sorted;
}
