function getFilteredHomeRecentRows(){
/*
 * MY BRANCH — RECENT REQUESTS
 * ---------------------------
 * This list must show ALL Material Request types raised for the branch:
 * - Monthly Indent Request
 * - Consumable / Special Material Request
 * - Advance Material Request
 * - Any other valid Material Request type
 *
 * Client-linked-only filtering belongs only in Sent Material /
 * Session Tracking, not in the branch Recent Requests list.
 */
var rows=
Array.isArray(state.requests)
?state.requests.slice()
:[];
var query=lifeTableNormalize(lifeHomeRecentTableState.search);
rows=rows.filter(function(row){
var type=requestType(row);
var branch=lifeHomeRequestBranch(row);
var requestedBy=lifeHomeRequestRequestedBy(row);
