return false;
}
if(lifeHomeRecentTableState.status&&status!==lifeHomeRecentTableState.status){
return false;
}
if(!query){
return true;
}
var searchText=lifeTableNormalize([
row.name,
type,
getHomeClientLabel(row),
branch,
requestedBy,
status,
formatDateTime(row.creation||row.modified||row.transaction_date),
formatDate(row.schedule_date)
].join(" "));
return searchText.indexOf(query)>=0;
});
return lifeTableSortRows(
rows,
lifeHomeRecentTableState.sortKey,
lifeHomeRecentTableState.sortDir,
function(row,key){
if(key==="expected_date"){
return lifeTableDateValue(row&&row.schedule_date);
}
return lifeTableDateValue(row&&row.creation||row&&row.modified||row&&row.transaction_date);
}
);
}
