function lifeReturnAfterMonthlyIndentSuccess(){
/*
 * Deterministic post-submit navigation:
 * 1. Close success modal.
 * 2. Reset Monthly Indent state.
 * 3. Force this embedded Material Request module to Branch mode.
 * 4. Leave Monthly Indent immediately via showPage("home").
 * 5. Synchronise the host Branch / Stock Manager toggle afterwards.
 *
 * The previous version clicked the host Branch button first. The host mount
 * logic intentionally preserves an already-open valid Branch request page,
 * so it could preserve "monthly-indent" while the reset helper had already
 * emptied its body — resulting in the blank page seen by the user.
 */
if(typeof closeModal==="function"){
closeModal();
}

lifeResetMonthlyIndentFormState();

try{
applyIntegratedRootMode("branch");
state.currentView="branch";

/*
 * Leave Monthly Indent NOW. This also clears monthly-indent-page-body through
 * showPage()'s normal previousPage cleanup, after the Home page is activated.
 */
showPage("home");
}
catch(error){
void 0;
}

/*
 * Keep the outer dashboard view switch in sync for System Manager users.
 * Run this after the embedded page has already returned Home so the host's
 * page-preservation logic preserves Home, not Monthly Indent.
 */
window.setTimeout(function(){
try{
var headerSwitch=byId("ls-header-view-switch");
var branchButton=
headerSwitch&&typeof headerSwitch.querySelector==="function"
?headerSwitch.querySelector('[data-stock-view="branch"]')
:null;

if(branchButton&&typeof branchButton.click==="function"){
branchButton.click();
}
else if(
window.LifeMaterialRequestModule&&
typeof window.LifeMaterialRequestModule.setView==="function"
){
Promise.resolve(
window.LifeMaterialRequestModule.setView("branch")
)
.catch(function(error){
void 0;
});
}
}
catch(error){
void 0;
}
},80);

/*
 * Final safety repaint after host synchronisation.
 */
window.setTimeout(function(){
try{
applyIntegratedRootMode("branch");
state.currentView="branch";
showPage("home");
}
catch(error){
void 0;
}
},220);
}

