            Array.isArray(rows)
                ? rows
                : []
        ).forEach(function (row) {

            if (!row) {
                return;
            }

            var name =
                String(
                    row.name ||
                    row.id ||
                    ""
                ).trim();

            if (!name) {
                return;
            }

            /*
             * Any request rejected during this browser session
             * must stay Rejected even if a delayed API response
             * still returns Pending.
             */
            var safeRow =
                lifeForceRejectedRequestRow(
                    row
                );

            if (
                indexByName[name] ===
                undefined
            ) {
                indexByName[name] =
                    merged.length;

                merged.push(
                    safeRow
                );

                return;
            }

            var existingIndex =
                indexByName[name];

            var existing =
                merged[existingIndex] || {};

            /*
             * Merge later/hydrated information onto the
             * existing row.
             */
            var combined =
                Object.assign(
                    {},
                    existing,
                    safeRow
                );

            /*
             * Apply reject protection one more time AFTER
             * merging because a later response may carry
             * Pending values.
             */
            merged[existingIndex] =
                lifeForceRejectedRequestRow(
                    combined
                );
        });
    });

    return merged;
}

function lifeMarkRequestLocallyRejected(requestName) {
    var name =
        String(
            requestName || ""
        ).trim();

    if (!name) {
        return;
    }

    LIFE_LOCALLY_REJECTED_REQUESTS[name] = {
        rejected_at: Date.now()
    };
}


function lifeUnmarkRequestLocallyRejected(requestName) {
    var name =
        String(
            requestName || ""
        ).trim();

    if (!name) {
        return;
    }

    delete LIFE_LOCALLY_REJECTED_REQUESTS[name];
}


function lifeIsRequestLocallyRejected(requestName) {
    var name =
        String(
            requestName || ""
        ).trim();

    if (!name) {
        return false;
    }

    return !!LIFE_LOCALLY_REJECTED_REQUESTS[name];
}


function lifeForceRejectedRequestRow(row) {
    if (!row) {
        return row;
    }

    var name =
        String(
            row.name ||
            row.id ||
            ""
        ).trim();

    if (
        !name ||
        !lifeIsRequestLocallyRejected(name)
    ) {
        return row;
    }

    /*
     * Force every status field used by
     * hoManagerStatusGroup().
     */
    return Object.assign(
        {},
        row,
        {
            workflow_state: "Rejected",
            custom_stock_request_status: "Rejected",
            status: "Rejected",

            /*
             * A released transfer state has priority over
             * rejected inside hoManagerStatusGroup().
             *
             * Clear it for a locally rejected request.
             */
            transfer_status: ""
        }
    );
}


function lifeProtectLocallyRejectedRows(rows) {
    return (
        Array.isArray(rows)
            ? rows
            : []
    ).map(function (row) {
        return lifeForceRejectedRequestRow(
            row
        );
    });
}

async function lifeLoadAllHORequestGroupRows(group) {
    group = String(group || "").trim().toLowerCase();

    if (
        ["pending", "approved"].indexOf(group) < 0
    ) {
        return [];
    }

    var page = 1;
    var totalPages = 1;
    var collected = [];

    do {
        var result =
            await lifeRequireAPI()
                .listRequests({
                    view: "ho",
                    branch: "",
                    group: group,
                    page: page,
                    page_size: 200,
                    limit: 5000
                });

        collected =
            lifeMergeUniqueMaterialRequestRows([
                collected,
                Array.isArray(result && result.rows)
                    ? result.rows
                    : []
            ]);

        totalPages = Math.max(
            1,
            Number(
                result && result.total_pages || 1
            ) || 1
        );

        page += 1;

    } while (
        page <= totalPages
    );

    return collected;
}

