async function lifeLoadHOInitialRowsFast(){
/*
 * Start the custom HO list and direct Material Request list together.
 * The first useful result wins. This avoids the old 10s + 10s + 15s
 * sequential wait that could leave the approval screen on Loading.
 */
return new Promise(function(resolve,reject){
var settled=0;
var resolved=false;
var errors=[];

function finishSuccess(rows){
if(resolved){
return;
}
if(Array.isArray(rows)&&rows.length){
resolved=true;
resolve(
lifeMergeUniqueMaterialRequestRows([rows])
);
}
}

function finishFailure(error){
settled+=1;
if(error){
errors.push(error);
}
if(settled>=2&&!resolved){
reject(
errors[0]||
new Error("No HO Material Request rows could be loaded.")
);
}
}

lifePromiseTimeout(
lifeRequireAPI().listRequests({
view:"ho",
branch:"",
page:1,
page_size:200,
limit:300
}),
15000,
"HO request list"
)
.then(function(result){
var rows=
Array.isArray(result&&result.rows)
?result.rows
:[];
if(rows.length){
finishSuccess(rows);
}
else{
finishFailure(
new Error("HO request list returned no rows.")
);
}
})
.catch(finishFailure);

lifePromiseTimeout(
lifeLoadHOMaterialRequestsDirect(),
15000,
"Direct HO Material Request list"
)
.then(function(rows){
if(Array.isArray(rows)&&rows.length){
finishSuccess(rows);
}
else{
finishFailure(
new Error("Direct Material Request list returned no rows.")
);
}
})
.catch(finishFailure);
});
}

async function lifeLoadHORequestRowsWithFallback(){
/*
 * FAST-FIRST HO LOADER
 * --------------------
 * The previous version waited for BOTH grouped loaders (Pending + Approved)
 * to finish all pagination before the screen could paint. If either server
 * call became slow, Requests & Approvals remained on the loading card.
 *
 * Now:
 *   1. Try one mixed HO request page first (quick initial paint).
 *   2. Fall back to direct Material Request get_list if needed.
 *   3. Grouped Pending/Approved pagination runs separately in background.
 */
try{
var quickResult=await lifePromiseTimeout(
lifeRequireAPI().listRequests({
view:"ho",
branch:"",
page:1,
page_size:300,
limit:500
}),
10000,
"Initial HO Requests & Approvals load"
);

var quickRows=
Array.isArray(quickResult&&quickResult.rows)
?quickResult.rows
:[];

if(quickRows.length){
return lifeMergeUniqueMaterialRequestRows([quickRows]);
}
}
catch(quickError){
void 0;
}

try{
var directRows=await lifeLoadHOMaterialRequestsDirect();

return lifeMergeUniqueMaterialRequestRows([
directRows
]);
}
catch(directError){
void 0;
}

/*
 * Final fallback: grouped API, but each complete grouped operation is
 * protected by a timeout so the UI cannot remain loading forever.
 */
var groupedRows=await lifePromiseTimeout(
Promise.all([
lifeLoadAllHORequestGroupRows("pending"),
lifeLoadAllHORequestGroupRows("approved")
]),
15000,
"Grouped HO Requests & Approvals load"
);

return lifeMergeUniqueMaterialRequestRows(groupedRows);
}

async function loadRequests() {
    var loadSequence =
        ++state.requestLoadSeq;

    var selectedView =
        state.currentView === "ho"
            ? "ho"
            : "branch";

    /*
     * Keep embedded Material Request module aligned with
     * the dashboard branch.
     */
    var hostContext =
        typeof synchronizeEmbeddedBranchFromHost ===
            "function"
            ? synchronizeEmbeddedBranchFromHost()
            : {
                role: "",
                branch_name: "",
                branch_code: "",
                warehouses: []
            };

    var selectedBranch = "";

    if (
        selectedView ===
        "branch"
    ) {
        selectedBranch =
            String(
                hostContext.branch_name ||
                state.branch ||
                ""
            ).trim();

        if (selectedBranch) {
            state.branch =
                selectedBranch;
        }

        if (!selectedBranch) {
            throw new Error(
                "The selected branch could not be resolved. " +
                "Select a branch again from the dashboard header."
            );
        }
    }

    var branchReceiptPromise =
        selectedView === "branch"
            ? renderBranchReceiving()
            : Promise.resolve();

    /*
     * ======================================================
     * HO REQUESTS & APPROVALS
     * ======================================================
     */
    if (
        selectedView ===
        "ho"
    ) {
        /*
         * Paint existing cached state immediately.
         */
        renderHOApproval();

        try {
            /*
             * Fast initial request load.
             */
            var initialRows =
                await lifeLoadHOInitialRowsFast();

            if (
                loadSequence !==
                state.requestLoadSeq
            ) {
                return state.requests;
            }

            /*
             * IMPORTANT:
             * Every row enters state through the central
             * merge function, which protects locally
             * rejected requests.
             */
            state.requests =
                lifeMergeUniqueMaterialRequestRows([
                    initialRows
                ]);

            state.requests =
                lifeProtectLocallyRejectedRows(
                    state.requests
                );

            state.homePage = 1;

            if (
                state.currentPage ===
                "ho-approval"
            ) {
                renderHOApproval();
            }

            /*
             * ==================================================
             * BACKGROUND PENDING + APPROVED REFRESH
             * ==================================================
             */
            lifePromiseTimeout(
                Promise.all([
                    lifeLoadAllHORequestGroupRows(
                        "pending"
                    ),
                    lifeLoadAllHORequestGroupRows(
                        "approved"
                    )
                ]),
                120000,
                "Background grouped HO request refresh"
            )
            .then(function (groupedRows) {

                if (
                    loadSequence !==
                    state.requestLoadSeq
                ) {
                    return;
                }

                state.requests =
                    lifeMergeUniqueMaterialRequestRows([
                        state.requests,
                        groupedRows[0] || [],
                        groupedRows[1] || []
                    ]);

                state.requests =
                    lifeProtectLocallyRejectedRows(
                        state.requests
                    );

                if (
                    state.currentPage ===
                    "ho-approval"
                ) {
                    renderHOApproval();
                }
            })
            .catch(function (error) {
                void 0;
            });

            /*
             * ==================================================
             * HOME / REPORT REQUEST DATA
             * ==================================================
             *
             * Keep your existing lightweight history/home loader
             * if available.
             */
            if (
                typeof lifeLoadHORequestHistoryRows ===
                "function"
            ) {
                lifePromiseTimeout(
                    lifeLoadHORequestHistoryRows(),
                    15000,
                    "HO request history refresh"
                )
                .then(function (historyRows) {

                    if (
                        loadSequence !==
                        state.requestLoadSeq
                    ) {
                        return;
                    }

                    state.requests =
                        lifeMergeUniqueMaterialRequestRows([
                            state.requests,
                            historyRows
                        ]);

                    state.requests =
                        lifeProtectLocallyRejectedRows(
                            state.requests
                        );

                    if (
                        state.currentPage ===
                        "ho-approval"
                    ) {
                        renderHOApproval();
                    }
                })
                .catch(function (error) {
                    void 0;
                });
            }

            /*
             * Refresh home/report presentation independently.
             */
            try {
                if (
                    typeof renderHOHome ===
                    "function"
                ) {
                    renderHOHome();
                }
            }
            catch (homeError) {
                void 0;
            }

            return state.requests;
        }
        catch (initialError) {
            /*
             * ==================================================
             * FULL FALLBACK
             * ==================================================
             */
            void 0;

            try {
                var fallbackRows =
                    await lifeLoadHORequestRowsWithFallback();

                if (
                    loadSequence !==
                    state.requestLoadSeq
                ) {
                    return state.requests;
                }

                state.requests =
                    lifeMergeUniqueMaterialRequestRows([
                        state.requests,
                        fallbackRows
                    ]);

                state.requests =
                    lifeProtectLocallyRejectedRows(
                        state.requests
                    );

                state.homePage = 1;

                if (
                    state.currentPage ===
                    "ho-approval"
                ) {
                    renderHOApproval();
                }

                return state.requests;
            }
            catch (fallbackError) {
                renderHOApprovalLoadError(
                    fallbackError
                );

                throw fallbackError;
            }
        }
    }

    /*
     * ======================================================
     * BRANCH VIEW
     * ======================================================
     */

    try {
        var branchRowsResult =
            await lifeRequireAPI()
                .listRequests({
                    view: "branch",
                    branch:
                        selectedBranch,

                    page: 1,
                    page_size: 500,
                    limit: 5000
                });

        if (
            loadSequence !==
            state.requestLoadSeq
        ) {
            return state.requests;
        }

        var branchRows =
            Array.isArray(
                branchRowsResult &&
                branchRowsResult.rows
            )
                ? branchRowsResult.rows
                : [];

        /*
         * Also include requests created by the logged-in user
         * if your existing branch workflow requires this.
         */
        var ownRows = [];

        try {
            ownRows =
                await lifeLoadCurrentUsersOwnMaterialRequests();
        }
        catch (ownError) {
            void 0;
        }

        if (
            loadSequence !==
            state.requestLoadSeq
        ) {
            return state.requests;
        }

        state.requests =
            lifeMergeUniqueMaterialRequestRows([
                branchRows,
                ownRows
            ]);

        state.homePage = 1;

        /*
         * Wait for branch receipt loader, but do not allow
         * receipt failure to break Material Requests.
         */
        try {
            await branchReceiptPromise;
        }
        catch (receiptError) {
            void 0;
        }

        if (
            state.currentPage ===
            "branch-home"
        ) {
            if (
                typeof renderBranchHome ===
                "function"
            ) {
                renderBranchHome();
            }
        }

        if (
            state.currentPage ===
            "branch-requests"
        ) {
            if (
                typeof renderBranchReqList ===
                "function"
            ) {
                renderBranchReqList();
            }
        }

        return state.requests;
    }
    catch (branchError) {
        void 0;

        throw branchError;
    }
}

async function refreshAfterMaterialRequestChange(
    options
){

    options =
        options ||
        {};


    /*
     * Always refresh Material Requests.
     */
    await loadRequests();


    var tasks =
        [];


    /*
     * ============================================================
     * RESOLVE ACTUAL VIEW
     * ============================================================
     */

    var hostContext =
        (
            typeof synchronizeEmbeddedBranchFromHost ===
            "function"
        )
            ? synchronizeEmbeddedBranchFromHost()
            : null;


    var currentView =
        String(
            state &&
            state.currentView
                ? state.currentView
                : ""
        )
        .trim()
        .toLowerCase();


    var isHOView =
        currentView ===
        "ho";


    /*
     * Host role wins over stale state.currentView.
     */
    if(
        hostContext &&
        hostContext.role
    ){

        var hostRole =
            String(
                hostContext.role
            )
            .trim()
            .toLowerCase();


        if(
            hostRole ===
            "branch"
        ){

            isHOView =
                false;
        }
        else if(
            hostRole === "ho" ||
            hostRole === "stock manager" ||
            hostRole === "stock_manager" ||
            hostRole === "manager"
        ){

            isHOView =
                true;
        }
    }


    /*
     * ============================================================
     * HO-ONLY SECONDARY TABLES
     * ============================================================
     */

    if(
        isHOView &&
        typeof renderHOReceiptTracking ===
            "function" &&
        (
            options.refreshReceiptTracking ||
            (
                state.hoSectionExpanded &&
                state.hoSectionExpanded.receipts
            )
        )
    ){

        tasks.push(
            renderHOReceiptTracking()
        );
    }


    if(
        isHOView &&
        typeof renderHOCompletedTracking ===
            "function" &&
        (
            options.refreshCompletedTracking ||
            (
                state.hoSectionExpanded &&
                state.hoSectionExpanded.completed
            )
        )
    ){

        tasks.push(
            renderHOCompletedTracking()
        );
    }


    /*
     * ============================================================
     * INTEGRATED HOST REFRESH
     * ============================================================
     *
     * Safe for both views.
     */

    if(
        window.LifeIntegratedStockHost &&
        typeof window.LifeIntegratedStockHost.refresh ===
            "function"
    ){

        tasks.push(
            window.LifeIntegratedStockHost.refresh({
                stockChanged:
                    !!options.stockChanged
            })
        );
    }


    /*
     * ============================================================
     * WAIT FOR SECONDARY REFRESHES
     * ============================================================
     */

    await Promise.all(
        tasks.map(
            function(task){

                return Promise.resolve(
                    task
                )
                .catch(
                    function(error){

                        void 0;
                    }
                );
            }
        )
    );
}
