function warehouseKeyDistance(left,right){
left=String(left||"");
right=String(right||"");
if(left===right){
return 0;
}
if(!left.length){
return right.length;
}
if(!right.length){
return left.length;
}
var previous=[];
var current=[];
var i;
var j;
for(j=0;
j<=right.length;
j++){
previous[j]=j;
}
for(i=1;
i<=left.length;
i++){
current[0]=i;
for(j=1;
j<=right.length;
j++){
current[j]=Math.min(current[j-1]+1,previous[j]+1,previous[j-1]+(left.charAt(i-1)===right.charAt(j-1)?0:1));
}
previous=current.slice();
}
return previous[right.length];
}
function warehouseKeysCloselyMatch(left,right){
var leftKey=compactWarehouseKey(left);
var rightKey=compactWarehouseKey(right);
if(!leftKey||!rightKey){
return false;
}
if(leftKey===rightKey||leftKey.indexOf(rightKey)>=0||rightKey.indexOf(leftKey)>=0){
return true;
}
var longest=Math.max(leftKey.length,rightKey.length);
return(longest>=6&&warehouseKeyDistance(leftKey,rightKey)<=Math.max(1,Math.floor(longest*0.14)));
}
