async function hydrateBranchReceiptClientNames(rows) {
    rows = Array.isArray(rows) ? rows : [];

    var requestNames = [];

    rows.forEach(function (stockEntry) {
        var items = Array.isArray(stockEntry.items)
            ? stockEntry.items
            : [];

        items.forEach(function (item) {
            var requestName = String(
                item && item.material_request || ""
            ).trim();

            if (
                requestName &&
                requestNames.indexOf(requestName) === -1
            ) {
                requestNames.push(requestName);
            }
        });
    });

    if (!requestNames.length) {
        return rows;
    }

    var requestMap = {};

    await Promise.all(
        requestNames.map(async function (requestName) {
            try {
                var result =
                    await lifeRequireAPI().getRequest(
                        requestName
                    );

                var request =
                    result &&
                    (
                        result.request ||
                        result.doc ||
                        result
                    );

                if (request) {
                    requestMap[requestName] =
                        request;
                }

            } catch (error) {
                void 0;
            }
        })
    );

    /*
     * Load actual Patient names for
     * Special Material Requests.
     */
    var patientIds = [];

    Object.keys(requestMap).forEach(
        function (requestName) {

            var request =
                requestMap[requestName];

            var kind =
                typeof branchRequestTypeKind === "function"
                    ? branchRequestTypeKind(request)
                    : "";

            if (kind !== "special") {
                return;
            }

            var patientId = String(
                request.custom_client_name ||
                request.custom_new_client_name ||
                ""
            ).trim();

            if (
                patientId &&
                patientIds.indexOf(patientId) === -1
            ) {
                patientIds.push(patientId);
            }
        }
    );

    var patientNameMap = {};

    await Promise.all(
        patientIds.map(async function (patientId) {
            try {
                var patient =
                    await getDoc(
                        "Patient",
                        patientId
                    );

                patientNameMap[patientId] =
                    String(
                        patient.patient_name ||
                        patient.customer_name ||
                        patient.name ||
                        patientId
                    ).trim();

            } catch (error) {
                /*
                 * Patient ID is still more useful than
                 * falling back to Target Warehouse.
                 */
                patientNameMap[patientId] =
                    patientId;
            }
        })
    );

    rows.forEach(function (stockEntry) {

        var clientNames = [];
        var requestTypes = [];
        var linkedRequests = [];

        var items =
            Array.isArray(stockEntry.items)
                ? stockEntry.items
                : [];

        items.forEach(function (item) {

            var requestName = String(
                item &&
                item.material_request ||
                ""
            ).trim();

            if (!requestName) {
                return;
            }

            var request =
                requestMap[requestName];

            if (!request) {
                return;
            }

            var kind =
                typeof branchRequestTypeKind === "function"
                    ? branchRequestTypeKind(request)
                    : "";

            var clientName = "";

            /*
             * SPECIAL MATERIAL REQUEST
             */
            if (kind === "special") {

                var patientId = String(
                    request.custom_client_name ||
                    request.custom_new_client_name ||
                    ""
                ).trim();

                clientName =
                    patientNameMap[patientId] ||
                    patientId ||
                    "";

                if (!clientName) {
                    clientName = String(
                        extractNoteValue(
                            request.custom_additional_notes || "",
                            "Client"
                        ) || ""
                    ).trim();
                }
            }

            /*
             * ADVANCE MATERIAL REQUEST
             */
            else if (kind === "advance") {

                clientName = String(
                    request.custom_expected_client_name ||
                    ""
                ).trim();

                if (!clientName) {
                    clientName = String(
                        extractNoteValue(
                            request.custom_additional_notes || "",
                            "Expected Client"
                        ) || ""
                    ).trim();
                }
            }

            /*
             * Monthly / normal Material Requests
             * intentionally do not receive a client label.
             */
            if (
                clientName &&
                clientName !== "—" &&
                clientNames.indexOf(clientName) === -1
            ) {
                clientNames.push(clientName);
            }

            if (
                kind &&
                requestTypes.indexOf(kind) === -1
            ) {
                requestTypes.push(kind);
            }

            if (
                linkedRequests.indexOf(requestName) === -1
            ) {
                linkedRequests.push(requestName);
            }
        });

        stockEntry._receipt_client_names =
            clientNames;

        stockEntry._receipt_client_label =
            clientNames.join(", ");

        stockEntry._receipt_request_types =
            requestTypes;

        stockEntry._receipt_material_requests =
            linkedRequests;
    });

    return rows;
}
