var targetWarehouse=String(stockEntry.to_warehouse||"").trim();
var hostContext=typeof synchronizeEmbeddedBranchFromHost==="function"
?synchronizeEmbeddedBranchFromHost()
:{role:"",branch_name:"",warehouses:[]};

