var branchRows=Array.isArray(state.branches)?state.branches:[];
for(var index=0;index<branchRows.length;index+=1){
var branchRow=branchRows[index]||{};
var candidates=[branchRow.branch,branchRow.name];
for(var candidateIndex=0;candidateIndex<candidates.length;candidateIndex+=1){
var candidate=String(candidates[candidateIndex]||"").trim();
if(!candidate){
continue;
}
var branchKey=normalizeWarehouseKey(candidate);
if(branchKey&&targetKey&&(
branchKey===targetKey||
targetKey.indexOf(branchKey)>=0||
branchKey.indexOf(targetKey)>=0
)){
return candidate;
}
}
}

/*
 * Compatibility fallback. normalizeWarehouseKey() removes words such as
 * Main / Store / Warehouse, so try to map the display label to Branch master.
 */
var targetLabel=String(stockEntryTargetBranchLabel(stockEntry)||"").trim();
var targetLabelKey=normalizeWarehouseKey(targetLabel);
for(var rowIndex=0;rowIndex<branchRows.length;rowIndex+=1){
var row=branchRows[rowIndex]||{};
var rowCandidates=[row.branch,row.name];
for(var rowCandidateIndex=0;rowCandidateIndex<rowCandidates.length;rowCandidateIndex+=1){
var rowCandidate=String(rowCandidates[rowCandidateIndex]||"").trim();
if(rowCandidate&&normalizeWarehouseKey(rowCandidate)===targetLabelKey){
return rowCandidate;
}
}
}

if(targetLabel&&targetLabel!=="—"&&targetLabel!=="No Branch"){
return targetLabel;
}
return"";
}

