/*
 * IMPORTANT:
 * Do NOT use frappe.client.get_list("Employee") here.
 * Normal Branch users can have Employee read restrictions, which caused
 * valid Vizag employees (for example HR-EMP-00223) to disappear.
 *
 * This uses the dedicated API Server Script:
 *     life_stock_receipt_employee_search
 *
 * That endpoint validates the logged-in user's Branch access and then
 * returns only Active Employee rows from the receiving branch.
 */
var response=await frappe.call({
method:"life_stock_receipt_employee_search",
type:"POST",
args:{
branch:receivingBranch,
query:cleanQuery,
limit:20
}
});

if(searchNumber!==branchReceiptEmployeeSearchSeq){
return;
}

var message=response&&response.message;
if(!message||message.ok!==true){
throw new Error(
message&&message.message
?String(message.message)
:"Employee search returned an invalid response."
);
}

var employees=Array.isArray(message.data)?message.data:[];

employees=employees.filter(function(employee){
return(
String(employee.status||"").toLowerCase()==="active"&&
branchReceiptEmployeeMatchesReceivingBranch(employee)
);
});

renderBranchReceiptEmployeeResults(employees,query);
}
catch(error){
if(searchNumber!==branchReceiptEmployeeSearchSeq){
return;
}

void 0;

if(results){
var errorMessage="Unable to load employees.";

if(error&&error._server_messages){
try{
var serverMessages=JSON.parse(error._server_messages);
if(serverMessages&&serverMessages.length){
var parsedMessage=JSON.parse(serverMessages[0]);
errorMessage=parsedMessage.message||serverMessages[0]||errorMessage;
}
}
catch(ignoreServerMessageError){}
}
else if(error&&error.responseJSON&&error.responseJSON._server_messages){
try{
var responseMessages=JSON.parse(error.responseJSON._server_messages);
if(responseMessages&&responseMessages.length){
var parsedResponseMessage=JSON.parse(responseMessages[0]);
errorMessage=parsedResponseMessage.message||responseMessages[0]||errorMessage;
}
}
catch(ignoreResponseMessageError){}
}
else if(error&&error.message){
errorMessage=String(error.message);
}

results.innerHTML=
'<div class="branch-receipt-employee-empty error">'+
'<div class="branch-receipt-employee-empty-icon">⚠️</div>'+
'<div><strong>Unable to load employees</strong>'+
'<div>'+escapeHtml(errorMessage)+'</div></div>'+
'</div>';
results.classList.add("show");
}
}
},180);
}
