/* =========================================================
   BRANCH RECEIPT — SPECIAL MATERIAL REQUEST CLIENT CONTEXT
   ---------------------------------------------------------
   View-only helper layer:
   - Reads the Material Request linked on each Stock Entry item.
   - Shows client information only for Special Material Requests.
   - Does not alter stock quantities, request workflow, or receipt payload.
   ========================================================= */
function lifeBranchReceiptIsSpecialRequest(requestDoc){
requestDoc=requestDoc||{};
var explicitType=String(
requestDoc.custom_stock_request_type||
requestDoc.custom_request_type||
""
).trim().toLowerCase();
if(
explicitType==="special material request"||
explicitType==="consumable request (for client)"
){
return true;
}
try{
if(typeof branchRequestTypeKind==="function"&&branchRequestTypeKind(requestDoc)==="special"){
return true;
}
}
catch(ignoreTypeError){
}
var titleText=String(requestDoc.title||"").toLowerCase();
var notesText=String(requestDoc.custom_additional_notes||"").toLowerCase();
return(
titleText.indexOf("special material request")>=0||
titleText.indexOf("consumable request (for client)")>=0||
notesText.indexOf("special material request")>=0||
notesText.indexOf("consumable request (for client)")>=0
);
}

function lifeBranchReceiptUniqueStrings(values){
var seen=Object.create(null);
var out=[];
(Array.isArray(values)?values:[]).forEach(function(value){
var clean=String(value||"").trim();
if(clean&&!seen[clean]){
seen[clean]=true;
out.push(clean);
}
});
return out;
}

async function hydrateBranchReceiptSpecialClientContext(stockEntry){
stockEntry=stockEntry||{};
var items=Array.isArray(stockEntry.items)?stockEntry.items:[];
stockEntry._branch_receipt_special_requests=[];
stockEntry._branch_receipt_special_request_map=Object.create(null);

items.forEach(function(item){
if(item){
item._branch_receipt_special_client=null;
}
});

var requestNames=lifeBranchReceiptUniqueStrings(items.map(function(item){
return item&&item.material_request;
}));

if(!requestNames.length){
return stockEntry;
}

var requestDocs=await Promise.all(requestNames.map(async function(requestName){
try{
return await getDoc("Material Request",requestName);
}
catch(error){
void 0;
return null;
}
}));

var specialRequests=requestDocs.filter(function(requestDoc){
return requestDoc&&lifeBranchReceiptIsSpecialRequest(requestDoc);
});

if(!specialRequests.length){
return stockEntry;
}

var patientIds=lifeBranchReceiptUniqueStrings(specialRequests.map(function(requestDoc){
return requestDoc&&(
requestDoc.custom_client_name||
requestDoc.custom_new_client_name||
""
);
}));

var patientPairs=await Promise.all(patientIds.map(async function(patientId){
try{
return{
id:patientId,
doc:await getDoc("Patient",patientId)
};
}
catch(error){
void 0;
return{
id:patientId,
doc:null
};
}
}));

var patientMap=Object.create(null);
patientPairs.forEach(function(pair){
if(pair&&pair.id){
patientMap[pair.id]=pair.doc||null;
}
});

specialRequests.forEach(function(requestDoc){
var requestName=String(requestDoc.name||"").trim();
if(!requestName){
return;
}

var clientId=String(
requestDoc.custom_client_name||
requestDoc.custom_new_client_name||
""
).trim();

var patient=clientId?patientMap[clientId]:null;

var context={
request_name:requestName,
request_type:"Consumable Request",
client_id:clientId,
client_name:String(
patient&&(
patient.patient_name||
patient.customer_name||
patient.full_name
)||
clientId||
"Client not linked"
).trim(),
client_branch:String(
patient&&(
patient.branch_name||
patient.branch
)||
""
).trim(),
appointment:String(
requestDoc.custom_patient_appointment||
(typeof extractNoteValue==="function"
?extractNoteValue(
requestDoc.custom_additional_notes||"",
"Patient Appointment"
)
:"")||
""
).trim(),
therapy_plan:String(
requestDoc.custom_therapy_id||
""
).trim(),
required_by:String(
requestDoc.schedule_date||
""
).trim()
};

stockEntry._branch_receipt_special_request_map[requestName]=context;
stockEntry._branch_receipt_special_requests.push(context);
});

items.forEach(function(item){
if(!item){
return;
}
var requestName=String(item.material_request||"").trim();
var context=requestName
?stockEntry._branch_receipt_special_request_map[requestName]
:null;

if(context){
item._branch_receipt_special_client=context;
return;
}

/*
 * Fallback for older transfer rows where a client was copied onto the
 * Stock Entry Detail but the Material Request link is incomplete.
 * Only use it when the Stock Entry already has at least one confirmed
 * Special Material Request context.
 */
var itemClientId=String(item.custom_client_name||"").trim();
if(
itemClientId&&
stockEntry._branch_receipt_special_requests.length===1&&
stockEntry._branch_receipt_special_requests[0].client_id===itemClientId
){
item._branch_receipt_special_client=
stockEntry._branch_receipt_special_requests[0];
}
});

return stockEntry;
}

