var status=stockEntryReceiptDisplayState(row);
if(lifeBranchReceivingTableState.targetBranch&&targetBranch!==lifeBranchReceivingTableState.targetBranch){
return false;
}
if(lifeBranchReceivingTableState.sourceWarehouse&&sourceWarehouse!==lifeBranchReceivingTableState.sourceWarehouse){
return false;
}
if(lifeBranchReceivingTableState.releasedBy&&releasedBy!==lifeBranchReceivingTableState.releasedBy){
return false;
}
if(lifeBranchReceivingTableState.sendingMethod&&sendingMethod!==lifeBranchReceivingTableState.sendingMethod){
return false;
}
if(lifeBranchReceivingTableState.status&&status!==lifeBranchReceivingTableState.status){
return false;
}
if(!query){
return true;
}
var searchText=lifeTableNormalize([
row&&row.name,
targetBranch,
sourceWarehouse,
releasedBy,
sendingMethod,
status,
formatDateTime(lifeBranchReceiptReleaseDate(row))
].join(" "));
return searchText.indexOf(query)>=0;
});
return lifeTableSortRows(
