function collectBranchReceiptPayload(stockEntryName){
var card=byId("branch-receive-card-"+stockEntryName);
if(!card){
throw new Error("The receiving form is unavailable. Refresh and try again.");
}
var selectedEmployee=branchReceiptSelectedEmployee;
var selectedEmployeeId=String((byId("branch-receipt-employee-id")||{
}
).value||"").trim();
if(!selectedEmployee||!selectedEmployee.name||!selectedEmployeeId||selectedEmployee.name!==selectedEmployeeId){
throw new Error("Search and select the active employee who received the stock.");
}
if(String(selectedEmployee.status||"").toLowerCase()!=="active"){
throw new Error("Only an active employee can be selected as Received By.");
}
if(!branchReceiptReceivingBranch){
throw new Error("The receiving branch could not be resolved. Refresh the page and open the receipt again.");
}
if(!branchReceiptEmployeeMatchesReceivingBranch(selectedEmployee)){
throw new Error(
"Selected employee belongs to "+
String(selectedEmployee.branch||"another branch")+
". Please select an active employee from "+
String(branchReceiptReceivingBranch)+
"."
);
}
var inputs=Array.prototype.slice.call(card.querySelectorAll(".branch-received-qty"));
if(!inputs.length){
throw new Error("No Stock Entry Detail rows were found.");
}
var items=inputs.map(function(input){
var textValue=String(input.value||"").trim();
var itemCode=input.dataset.itemCode||"Material";
var itemName=input.dataset.itemName||itemCode;
if(textValue===""){
throw new Error("Enter Received Quantity for "+itemCode+". Enter 0 when it was not received.");
}
var receivedQty=Number(textValue);
var releasedQty=Math.max(0,num(input.dataset.releasedQty,0));
if(!isFinite(receivedQty)||receivedQty<0){
throw new Error("Received Quantity for "+itemCode+" must be zero or greater.");
}
if(receivedQty>releasedQty){
throw new Error("Received Quantity for "+itemCode+" cannot exceed Released Quantity "+formatStockQty(releasedQty)+".");
}
return{
row_name:input.dataset.stockEntryDetail||"",
item_code:itemCode,
item_name:itemName,
released_qty:releasedQty,
received_qty:receivedQty
}
;
}
);
var remarksElement=byId("branch-receipt-remarks-"+stockEntryName);
var receiptRemarks=String(remarksElement&&remarksElement.value||"").trim();
return{
stock_entry:stockEntryName,received_by:selectedEmployee.name,received_by_name:selectedEmployee.employee_name||selectedEmployee.name,received_date:nowDateTime(),receipt_remarks:receiptRemarks,items:items}
;
}
