function hasLinkedClientPackageData(doc) {
    doc = doc || {};

    var hasClient =
        String(
            doc.custom_client_name ||
            doc.custom_new_client_name ||
            ""
        ).trim() !== "";

    var hasTherapyIds =
        String(
            doc.custom_therapy_id || ""
        ).trim() !== "";

    var therapyTables = [
        doc.custom_special_material_request_details,
        doc.custom_therapy_plan_deatils,
        doc.custom_therapy_plan_details
    ];

    var hasTherapyRows = therapyTables.some(function (rows) {
        return Array.isArray(rows) && rows.length > 0;
    });

    return (
        hasClient ||
        hasTherapyIds ||
        hasTherapyRows
    );
}

function isGenuineMonthlyIndentRequest(doc) {
    doc = doc || {};

    return (
        String(requestType(doc) || "").trim() ===
            "Monthly Indent Request" &&
        !hasLinkedClientPackageData(doc)
    );
}

function requestDisplayType(doc) {
    doc = doc || {};

    var storedType =
        String(
            requestType(doc) || ""
        ).trim();

    var kind =
        branchRequestTypeKind(
            doc
        );

    /*
     * Historical and current Special Material Request records
     * are displayed with the new business-facing name.
     *
     * The stored ERPNext Select value remains unchanged.
     */
    if (kind === "special") {
        return "Consumable Request";
    }

    if (kind === "advance") {
        return "Advance Booking Material Request";
    }

    if (kind === "monthly") {
        return "Monthly Indent Request (General)";
    }

    /*
     * Some older client-linked requests were incorrectly saved
     * with Monthly Indent Request in custom_stock_request_type.
     * branchRequestTypeKind() above already classifies those as
     * client-linked/consumable when client/package data exists.
     */
    if (
        storedType === "Special Material Request"
    ) {
        return "Consumable Request";
    }

    return storedType || "Material Request";
}
function branchRequestTypeKind(doc) {
    doc = doc || {};

    /*
     * Client and Therapy Plan data takes priority over an
     * incorrect legacy request-type value.
     */
    if (hasLinkedClientPackageData(doc)) {
        return "special";
    }

    var combinedText = String(
        (requestType(doc) || "") +
        " " +
        (doc.custom_additional_notes || "")
    ).toLowerCase();

    if (combinedText.indexOf("monthly indent") >= 0) {
        return "monthly";
    }

    if (combinedText.indexOf("advance material") >= 0) {
        return "advance";
    }

    if (
        combinedText.indexOf("special material") >= 0 ||
        combinedText.indexOf("consumable request") >= 0
    ) {
        return "special";
    }

    return "general";
}


/* =========================================================
   CLIENT-LINKED MATERIAL REQUEST LIST RULE
   ========================================================= */

/*
 * Request lists used for client material tracking must contain
 * only:
 *
 *   1. Consumable / Special Material Request
 *      -> must have an actual client reference.
 *
 *   2. Advance Material Request
 *      -> must have an expected-client reference.
 *
 * Monthly Indent / General Material Requests are intentionally
 * excluded from these lists.
 */
function lifeClientLinkedRequestReference(doc) {
    doc = doc || {};

    var kind =
        branchRequestTypeKind(
            doc
        );

    var notes =
        String(
            doc.custom_additional_notes ||
            ""
        );

    if (kind === "special") {
        return String(
            doc.custom_client_name ||
            doc.custom_new_client_name ||
            extractNoteValue(
                notes,
                "Client ID"
            ) ||
            extractNoteValue(
                notes,
                "Client"
            ) ||
            ""
        ).trim();
    }

    if (kind === "advance") {
        return String(
            doc.custom_expected_client_name ||
            extractNoteValue(
                notes,
                "Expected Client"
            ) ||
            ""
        ).trim();
    }

    return "";
}

function lifeIsClientLinkedMaterialRequest(doc) {
    doc = doc || {};

    var kind =
        branchRequestTypeKind(
            doc
        );

    if (
        kind !== "special" &&
        kind !== "advance"
    ) {
        return false;
    }

    return !!lifeClientLinkedRequestReference(
        doc
    );
}

function lifeFilterClientLinkedMaterialRequests(rows) {
    return (
        Array.isArray(rows)
            ? rows
            : []
    ).filter(
        lifeIsClientLinkedMaterialRequest
    );
}

