/* =========================================================
   SPECIAL MATERIAL REQUEST — FAST / SAFE CLIENT SEARCH
   Build: 2026-10-01

   Fixes:
   - no permanent "Searching clients..." state
   - 250 ms debounce
   - sequence cancellation when input is changed/cleared
   - direct frappe.client.get_list first
   - existing LIFE gateway as fallback
   - hard timeout for both paths
   - name, Client ID and mobile supported
   ========================================================= */

function lifeSSRClientSearchTimeout(promise,ms,label){
return new Promise(function(resolve,reject){
var finished=false;
var timer=window.setTimeout(function(){
if(finished){
return;
}
finished=true;
reject(
new Error(
(label||"Client search")+
" timed out. Please try again."
)
);
},Math.max(1000,Number(ms||7000)));

Promise.resolve(promise)
.then(function(value){
if(finished){
return;
}
finished=true;
window.clearTimeout(timer);
resolve(value);
})
.catch(function(error){
if(finished){
return;
}
finished=true;
window.clearTimeout(timer);
reject(error);
});
});
}


/* =========================================================
   LIFE BRANCH SCOPE — CLIENTS + EMPLOYEES
   ---------------------------------------------------------
   Normal branch users must only see records belonging to the
   active/logged-in branch.

   Branch source priority:
     1. Integrated dashboard active branch
     2. Request module state.branch
     3. Logged-in Employee.branch

   System-wide pages can still use their own explicit branch
   switcher because this helper follows the active dashboard
   branch value first.
   ========================================================= */

function lifeActiveLoggedInBranch() {
    return String(
        window.__lifeIntegratedStockBranchName ||
        state.branch ||
        (
            state.employee &&
            state.employee.branch
                ? state.employee.branch
                : ""
        ) ||
        ""
    ).trim();
}

function lifeNormalizeBranchForFilter(value) {
    var key = String(value || "")
        .toLowerCase()
        .replace(/&/g, "and")
        .replace(/\s*-\s*lsacpl\s*$/i, "")
        .replace(/\bbranch\b/gi, "")
        .replace(/\bmain\s*stores?\b/gi, "")
        .replace(/\bsub\s*stores?\b/gi, "")
        .replace(/\bstores?\b/gi, "")
        .replace(/\bwarehouses?\b/gi, "")
        .replace(/[^a-z0-9]+/g, "")
        .trim();

    var aliases = {
        himayathnagar: "himayatnagar",
        himayatnagar: "himayatnagar",
        dilshuknagar: "dilsukhnagar",
        dilsukhnagar: "dilsukhnagar",
        banjarahill: "banjarahills",
        banjarahills: "banjarahills",
        srinagar: "srnagar",
        srnagar: "srnagar",
        chandhanagar: "chandanagar",
        chandanagar: "chandanagar",
        vizag: "vizag",
        visakhapatnam: "vizag",
        vijayawada: "vijayawada",
        kukatpally: "kukatpally",
        madhapur: "madhapur",
        gachibowli: "gachibowli",
        nellore: "nellore"
    };

    return aliases[key] || key;
}

function lifeRecordBelongsToActiveBranch(record) {
    record = record || {};

    var activeBranch = lifeActiveLoggedInBranch();
    var wanted = lifeNormalizeBranchForFilter(activeBranch);

    /*
     * If branch context is genuinely unavailable, do not destroy
     * search results. loadContext() normally resolves this first.
     */
    if (!wanted) {
        return true;
    }

    var recordBranch = String(
        record.branch_name ||
        record.branch ||
        record.custom_branch ||
        ""
    ).trim();

    var actual = lifeNormalizeBranchForFilter(recordBranch);

    return !!actual && actual === wanted;
}

function lifeSSRDirectPatientList(fields,orFilters){
return new Promise(function(resolve,reject){
if(
!window.frappe||
typeof frappe.call!=="function"
){
reject(
new Error(
"frappe.call is unavailable."
)
);
return;
}

var settled=false;

function done(fn,value){
if(settled){
return;
}
settled=true;
fn(value);
}

try{
frappe.call({
method:"frappe.client.get_list",
args:{
doctype:"Patient",
fields:fields,
filters:[],
or_filters:orFilters,
order_by:"patient_name asc",
limit_start:0,
limit_page_length:30
},
callback:function(response){
if(response&&response.exc){
done(
reject,
new Error(
response.exception||
response.exc||
"Patient search failed."
)
);
return;
}

done(
resolve,
response&&Array.isArray(response.message)
?response.message
:[]
);
},
error:function(error){
var message=
error&&error.responseJSON&&(
error.responseJSON.exception||
error.responseJSON.exc_type||
error.responseJSON._server_messages
)
?String(
error.responseJSON.exception||
error.responseJSON.exc_type||
error.responseJSON._server_messages
)
:error&&error.message
?error.message
:"Patient search request failed.";

done(
reject,
new Error(message)
);
}
});
}
catch(error){
done(reject,error);
}
});
}

async function lifeSSRRunClientSearch(
cleanQuery,
digits,
isMobileOnly,
drop,
seq
){
var fieldSets=[
["name","patient_name","mobile","branch_name","custom_branch","sex","email","status"],
["name","patient_name","mobile","branch_name","custom_branch","status"],
["name","patient_name","mobile","branch_name","status"],
["name","patient_name","mobile","status"],
["name","patient_name","mobile"],
["name","patient_name"]
];

var orFilters=
isMobileOnly
?[
["mobile","like","%"+digits+"%"],
["name","like","%"+cleanQuery+"%"]
]
:[
["name","like","%"+cleanQuery+"%"],
["patient_name","like","%"+cleanQuery+"%"]
];

var rows=null;
var directError=null;

/*
 * Fast path:
 * A normal frappe.client.get_list is much quicker for Patient search
 * and does not wait behind the large Stock gateway request queue.
 */
for(var directIndex=0;directIndex<fieldSets.length;directIndex++){
try{
rows=
await lifeSSRClientSearchTimeout(
lifeSSRDirectPatientList(
fieldSets[directIndex],
orFilters
),
6500,
"Direct client search"
);

break;
}
catch(error){
directError=error;
}
}

/*
 * Compatibility fallback:
 * Some portal users may not have direct Patient get_list permission.
 * In that case reuse the existing LIFE Stock API gateway, but protect
 * it with a timeout so the screen can never stay on Loading forever.
 */
if(!Array.isArray(rows)){
try{
rows=
await lifeSSRClientSearchTimeout(
safeGetList(
"Patient",
fieldSets,
[],
{
or_filters:orFilters,
order_by:"patient_name asc",
limit_page_length:30
}
),
8000,
"Client search"
);
}
catch(gatewayError){
throw(
gatewayError||
directError||
new Error(
"Unable to search clients."
)
);
}
}

if(seq!==state.searchSeq){
return;
}

rows=Array.isArray(rows)?rows:[];

/*
 * BRANCH SCOPE:
 * Only show clients from the currently logged-in / active branch.
 */
rows=rows.filter(function(patient){
    return lifeRecordBelongsToActiveBranch(patient);
