void 0;

var seenPatients=Object.create(null);

rows=rows.filter(function(patient){
var patientId=
String(
patient&&patient.name||""
).trim();

if(
!patientId||
seenPatients[patientId]
){
return false;
}

seenPatients[patientId]=true;
return true;
});

var normalizedSearch=
String(cleanQuery||"")
.toLowerCase();

rows.sort(function(left,right){
var leftId=
String(left.name||"")
.trim()
.toLowerCase();

var rightId=
String(right.name||"")
.trim()
.toLowerCase();

var leftName=
String(left.patient_name||"")
.trim()
.toLowerCase();

var rightName=
String(right.patient_name||"")
.trim()
.toLowerCase();

var leftRank=
leftId===normalizedSearch
?0
:leftId.indexOf(normalizedSearch)===0
?1
:leftName===normalizedSearch
?2
:leftName.indexOf(normalizedSearch)===0
?3
:4;

var rightRank=
rightId===normalizedSearch
?0
:rightId.indexOf(normalizedSearch)===0
?1
:rightName===normalizedSearch
?2
:rightName.indexOf(normalizedSearch)===0
?3
:4;

if(leftRank!==rightRank){
return leftRank-rightRank;
}

return leftId.localeCompare(
rightId,
undefined,
{
numeric:true,
sensitivity:"base"
}
);
});

if(seq!==state.searchSeq){
return;
