String(
query||""
).trim();

var drop=
byId(
dropId
);

if(!drop){
return;
}

/*
 * IMPORTANT:
 * Increment on EVERY keystroke, including clearing the field.
 * This invalidates an old request immediately.
 */
var seq=
++state.searchSeq;

if(state.clientSearchTimer){
window.clearTimeout(
state.clientSearchTimer
);
state.clientSearchTimer=null;
}

var cleanQuery=
query
.replace(
/[%_]/g,
""
)
.replace(
/\s+/g,
" "
)
.trim();

var isMobileOnly=
/^[+\d\s\-()]+$/.test(
cleanQuery
)&&
!/[a-z]/i.test(
cleanQuery
);

var digits=
cleanQuery.replace(
/\D/g,
""
);

if(
!cleanQuery||
(
isMobileOnly&&
digits.length<5
)||
(
!isMobileOnly&&
cleanQuery.length<3
)
){
drop.classList.remove(
"show"
);
drop.innerHTML="";
drop._rows=[];
return;
}

drop.classList.add(
"show"
);

drop.innerHTML=
'<div class="sd-item" style="cursor:default">'+
'<div class="sd-av">⏳</div>'+
'<div>'+
'<div class="sd-name">Searching clients…</div>'+
'<div class="sd-sub">'+
(
isMobileOnly
?"Searching by mobile number"
:"Searching by client name or Client ID"
)+
'</div>'+
'</div>'+
'</div>';

/*
 * Debounce typing. The old code sent one server request for every
 * keystroke, which could queue several gateway calls and make the latest
 * search appear to load forever.
 */
