/* ============================================================
   CLIENT / PLAN FINANCIAL SUMMARY — UNIQUE SALES INVOICES ONLY
   ------------------------------------------------------------
   A single Sales Invoice can contain multiple therapy rows.
   Never calculate the client header or Material Request totals by
   adding therapy-row paid_amount values because that can count the
   same invoice more than once.

   Pass an optional array of Therapy Plan names to restrict the
   summary to those plans. If omitted, all loaded client plans are
   included.
   ============================================================ */
function getSSRClientInvoiceSummary(planNames){
var wantedPlans=null;

if(Array.isArray(planNames)&&planNames.length){
wantedPlans=Object.create(null);
planNames.forEach(function(planName){
planName=String(planName||"").trim();
if(planName){
wantedPlans[planName]=true;
}
});
}

var seenInvoices=Object.create(null);
var totalBilled=0;
var totalPaid=0;
var totalDue=0;
var groups=(state&&state.invoicesByPlan&&typeof state.invoicesByPlan==="object")
?state.invoicesByPlan
:{};

Object.keys(groups).forEach(function(planName){
if(wantedPlans&&!wantedPlans[planName]){
return;
}

var invoices=Array.isArray(groups[planName])?groups[planName]:[];

invoices.forEach(function(invoice){
if(!invoice){
return;
}

var invoiceName=String(invoice.name||"").trim();
if(!invoiceName||seenInvoices[invoiceName]){
return;
}
seenInvoices[invoiceName]=true;

var invoiceTotal=Math.max(0,getInvoiceTotal(invoice));
var invoiceDue=Math.max(0,getInvoiceDue(invoice));
var invoicePaid=Math.max(0,getInvoicePaid(invoice));

totalBilled+=invoiceTotal;
totalPaid+=invoicePaid;
totalDue+=invoiceDue;
});
});

return{
total_billed:roundMoney(totalBilled),
total_paid:roundMoney(totalPaid),
total_due:roundMoney(totalDue),
invoice_count:Object.keys(seenInvoices).length
};
}
function calculatePaidStockEligibility(
booked,
completed,
remaining,
ratePerSession,
paidAmount,
dueAmount
){
booked=Math.max(0,num(booked,0));
completed=Math.max(0,num(completed,0));
remaining=Math.max(
0,
num(
remaining,
booked-completed
)
);
ratePerSession=Math.max(
0,
num(ratePerSession,0)
);
paidAmount=Math.max(
0,
num(paidAmount,0)
);
dueAmount=Math.max(
0,
num(dueAmount,0)
);

/*
 * PAYMENT-BASED SESSION ENTITLEMENT
 * ---------------------------------
 * Paid Sessions are determined ONLY by how much of this therapy
 * service has actually been paid for:
 *
 *     floor(Paid Service Amount / Per Session Rate)
 *
 * No "due <= 1000 => all sessions paid" shortcut is used anymore.
 */
var paidSessions=0;

if(
ratePerSession>0&&
paidAmount>0
){
paidSessions=
Math.floor(
(paidAmount+0.01)/
ratePerSession
);
}

paidSessions=
Math.min(
booked,
Math.max(
0,
paidSessions
)
);

var unusedPaidSessions=
Math.max(
0,
paidSessions-completed
);

var stockEligibleSessions=
Math.min(
remaining,
unusedPaidSessions
);

return{
paid_sessions:paidSessions,
unused_paid_sessions:unusedPaidSessions,
stock_eligible_sessions:stockEligibleSessions
};
}
