timeText.match(
/^(\d{1,2}):(\d{2})(?::(\d{2}))?/
);

var hours=
timeParts
?num(timeParts[1],23)
:23;

var minutes=
timeParts
?num(timeParts[2],59)
:59;

var seconds=
timeParts
