/*
 * Small, local Levenshtein implementation used only for
 * appointment <-> therapy matching.
 */
function ssrTherapyEditDistance(left,right){
left=normalizeSSRComparable(left);
right=normalizeSSRComparable(right);

if(left===right){
return 0;
}

if(!left){
return right.length;
}

if(!right){
return left.length;
}

var previous=[];
var current=[];
var i;
var j;

for(j=0;j<=right.length;j++){
previous[j]=j;
}

for(i=1;i<=left.length;i++){
current[0]=i;

for(j=1;j<=right.length;j++){
var cost=
left.charAt(i-1)===right.charAt(j-1)
?0
:1;

current[j]=Math.min(
current[j-1]+1,
previous[j]+1,
previous[j-1]+cost
);
}

previous=current.slice();
}

return previous[right.length];
}

function ssrTherapyTokenOverlap(left,right){
var leftTokens=
normalizeSSRComparable(left)
.split(" ")
.filter(Boolean);

var rightTokens=
normalizeSSRComparable(right)
.split(" ")
.filter(Boolean);

if(!leftTokens.length||!rightTokens.length){
return 0;
}

var leftMap=Object.create(null);
var rightMap=Object.create(null);

leftTokens.forEach(function(token){
leftMap[token]=true;
});

rightTokens.forEach(function(token){
rightMap[token]=true;
});

var intersection=0;
var unionMap=Object.create(null);

Object.keys(leftMap).forEach(function(token){
unionMap[token]=true;
if(rightMap[token]){
intersection+=1;
}
});

Object.keys(rightMap).forEach(function(token){
unionMap[token]=true;
});

var unionCount=
Object.keys(unionMap).length;

return unionCount
?intersection/unionCount
:0;
}

function ssrTherapyNameSimilarity(left,right){
var normalizedLeft=
normalizeSSRComparable(left);

var normalizedRight=
normalizeSSRComparable(right);

if(!normalizedLeft||!normalizedRight){
return{
score:0,
distance:999,
token_overlap:0,
exact:false,
strong:false
};
}

if(normalizedLeft===normalizedRight){
return{
score:1,
distance:0,
token_overlap:1,
exact:true,
strong:true
};
}

var distance=
ssrTherapyEditDistance(
normalizedLeft,
normalizedRight
);

var maxLength=
Math.max(
normalizedLeft.length,
normalizedRight.length
);

var editScore=
maxLength
?1-(distance/maxLength)
:0;

var tokenOverlap=
ssrTherapyTokenOverlap(
normalizedLeft,
normalizedRight
);

/*
 * Strong fuzzy matching is intentionally conservative.
 *
 * It accepts:
 * - one-character typos in meaningful names, or
 * - >= 90% edit similarity, or
 * - >= 86% edit similarity with >= 80% token overlap.
 *
 * Example:
 * "Weight Maintenance Session"
 * "Weight Maintenance Sessionn"
 * -> distance 1 -> strong match.
 */
var strong=
(
distance<=1&&
Math.min(
normalizedLeft.length,
normalizedRight.length
)>=6
)||
editScore>=0.90||
(
editScore>=0.86&&
tokenOverlap>=0.80
);

return{
score:Math.max(
0,
Math.min(
1,
editScore
)
),
distance:distance,
token_overlap:tokenOverlap,
exact:false,
strong:strong
};
}

function ssrAppointmentTherapyMatchInfo(appointment,therapyRows){
appointment=appointment||{};
therapyRows=
Array.isArray(therapyRows)
?therapyRows
:[];

var appointmentPlan=
getSSRAppointmentTherapyPlan(
appointment
);

var appointmentType=
getSSRAppointmentTherapyType(
appointment
);

var normalizedAppointmentType=
normalizeSSRComparable(
appointmentType
);

var workingRows=
therapyRows.slice();

var result={
mode:"none",
rows:[],
appointment_plan:appointmentPlan,
appointment_type:appointmentType,
matched_plan:"",
matched_type:"",
score:0,
distance:999,
message:""
};

/*
 * 1. Therapy Plan link is authoritative when present.
 */
if(appointmentPlan){
workingRows=
workingRows.filter(function(row){
return String(
row.plan_name||""
).trim()===appointmentPlan;
});

if(!workingRows.length){
result.mode="plan_missing";
result.message=
"The appointment is linked to Therapy Plan "+
appointmentPlan+
", but that plan has no remaining therapy session available.";
return result;
}
}

/*
 * If the appointment has no therapy/service value, an exact plan
 * link can still safely restrict the user to rows from that plan.
 */
if(!normalizedAppointmentType){
if(appointmentPlan){
result.rows=workingRows;

if(workingRows.length===1){
result.mode="plan_only";
result.matched_plan=
String(
workingRows[0].plan_name||""
);
result.matched_type=
String(
workingRows[0].service||
workingRows[0].therapy_type||
""
);
result.message=
"The appointment has no therapy type, so the therapy service was identified from its exact Therapy Plan link.";
}
else{
result.mode="ambiguous";
result.message=
"The appointment has an exact Therapy Plan link but no therapy type. Select the correct therapy row below.";
}

return result;
}

result.mode="therapy_missing";
result.message=
"The appointment has neither a Therapy Plan link nor a therapy type.";
return result;
}

/*
 * 2. Exact normalized therapy-name match.
 */
var exactRows=
workingRows.filter(function(row){
return normalizeSSRComparable(
row.service||
row.therapy_type
)===normalizedAppointmentType;
});

if(exactRows.length===1){
result.mode=
appointmentPlan
?"plan_exact"
:"exact";

result.rows=exactRows;
result.score=1;
result.distance=0;
result.matched_plan=
String(
exactRows[0].plan_name||""
);
result.matched_type=
String(
exactRows[0].service||
exactRows[0].therapy_type||
""
);

return result;
}

if(exactRows.length>1){
result.mode="ambiguous";
result.rows=exactRows;
result.score=1;
result.distance=0;
result.message=
"More than one remaining therapy row exactly matches the appointment. Select the correct package row below.";
return result;
}

/*
 * 3. Controlled typo-tolerant match.
 */
var scored=
workingRows.map(function(row){
var rowType=
String(
row.service||
row.therapy_type||
""
);

var similarity=
ssrTherapyNameSimilarity(
appointmentType,
rowType
);

return{
row:row,
score:similarity.score,
distance:similarity.distance,
token_overlap:similarity.token_overlap,
strong:similarity.strong
};
})
.filter(function(candidate){
return candidate.strong;
})
.sort(function(left,right){
if(right.score!==left.score){
return right.score-left.score;
}

if(left.distance!==right.distance){
return left.distance-right.distance;
}

return String(
left.row.plan_name||""
).localeCompare(
String(
right.row.plan_name||""
)
);
});

if(!scored.length){
result.mode="none";
result.message=
"No remaining therapy row is sufficiently similar to the selected appointment therapy.";
return result;
}

var top=
scored[0];

var second=
scored.length>1
?scored[1]
:null;

var scoreGap=
second
?top.score-second.score
:1;

/*
 * One clear strong candidate can be used automatically.
 * If two candidates are almost equally strong, show both and
 * require the user to choose.
 */
if(
!second||
scoreGap>=0.08||
top.distance+2<=second.distance
){
result.mode=
appointmentPlan
?"plan_fuzzy"
:"fuzzy";

result.rows=[
top.row
];

result.score=
top.score;

result.distance=
top.distance;

result.matched_plan=
String(
top.row.plan_name||""
);

result.matched_type=
String(
top.row.service||
top.row.therapy_type||
""
);

result.message=
"Appointment therapy \""+
appointmentType+
"\" closely matches therapy \""+
result.matched_type+
"\".";

return result;
}

/*
 * Ambiguous strong candidates.
 */
var ambiguityFloor=
Math.max(
0.86,
top.score-0.05
);

result.mode="ambiguous";
result.rows=
scored
.filter(function(candidate){
return candidate.score>=ambiguityFloor;
})
.map(function(candidate){
return candidate.row;
});

result.score=
top.score;

result.distance=
top.distance;

result.message=
"Multiple remaining therapy rows are similarly matched to the appointment. Select the correct row below.";

return result;
}

