async function ssrHistoryLoadRequestItems(requestNames){
requestNames=(Array.isArray(requestNames)?requestNames:[]).map(function(name){
return String(name||"").trim();
}).filter(Boolean);
var byRequest=Object.create(null);
if(!requestNames.length){return byRequest;}

/*
 * Do not query the child DocType "Material Request Item" directly here.
 * On website/branch-user sessions Frappe can reject child-table get_list
 * calls during permission validation because the parent DocType context is
 * not available consistently through the API Server Script gateway.
 *
 * Material Request itself is the authoritative parent and getDoc() returns
 * its items child table safely with the parent document. Reuse any rows that
 * are already hydrated in state.requests, then fetch only the missing parent
 * documents in small parallel batches.
 */
var loadedRequests=Array.isArray(state.requests)?state.requests:[];
var missingNames=[];
requestNames.forEach(function(requestName){
var loaded=loadedRequests.find(function(row){
return String(row&&row.name||"").trim()===requestName;
});
if(loaded&&Array.isArray(loaded.items)&&loaded.items.length){
byRequest[requestName]=loaded.items.slice();
}
else{
missingNames.push(requestName);
}
});

for(var start=0;start<missingNames.length;start+=8){
var batch=missingNames.slice(start,start+8);
var docs=await Promise.all(batch.map(async function(requestName){
try{
return await getDoc(DOCTYPE,requestName);
}
catch(error){
void 0;
return null;
}
}));
docs.forEach(function(doc,index){
var requestName=batch[index];
if(doc&&doc.name){
byRequest[doc.name]=Array.isArray(doc.items)?doc.items:[];
}
else if(!byRequest[requestName]){
byRequest[requestName]=[];
}
});
}
return byRequest;
}
async function ssrHistoryLoadAppointments(appointmentNames){
