function applySSRAppointmentRequiredByLimit(){

    var requiredBy =
        byId(
            "ssr-required-by"
        );


    if(
        !requiredBy
    ){
        return;
    }


    var today =
        todayISO();


    /*
     * Required By can never be before today.
     */
    requiredBy.min =
        today;


    /*
     * No appointment selected yet.
     */
    if(
        !state.selectedAppointment
    ){

        requiredBy.removeAttribute(
            "max"
        );


        /*
         * Keep today only until an appointment is selected.
         */
        if(
            !requiredBy.value
        ){

            requiredBy.value =
                today;
        }


        return;
    }


    /*
     * =========================================================
     * APPOINTMENT DATE IS THE DEFAULT REQUIRED BY DATE
     * =========================================================
     */

    var appointmentDate =
        String(
            state.selectedAppointment
                .appointment_date ||
            ""
        )
        .slice(
            0,
            10
        );


    if(
        !appointmentDate
    ){

        requiredBy.removeAttribute(
            "max"
        );


        if(
            !requiredBy.value
        ){

            requiredBy.value =
                today;
        }


        return;
    }


    /*
     * Required By must not go later than appointment date.
     */
    requiredBy.max =
        appointmentDate;


    /*
     * IMPORTANT:
     *
     * As soon as an appointment exists, use that appointment date
     * as the Required By date.
     *
     * This also fixes the single-appointment auto-selection case,
     * where selectSSRAppointment() may not have been called.
     */
    requiredBy.value =
        appointmentDate;
}
function selectSSRAppointment(
    appointmentName
){

    appointmentName =
        String(
            appointmentName ||
            ""
        ).trim();


    var appointment =
        (
            state.futureAppointments ||
            []
        )
        .find(
            function(row){

                return (
                    String(
                        row.name ||
                        ""
                    ) ===
                    appointmentName
                );
            }
        ) ||
        null;


    /*
     * Store selected appointment.
     */
    state.selectedAppointment =
        appointment;


    state.ssrAppointmentMatch =
        null;


    /*
     * Appointment change can change the destination branch /
     * warehouse, so clear the cached warehouse lookup.
     */
    LIFE_REQUEST_TARGET_WAREHOUSE_LOOKUP_CACHE.key =
        "";


    LIFE_REQUEST_TARGET_WAREHOUSE_LOOKUP_CACHE.rows =
        [];


    LIFE_REQUEST_TARGET_WAREHOUSE_LOOKUP_CACHE.promise =
        null;


    /*
     * Therapy selection belongs to the previous appointment
     * context, so clear it when appointment changes.
     */
    state.selectedPlans = {};


    /*
     * =========================================================
     * APPOINTMENT DATE → DEFAULT REQUIRED BY DATE
     * =========================================================
     *
     * Business rule:
     *
     * When a future appointment is selected, its appointment
     * date becomes the default Required By date.
     *
     * Example:
     *
     * Appointment Date : 05-Oct-2026
     * Required By      : 05-Oct-2026
     *
     * The user can still manually change Required By later,
     * subject to the existing validations:
     *
     * - not before Request Date
     * - not after Appointment Date
     * =========================================================
     */

    var requiredByInput =
        byId(
            "ssr-required-by"
        );


    if(
        requiredByInput
    ){

        requiredByInput.min =
            todayISO();


        if(
            appointment &&
            appointment.appointment_date
        ){

            var appointmentDate =
                String(
                    appointment.appointment_date
                )
                .slice(
                    0,
                    10
                );


            /*
             * Appointment is the maximum allowed Required By date.
             */
            requiredByInput.max =
                appointmentDate;


            /*
             * IMPORTANT:
             * Set appointment date as the default immediately.
             *
             * This intentionally replaces the initial "today"
             * value populated when the form was reset.
             */
            requiredByInput.value =
                appointmentDate;
        }
        else{

            requiredByInput.removeAttribute(
                "max"
            );


            requiredByInput.value =
                todayISO();
        }
    }


    /*
     * =========================================================
     * APPOINTMENT BRANCH → TARGET WAREHOUSE
     * =========================================================
     *
     * Appointment branch remains the authoritative destination
     * branch for a Consumable Material Request.
     */

    var appointmentTargets =
        getRequestTargetWarehouses();


    state.targetWarehouse =
        appointmentTargets.length
            ? String(
                appointmentTargets[0].name ||
                ""
            ).trim()
            : "";


    /*
     * Reset downstream form sections because the appointment
     * changed.
     */
    hide(
        "ssr-remarks-card"
    );


    hide(
        "ssr-proceed-row"
    );


    /*
     * Keep the normal Required By min/max validation logic.
     *
     * Since we already assigned appointmentDate above,
     * this will preserve the same value.
     */
    applySSRAppointmentRequiredByLimit();


    /*
     * Refresh client / therapy UI for newly selected appointment.
     */
    renderSSRClientArea();
}
async function validateSelectedSSRAppointment(){
var selectedClient=state.selectedClient;
var selectedAppointment=state.selectedAppointment;
if(!selectedClient){
throw new Error("Select a client.");
}
if(!selectedAppointment||!selectedAppointment.name){
throw new Error("Select a future client appointment.");
}
var appointment=await getDoc("Patient Appointment",selectedAppointment.name);
if(String(appointment.patient||"").trim()!==String(selectedClient.name||"").trim()){
throw new Error("The selected appointment does not belong to the selected client.");
}
if(isSSRCancelledAppointment(appointment)){
throw new Error("The selected appointment is cancelled, closed, or marked No Show. Select another future appointment.");
