function ssrSessionExecutionDate(session){
session=session||{};

/*
 * FINAL APPOINTMENT / THERAPY SESSION DATE RULE
 *
 * 1. If custom_actual_session_date exists, it is authoritative.
 * 2. Otherwise use start_date.
