function ssrComparableDateTimeValue(value){
value=String(value||"").trim();
if(!value){
return NaN;
}
var normalized=value.replace(" ","T");
var time=new Date(normalized).getTime();
return isNaN(time)?NaN:time;
}

function ssrSessionOccurredDateTimeValue(session){
session=session||{};

var sessionDate=
String(
ssrSessionExecutionDate(
session
)||
""
).slice(0,10);

var sessionTime=
String(
session.custom_in_time_||
session.start_time||
""
).trim();

if(sessionDate&&sessionTime){
var explicitTime=
ssrComparableDateTimeValue(
sessionDate+
"T"+
sessionTime
);

if(!isNaN(explicitTime)){
return explicitTime;
}
}

/*
 * Therapy Session.creation is a useful second-level audit time
 * when the actual session row has no usable start time.
 */
var creationTime=
ssrComparableDateTimeValue(
ssrSessionCreatedTime(
session
)
);

if(!isNaN(creationTime)){
return creationTime;
}

/*
 * Last fallback: session date only.
 * Noon is used instead of midnight so a same-day session is not
 * automatically treated as "before sent" just because its time
 * was not recorded.
 */
if(sessionDate){
var dateOnly=
ssrComparableDateTimeValue(
sessionDate+
"T12:00:00"
);

if(!isNaN(dateOnly)){
return dateOnly;
}
}

return NaN;
}

function ssrSessionOccurredAfterSent(session,sentDate){
if(!sentDate){
return true;
}

var sentTime=
ssrComparableDateTimeValue(
sentDate
);

if(isNaN(sentTime)){
return true;
}

var sessionTime=
ssrSessionOccurredDateTimeValue(
session
);

/*
 * Unknown session timing must not be falsely classified as
 * "before material sent".
 */
if(isNaN(sessionTime)){
return true;
}

return sessionTime>=sentTime;
}

function ssrSessionOccurredBeforeSent(session,sentDate){
if(!sentDate){
return false;
}

var sentTime=
ssrComparableDateTimeValue(
sentDate
);

var sessionTime=
ssrSessionOccurredDateTimeValue(
session
);

if(
isNaN(sentTime)||
isNaN(sessionTime)
){
return false;
}

return sessionTime<sentTime;
}

