function ssrISODateFromLooseText(value){
value=String(value||"").trim();

if(!value){
return"";
}

/* ISO yyyy-mm-dd */
var iso=value.match(
/\b(\d{4})-(\d{2})-(\d{2})\b/
);

if(iso){
return(
iso[1]+"-"+iso[2]+"-"+iso[3]
);
}

/* dd Mon yy / dd Mon yyyy / dd-Mon-yy */
var monthNames={
jan:"01",january:"01",
feb:"02",february:"02",
mar:"03",march:"03",
apr:"04",april:"04",
may:"05",
jun:"06",june:"06",
jul:"07",july:"07",
aug:"08",august:"08",
sep:"09",sept:"09",september:"09",
oct:"10",october:"10",
nov:"11",november:"11",
dec:"12",december:"12"
};

var named=value.match(
/\b(\d{1,2})[\s\-\/]+([A-Za-z]{3,9})[\s\-\/]+(\d{2,4})\b/
);

if(named){
var day=String(
num(
named[1],
0
)
).padStart(
2,
"0"
);

var month=
monthNames[
String(
named[2]||
""
).toLowerCase()
];

var year=
String(
named[3]||
""
);

if(year.length===2){
year=
num(
year,
0
)>=70
?"19"+year
:"20"+year;
}

if(month&&year.length===4){
return(
year+"-"+month+"-"+day
);
}
}

/* dd/mm/yyyy */
var numeric=value.match(
/\b(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})\b/
);

if(numeric){
return(
String(
numeric[3]
)+"-"+
String(
num(
numeric[2],
0
)
).padStart(
2,
"0"
)+"-"+
String(
num(
numeric[1],
0
)
).padStart(
2,
"0"
)
);
}

return"";
}

