score+=60;
evidence.push(
"Exact Appointment Date"
);
}

/*
 * Without a stored date hint we require therapy context.
 * Same-client alone is never enough to recover an appointment.
 */
if(
!dateHint&&
!evidence.length
){
return{
matched:false,
score:0,
evidence:[]
};
}

return{
matched:true,
score:score,
evidence:evidence
};
}

