function ssrHistoricalDateWindowAllows(
appointment,
sentDate,
dateHint
){
appointment=appointment||{};

var appointmentDate=
String(
appointment.appointment_date||
""
).slice(
0,
10
);

if(!appointmentDate){
return false;
}

if(dateHint){
return appointmentDate===dateHint;
}

var sentISO=
ssrISODateFromLooseText(
sentDate
);

if(!sentISO){
return false;
}

var sentTime=
ssrComparableDateTimeValue(
sentISO+
"T00:00:00"
);

var appointmentTime=
ssrComparableDateTimeValue(
appointmentDate+
"T00:00:00"
);

if(
isNaN(sentTime)||
isNaN(appointmentTime)
){
return false;
}

/*
 * For a request with no stored appointment link/date, only look
 * forward from material dispatch. 45 days is intentionally
 * conservative; appointments outside this window are not guessed.
 */
var diffDays=
(
appointmentTime-
sentTime
)/
86400000;

return(
diffDays>=0&&
diffDays<=45
);
}

function ssrHistoricalSessionMatchesRecoveredAppointment(
session,
