if(
num(
session.docstatus,
0
)===2
){
return false;
}

var appointmentName=
String(
appointment.name||
""
).trim();

var sessionAppointment=
String(
session.appointment||
""
).trim();

/*
 * A session explicitly linked to another appointment cannot be
 * used for this recovered appointment.
 */
if(
sessionAppointment&&
appointmentName&&
sessionAppointment!==appointmentName
){
return false;
}

var sessionDate=
ssrSessionExecutionDate(
session
);

var appointmentDate=
String(
appointment.appointment_date||
""
).slice(
0,
10
);

/*
 * Appointment-linked DATE is authoritative for historical
 * recovery. Session must have happened on that same date.
 */
if(
!sessionDate||
!appointmentDate||
sessionDate!==appointmentDate
){
return false;
}

return ssrSessionMatchesAppointmentService(
session,
appointment
);
}


function ssrHistoricalSessionMatchesRequestContext(
session,
requestPlans,
requestTypes
){
session=session||{};

requestPlans=
Array.isArray(
requestPlans
)
?requestPlans
:[];

requestTypes=
Array.isArray(
requestTypes
)
?requestTypes
:[];

var evidence=[];
var score=0;

var sessionPlan=
String(
session.therapy_plan||
""
).trim();

var sessionType=
String(
session.therapy_type||
""
).trim();

var planMatched=false;
var typeMatched=false;


/* ---------------------------------------------------------
   Therapy Plan
   --------------------------------------------------------- */

if(
requestPlans.length&&
sessionPlan
){

planMatched=
requestPlans.some(function(value){

return(
normalizeSSRComparable(
value
)===
normalizeSSRComparable(
sessionPlan
)
);

});

if(planMatched){

score+=70;

evidence.push(
"Therapy Plan"
);

}
else{

/*
 * A Therapy Session explicitly linked to a DIFFERENT Therapy Plan
 * cannot belong to this Material Request.
 */
return{
matched:false,
score:0,
evidence:[],
plan_match:false,
type_match:false
};

}

}


/* ---------------------------------------------------------
   Therapy Type
   --------------------------------------------------------- */

if(
requestTypes.length&&
sessionType
){

var bestMatch=null;

requestTypes.forEach(function(value){

var similarity=
ssrTherapyNameSimilarity(
value,
sessionType
);

if(
similarity.strong&&
(
!bestMatch||
similarity.score>
bestMatch.score
)
){

bestMatch=
similarity;

}

});

if(bestMatch){

typeMatched=true;

score+=
bestMatch.exact
?50
:40;

evidence.push(
bestMatch.exact
?"Therapy Type"
:"Therapy Type (near match)"
);

}
else if(planMatched){

/*
 * Older Therapy Sessions and Appointment records are not always
 * consistent in therapy-type text.
 *
 * If the Therapy Plan is an exact match, keep the candidate and
 * let the exact Session → Appointment relationship + appointment
 * date decide it. We DO NOT call the therapy type confirmed.
 */
evidence.push(
"Therapy Type not confirmed"
);

}
else{

/*
 * No plan evidence and therapy type does not match: unsafe.
 */
return{
matched:false,
score:0,
evidence:[],
plan_match:false,
type_match:false
};

}

}


/*
 * At least one real package/service signal is required.
 * Same-client alone is never enough.
 */
if(
!planMatched&&
!typeMatched
){

return{
matched:false,
score:0,
evidence:[],
plan_match:false,
type_match:false
};

}

return{
matched:true,
score:score,
evidence:evidence,
plan_match:planMatched,
type_match:typeMatched
};
}

function ssrHistoricalSessionDateInsideRequestWindow(
doc,
session,
sentDate
){
doc=doc||{};
session=session||{};

var sessionDate=
String(
ssrSessionExecutionDate(
session
)||
""
).slice(
0,
10
);

if(!sessionDate){
return false;
}


/*
 * Never connect an old therapy session that happened before this
 * Material Request existed.
 */
var requestStart=
String(
doc.transaction_date||
doc.creation||
""
).slice(
0,
10
);

if(
requestStart&&
sessionDate<
requestStart
){
return false;
}


/*
 * Prevent a very distant future therapy session from being attached
 * to an old consumable dispatch.
 */
var sentISO=
ssrISODateFromLooseText(
sentDate
);

if(sentISO){

var sentTime=
ssrComparableDateTimeValue(
sentISO+
"T00:00:00"
);

var sessionTime=
ssrComparableDateTimeValue(
sessionDate+
"T00:00:00"
);

if(
!isNaN(sentTime)&&
!isNaN(sessionTime)
){

var diffDays=
(
sessionTime-
sentTime
)/
86400000;

/*
 * Allow sessions before exact dispatch time/date because those are
 * important audit exceptions, but not sessions from before the
 * Material Request transaction date. Future matches are limited.
 */
if(diffDays>45){
return false;
}

}

}

return true;
}

async function loadSSRHistoricalExactSessionAppointmentPairs(
doc,
options
){
doc=doc||{};
options=options||{};

var sentDate=
String(
options.sentDate||
options.materialSentDate||
""
).trim();

var patient=
String(
doc.custom_client_name||
doc.custom_new_client_name||
extractNoteValue(doc.custom_additional_notes||"","Client ID")||
""
).trim();

if(!patient){
return[];
}

var planContext=
options.planContext||
await loadSSRHistoricalRequestTherapyContext(doc);

if(
!planContext.plan_ids.length&&
!planContext.all_types.length
){
return[];
}

var sessions=[];

try{
sessions=
await loadSSRFallbackSessionsForPatient(patient);
}
catch(error){
void 0;
return[];
}

var sessionCandidates=
(sessions||[]).filter(function(session){

if(num(session&&session.docstatus,0)!==1){
return false;
}

var appointmentName=
String(session&&session.appointment||"").trim();

if(!appointmentName){
return false;
}

if(
!ssrHistoricalSessionDateInsideRequestWindow(
doc,
session,
sentDate
)
){
return false;
}

var context=
ssrHistoricalSessionContextMatchMapped(
session,
planContext
);

if(!context.matched){
return false;
}

session.__ssrRequestContext=context;

session.__ssrBeforeMaterialSent=
ssrSessionOccurredBeforeSent(
session,
sentDate
);

return true;
});

if(!sessionCandidates.length){
return[];
}

var appointmentNames=
uniqueValues(
sessionCandidates
.map(function(session){
return String(session.appointment||"").trim();
})
.filter(Boolean)
);

var appointmentDocs=
await Promise.all(
appointmentNames.map(async function(appointmentName){
try{
return await loadSSRAppointmentForExecution(
appointmentName
);
}
catch(error){
void 0;
return null;
}
})
);

var appointmentMap=Object.create(null);

appointmentDocs.filter(Boolean).forEach(function(appointment){
appointmentMap[
String(appointment.name||"")
]=appointment;
});

var pairs=[];

sessionCandidates.forEach(function(session){

var appointmentName=
String(session.appointment||"").trim();

var appointment=
appointmentMap[appointmentName];

if(!appointment){
return;
}

var appointmentPatient=
String(appointment.patient||"").trim();

if(
appointmentPatient&&
normalizeSSRComparable(appointmentPatient)!==
normalizeSSRComparable(patient)
){
return;
}

/*
 * Appointment-linked date is the accuracy anchor.
 */
var sessionDate=
String(
ssrSessionExecutionDate(session)||
""
).slice(0,10);

var appointmentDate=
String(
appointment.appointment_date||
""
).slice(0,10);

if(
!sessionDate||
!appointmentDate||
sessionDate!==appointmentDate
){
return;
}

var requestContext=
session.__ssrRequestContext||
{
score:0,
evidence:[]
};

var appointmentContext=
ssrHistoricalAppointmentContextMatchMapped(
appointment,
planContext,
""
);

var evidence=[
"Therapy Session → Patient Appointment",
"Session Date = Appointment Date"
].concat(
requestContext.evidence||
[]
);

var score=
350+
requestContext.score;

if(
appointmentContext&&
appointmentContext.matched
){
score+=appointmentContext.score;
evidence=
evidence.concat(
appointmentContext.evidence||
[]
);
}
else{
evidence.push(
"Appointment therapy metadata not required"
);
}

var requiredBy=
String(doc.schedule_date||"").slice(0,10);

if(requiredBy&&appointmentDate===requiredBy){
score+=15;
evidence.push(
"Appointment Date = Required By"
);
}

pairs.push({
appointment:appointment,
session:session,
score:score,
before_sent:
!!session.__ssrBeforeMaterialSent,
evidence:
uniqueValues(evidence)
});

});

pairs.sort(function(left,right){
if(right.score!==left.score){
return right.score-left.score;
}

return String(
right.session&&(
right.session.modified||
right.session.creation
)||
""
).localeCompare(
String(
left.session&&(
left.session.modified||
left.session.creation
)||
""
)
);
});

return pairs;
}

async function loadSSRHistoricalAppointmentExecution(
doc,
options
){
doc=doc||{};
options=options||{};

var sentDate=
String(
options.sentDate||
options.materialSentDate||
""
).trim();

var receiptDate=
String(
options.receiptDate||
""
).trim();

function historicalResult(extra){
return Object.assign(
{
linked:false,
status_key:"not_linked",
status_label:"Appointment Not Linked",
appointment:null,
session:null,
match_type:"none",
match_basis:"",
candidate_count:0,
sent_date:sentDate,
receipt_date:receiptDate,
historical_recovery:true
},
extra||{}
);
}

var patient=
String(
doc.custom_client_name||
doc.custom_new_client_name||
extractNoteValue(
doc.custom_additional_notes||
"",
"Client ID"
)||
""
).trim();

if(!patient){
return historicalResult({
match_basis:
"Historical request has no client reference"
});
}

var dateHint=
ssrHistoricalRequestAppointmentDateHint(
doc
);

var planContext=
await loadSSRHistoricalRequestTherapyContext(
doc
);

var requestPlans=
planContext.plan_ids;

var requestTypes=
planContext.all_types;


/* ---------------------------------------------------------
   STRONGEST HISTORICAL RECOVERY
   ---------------------------------------------------------
   Older Material Requests may not contain custom_patient_appointment,
   while the Therapy Session itself may still have the exact
   appointment relationship.

   This path is stronger than trying to infer an appointment from
   appointment metadata because it uses:

     Material Request therapy context
          ↓
     submitted Therapy Session
          ↓
     Therapy Session.appointment
          ↓
     exact Patient Appointment
          ↓
     Session date = Appointment date
 */
var exactPairs=
await loadSSRHistoricalExactSessionAppointmentPairs(
doc,
{
sentDate:
sentDate,

receiptDate:
receiptDate,

planContext:
planContext
}
);

if(exactPairs.length===1){

var exactPair=
exactPairs[0];

if(
exactPair.before_sent
){

return historicalResult({
linked:true,
status_key:"session_before_sent",
status_label:
"Session Given Before Material Sent — Verify",
appointment:
exactPair.appointment,
session:
exactPair.session,
match_type:"recovered_exact",
candidate_count:1,
match_basis:
"Historical request recovered using "+
exactPair.evidence.join(" + ")+
". The submitted Therapy Session is linked to this Patient Appointment and occurred on the exact appointment date, but the session time is earlier than the Stores material-dispatch time."
});

}

return historicalResult({
linked:true,
status_key:"executed",
status_label:
"Session Given — Exact Session/Appointment Match",
appointment:
exactPair.appointment,
session:
exactPair.session,
match_type:"recovered_exact",
candidate_count:1,
match_basis:
"Historical request recovered using "+
exactPair.evidence.join(" + ")
});

}

if(exactPairs.length>1){

return historicalResult({
linked:true,
status_key:"multiple_sessions",
status_label:
"Multiple Exact Session/Appointment Matches — Verify",
appointment:null,
session:null,
match_type:"ambiguous",
candidate_count:
exactPairs.length,
candidates:
exactPairs.map(function(pair){
return pair.session;
}),
match_basis:
"More than one submitted Therapy Session matches the Material Request therapy context and has its own exact Patient Appointment on the same session date."
});

}


if(
!dateHint&&
!requestPlans.length&&
!requestTypes.length
){
return historicalResult({
status_key:"appointment_ambiguous",
status_label:
"Appointment Link Missing — Verify Manually",
linked:true,
match_type:"ambiguous",
match_basis:
"Client is known, but the historical request has no appointment date or therapy context. No automatic match was attempted."
});
}

var appointments=[];

try{
appointments=
await loadSSRHistoricalAppointmentsForPatient(
patient
);
}
catch(error){
return historicalResult({
status_key:"appointment_missing",
status_label:
"Appointment Lookup Unavailable",
linked:true,
match_type:"none",
error:error,
match_basis:
"Historical Patient Appointment lookup failed"
});
}

var candidates=
appointments
.filter(function(appointment){

if(
!ssrHistoricalDateWindowAllows(
appointment,
sentDate,
dateHint
)
){
return false;
}

var context=
ssrHistoricalAppointmentContextMatchMapped(
appointment,
planContext,
dateHint
);

if(!context.matched){
return false;
}

appointment.__ssrHistoricalMatch=
context;

return true;
});


if(!candidates.length){
return historicalResult({
status_key:"appointment_ambiguous",
status_label:
"Appointment Link Missing — No Accurate Match",
linked:true,
match_type:"ambiguous",
match_basis:
dateHint
?(
"No Patient Appointment matched the stored appointment date "+
dateHint+
" and request therapy context."
)
:
"Client appointments were checked after material dispatch, but none matched the request therapy context accurately."
});
}


/*
 * Sessions are fetched only after real Patient Appointment
 * candidates exist. We do not search arbitrary client sessions.
 */
var patientSessions=[];

try{
patientSessions=
await loadSSRFallbackSessionsForPatient(
patient
);
}
catch(error){
return historicalResult({
status_key:"appointment_missing",
status_label:
"Session Lookup Unavailable",
linked:true,
match_type:"none",
error:error,
match_basis:
"Historical Therapy Session lookup failed after appointment recovery"
});
}


var pairs=[];

candidates.forEach(function(appointment){

var appointmentSessions=
patientSessions.filter(function(session){
return ssrHistoricalSessionMatchesRecoveredAppointment(
session,
appointment
);
});

appointmentSessions.forEach(function(session){

var context=
appointment.__ssrHistoricalMatch||
{
score:0,
evidence:[]
};

var exactSessionAppointment=
String(
session.appointment||
""
).trim()===
String(
appointment.name||
""
).trim();

pairs.push({
appointment:appointment,
session:session,
score:
context.score+
(
exactSessionAppointment
?80
:20
),
evidence:
(context.evidence||[])
.concat(
exactSessionAppointment
?[
"Therapy Session → Patient Appointment"
]
:[
"Session Date = Appointment Date"
]
),
exact_session_appointment:
exactSessionAppointment
});

});

});


var submittedPairs=
pairs
.filter(function(pair){
return num(
pair.session&&
pair.session.docstatus,
0
)===1;
})
.sort(function(left,right){
return right.score-left.score;
});


/*
 * If more than one submitted appointment/session pair exists,
 * only auto-select when ONE pair has a direct Therapy Session
 * appointment link and every other candidate is weaker.
 */
if(submittedPairs.length>1){

var exactPairs=
submittedPairs.filter(function(pair){
return pair.exact_session_appointment;
});

if(exactPairs.length!==1){
return historicalResult({
status_key:"multiple_sessions",
status_label:
"Multiple Appointment-Date Sessions — Verify Manually",
linked:true,
match_type:"ambiguous",
candidates:
submittedPairs.map(function(pair){
return pair.session;
}),
candidate_count:
submittedPairs.length,
match_basis:
"More than one client appointment has a matching Therapy Session on its own appointment date. The Material Request itself does not identify which appointment was intended."
});
}

submittedPairs=[
exactPairs[0]
];
}


if(submittedPairs.length===1){

var pair=
submittedPairs[0];

if(
ssrSessionOccurredBeforeSent(
pair.session,
sentDate
)
){
return historicalResult({
linked:true,
status_key:"session_before_sent",
status_label:
"Session Given Before Material Sent — Verify",
appointment:
pair.appointment,
session:
pair.session,
match_type:"recovered",
candidate_count:1,
match_basis:
"Historical appointment recovered using "+
pair.evidence.join(" + ")+
"; session date matches the appointment date, but its time is earlier than material dispatch."
});
}

return historicalResult({
linked:true,
status_key:"probable_executed",
status_label:
"Session Given — Appointment-Date Match",
appointment:
pair.appointment,
session:
pair.session,
match_type:"recovered",
candidate_count:1,
match_basis:
"Historical request: appointment recovered using "+
pair.evidence.join(" + ")+
". Therapy Session occurred on the recovered Patient Appointment date."
});
}


/*
 * No submitted session. Draft sessions are handled only if one
 * appointment/date pair is unique.
 */
var draftPairs=
pairs
.filter(function(pair){
return num(
pair.session&&
pair.session.docstatus,
0
)===0;
});

if(draftPairs.length===1){
return historicalResult({
linked:true,
status_key:"probable_draft",
status_label:
"Session Entry Draft — Appointment-Date Match",
appointment:
draftPairs[0].appointment,
session:
draftPairs[0].session,
match_type:"recovered",
candidate_count:1,
match_basis:
"Draft Therapy Session occurs on the recovered Patient Appointment date."
});
}

if(draftPairs.length>1){
return historicalResult({
linked:true,
status_key:"multiple_sessions",
status_label:
"Multiple Draft Appointment-Date Sessions — Verify",
match_type:"ambiguous",
candidate_count:
draftPairs.length,
candidates:
draftPairs.map(function(pair){
return pair.session;
}),
match_basis:
"More than one draft Therapy Session matches a possible appointment date."
});
}


/*
 * No session exists. We can say Awaiting / Not Given only when
 * exactly ONE real appointment candidate remains. Otherwise the
 * intended appointment cannot be identified accurately.
 */
if(candidates.length!==1){
return historicalResult({
linked:true,
status_key:"appointment_ambiguous",
status_label:
"Multiple Possible Appointments — Verify Manually",
match_type:"ambiguous",
candidate_count:
candidates.length,
match_basis:
"Multiple Patient Appointments match the client/date/therapy context and the historical Material Request has no direct appointment link."
});
}


var recoveredAppointment=
candidates[0];

if(
isSSRCancelledAppointment(
recoveredAppointment
)
){
return historicalResult({
linked:true,
status_key:"cancelled",
status_label:
"Recovered Appointment Cancelled / Closed",
appointment:
recoveredAppointment,
match_type:"recovered",
candidate_count:1,
match_basis:
"One Patient Appointment uniquely matched the historical request, but it is cancelled/closed."
});
}


if(
isSSRFutureAppointment(
recoveredAppointment
)
){
return historicalResult({
linked:true,
status_key:"upcoming",
status_label:
"Awaiting Session — Recovered Appointment Upcoming",
appointment:
recoveredAppointment,
match_type:"recovered",
candidate_count:1,
match_basis:
"One future Patient Appointment uniquely matches the client/date/therapy context. Session will be checked against that appointment date."
});
}


return historicalResult({
linked:true,
status_key:"not_executed",
status_label:
"Session Not Given on Appointment Date",
appointment:
recoveredAppointment,
match_type:"recovered",
candidate_count:1,
match_basis:
"One historical Patient Appointment uniquely matches the request, but no submitted Therapy Session was found on that appointment date."
});
}



function ssrSessionEffectiveTime(session){
session=session||{};

/*
 * Prefer the actual in-time captured on the Therapy Session.
 * Fall back to start_time when custom_in_time_ is unavailable.
 */
return String(
session.custom_in_time_||
session.start_time||
""
).trim();
}

function ssrTimeSeconds(value){
value=
String(
value||
""
).trim();

var match=
value.match(
/^(\d{1,2}):(\d{2})(?::(\d{2}(?:\.\d+)?))?/
);

if(!match){
return NaN;
}

return(
num(
match[1],
0
)*3600+
num(
match[2],
0
)*60+
num(
match[3],
0
)
);
}

function ssrSessionTimeDistanceFromAppointment(
session,
appointment
){
session=session||{};
appointment=appointment||{};

var sessionSeconds=
ssrTimeSeconds(
ssrSessionEffectiveTime(
session
)
);

var appointmentSeconds=
ssrTimeSeconds(
appointment.appointment_time
);

if(
isNaN(
sessionSeconds
)||
isNaN(
appointmentSeconds
)
){
return Number.MAX_SAFE_INTEGER;
}

return Math.abs(
sessionSeconds-
appointmentSeconds
);
}

