function ssrFilterAndSortSessionCandidates(
rows,
patient,
appointmentDate,
appointmentTherapyType,
appointment
){
rows=
Array.isArray(
rows
)
?rows
:[];

patient=
String(
patient||
""
).trim();

appointmentDate=
String(
appointmentDate||
""
).slice(
0,
10
);

appointmentTherapyType=
String(
appointmentTherapyType||
""
).trim();

appointment=
appointment||
{};

var sessionMap=
Object.create(null);

rows.forEach(function(session){

session=
session||
{};

var name=
String(
session.name||
""
).trim();

if(!name){
return;
}

if(
normalizeSSRComparable(
session.patient
)!==
normalizeSSRComparable(
patient
)
){
return;
}


/*
 * FINAL DATE RULE:
 * custom_actual_session_date has priority; only when it is blank
 * does start_date count.
 */
if(
ssrSessionExecutionDate(
session
)!==appointmentDate
){
return;
}

if(
num(
session.docstatus,
0
)===2
){
return;
}

var sessionTherapyType=
String(
session.therapy_type||
""
).trim();

if(!sessionTherapyType){
return;
}

var therapySimilarity=
ssrTherapyNameSimilarity(
appointmentTherapyType,
sessionTherapyType
);

if(!therapySimilarity.strong){
return;
}

session.__life_therapy_match={
appointment_therapy_type:
appointmentTherapyType,

session_therapy_type:
sessionTherapyType,

exact:
therapySimilarity.exact,

score:
therapySimilarity.score,

distance:
therapySimilarity.distance
};

sessionMap[
name
]=session;

});


var sessions=
Object.keys(
sessionMap
)
.map(function(name){
return sessionMap[
name
];
});


sessions.sort(function(left,right){

var leftStatus=
num(
left&&left.docstatus,
0
);

var rightStatus=
num(
right&&right.docstatus,
0
);

if(
leftStatus!==rightStatus
){
return rightStatus-leftStatus;
}


var appointmentName=
String(
appointment&&appointment.name||
""
).trim();

var leftAppointmentLinked=
!!(
appointmentName&&
String(
left&&left.appointment||
""
).trim()===appointmentName
);

var rightAppointmentLinked=
!!(
appointmentName&&
String(
right&&right.appointment||
""
).trim()===appointmentName
);

if(
leftAppointmentLinked!==
rightAppointmentLinked
){
return rightAppointmentLinked-leftAppointmentLinked;
}


var leftExact=
!!(
left&&
left.__life_therapy_match&&
left.__life_therapy_match.exact
);

var rightExact=
!!(
right&&
right.__life_therapy_match&&
right.__life_therapy_match.exact
);

if(leftExact!==rightExact){
return rightExact-leftExact;
}


var leftDistance=
ssrSessionTimeDistanceFromAppointment(
left,
appointment
);

var rightDistance=
ssrSessionTimeDistanceFromAppointment(
right,
appointment
);

if(leftDistance!==rightDistance){
return leftDistance-rightDistance;
}


return String(
left&&left.creation||
""
).localeCompare(
String(
right&&right.creation||
""
)
);

});

return sessions;
}

