async function ssrFlushSessionLookupBatch(){
var batch=
ssrSessionLookupBatchQueue.splice(
0,
ssrSessionLookupBatchQueue.length
);

ssrSessionLookupBatchTimer=null;

if(!batch.length){
return;
}


var patients=
uniqueValues(
batch.map(function(entry){
return entry.patient;
}).filter(Boolean)
);

var dates=
uniqueValues(
batch.map(function(entry){
return entry.appointmentDate;
}).filter(Boolean)
);


try{

var fieldSets=
ssrTherapySessionLookupFieldSets();

var responses=
await Promise.all([
safeGetList(
"Therapy Session",
fieldSets,
[
[
"patient",
"in",
patients
],
[
"start_date",
"in",
dates
],
[
"docstatus",
"in",
[
0,
1
]
]
],
{
order_by:
"docstatus desc, start_date asc, start_time asc, creation asc",

limit_page_length:
Math.max(
150,
patients.length*
dates.length*
20
)
}
),

safeGetList(
"Therapy Session",
fieldSets,
[
[
"patient",
"in",
patients
],
[
"custom_actual_session_date",
"in",
dates
],
[
"docstatus",
"in",
[
0,
1
]
]
],
{
order_by:
"docstatus desc, custom_actual_session_date asc, start_time asc, creation asc",

limit_page_length:
Math.max(
150,
patients.length*
dates.length*
20
)
}
)
]);


var allRows=
[]
.concat(
responses[0]||
[],
responses[1]||
[]
);


void 0;


batch.forEach(function(entry){

try{

entry.resolve(
ssrFilterAndSortSessionCandidates(
allRows,
entry.patient,
entry.appointmentDate,
entry.appointmentTherapyType,
entry.appointment
)
);

}
catch(error){

entry.reject(
error
);

}

});

}
catch(batchError){

void 0;


/*
 * Safe compatibility fallback: only if the server rejects the
 * batch `in` filters do we return to the old two-query lookup.
 */
await Promise.all(
batch.map(async function(entry){

try{

entry.resolve(
await ssrDirectSessionLookup(
entry.patient,
entry.appointmentDate,
entry.appointmentTherapyType,
entry.appointment
)
);

}
catch(error){

entry.reject(
error
);

}

})
);

}
}

async function loadSSRSessionsByClientDateAndTherapyType(
patient,
appointmentDate,
appointmentTherapyType,
appointment
){
patient=
String(
patient||
""
).trim();

appointmentDate=
String(
appointmentDate||
""
).slice(
0,
10
);

appointmentTherapyType=
String(
appointmentTherapyType||
""
).trim();

appointment=
appointment||
{};

if(
!patient||
!appointmentDate||
!appointmentTherapyType
){
return[];
}


/*
 * Concurrent visible-card requests are collected for a few
 * milliseconds, then resolved with two Therapy Session queries:
 *
 *   1. start_date IN visible appointment dates
 *   2. custom_actual_session_date IN visible appointment dates
 *
 * This replaces roughly 20 session queries for 10 cards with
 * normally 2–4 batched queries.
 */
return new Promise(function(resolve,reject){

ssrSessionLookupBatchQueue.push({
patient:
patient,

appointmentDate:
appointmentDate,

appointmentTherapyType:
appointmentTherapyType,

appointment:
appointment,

resolve:
resolve,

reject:
reject
});

if(!ssrSessionLookupBatchTimer){

ssrSessionLookupBatchTimer=
window.setTimeout(function(){

ssrFlushSessionLookupBatch()
.catch(function(error){

void 0;

});

},20);

}

});
}

async function loadSSRAppointmentExecution(
doc,
options
){
doc=doc||{};
options=options||{};

var sentDate=
String(
options.sentDate||
options.materialSentDate||
""
).trim();

var receiptDate=
String(
options.receiptDate||
""
).trim();

var appointmentReference=
ssrRequestAppointmentReference(
doc
);

var appointmentName=
appointmentReference.name;

var requestClient=
String(
doc.custom_client_name||
""
).trim();

function result(extra){

return Object.assign(
{
linked:false,

status_key:
"not_linked",

status_label:
"Appointment Not Linked",

appointment:
null,

session:
null,

matching_sessions:
[],

match_type:
"none",

match_basis:
"",

candidate_count:
0,

stored_appointment_name:
appointmentReference.stored_name||
"",

requested_appointment_name:
appointmentName||
"",

appointment_source:
appointmentReference.source||
"Not stored",

appointment_verified:
false,

request_client:
requestClient,

sent_date:
sentDate,

receipt_date:
receiptDate
},
extra||
{}
);

}


/* ---------------------------------------------------------
   A. Resolve Patient Appointment
   --------------------------------------------------------- */

var appointment=null;
var historicalAppointmentBasis="";

if(!appointmentName){

/*
 * Historical Material Requests may not have
 * custom_patient_appointment.
 *
 * Historical logic is used ONLY to recover the real appointment.
 * Once recovered, the code continues into the SAME final session
 * calculation used by directly linked requests:
 *
 *   Client
 *   + Appointment Therapy Type
 *   + Appointment Date
 */
var historicalExecution=
await loadSSRHistoricalAppointmentExecution(
doc,
{
sentDate:
sentDate,

receiptDate:
receiptDate
}
);

historicalExecution=
historicalExecution||
{};

appointment=
historicalExecution.appointment||
null;

if(
!appointment||
!appointment.name
){

historicalExecution.stored_appointment_name=
"";

historicalExecution.requested_appointment_name=
"";

historicalExecution.appointment_source=
"No appointment stored or safely recovered";

historicalExecution.appointment_verified=
false;

historicalExecution.request_client=
requestClient;

historicalExecution.sent_date=
historicalExecution.sent_date||
sentDate;

historicalExecution.receipt_date=
historicalExecution.receipt_date||
receiptDate;

return historicalExecution;

}

appointmentName=
String(
appointment.name
);

appointmentReference={
name:
appointmentName,

stored_name:
"",

source:
"Historical Patient Appointment recovery",

is_direct:
false
};

historicalAppointmentBasis=
String(
historicalExecution.match_basis||
""
).trim();

}
else{

try{

appointment=
await loadSSRAppointmentForExecution(
appointmentName
);

}
catch(error){

return result({
linked:true,

status_key:
"appointment_missing",

status_label:
"Appointment Unavailable",

appointment:{
name:
appointmentName
},

error:
error,

match_type:
"verify",

match_basis:
"Patient Appointment lookup failed."
});

}

}


if(!appointment){

return result({
linked:true,

status_key:
"appointment_missing",

status_label:
"Appointment Unavailable",

appointment:{
name:
appointmentName
},

match_type:
"verify",

match_basis:
"Patient Appointment does not exist or is no longer available."
});

}


/* ---------------------------------------------------------
   B. Confirm the appointment belongs to the request client
   --------------------------------------------------------- */

var appointmentPatient=
String(
appointment.patient||
""
).trim();

if(
requestClient&&
appointmentPatient&&
normalizeSSRComparable(
requestClient
)!==
normalizeSSRComparable(
appointmentPatient
)
){

return result({
linked:true,

status_key:
"appointment_client_mismatch",

status_label:
"Linked Appointment Client Mismatch — Verify",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"verify",

appointment_verified:
false,

match_basis:
"Material Request client "+
requestClient+
" does not match Patient Appointment client "+
appointmentPatient+
"."
});

}


var patientForMatch=
requestClient||
appointmentPatient;

var appointmentDate=
String(
appointment.appointment_date||
""
).slice(
0,
10
);

var appointmentTherapyType=
String(
getSSRAppointmentTherapyType(
appointment
)||
""
).trim();


if(
!patientForMatch||
!appointmentDate
){

return result({
linked:true,

status_key:
"appointment_missing",

status_label:
"Appointment Matching Data Incomplete",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"verify",

appointment_verified:
true,

match_basis:
"Patient or Appointment Date is missing, so session matching cannot run."
});

}


if(!appointmentTherapyType){

return result({
linked:true,

status_key:
"appointment_therapy_missing",

status_label:
"Appointment Therapy Type Missing — Verify",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"verify",

appointment_verified:
true,

match_basis:
"The linked Patient Appointment does not contain a Therapy Type. Client/date matching was not used because the final rule requires Client + Therapy Type + Appointment Date."
});

}


/* ---------------------------------------------------------
   C. FINAL SESSION CALCULATION
   ---------------------------------------------------------

   Therapy Session is considered a match ONLY when:

      Therapy Session.patient
            =
      Material Request / Patient Appointment client

   AND

      Therapy Session.therapy_type
            =
      Patient Appointment Therapy Type
      (controlled typo-tolerant comparison)

   AND

      Therapy Session effective date
            =
      Patient Appointment.appointment_date

   Effective Therapy Session date:
      custom_actual_session_date, when present
      otherwise start_date

   IMPORTANT:
      creation date is NEVER used for appointment-date matching.

   Effective Therapy Session time:
      custom_in_time_, when present
      otherwise start_time

   Time is used to order multiple valid matches by proximity to the
   Patient Appointment time. An exact time equality is NOT required.
   --------------------------------------------------------- */

var matchingSessions=
await loadSSRSessionsByClientDateAndTherapyType(
patientForMatch,
appointmentDate,
appointmentTherapyType,
appointment
);

var submittedSessions=
matchingSessions.filter(function(session){

return(
num(
session&&session.docstatus,
0
)===1
);

});

var draftSessions=
matchingSessions.filter(function(session){

return(
num(
session&&session.docstatus,
0
)===0
);

});

var primarySession=
submittedSessions[0]||
draftSessions[0]||
null;

var exactAppointmentLinks=
matchingSessions.filter(function(session){

return(
String(
session&&session.appointment||
""
).trim()===
String(
appointment.name||
""
).trim()
);

}).length;

var evidence=
"Matched by Client + Therapy Type + Appointment Date: "+
"Therapy Session.patient = "+
patientForMatch+
", Therapy Session.therapy_type = "+
appointmentTherapyType+
", and effective Therapy Session date = "+
appointmentDate+
".";

if(historicalAppointmentBasis){

evidence=
"Historical appointment resolved. "+
historicalAppointmentBasis+
" Final Therapy Session check: "+
evidence;

}

if(primarySession){

var effectiveSessionTime=
ssrSessionEffectiveTime(
primarySession
);

if(effectiveSessionTime){

evidence+=
" Session time used for ordering: "+
effectiveSessionTime+
(
appointment.appointment_time
?" against appointment time "+
String(
appointment.appointment_time
)
:""
)+
".";

}

}

if(
exactAppointmentLinks
){

evidence+=
" "+
String(
exactAppointmentLinks
)+
" matching session(s) also contain the exact Patient Appointment link.";

}


/*
 * A submitted Therapy Session on the appointment date is enough
 * to show Session Given.
 */
if(submittedSessions.length){

var beforeSentCount=
submittedSessions.filter(function(session){

return ssrSessionOccurredBeforeSent(
session,
sentDate
);

}).length;

return result({
linked:true,

status_key:
"executed",

status_label:
submittedSessions.length===1
?"Session Given — Client + Therapy Type + Appointment Date"
:String(
submittedSessions.length
)+" Matching Sessions Given on Appointment Date",

appointment:
appointment,

session:
primarySession,

matching_sessions:
matchingSessions,

match_type:
"patient_date_therapy",

appointment_verified:
true,

match_basis:
evidence+
(
beforeSentCount
?" "+String(
beforeSentCount
)+" submitted session(s) occurred before material dispatch; they are still displayed because the client and appointment date match."
:""
),

candidate_count:
matchingSessions.length
});

}


/*
 * A Draft Therapy Session is also shown because a session entry
 * has been created for the client on the appointment date.
 */
if(draftSessions.length){

return result({
linked:true,

status_key:
"draft",

status_label:
draftSessions.length===1
?"Matching Session Entry Created — Draft"
:String(
draftSessions.length
)+" Matching Draft Sessions on Appointment Date",

appointment:
appointment,

session:
primarySession,

matching_sessions:
matchingSessions,

match_type:
"patient_date_therapy",

appointment_verified:
true,

match_basis:
evidence+
" Matching Therapy Session entry exists but is still Draft.",

candidate_count:
matchingSessions.length
});

}


/* ---------------------------------------------------------
   D. Nothing exists on that client + appointment date
   --------------------------------------------------------- */

if(
isSSRCancelledAppointment(
appointment
)
){

return result({
linked:true,

status_key:
"cancelled",

status_label:
"Appointment Cancelled / Closed",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"patient_date_therapy",

appointment_verified:
true,

match_basis:
"No Therapy Session entry exists for client "+
patientForMatch+
" with therapy type "+
appointmentTherapyType+
" on appointment date "+
appointmentDate+
"."
});

}


if(
isSSRFutureAppointment(
appointment
)
){

return result({
linked:true,

status_key:
"upcoming",

status_label:
"Awaiting Session — Appointment Upcoming",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"patient_date_therapy",

appointment_verified:
true,

match_basis:
"No Therapy Session entry exists yet for client "+
patientForMatch+
" with therapy type "+
appointmentTherapyType+
" on appointment date "+
appointmentDate+
"."
});

}


return result({
linked:true,

status_key:
"not_executed",

status_label:
"Session Not Given",

appointment:
appointment,

session:
null,

matching_sessions:
[],

match_type:
"patient_date_therapy",

appointment_verified:
true,

match_basis:
"No Therapy Session entry was found where patient = "+
patientForMatch+
", therapy_type = "+
appointmentTherapyType+
", and effective session date = appointment date "+
appointmentDate+
"."
});
}

