}
function normalizeSSRServiceKey(value){
return String(value||"")
.toLowerCase()
.replace(/&amp;/g,"and")
.replace(/&/g,"and")
.replace(/[^a-z0-9]+/g,"")
.trim();
}

function getSSRInvoiceGrossTotal(invoice){
invoice=invoice||{};

return Math.max(
0,
num(
invoice.rounded_total||
invoice.grand_total||
invoice.base_grand_total||
0,
0
)
);
}

function getSSRInvoiceNetTotal(invoice){
invoice=invoice||{};

var explicit=
num(
invoice.net_total||
invoice.base_net_total||
invoice.total||
invoice.base_total||
0,
0
);

if(explicit>0){
return explicit;
}

var items=
Array.isArray(invoice.items)
?invoice.items
:[];

return items.reduce(
function(total,item){
return total+Math.max(
0,
num(
item.net_amount||
item.base_net_amount||
item.amount||
item.base_amount||
0,
0
)
);
},
0
);
}

function getSSRInvoicePaymentCoverage(invoice){
invoice=invoice||{};

var grossTotal=
getSSRInvoiceGrossTotal(invoice);

if(grossTotal<=0){
return 0;
}

var outstanding=
Math.max(
0,
num(
invoice.outstanding_amount,
0
)
);

var grossPaid=
Math.max(
0,
grossTotal-outstanding
);

return Math.max(
0,
Math.min(
1,
grossPaid/grossTotal
)
);
}

function getSSRInvoiceItemNetAmount(item){
item=item||{};

return Math.max(
0,
num(
item.net_amount||
item.base_net_amount||
item.amount||
item.base_amount||
0,
0
)
);
}

function getSSRInvoiceItemQty(item){
item=item||{};

return Math.max(
0,
num(
item.qty||
item.stock_qty||
0,
0
)
);
}

function getSSRInvoiceItemRate(item){
item=item||{};

var rate=
Math.max(
0,
num(
item.net_rate||
item.base_net_rate||
item.rate||
item.base_rate||
0,
0
)
);

if(rate>0){
return rate;
}

var amount=
getSSRInvoiceItemNetAmount(item);

var qty=
getSSRInvoiceItemQty(item);

if(
qty>0&&
amount>0
){
return amount/qty;
}

return 0;
}

function getSSRServiceFinancialsFromInvoices(
planInvoices,
plan,
detail
){
var serviceName=
getTherapyServiceName(
detail,
plan
);

var serviceKey=
normalizeSSRServiceKey(
serviceName
);

var matches=[];

(Array.isArray(planInvoices)?planInvoices:[])
.forEach(function(invoice){
var items=
Array.isArray(invoice&&invoice.items)
?invoice.items
:[];

var coverage=
getSSRInvoicePaymentCoverage(
invoice
);

items.forEach(function(item){
var itemCode=
String(
item.item_code||
""
).trim();

var itemName=
String(
item.item_name||
""
).trim();

var itemCodeKey=
normalizeSSRServiceKey(
itemCode
);

var itemNameKey=
normalizeSSRServiceKey(
itemName
);

var itemReferencePlan=
String(
item.reference_dn||
""
).trim();

var exactServiceMatch=
serviceKey&&
(
itemCodeKey===serviceKey||
itemNameKey===serviceKey
);

var planReferenceMatch=
itemReferencePlan&&
plan&&
String(plan.name||"").trim()===
itemReferencePlan;

if(
!exactServiceMatch&&
!planReferenceMatch
){
return;
}

/*
 * When reference_dn matches the Therapy Plan but the invoice has
 * several service lines, still require the service name to match
 * unless this is the only plausible line.
 */
if(
planReferenceMatch&&
!exactServiceMatch&&
items.length>1
){
return;
}

var netAmount=
getSSRInvoiceItemNetAmount(
item
);

var qty=
getSSRInvoiceItemQty(
item
);

var rate=
getSSRInvoiceItemRate(
item
);

matches.push({
invoice:invoice,
item:item,
net_amount:netAmount,
qty:qty,
rate:rate,
payment_coverage:coverage,
paid_service_amount:
netAmount*coverage
});
});
});

if(!matches.length){
return null;
}

var totalAmount=
matches.reduce(
function(total,row){
return total+row.net_amount;
},
0
);

var totalQty=
matches.reduce(
function(total,row){
return total+row.qty;
},
0
);

var paidServiceAmount=
matches.reduce(
function(total,row){
return total+
row.paid_service_amount;
},
0
);

var rate=0;

if(totalQty>0&&totalAmount>0){
rate=
totalAmount/
totalQty;
}
else{
var firstRate=
matches.find(function(row){
return row.rate>0;
});

rate=
firstRate
?firstRate.rate
:0;
}

var dueServiceAmount=
Math.max(
0,
totalAmount-paidServiceAmount
);

/* LIFE_GLP_STOCK_ENTITLEMENT_X4_V1 */
var glpServiceKey = String(serviceName || "")
  .toLowerCase()
  .replace(/[^a-z0-9]/g, "");

var sessionMultiplier =
  glpServiceKey.indexOf("glp1") !== -1 ? 4 : 1;

// GLP invoice rate is per billed unit.
// One billed unit includes four Therapy Plan sessions.
if (sessionMultiplier === 4 && totalQty > 0) {
  rate = rate / sessionMultiplier;
}

return{
service:serviceName,
rate:rate,
amount:totalAmount,
paid_amount:paidServiceAmount,
due_amount:dueServiceAmount,
invoice_items:matches
};
}

/* ============================================================
   PACKAGE-CONVERSION STOCK ELIGIBILITY
   ============================================================
   Normal Therapy Plans continue to use Sales Invoice payment-based
   eligibility.

   This fallback is used ONLY when the current Therapy Plan has no
   valid linked Sales Invoice and there is explicit conversion history:

   P2P (same client):
     LIFE Client Package Conversion Same Client Package To Package
       updated_therapy_plan = current Therapy Plan
       package_conversion_applied = 1

   C2C (client-to-client):
     Client Package Transfer Ledger
       created_receiving_therapy_plan = current Therapy Plan

   Conversion history grants session entitlement; it does NOT create a
   fake Sales Invoice.
   ============================================================ */

function ssrConversionStatusAccepted(value){
var status=String(value||"").trim().toLowerCase();
if(!status){
return true;
}
return(
status.indexOf("approved")>=0||
status.indexOf("complete")>=0||
status.indexOf("applied")>=0||
status.indexOf("process completed")>=0
);
}

function ssrConversionRowService(row){
return String(
row&&(
row.therapy_type||
row.converted_package__service_name||
row.complete_package_details_therapy_plans||
row.therapy_plans_been_transferred
)||""
).trim();
}

function ssrFindConversionRow(rows,serviceName){
var wanted=normalizeSSRServiceKey(serviceName);
if(!wanted){
return null;
}

var list=Array.isArray(rows)?rows:[];

var exact=list.find(function(row){
return normalizeSSRServiceKey(ssrConversionRowService(row))===wanted;
});
if(exact){
return exact;
}

return list.find(function(row){
var key=normalizeSSRServiceKey(ssrConversionRowService(row));
return(
key&&
wanted&&
key.length>=5&&
wanted.length>=5&&
(
key.indexOf(wanted)>=0||
wanted.indexOf(key)>=0
)
);
})||null;
}

async function loadSSRPackageConversionEvidence(planDocs){
    var plans=Array.isArray(planDocs)?planDocs:[];

    var planNames=plans.map(function(plan){
        return String(plan&&plan.name||"").trim();
    }).filter(Boolean);

    var result={
        p2p:Object.create(null),
        c2c:Object.create(null),
        b2b:Object.create(null)
    };

    if(!planNames.length){
        return result;
    }

    /* =========================================================
       P2P — SAME CLIENT PACKAGE CONVERSION
       ========================================================= */
    try{
        var p2pRows=await safeGetList(
            "LIFE Client Package Conversion Same Client Package To Package",
            [[
                "name",
                "updated_therapy_plan",
                "package_conversion_applied",
                "automation_status",
                "approval_stage",
                "final_approval_status",
                "approval_display_status",
                "source_therapy_plan",
                "source_therapy_plans_text",
                "modified"
            ],[
                "name",
                "updated_therapy_plan",
                "package_conversion_applied",
                "automation_status",
                "approval_stage",
                "final_approval_status",
                "modified"
            ],[
                "name",
                "updated_therapy_plan",
                "package_conversion_applied",
                "modified"
            ]],
            [
                ["updated_therapy_plan","in",planNames],
                ["package_conversion_applied","=",1]
            ],
            {
                order_by:"modified desc",
                limit_page_length:200
            }
        );

        p2pRows=Array.isArray(p2pRows)?p2pRows:[];

        for(var p=0;p<p2pRows.length;p++){
            var header=p2pRows[p]||{};
            var currentPlan=String(
                header.updated_therapy_plan||""
            ).trim();

            if(
                !currentPlan||
                result.p2p[currentPlan]
            ){
                continue;
            }

            var accepted=
                ssrConversionStatusAccepted(header.final_approval_status)&&
                ssrConversionStatusAccepted(header.approval_stage)&&
                ssrConversionStatusAccepted(header.automation_status)&&
                ssrConversionStatusAccepted(header.approval_display_status);

            if(!accepted){
                continue;
            }

            var fullDoc=header;

            try{
                fullDoc=await getDoc(
                    "LIFE Client Package Conversion Same Client Package To Package",
                    header.name
                );
            }
            catch(error){
                void 0;
            }

            var finalRows=
                (
                    Array.isArray(fullDoc.coo_management_final_package)&&
                    fullDoc.coo_management_final_package.length
                    ?fullDoc.coo_management_final_package
                    :null
                )||
                (
                    Array.isArray(fullDoc.audit_team_requested_package)&&
                    fullDoc.audit_team_requested_package.length
                    ?fullDoc.audit_team_requested_package
                    :null
                )||
                (
                    Array.isArray(fullDoc.branch_requested_package)&&
                    fullDoc.branch_requested_package.length
                    ?fullDoc.branch_requested_package
                    :null
                )||
                (
                    Array.isArray(fullDoc.converted_package__service_name)&&
                    fullDoc.converted_package__service_name.length
                    ?fullDoc.converted_package__service_name
                    :[]
                );

            result.p2p[currentPlan]={
                type:"P2P",
                request_name:String(
                    fullDoc.name||
                    header.name||
                    ""
                ),
                rows:finalRows,
                doc:fullDoc
            };
        }
    }
    catch(error){
        void 0;
    }


    /* =========================================================
       C2C — CLIENT TO CLIENT TRANSFER
       ========================================================= */
    try{
        var ledgerRows=await safeGetList(
            "Client Package Transfer Ledger",
            [[
                "name",
                "conversion_request",
                "created_receiving_therapy_plan",
                "source_therapy_plan",
                "therapy_type",
                "transferred_sessions",
                "status",
                "source_invoice",
                "pending_balance_transferred",
                "created_sales_invoice",
                "applied_on"
            ],[
                "name",
                "conversion_request",
                "created_receiving_therapy_plan",
                "source_therapy_plan",
                "therapy_type",
                "transferred_sessions",
                "status",
                "source_invoice",
                "applied_on"
            ],[
                "name",
                "created_receiving_therapy_plan",
                "therapy_type",
                "transferred_sessions",
                "status"
            ]],
            [
                ["created_receiving_therapy_plan","in",planNames]
            ],
            {
                order_by:"applied_on desc, modified desc",
                limit_page_length:500
            }
        );

        ledgerRows=Array.isArray(ledgerRows)?ledgerRows:[];

        ledgerRows.forEach(function(row){
            var currentPlan=String(
                row.created_receiving_therapy_plan||""
            ).trim();

            if(!currentPlan){
                return;
            }

            if(!ssrConversionStatusAccepted(row.status)){
                return;
            }

            if(num(row.transferred_sessions,0)<=0){
                return;
            }

            if(!result.c2c[currentPlan]){
                result.c2c[currentPlan]={
                    type:"C2C",
                    rows:[],
                    request_names:[],
                    ledger_names:[]
                };
            }

            result.c2c[currentPlan].rows.push(row);

            var requestName=String(
                row.conversion_request||""
            ).trim();

            if(
                requestName&&
                result.c2c[currentPlan].request_names.indexOf(
                    requestName
                )===-1
            ){
                result.c2c[currentPlan].request_names.push(
                    requestName
                );
            }

            var ledgerName=String(
                row.name||""
            ).trim();

            if(
                ledgerName&&
                result.c2c[currentPlan].ledger_names.indexOf(
                    ledgerName
                )===-1
            ){
                result.c2c[currentPlan].ledger_names.push(
                    ledgerName
                );
            }
        });
    }
    catch(error){
        void 0;
    }


    /* =========================================================
   B2B — BRANCH TO BRANCH CLIENT TRANSFER
   =========================================================
   IMPORTANT:

   Do NOT depend only on reading Client Transfer Request Form.
   Branch users may not have permission to that DocType.

   Final approved B2B already writes the transferred branch into:

       Patient.custom_brnch_list

   with remarks like:

       Branch transferred from X to Y through
       Client Transfer Request Form REQUEST-ID

   Therefore Patient branch history is the reliable runtime proof.

   Conditions:
   1. Therapy Plan belongs to this Patient
   2. Plan is now at the transferred-to branch
   3. Patient branch history contains that branch
   4. History row represents an actual branch transfer
   5. Plan existed on/before transfer
   ========================================================= */

try {

    var patientIds=[];

    plans.forEach(function(plan){

        var patientId=String(
            plan&&(
                plan.patient||
                plan.patient_name
            )||
            ""
        ).trim();

        if(
            patientId&&
            patientIds.indexOf(patientId)===-1
        ){
            patientIds.push(patientId);
        }
    });


    var patientB2BHistory=Object.create(null);


    /*
     * ---------------------------------------------------------
     * LOAD PATIENT BRANCH HISTORY
     * ---------------------------------------------------------
     */
    for(var patientIndex=0;
        patientIndex<patientIds.length;
        patientIndex++
    ){

        var patientId=patientIds[patientIndex];

        try{

            var patientDoc=
                await getDoc(
                    "Patient",
                    patientId
                );

            var branchRows=
                Array.isArray(
                    patientDoc.custom_brnch_list
                )
                ?patientDoc.custom_brnch_list
                :[];

            var transferRows=
                branchRows.filter(function(row){

                    row=row||{};

                    var branch=String(
                        row.branch||
                        ""
                    ).trim();

                    var remarks=String(
                        row.remarks||
                        ""
                    ).trim();

                    if(!branch){
                        return false;
                    }

                    /*
                     * Only rows generated by / representing
                     * branch transfer should become B2B evidence.
                     */
                    var transferRemark=
                        /branch\s+transferred/i.test(remarks)||
                        /client\s+transfer\s+request/i.test(remarks)||
                        /transferred\s+from/i.test(remarks);

                    return transferRemark;
                });


            /*
             * Newest transfer first.
             */
            transferRows.sort(function(a,b){

                var ad=
                    new Date(
                        a.transfer_date||
                        a.creation||
                        0
                    ).getTime();

                var bd=
                    new Date(
                        b.transfer_date||
                        b.creation||
                        0
                    ).getTime();

                return bd-ad;
            });


            patientB2BHistory[patientId]={
                patient:patientDoc,
                rows:transferRows
            };

        }
        catch(patientError){

            void 0;

            patientB2BHistory[patientId]={
                patient:null,
                rows:[]
            };
        }
    }


    /*
     * ---------------------------------------------------------
     * OPTIONAL:
     * TRY TO LOAD APPROVED CLIENT TRANSFER REQUESTS TOO.
     *
     * Useful for System Manager / users having permission.
     * Failure DOES NOT remove valid Patient-history evidence.
     * ---------------------------------------------------------
     */

    var approvedTransferRequests=[];

    if(patientIds.length){

        try{

            var requestRows=
                await safeGetList(
                    "Client Transfer Request Form",
                    [[
                        "name",
                        "client_full_name",
                        "client",
                        "client_id__crm_no",
                        "transfer_from_branch",
                        "transfer_to_branch",
                        "approval_display_status",
                        "final_approval_status",
                        "remarks",
                        "date_of_transfer_request",
                        "creation",
                        "modified"
                    ],[
                        "name",
                        "client_full_name",
                        "client",
                        "transfer_from_branch",
                        "transfer_to_branch",
                        "approval_display_status",
                        "final_approval_status",
                        "remarks",
                        "modified"
                    ]],
                    [
                        [
                            "client_full_name",
                            "in",
                            patientIds
                        ]
                    ],
                    {
                        order_by:"modified desc",
                        limit_page_length:500
                    }
                );


            requestRows=
                Array.isArray(requestRows)
                ?requestRows
                :[];


            approvedTransferRequests=
                requestRows.filter(function(row){

                    row=row||{};

                    var displayStatus=
                        String(
                            row.approval_display_status||
                            row.remarks||
                            ""
                        )
                        .trim()
                        .toLowerCase();

                    var finalStatus=
                        String(
                            row.final_approval_status||
                            ""
                        )
                        .trim()
                        .toLowerCase();

                    var fromBranch=
                        String(
                            row.transfer_from_branch||
                            ""
                        ).trim();

                    var toBranch=
                        String(
                            row.transfer_to_branch||
                            ""
                        ).trim();


                    var completed=
                        displayStatus.indexOf(
                            "approved / transfer completed"
                        )>=0;

                    var finalApproved=
                        finalStatus==="approved";


                    return(
                        completed&&
                        finalApproved&&
                        fromBranch&&
                        toBranch&&
                        normalizeSSRComparable(fromBranch)!==
                        normalizeSSRComparable(toBranch)
                    );
                });

        }
        catch(requestError){

            /*
             * THIS IS NOT FATAL.
             *
             * Branch user may not be permitted to read
             * Client Transfer Request Form.
             */
            void 0;

            approvedTransferRequests=[];
        }
    }


    /*
     * ---------------------------------------------------------
     * MAP B2B EVIDENCE TO EACH THERAPY PLAN
     * ---------------------------------------------------------
     */

    plans.forEach(function(plan){

        plan=plan||{};

        var planName=
            String(
                plan.name||
                ""
            ).trim();

        var patientId=
            String(
                plan.patient||
                plan.patient_name||
                ""
            ).trim();

        var planBranch=
            String(
                plan.branch||
                plan.branch_name||
                plan.custom_branch||
                ""
            ).trim();


        if(
            !planName||
            !patientId||
            !planBranch
        ){
            return;
        }


        var evidence=null;


        /* =====================================================
           METHOD 1 — APPROVED REQUEST RECORD
           ===================================================== */

        for(
            var r=0;
            r<approvedTransferRequests.length;
            r++
        ){

            var request=
                approvedTransferRequests[r]||{};

            var requestPatient=
                String(
                    request.client_full_name||
                    request.client||
                    request.client_id__crm_no||
                    ""
                ).trim();

            var toBranch=
                String(
                    request.transfer_to_branch||
                    ""
                ).trim();


            if(
                normalizeSSRComparable(
                    requestPatient
                )!==
                normalizeSSRComparable(
                    patientId
                )
            ){
                continue;
            }


            if(
                normalizeSSRComparable(
                    toBranch
                )!==
                normalizeSSRComparable(
                    planBranch
                )
            ){
                continue;
            }


            /*
             * Plan must already have existed when B2B happened.
             */
            var requestDate=
                request.date_of_transfer_request||
                request.modified||
                request.creation||
                "";

            if(
                plan.creation&&
                requestDate
            ){

                var planTime=
                    new Date(
                        plan.creation
                    ).getTime();

                var transferTime=
                    new Date(
                        requestDate
                    ).getTime();


                if(
                    isFinite(planTime)&&
                    isFinite(transferTime)&&
                    planTime>transferTime
                ){
                    continue;
                }
            }


            evidence={
                type:"B2B",

                request_name:String(
                    request.name||
                    ""
                ),

                from_branch:String(
                    request.transfer_from_branch||
                    ""
                ),

                to_branch:toBranch,

                transfer_date:
                    request.date_of_transfer_request||
                    request.modified||
                    "",

                source:"Client Transfer Request Form",

                doc:request
            };

            break;
        }


        /* =====================================================
           METHOD 2 — PATIENT BRANCH TRANSFER HISTORY

           This is the important fallback for normal branch users.
           ===================================================== */

        if(!evidence){

            var historyInfo=
                patientB2BHistory[
                    patientId
                ]||{
                    rows:[]
                };

            var rows=
                Array.isArray(
                    historyInfo.rows
                )
                ?historyInfo.rows
                :[];


            for(
                var h=0;
                h<rows.length;
                h++
            ){

                var historyRow=
                    rows[h]||{};

                var historyBranch=
                    String(
                        historyRow.branch||
                        ""
                    ).trim();


                if(
                    normalizeSSRComparable(
                        historyBranch
                    )!==
                    normalizeSSRComparable(
                        planBranch
                    )
                ){
                    continue;
                }


                var transferDate=
                    historyRow.transfer_date||
                    historyRow.creation||
                    "";


                /*
                 * A therapy plan created after the transfer
                 * is NOT an old B2B transferred package.
                 */
                if(
                    plan.creation&&
                    transferDate
                ){

                    var planCreated=
                        new Date(
                            plan.creation
                        ).getTime();

                    /*
                     * transfer_date is normally date-only.
                     * Give the entire transfer day as valid.
                     */
                    var transferDayEnd=
                        new Date(
                            String(
                                transferDate
                            ).slice(0,10)+
                            "T23:59:59"
                        ).getTime();


                    if(
                        isFinite(planCreated)&&
                        isFinite(transferDayEnd)&&
                        planCreated>transferDayEnd
                    ){
                        continue;
                    }
                }


                var remarks=
                    String(
                        historyRow.remarks||
                        ""
                    ).trim();


                /*
                 * Extract Client Transfer Request ID where possible.
                 */
                var requestMatch=
                    remarks.match(
                        /Client\s+Transfer\s+Request\s+Form\s+(.+)$/i
                    );


                /*
                 * Extract old branch where possible:
                 * "Branch transferred from Banjara Hills to Madhapur..."
                 */
                var branchMatch=
                    remarks.match(
                        /transferred\s+from\s+(.+?)\s+to\s+(.+?)(?:\s+through|$)/i
                    );


                evidence={
                    type:"B2B",

                    request_name:
                        requestMatch&&
                        requestMatch[1]
                        ?String(
                            requestMatch[1]
                        ).trim()
                        :"",

                    from_branch:
                        branchMatch&&
                        branchMatch[1]
                        ?String(
                            branchMatch[1]
                        ).trim()
                        :"",

                    to_branch:
                        historyBranch,

                    transfer_date:
                        transferDate,

                    source:
                        "Patient Branch History",

                    doc:
                        historyRow
                };

                break;
            }
        }


        if(!evidence){
            return;
        }


        /*
         * -----------------------------------------------------
         * FINAL B2B EVIDENCE
         * -----------------------------------------------------
         */
        result.b2b[
            planName
        ]=evidence;

    });


}
catch(error){

    void 0;
}


    return result;
}

function getSSRConversionFinancials(evidence,plan,detail){
if(!evidence){
return null;
}

var serviceName=getTherapyServiceName(detail,plan);
var booked=getTherapyBookedSessions(detail);

if(evidence.type==="P2P"){
var p2pRow=ssrFindConversionRow(evidence.rows,serviceName);
if(!p2pRow){
return null;
}

var entitlementQty=Math.max(
0,
num(
p2pRow.no_of_sessions||
p2pRow.converted_quantity||
p2pRow.booked_quantity||
0,
0
)
);

if(entitlementQty<=0){
return null;
}

var rate=Math.max(0,num(p2pRow.rate,0));
var amount=Math.max(
0,
num(
p2pRow.amount||
p2pRow.balance_amount||
0,
0
)
);

if(rate<=0&&amount>0&&entitlementQty>0){
rate=amount/entitlementQty;
}
if(amount<=0&&rate>0&&entitlementQty>0){
amount=rate*entitlementQty;
}

return{
type:"P2P",
reference:evidence.request_name||"Package Conversion",
service:serviceName,
entitlement_sessions:Math.min(booked,entitlementQty),
rate:rate,
amount:amount,
paid_amount:amount,
due_amount:0,
source_row:p2pRow
};
}

if(evidence.type==="C2C"){
var matchingRows=(Array.isArray(evidence.rows)?evidence.rows:[]).filter(function(row){
return ssrFindConversionRow([row],serviceName)!==null;
});

if(!matchingRows.length){
return null;
}

var entitlementQty=matchingRows.reduce(function(total,row){
return total+Math.max(0,num(row.transferred_sessions,0));
},0);

if(entitlementQty<=0){
return null;
}

var c2cRequestRefs=
(evidence.request_names||[]).filter(Boolean);

var c2cLedgerRefs=
matchingRows.map(function(row){
return String(row.name||"").trim();
}).filter(Boolean);

var c2cReferenceParts=[];

if(c2cRequestRefs.length){
c2cReferenceParts.push(
"C2C: "+c2cRequestRefs.join(", ")
);
}

if(c2cLedgerRefs.length){
c2cReferenceParts.push(
"Ledger: "+c2cLedgerRefs.join(", ")
);
}

return{
type:"C2C",
reference:c2cReferenceParts.join(" / ")||"C2C Package Transfer",
service:serviceName,
entitlement_sessions:Math.min(booked,entitlementQty),
rate:0,
amount:0,
paid_amount:0,
due_amount:0,
source_rows:matchingRows
};
}

if(evidence.type==="B2B"){
    var serviceName=
        getTherapyServiceName(
            detail,
            plan
        );

    var booked=
        Math.max(
            0,
            getTherapyBookedSessions(
                detail
            )
        );

    if(booked<=0){
        return null;
    }

    /*
     * B2B does NOT create a new invoice.
     *
     * The complete original Therapy Plan is transferred from one
     * branch to another. Therefore the original booked sessions
     * remain the entitlement.
     *
     * calculateConvertedStockEligibility() will subtract already
     * completed sessions.
     */
    return{
        type:"B2B",

        reference:
            evidence.request_name
            ?(
                "B2B: "+
                evidence.request_name+
                " ("+
                (evidence.from_branch||"—")+
                " → "+
                (evidence.to_branch||"—")+
                ")"
            )
            :"B2B Branch Transfer",

        service:serviceName,

        entitlement_sessions:booked,

        rate:0,
        amount:0,
        paid_amount:0,
        due_amount:0,

        source_row:
            evidence.doc||
            evidence
    };
}

return null;
}

function calculateConvertedStockEligibility(
booked,
completed,
remaining,
entitlementSessions
){
booked=Math.max(0,num(booked,0));
completed=Math.max(0,num(completed,0));
remaining=Math.max(0,num(remaining,booked-completed));
entitlementSessions=Math.min(
booked,
Math.max(0,num(entitlementSessions,0))
);

var unusedPaidSessions=Math.max(
0,
entitlementSessions-completed
);

return{
paid_sessions:entitlementSessions,
unused_paid_sessions:unusedPaidSessions,
stock_eligible_sessions:Math.min(
remaining,
unusedPaidSessions
)
};
}

async function loadSSRClientTherapyData(client){
var planHeaders=await safeGetList("Therapy Plan",[["name","patient","patient_name","branch","status","start_date","due_date","category","therapy_plan_template","custom_total_plan_amount","total_sessions","total_sessions_completed","invoiced","creation","modified"],["name","patient","patient_name","branch","status","start_date","category","custom_total_plan_amount","total_sessions","total_sessions_completed"],["name","patient","branch","status","start_date","total_sessions","total_sessions_completed"]],[["patient","=",client.name]],{
