);
var planDocs=await Promise.all(planHeaders.map(async function(plan){
try{
return await getDoc("Therapy Plan",plan.name);
}
catch(error){
void 0;
return plan;
}
}
));
/*
 * Load package-conversion evidence in parallel with the financial path.
 * It is used only for Therapy Plans that have NO valid linked invoice.
 */
var conversionEvidence=
await loadSSRPackageConversionEvidence(
planDocs
);

var invoices=[];
try{
invoices=await safeGetList("Sales Invoice",[["name","patient","patient_name","branch","posting_date","status","docstatus","therapy_plan_reference_id","custom_therapy_plan","grand_total","rounded_total","base_grand_total","paid_amount","outstanding_amount"],["name","patient","posting_date","status","docstatus","therapy_plan_reference_id","custom_therapy_plan","grand_total","paid_amount","outstanding_amount"],["name","patient","posting_date","docstatus","therapy_plan_reference_id","grand_total","outstanding_amount"]],[["patient","=",client.name],["docstatus","=",1],["status","in",["Paid","Partly Paid","Overdue"]]],{
order_by:"posting_date desc, modified desc",limit_page_length:200}
);
}
catch(invoiceError){
void 0;
invoices=[];
}
invoices=filterSSRValidTherapyInvoices(invoices);

/*
 * Full Sales Invoice docs are required because payment eligibility is
 * now calculated from the matching Sales Invoice Item rate/amount.
 */
invoices=await Promise.all(
invoices.map(
async function(invoice){
try{
return await getDoc(
"Sales Invoice",
invoice.name
);
}
catch(error){
void 0;
return invoice;
}
}
)
);

invoices=filterSSRValidTherapyInvoices(invoices);

var invoicesByPlan={
}
;
invoices.forEach(function(invoice){
var planName=getInvoicePlanName(invoice);
if(!planName){
return;
}
if(!invoicesByPlan[planName]){
invoicesByPlan[planName]=[];
}
invoicesByPlan[planName].push(invoice);
}
);
state.therapyPlans=planDocs;
state.invoicesByPlan=invoicesByPlan;
state.therapyRows=[];
planDocs.forEach(function(plan){
if(String(plan.status||"").toLowerCase()==="cancelled"){
return;
}
var details=Array.isArray(plan.therapy_plan_details)?plan.therapy_plan_details:[];
if(!details.length){
details=[{
name:plan.name+"-parent-row",therapy_type:plan.therapy_plan_template||plan.category||plan.name,no_of_sessions:plan.total_sessions,sessions_completed:plan.total_sessions_completed,amount:plan.custom_total_plan_amount}
];
}
var planInvoices=invoicesByPlan[plan.name]||[];
if(!Array.isArray(planInvoices)){
planInvoices=planInvoices?[planInvoices]:[];
}
var planConversionEvidence=
conversionEvidence.p2p[plan.name]||
conversionEvidence.c2c[plan.name]||
conversionEvidence.b2b[plan.name]||
null;

/*
 * Normal plans still require an invoice. A verified converted/
 * transferred plan may continue without one.
 */
var planMarkedInvoiced =
    num(
        plan && plan.invoiced,
        0
    ) === 1;


/*
 * ELIGIBILITY RULE
 *
 * Keep the Therapy Plan when:
 *
 * 1. A readable Sales Invoice exists, OR
 * 2. It is a verified converted/transferred package, OR
 * 3. Therapy Plan.invoiced = 1
 *
 * This prevents Branch users from losing an otherwise valid
 * Therapy Plan merely because Sales Invoice permissions are restricted.
 */
if(
    !planInvoices.length &&
    !planConversionEvidence &&
    !planMarkedInvoiced
){
    return;
}

var invoicePaid=planInvoices.reduce(function(total,invoice){
return(total+getInvoicePaid(invoice));
}
,0);

var invoiceDue=planInvoices.reduce(function(total,invoice){
return(total+getInvoiceDue(invoice));
}
,0);

var invoiceIds=planInvoices.map(function(invoice){
return invoice.name;
}
).filter(Boolean).join(", ");

/*
 * OVERALL INVOICE DISPLAY VALUES
 * ------------------------------
 * These are shown in the Paid Amount / Due Amount columns.
 * They are NOT therapy-wise allocated values.
 */
var overallInvoicePaid=planInvoices.reduce(function(total,invoice){
return total+getInvoicePaid(invoice);
},0);

var overallInvoiceDue=planInvoices.reduce(function(total,invoice){
return total+getInvoiceDue(invoice);
},0);

/*
 * Keep old Therapy Plan detail amounts only as a FALLBACK.
 * Primary pricing/payment now comes from matching Sales Invoice Items.
 */
var detailAmounts=details.map(function(detail){
var booked=getTherapyBookedSessions(detail);
var rate=getTherapyRate(detail);
var amount=getTherapyAmount(detail);

if(
amount<=0&&
booked>0&&
rate>0
){
amount=booked*rate;
}

return amount;
}
);

var totalDetailAmount=
detailAmounts.reduce(
function(total,amount){
return total+amount;
},
0
);

var totalBooked=
details.reduce(
function(total,detail){
return(
total+
getTherapyBookedSessions(detail)
);
},
0
);

var allocatedPaid=0;
var allocatedDue=0;

details.forEach(function(detail,detailIndex){
var booked=
getTherapyBookedSessions(
detail
);

var completed=
Math.min(
booked,
getTherapyCompletedSessions(
detail
)
);

var remaining=
Math.max(
0,
booked-completed
);

/*
 * Financial / entitlement source priority:
 *   1. Sales Invoice Item (normal plan)
 *   2. Verified P2P/C2C conversion history (no-invoice plan)
 *   3. Existing invoice proportional fallback when invoice exists but
 *      the individual Sales Invoice Item cannot be matched.
 */
var serviceFinancials=
getSSRServiceFinancialsFromInvoices(
planInvoices,
plan,
detail
);

var conversionFinancials=
!planInvoices.length&&planConversionEvidence
?getSSRConversionFinancials(
planConversionEvidence,
plan,
detail
)
:null;

var rate=0;
var amount=0;
var paidAmount=0;
var dueAmount=0;
var paidEligibility=null;
var paymentSource="";
var displayReference="";
var overallPaidForDisplay=overallInvoicePaid;
var overallDueForDisplay=overallInvoiceDue;

if(serviceFinancials){
rate=Math.max(0,num(serviceFinancials.rate,0));
amount=Math.max(0,num(serviceFinancials.amount,0));
paidAmount=Math.max(0,roundMoney(serviceFinancials.paid_amount));
dueAmount=Math.max(0,roundMoney(serviceFinancials.due_amount));

paidEligibility=calculatePaidStockEligibility(
booked,
completed,
remaining,
rate,
paidAmount,
dueAmount
);

paymentSource="Sales Invoice Item";
displayReference=invoiceIds||"—";
}
else if(conversionFinancials){
rate=Math.max(0,num(conversionFinancials.rate,0));
amount=Math.max(0,num(conversionFinancials.amount,0));
paidAmount=Math.max(0,num(conversionFinancials.paid_amount,0));
dueAmount=0;

paidEligibility=calculateConvertedStockEligibility(
booked,
completed,
remaining,
conversionFinancials.entitlement_sessions
);

if(conversionFinancials.type==="P2P"){
    paymentSource="P2P Package Conversion";
}
else if(conversionFinancials.type==="C2C"){
    paymentSource="C2C Package Transfer";
}
else if(conversionFinancials.type==="B2B"){
    paymentSource="B2B Branch Transfer";
}
else{
    paymentSource="Package Conversion";
}

displayReference=
conversionFinancials.reference||
"Package Conversion";

/*
 * There is intentionally no fake invoice balance for a converted plan.
 * P2P amount can be shown as the converted package value; C2C may have
 * no directly comparable monetary value in the receiving plan.
 */
overallPaidForDisplay=
conversionFinancials.type==="P2P"
?roundMoney(amount)
:0;

overallDueForDisplay=0;
}
else if(planInvoices.length){
/*
 * Existing invoice proportional fallback when an invoice exists but its
 * item cannot be matched to this Therapy Plan detail.
 */
rate=getTherapyRate(detail);
amount=detailAmounts[detailIndex];

if(rate<=0&&booked>0&&amount>0){
rate=amount/booked;
}

var weight=0;
if(totalDetailAmount>0){
weight=amount/totalDetailAmount;
}
else if(totalBooked>0){
weight=booked/totalBooked;
}
else{
weight=1/details.length;
}

var isLast=detailIndex===details.length-1;

paidAmount=isLast
?roundMoney(invoicePaid-allocatedPaid)
:roundMoney(invoicePaid*weight);

dueAmount=isLast
?roundMoney(invoiceDue-allocatedDue)
:roundMoney(invoiceDue*weight);

paidAmount=Math.max(0,paidAmount);
dueAmount=Math.max(0,dueAmount);
allocatedPaid+=paidAmount;
allocatedDue+=dueAmount;

paidEligibility=calculatePaidStockEligibility(
booked,
completed,
remaining,
rate,
paidAmount,
dueAmount
);

paymentSource="Therapy Plan fallback";
displayReference=invoiceIds||"—";
}

else if(planMarkedInvoiced){

    /*
     * Sales Invoice exists according to Therapy Plan.invoiced,
     * but this logged-in user cannot read the Sales Invoice.
     *
     * Do NOT treat that as unpaid.
     * Do NOT fabricate invoice financial values.
     *
     * Stock entitlement is based on remaining Therapy Plan sessions.
     */

    rate =
        Math.max(
            0,
            num(
                getTherapyRate(detail),
                0
            )
        );

    amount =
        Math.max(
            0,
            num(
                getTherapyAmount(detail),
                0
            )
        );

    if(
        amount <= 0 &&
        booked > 0 &&
        rate > 0
    ){
        amount =
            booked * rate;
    }


    /*
     * Financial amounts intentionally remain unavailable.
     * We know the plan was invoiced, but we are not bypassing
     * Sales Invoice permissions to expose billing information.
     */
    paidAmount = 0;
    dueAmount = 0;


    /*
     * IMPORTANT:
     * This is STOCK eligibility, not a statement that all sessions
     * have been financially paid.
     */
    paidEligibility = {
        paid_sessions: 0,
        unused_paid_sessions: 0,

        /*
         * Therapy Plan.invoiced = 1 is sufficient for stock eligibility.
         */
        stock_eligible_sessions:
            Math.max(
                0,
                remaining
            )
    };


    paymentSource =
        "Therapy Plan Invoiced Flag";


    displayReference =
        plan.name;


    overallPaidForDisplay = 0;
    overallDueForDisplay = 0;
}
else{

    return;
}
var detailName=detail.name||String(detailIndex+1);

/*
 * IMPORTANT:
 * paidEligibility has already been calculated from the correct source:
 *   - Sales Invoice Item for normal plans, OR
 *   - converted/transferred session entitlement for P2P/C2C plans.
 *
 * Do NOT recalculate it here with the invoice formula, because C2C
 * receiving plans intentionally have no invoice amount/rate on the
 * newly-created Therapy Plan.
 */
state.therapyRows.push({
key:plan.name+"__"+detailName,
plan_name:plan.name,
detail_name:detailName,
service:getTherapyServiceName(detail,plan),
branch:plan.branch||client.branch_name||"",
status:plan.status||"",
plan_invoiced:
    planMarkedInvoiced
        ? 1
        : 0,

invoice_visible:
    planInvoices.length
        ? 1
        : 0,

eligibility_source:
    planInvoices.length
        ? "sales_invoice"
        : (
            conversionFinancials
                ? "package_conversion"
                : (
                    planMarkedInvoiced
                        ? "therapy_plan_invoiced"
                        : ""
                )
        ),
start_date:plan.start_date,
invoice_id:displayReference||"—",
paid_sessions:paidEligibility.paid_sessions,
unused_paid_sessions:paidEligibility.unused_paid_sessions,
stock_eligible_sessions:paidEligibility.stock_eligible_sessions,
booked:booked,
done:completed,
remaining:remaining,
rate:roundMoney(rate),
total_amount:roundMoney(amount),
paid_amount:roundMoney(paidAmount),
due_amount:roundMoney(dueAmount),
overall_invoice_paid:roundMoney(overallPaidForDisplay),
overall_invoice_due:roundMoney(overallDueForDisplay),
payment_source:paymentSource,
is_package_conversion:!!conversionFinancials,
package_conversion_type:conversionFinancials?conversionFinancials.type:"",
package_conversion_reference:conversionFinancials?conversionFinancials.reference:"",
package_conversion_source_rows:
conversionFinancials&&Array.isArray(conversionFinancials.source_rows)
?conversionFinancials.source_rows
:(
conversionFinancials&&conversionFinancials.source_row
?[conversionFinancials.source_row]
:[]
),
plan:plan,
detail:detail,
invoice:planInvoices
}
);
}
);
}
);
}
