function showSSRClientLoading(){
var area=byId("ssr-client-area");
if(!area){
return;
}

/*
 * IMPORTANT:
 * Do not replace #ssr-client-area.innerHTML here.
 * That container owns permanent nodes such as:
 * #ssr-client-strip, #ssr-appointment-select and #ssr-therapy-wrap.
 * Replacing its HTML destroys them and prevents renderSSRClientArea()
 * from restoring the client details.
 */
var loader=byId("ssr-client-loading-host");
if(!loader){
loader=document.createElement("div");
loader.id="ssr-client-loading-host";
loader.className="ssr-client-loading";
loader.setAttribute("role","status");
loader.setAttribute("aria-live","polite");
loader.innerHTML=
'<div class="ssr-client-loading-spinner" aria-hidden="true"></div>'+
'<div class="ssr-client-loading-copy">'+
'<div class="ssr-client-loading-title">Loading client details…</div>'+
'<div class="ssr-client-loading-sub">Checking appointments, therapy plans, payments and session history</div>'+
'<div class="ssr-client-loading-progress" aria-hidden="true"><span></span></div>'+
'</div>';

if(area.parentNode){
area.parentNode.insertBefore(loader,area);
}
}

loader.style.display="flex";
area.style.display="none";
}

function hideSSRClientLoading(){
var loader=byId("ssr-client-loading-host");
if(loader&&loader.parentNode){
loader.parentNode.removeChild(loader);
}

var area=byId("ssr-client-area");
if(area){
area.style.display="";
}
}


/* LIFE_CLIENT_DOCUMENT_REUSE_V1 */
async function lifeLoadReusableClientDocuments(client){
    var result=await lifeStockServerCall("get_client_reusable_documents",{client:client.name});
    if(!state.selectedClient||state.selectedClient.name!==client.name){return;}
    state.lifeReusableClient=client.name;
    state.lifeReusableDocuments=result.documents||{};
}
function lifeReusableDocument(index){
    if(index>1||!state.selectedClient||state.lifeReusableClient!==state.selectedClient.name){return null;}
    return (state.lifeReusableDocuments||{})[String(index+1)]||null;
}
async function lifeUploadSSRDocuments(){
    if(!state.selectedClient){throw new Error("Select a client first.");}
    await lifeLoadReusableClientDocuments(state.selectedClient);
    var required=getSSRRequiredAttachmentIndexes().filter(function(index){
        return !lifeReusableDocument(index);
    });
    var rows=await lifeUploadRequestAttachments(state.ssrAttachments,SSR_ATTACHMENT_LABELS,required);
    [0,1].forEach(function(index){
        if(!state.ssrAttachments[index]){
            var saved=lifeReusableDocument(index);
            if(saved){rows.push({file_url:saved.file_url,label:SSR_ATTACHMENT_LABELS[index],slot_number:index+1});}
        }
    });
    return rows;
}

async function selectClientForSSR(index, drop) {
    var rows = drop && drop._rows ? drop._rows : [];
    var client = rows[index];
    if (!client) {
        return;
    }
    state.selectedClient = client;
    state.ssrAttachments=[];
    state.lifeReusableClient=client.name;
    state.lifeReusableDocuments={};
    state.futureAppointments = [];
    state.selectedAppointment = null;
    state.ssrAppointmentMatch = null;
    state.selectedPlans = {};
    state.therapyRows = [];
    state.invoicesByPlan = {};
    state.ssrHasRecordedSession = false;
    hide("ssr-remarks-card");
    hide("ssr-proceed-row");

    // ============================================================
    // FIX: Show loading state with proper visibility
    // ============================================================
    // First, clear the client area
    var clientStrip = byId("ssr-client-strip");
    if (clientStrip) {
        clientStrip.innerHTML = '';
    }

    // Hide the therapy wrap
    var therapyWrap = byId("ssr-therapy-wrap");
    if (therapyWrap) {
        therapyWrap.innerHTML = '';
    }

    // Show the loading overlay
    showSSRClientLoading();

    if (drop) {
        drop.classList.remove("show");
    }
    var search = byId("ssr-search");
    if (search) {
        search.value = client.patient_name || client.name;
    }
    updateSSRClearButton();

    try {
        setBusy(true, "Loading future appointments, therapy services, invoices, and session history…");
        var clientLoadResults = await Promise.all([
            loadSSRFutureAppointments(client),
            loadSSRClientTherapyData(client),
            getSSRClientRecordedSessionPresence(client),
            lifeLoadReusableClientDocuments(client)
