function lifeSanitizeStandardRequestQtyInput(inputElement){
if(!inputElement){return null;}
var digits=String(inputElement.value==null?"":inputElement.value)
.replace(/\D/g,"");

if(!digits){
inputElement.value="";
return null;
}

digits=digits.replace(/^0+(?=\d)/,"");
var quantity=parseInt(digits,10);
if(!isFinite(quantity)||quantity<1){
quantity=1;
}
inputElement.value=String(quantity);
return quantity;
}

function lifeFinalizeStandardRequestQtyInput(inputElement){
var quantity=lifeSanitizeStandardRequestQtyInput(inputElement);
if(quantity===null){
quantity=1;
inputElement.value="1";
}
return quantity;
}

