async function searchItems(query){
    query = String(query || "").trim();

    var filters = [
        ["disabled", "=", 0],
        ["is_stock_item", "=", 1],
        ["item_group", "not in", ["ASSETS", "Assets", "Services", "SERVICES"]]
    ];

    /*
     * LIFE Stock typo / naming compatibility.
     *
     * Therapy/service names in old ERP data sometimes use "Cosmelon"
     * while the actual physical stock Items are named "Cosmelan".
     *
     * Example:
     *   Therapy: Cosmelon-2 Full Home Care kit
     *   Stock:   D-CFK — Cosmelan Full Kit
     *   Stock:   MI-COSKIT — Cosmelan / Depigmentation Peel Kit
     *
     * Search both spellings and merge the results.
     */
    function searchVariants(value){
        value = String(value || "").trim();

        if(!value){
            return [""];
        }

        var values = [value];
        var lower = value.toLowerCase();

        var aliases = [
            ["cosmelon", "cosmelan"],
            ["cosmelan", "cosmelon"]
        ];

        aliases.forEach(function(pair){
            if(lower.indexOf(pair[0]) >= 0){
                var replaced = value.replace(
                    new RegExp(pair[0], "ig"),
                    pair[1]
                );

                if(values.indexOf(replaced) < 0){
                    values.push(replaced);
                }
            }
        });

        return values;
    }

    async function runOneItemSearch(term){
        var options = {
            order_by: "item_name asc",
            limit_page_length: 100
        };

        if(term){
            options.or_filters = [
                ["name", "like", "%" + term + "%"],
                ["item_code", "like", "%" + term + "%"],
                ["item_name", "like", "%" + term + "%"]
            ];
        }

        return safeGetList(
            "Item",
            [
                [
                    "name",
                    "item_code",
                    "item_name",
                    "stock_uom",
                    "item_group",
                    "disabled",
                    "is_stock_item",
                    "valuation_rate",
                    "last_purchase_rate",
                    "standard_rate"
                ],
                [
                    "name",
                    "item_code",
                    "item_name",
                    "stock_uom",
                    "item_group",
                    "disabled",
                    "is_stock_item",
                    "valuation_rate",
                    "last_purchase_rate"
                ],
                [
                    "name",
                    "item_code",
                    "item_name",
                    "stock_uom",
                    "item_group",
                    "disabled",
                    "is_stock_item"
                ]
            ],
            filters,
            options
        );
    }

    var variants = searchVariants(query);
    var groups = [];

    for(var variantIndex = 0; variantIndex < variants.length; variantIndex++){
        try{
            groups.push(
                await runOneItemSearch(
                    variants[variantIndex]
                )
            );
        }
        catch(error){
            void 0;
        }
    }

    /*
     * Additional practical fallback:
     * If a user types a therapy wording such as "cosmelon kit" and no
     * stock Item is returned, retry the meaningful tokens separately.
     */
    var mergedCount = groups.reduce(function(total, list){
        return total + (Array.isArray(list) ? list.length : 0);
    }, 0);

    if(query && mergedCount === 0){
        var tokens = query
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, " ")
            .split(/\s+/)
            .filter(function(token){
                return token.length >= 3;
            });

        var tokenAliases = [];

        tokens.forEach(function(token){
            if(token === "cosmelon"){
                token = "cosmelan";
            }

            if(tokenAliases.indexOf(token) < 0){
                tokenAliases.push(token);
            }
        });

        for(var tokenIndex = 0; tokenIndex < tokenAliases.length; tokenIndex++){
            try{
                groups.push(
                    await runOneItemSearch(
                        tokenAliases[tokenIndex]
                    )
                );
            }
            catch(tokenError){
                void 0;
            }
        }
    }

    var byCode = Object.create(null);

    groups.forEach(function(rows){
        (Array.isArray(rows) ? rows : []).forEach(function(item){
            var code = String(
                item.item_code ||
                item.name ||
                ""
            ).trim();

            if(!code){
                return;
            }

            if(
                num(item.disabled, 0) === 1 ||
                num(item.is_stock_item, 0) !== 1 ||
                isExcludedRequestItemGroup(item.item_group)
            ){
                return;
            }

            if(!byCode[code]){
                byCode[code] = item;
            }
        });
    });

    var rows = Object.keys(byCode).map(function(code){
        return byCode[code];
    });

    /*
     * Rank exact / close query matches first.
     * This keeps D-CFK and MI-COSKIT near the top for "cosmelon".
     */
    var normalizedQuery = query
        .toLowerCase()
        .replace(/cosmelon/g, "cosmelan");

    rows.sort(function(a, b){
        function rank(item){
            var code = String(
                item.item_code ||
                item.name ||
                ""
            ).toLowerCase();

            var name = String(
                item.item_name ||
                ""
            ).toLowerCase();

            var normalizedName =
                name.replace(/cosmelon/g, "cosmelan");

            var normalizedCode =
                code.replace(/cosmelon/g, "cosmelan");

            if(normalizedName === normalizedQuery){
                return 0;
            }

            if(normalizedName.indexOf(normalizedQuery) === 0){
                return 1;
            }

            if(normalizedName.indexOf(normalizedQuery) >= 0){
                return 2;
            }

            if(normalizedCode.indexOf(normalizedQuery) >= 0){
                return 3;
            }

            return 4;
        }

        var ar = rank(a);
        var br = rank(b);

        if(ar !== br){
            return ar - br;
        }

        return String(a.item_name || a.item_code || "")
            .localeCompare(
                String(b.item_name || b.item_code || ""),
                undefined,
                {
                    numeric: true,
                    sensitivity: "base"
                }
            );
    });

    return rows.slice(0, 100);
}

