var LIFE_THERAPY_CONSUMED_ITEMS_CACHE = Object.create(null);
var LIFE_THERAPY_CONSUMED_ITEMS_PROMISES = Object.create(null);

/*
 * Fetch the child table rows from Therapy Type.custom_consumed_items_details
 * for a given therapy_type doc name. Returns an array of:
 *   { item_code: "...", item_name: "..." }
 *
 * The Item doc name is resolved from the child row via these fields
 * (first one present wins):
 *   - item_code
 *   - item
 *   - item_name (fallback — some child schemas store the item here)
 */
function lifeLoadTherapyConsumedItems(therapyTypeName) {

    var key = String(
        therapyTypeName || ""
    ).trim();

    if (!key) {
        return Promise.resolve([]);
    }

    if (
        LIFE_THERAPY_CONSUMED_ITEMS_CACHE[key]
    ) {
        return Promise.resolve(
            LIFE_THERAPY_CONSUMED_ITEMS_CACHE[key]
        );
    }

    if (
        LIFE_THERAPY_CONSUMED_ITEMS_PROMISES[key]
    ) {
        return LIFE_THERAPY_CONSUMED_ITEMS_PROMISES[key];
    }

    LIFE_THERAPY_CONSUMED_ITEMS_PROMISES[key] =
        callGet("Therapy Type", key)

        .then(function (doc) {

            doc = doc || {};

            /*
             * Read ALL Therapy Type material tables.
             */
            var groups = [
                Array.isArray(doc.custom_main_treatment_consumables)
                    ? doc.custom_main_treatment_consumables
                    : [],
                Array.isArray(doc.custom_supporting_materials)
                    ? doc.custom_supporting_materials
                    : [],
                Array.isArray(doc.custom_consumed_items_details)
                    ? doc.custom_consumed_items_details
                    : []
            ];

            var configured = [];
            var seenConfigured = Object.create(null);

            groups.forEach(function (rows) {

                rows.forEach(function (row) {

                    row = row || {};

                    var ref = String(
                        row.item_code ||
                        row.item ||
                        row.item_name ||
                        row.material ||
                        row.material_item ||
                        row.consumed_item ||
                        row.stock_item ||
                        row.custom_item ||
                        ""
                    ).trim();

                    if (
                        !ref ||
                        seenConfigured[ref]
                    ) {
                        return;
                    }

                    seenConfigured[ref] = true;

                    configured.push({
                        ref: ref,
                        row: row
                    });

                });

            });

            var refs = configured.map(function (entry) {
                return entry.ref;
            });

            void 0;

