                                entry.ref
                            ).trim(),

                        stock_uom:
                            String(
                                item.stock_uom ||
                                "Nos"
                            ).trim(),

                        item_group:
                            String(
                                item.item_group ||
                                ""
                            ).trim(),

                        is_stock_item:
                            item.is_stock_item ===
                            undefined
                                ? 1
                                : num(
                                    item.is_stock_item,
                                    0
                                ),

                        disabled:
                            num(
                                item.disabled,
                                0
                            )
                    };

                    if (
                        normalized.disabled === 1 ||
                        normalized.is_stock_item !== 1 ||
                        isExcludedRequestItemGroup(
                            normalized.item_group
                        )
                    ) {
                        return;
                    }

                    if (
                        finalSeen[
                            normalized.item_code
                        ]
                    ) {
                        return;
                    }

                    finalSeen[
                        normalized.item_code
                    ] = true;

                    finalRows.push(
                        normalized
                    );

                });

                finalRows.sort(function (a, b) {

                    return String(
                        a.item_name ||
                        a.item_code ||
                        ""
                    ).localeCompare(
                        String(
                            b.item_name ||
                            b.item_code ||
                            ""
                        ),
                        undefined,
                        {
                            numeric: true,
                            sensitivity: "base"
                        }
                    );

                });

                void 0;

                LIFE_THERAPY_CONSUMED_ITEMS_CACHE[key] =
                    finalRows;

                return finalRows;

            });

        })

        .catch(function (error) {

            void 0;

            LIFE_THERAPY_CONSUMED_ITEMS_CACHE[key] = [];

            return [];

        })

        .finally(function () {

            delete LIFE_THERAPY_CONSUMED_ITEMS_PROMISES[key];

        });

    return LIFE_THERAPY_CONSUMED_ITEMS_PROMISES[key];
}


/*
 * Given the list of Therapy Type names, return a Promise resolving
 * to the union of all consumed items across those therapy types.
 * Used by therapy rows in the Consumable Request screen.
 */
function lifeLoadConsumedItemsForTherapyNames(therapyNames) {
    var unique = uniqueValues(
        (Array.isArray(therapyNames) ? therapyNames : [])
            .map(function (value) {
                return String(value || "").trim();
            })
            .filter(Boolean)
    );

    if (!unique.length) {
        return Promise.resolve([]);
    }

    return Promise.all(
        unique.map(lifeLoadTherapyConsumedItems)
    ).then(function (groups) {
        var byCode = Object.create(null);

        groups.forEach(function (list) {
            (list || []).forEach(function (row) {
                if (
                    row &&
                    row.item_code &&
                    !byCode[row.item_code]
                ) {
                    byCode[row.item_code] = row;
                }
            });
        });

        return Object.keys(byCode).map(function (code) {
            return byCode[code];
        });
    });
}

