lifeShowPendingTherapyRequestPopup(
clientName,
therapyType,
pendingTherapyRequests
);
return;
}
}
}
catch(error){
void 0;
toast(
"Unable to verify previous Consumable Requests. Please try again.",
"r"
);
return;
}
}

selection.stocks.push({
item_code:itemCode,
item_name:item.item_name||itemCode,
stock_uom:item.stock_uom||"Nos",
item_group:item.item_group||"Item",
