/* ============================================================
   PENDING THERAPY-TYPE REQUEST PROTECTION
   ------------------------------------------------------------
   Business rule:

     SAME CLIENT + SAME THERAPY TYPE + PREVIOUS SPECIAL MATERIAL
     REQUEST STILL PENDING
       => BLOCK ANOTHER CONSUMABLE / STOCK REQUEST FOR THAT THERAPY.

   The selected stock item does NOT matter. If GLP-1 already has a
   pending Consumable Request for the client, another GLP-1 request is
   blocked even when the user selects a different consumable.

   Feature switch:
     LIFE_CONSUMABLE_BLOCK_PENDING_THERAPY_REQUEST = true  -> enabled
     LIFE_CONSUMABLE_BLOCK_PENDING_THERAPY_REQUEST = false -> disabled

   A previous request stops blocking after it is Approved or Rejected.
   A cancelled Material Request also does not block a future request.
   ============================================================ */
function normalizeSSRPendingTherapyValue(value){
return String(value||"")
.trim()
.toLowerCase()
.replace(/&/g," and ")
.replace(/[^a-z0-9]+/g," ")
.replace(/\s+/g," ")
.trim();
}

function isSSRConsumableTherapyRequestClosed(doc){
doc=doc||{};

/* Cancelled ERP document must never block a new request. */
if(num(doc.docstatus,0)===2){
return true;
}

var workflowState=normalizeSSRPendingTherapyValue(doc.workflow_state);
var stockStatus=normalizeSSRPendingTherapyValue(doc.custom_stock_request_status);
var status=normalizeSSRPendingTherapyValue(doc.status);

/*
 * Requested business rule: allow a new request once the earlier
 * therapy request has reached Approved or Rejected.
 */
if(workflowState==="approved"||workflowState==="rejected"){
return true;
}
if(stockStatus==="approved"||stockStatus==="rejected"){
return true;
}
if(status==="approved"||status==="rejected"||status==="cancelled"||status==="canceled"){
return true;
}

return false;
}

function getSSRRequestTherapyNames(doc){
doc=doc||{};
var names=[];

/*
 * Preferred source for newly-created requests:
 * Material Request.custom_therapy_plan_deatils
 */
var detailRows=Array.isArray(doc.custom_therapy_plan_deatils)
?doc.custom_therapy_plan_deatils
:[];

detailRows.forEach(function(row){
var therapyName=String(
row&&(
row.therapy_type||
row.service||
row.service_name
)||""
).trim();
if(therapyName){
names.push(therapyName);
}
});

/*
 * Compatibility fallback for existing requests. The dashboard already
 * stores a line like:
 *   Selected Services: GLP-1 (WM Inj) 1 Dose
 * in custom_additional_notes.
 */
var notes=String(doc.custom_additional_notes||"");
if(notes){
var selectedServicesMatch=notes.match(/Selected Services:\s*([^\r\n]+)/i);
if(selectedServicesMatch&&selectedServicesMatch[1]){
selectedServicesMatch[1]
.split(",")
.map(function(value){return String(value||"").trim();})
.filter(Boolean)
.forEach(function(value){names.push(value);});
}
}

/* Last-resort fallback from SERVICE-WISE DETAILS headings. */
if(!names.length&&notes){
var serviceMatches=notes.match(/(?:^|\n)\s*\d+\.\s+[^\r\n]+/g)||[];
serviceMatches.forEach(function(line){
var therapy=String(line||"")
.replace(/^\s*\n?\s*\d+\.\s*/,"")
.trim();
if(therapy){
names.push(therapy);
}
});
}

var seen=Object.create(null);
return names.filter(function(name){
var key=normalizeSSRPendingTherapyValue(name);
if(!key||seen[key]){
return false;
}
seen[key]=true;
return true;
});
}

async function lifeFindPendingConsumableRequestForTherapy(clientName,therapyType){
if(LIFE_CONSUMABLE_BLOCK_PENDING_THERAPY_REQUEST!==true){
return[];
}

clientName=String(clientName||"").trim();
therapyType=String(therapyType||"").trim();

if(!clientName||!therapyType){
return[];
}

var wantedTherapy=normalizeSSRPendingTherapyValue(therapyType);

var requests=await safeGetList(
"Material Request",
[[
"name",
"docstatus",
"status",
"workflow_state",
"custom_stock_request_status",
"custom_stock_request_type",
"custom_client_name",
"custom_therapy_id",
"custom_patient_appointment",
"transaction_date",
"modified"
]],
[
["custom_client_name","=",clientName],
["custom_stock_request_type","=","Special Material Request"],
["docstatus","<",2]
],
{
order_by:"modified desc",
limit_page_length:100
}
);

requests=Array.isArray(requests)?requests:[];

var pendingRows=requests.filter(function(row){
return row&&row.name&&!isSSRConsumableTherapyRequestClosed(row);
});

if(!pendingRows.length){
return[];
}

var fullDocs=await Promise.all(
pendingRows.map(async function(row){
try{
return await getDoc("Material Request",row.name);
}
catch(error){
void 0;
return null;
}
})
);

var matches=[];

fullDocs.forEach(function(doc){
if(!doc||isSSRConsumableTherapyRequestClosed(doc)){
return;
}

var therapies=getSSRRequestTherapyNames(doc);
var therapyMatched=therapies.some(function(name){
return normalizeSSRPendingTherapyValue(name)===wantedTherapy;
});

if(!therapyMatched){
return;
}

matches.push({
request_name:doc.name,
therapy_type:therapyType,
workflow_state:doc.workflow_state||"",
stock_status:doc.custom_stock_request_status||"",
status:doc.status||"",
appointment:doc.custom_patient_appointment||"",
transaction_date:doc.transaction_date||""
});
});

return matches;
}

