async function lifeValidatePendingTherapyRequestsForDocument(requestDoc){
if(LIFE_CONSUMABLE_BLOCK_PENDING_THERAPY_REQUEST!==true){
return{ok:true,duplicates:[]};
}

requestDoc=requestDoc||{};
var clientName=String(requestDoc.custom_client_name||"").trim();
if(!clientName){
