}

var therapyNames=getSSRRequestTherapyNames(requestDoc);

/*
 * buildSSRDoc() always writes Selected Services to additional notes,
 * so an empty therapy list indicates that the request is malformed.
 */
if(!therapyNames.length){
throw new Error("Unable to determine the selected therapy type for pending-request validation.");
}

var allMatches=[];
for(var index=0;index<therapyNames.length;index++){
var therapyType=therapyNames[index];
var matches=await lifeFindPendingConsumableRequestForTherapy(clientName,therapyType);
(matches||[]).forEach(function(row){
allMatches.push(row);
});
