async function validateASBRSubmitV2(){
    try{
        setBusy(true,"Validating Advance Booking Material Request…");

        /*
         * BOTH existing LIFE clients and new / expected clients are allowed.
         *
         * The Material Request DocType Before Validate Server Script is
         * responsible only for detecting an existing Patient and marking
         * custom_existing_life_client = "Yes". It must NOT throw merely
         * because the mobile already exists.
         *
         * Submit through the existing LIFE Stock gateway so all of the
         * dashboard's normal Material Request creation / attachment logic
         * remains in one place.
         */
        var requestDoc=lifeBuildAdvanceRequestDocForAPI();

        setBusy(true,"Uploading supporting documents…");

        var attachments=await lifeUploadRequestAttachments(
            state.asbrAttachments,
            ASBR_ATTACHMENT_LABELS,
            ASBR_REQUIRED_ATTACHMENT_INDEXES
        );

        setBusy(true,"Submitting Advance Booking Material Request…");

        var result=await lifeRequireAPI().submitRequest(
            requestDoc,
            attachments
        );

        var request=lifeApiResultRequest(result);
        var requestName=String(
            request&&request.name||
            result&&result.request_name||
            ""
        ).trim();

        if(!requestName){
            throw new Error(
                "Advance Booking Material Request was submitted but ERPNext did not return the Material Request ID."
            );
        }

        /* Reset immediately after confirmed success. */
        resetASBR();

        /* Refresh request lists in the background. */
        Promise.resolve()
            .then(function(){
                return loadRequests();
            })
            .catch(function(refreshError){
                void 0;
            });

        lifeShowApiSuccess(
            "Advance Request Submitted",
            "Advance Booking Material Request submitted successfully for the selected client. Existing LIFE clients and new / expected clients are both allowed.",
            "Material Request",
            requestName
        );
    }
    catch(error){
        void 0;
        showError(error);
    }
    finally{
        setBusy(false);
    }
}

