var lifeRequestDropdownObserver=null;
var lifeRequestDropdownFrame=0;

function lifeRequestDropdownIsVisible(drop){
return!!(
drop&&
drop.classList&&
drop.classList.contains("show")
);
}

function lifeRequestDropdowns(){
var root=resolveRoot();
if(!root){
return[];
}
return Array.prototype.slice.call(
root.querySelectorAll(
".search-drop.show,"+
".stock-drop.show,"+
".branch-receipt-employee-results.show,"+
"#asbr-employee-drop.show,"+
"#asbr-cluster-head-drop.show"
)
);
}

function lifeRequestDropdownAnchor(drop){
if(!drop){
return null;
}
return(
drop.closest(".search-wrap")||
drop.closest(".stock-search-wrap")||
drop.closest(".branch-receipt-employee-search-wrap")||
drop.parentElement
);
}

function lifePositionRequestDropdown(drop){

    if(!drop){
        return;
    }


    var isSSRClientDropdown =
        drop.id === "ssr-drop";


    var isASBRPrecheckDropdown =
        drop.id === "asbr-pre-drop";


    /*
     * ============================================================
     * CONSUMABLE REQUEST CLIENT SEARCH
     * ============================================================
     *
     * IMPORTANT:
     * Do NOT use fixed viewport positioning for #ssr-drop.
     *
     * Keep it anchored to .ssr-search-wrap and always render it
     * underneath the search input.
     */
    if(
        isSSRClientDropdown
    ){

        /*
         * Remove all classes/styles left by the old floating logic.
         */
        drop.classList.remove(
            "life-request-drop-fixed",
            "life-request-drop-up"
        );


        drop.style.removeProperty(
            "position"
        );

        drop.style.removeProperty(
            "left"
        );

        drop.style.removeProperty(
            "right"
        );

        drop.style.removeProperty(
            "top"
        );

        drop.style.removeProperty(
            "bottom"
        );

        drop.style.removeProperty(
            "width"
        );

        drop.style.removeProperty(
            "z-index"
        );

        drop.style.removeProperty(
            "max-height"
        );

        drop.style.removeProperty(
            "overflow-y"
        );

        drop.style.removeProperty(
            "overflow-x"
        );

        drop.style.removeProperty(
            "box-sizing"
        );


        /*
         * If dropdown is closed, cleanup is enough.
         */
        if(
            !lifeRequestDropdownIsVisible(
                drop
            )
        ){
            return;
        }


        /*
         * Force stable position directly below the input.
         */
        drop.style.setProperty(
            "position",
            "absolute",
            "important"
        );


        drop.style.setProperty(
            "left",
            "0",
            "important"
        );


        drop.style.setProperty(
            "right",
            "0",
            "important"
        );


        drop.style.setProperty(
            "top",
            "calc(100% + 8px)",
            "important"
        );


        drop.style.setProperty(
            "bottom",
            "auto",
            "important"
        );


        drop.style.setProperty(
            "width",
            "100%",
            "important"
        );


        drop.style.setProperty(
            "max-height",
            "320px",
            "important"
        );


        drop.style.setProperty(
            "overflow-y",
            "auto",
            "important"
        );


        drop.style.setProperty(
            "overflow-x",
            "hidden",
            "important"
        );


        drop.style.setProperty(
            "box-sizing",
            "border-box",
            "important"
        );


        drop.style.setProperty(
            "z-index",
            "2147482000",
            "important"
        );


        return;
    }


    /*
     * ============================================================
     * ALL OTHER DROPDOWNS
     * ============================================================
     */

    if(
        !lifeRequestDropdownIsVisible(
            drop
        )
    ){

        if(
            isASBRPrecheckDropdown
        ){

            drop.classList.remove(
                "life-request-drop-fixed",
                "life-request-drop-up"
            );


            drop.style.removeProperty(
                "left"
            );

            drop.style.removeProperty(
                "top"
            );

            drop.style.removeProperty(
                "right"
            );

            drop.style.removeProperty(
                "bottom"
            );

            drop.style.removeProperty(
                "width"
            );

            drop.style.removeProperty(
                "max-height"
            );

            drop.style.removeProperty(
                "position"
            );

            drop.style.removeProperty(
                "z-index"
            );

            drop.style.removeProperty(
                "overflow-y"
            );

            drop.style.removeProperty(
                "overflow-x"
            );

            drop.style.removeProperty(
                "box-sizing"
            );
        }


        return;
    }


    var anchor =
        lifeRequestDropdownAnchor(
            drop
        );


    if(
        !anchor ||
        !anchor.getBoundingClientRect
    ){
        return;
    }


    var field =
        anchor.querySelector(
            "input,select,textarea,button"
        ) ||
        anchor;


    if(
        !field ||
        !field.getBoundingClientRect
    ){
        return;
    }


    var rect =
        field.getBoundingClientRect();


    var viewportHeight =
        window.innerHeight ||
        document.documentElement.clientHeight ||
        800;


    var viewportWidth =
        window.innerWidth ||
        document.documentElement.clientWidth ||
        1200;


    var edgeGap =
        14;


    var dropdownGap =
        6;


    var availableBelow =
        Math.max(
            0,
            viewportHeight -
            rect.bottom -
            edgeGap
        );


    var availableAbove =
        Math.max(
            0,
            rect.top -
            edgeGap
        );


    var isSearchDrop =
        drop.classList.contains(
            "search-drop"
        );


    var maximumHeight =
        isSearchDrop
            ? 380
            : 330;


    var contentHeight =
        Math.max(
            0,
            Number(
                drop.scrollHeight
            ) ||
            0
        );


    var fallbackDesiredHeight =
        isSearchDrop
            ? 280
            : 220;


    var desiredHeight =
        Math.min(
            maximumHeight,
            Math.max(
                96,
                contentHeight ||
                fallbackDesiredHeight
            )
        );


    var openUp =
        availableBelow <
            desiredHeight &&
        availableAbove >
            availableBelow;


    var availableSpace =
        Math.max(
            72,
            (
                openUp
                    ? availableAbove
                    : availableBelow
            ) -
            dropdownGap
        );


    var calculatedHeight =
        Math.max(
            72,
            Math.min(
                maximumHeight,
                desiredHeight,
                Math.floor(
                    availableSpace
                )
            )
        );


    drop.classList.toggle(
        "life-request-drop-up",
        openUp
    );


    drop.style.maxHeight =
        calculatedHeight +
        "px";


    /*
     * ============================================================
     * NORMAL RELATIVE DROPDOWNS
     * ============================================================
     */

    if(
        !isASBRPrecheckDropdown
    ){

        drop.classList.remove(
            "life-request-drop-fixed"
        );


        drop.style.removeProperty(
            "left"
        );

        drop.style.removeProperty(
            "right"
        );

        drop.style.removeProperty(
            "width"
        );

        drop.style.removeProperty(
            "position"
        );

        drop.style.removeProperty(
            "top"
        );

        drop.style.removeProperty(
            "bottom"
        );


        return;
    }


    /*
     * ============================================================
     * ADVANCE BOOKING PRE-CHECK ONLY
     * Keep viewport-fixed behavior here.
     * ============================================================
     */

    var fixedWidth =
        Math.max(
            220,
            Math.min(
                rect.width,
                viewportWidth -
                (
                    edgeGap *
                    2
                )
            )
        );


    var fixedLeft =
        Math.max(
            edgeGap,
            Math.min(
                rect.left,
                viewportWidth -
                edgeGap -
                fixedWidth
            )
        );


    var fixedTop;


    if(
        openUp
    ){

        fixedTop =
            Math.max(
                edgeGap,
                rect.top -
                dropdownGap -
                calculatedHeight
            );
    }
    else{

        fixedTop =
            Math.min(
                viewportHeight -
                edgeGap -
                calculatedHeight,

                rect.bottom +
                dropdownGap
            );


        fixedTop =
            Math.max(
                edgeGap,
                fixedTop
            );
    }


    drop.classList.add(
        "life-request-drop-fixed"
    );


    drop.style.setProperty(
        "position",
        "fixed",
        "important"
    );


    drop.style.setProperty(
        "left",
        Math.round(
            fixedLeft
        ) +
        "px",
        "important"
    );


    drop.style.setProperty(
        "top",
        Math.round(
            fixedTop
        ) +
        "px",
        "important"
    );


    drop.style.setProperty(
        "right",
        "auto",
        "important"
    );


    drop.style.setProperty(
        "bottom",
        "auto",
        "important"
    );


    drop.style.setProperty(
        "width",
        Math.round(
            fixedWidth
        ) +
        "px",
        "important"
    );


    drop.style.setProperty(
        "max-height",
        Math.round(
            calculatedHeight
        ) +
        "px",
        "important"
    );


    drop.style.setProperty(
        "overflow-y",
        "auto",
        "important"
    );


    drop.style.setProperty(
        "overflow-x",
        "hidden",
        "important"
    );


    drop.style.setProperty(
        "box-sizing",
        "border-box",
        "important"
    );


    drop.style.setProperty(
        "z-index",
        "2147482000",
        "important"
    );
}

function lifePositionVisibleRequestDropdowns(){
lifeRequestDropdownFrame=0;
lifeRequestDropdowns().forEach(
lifePositionRequestDropdown
);
}

