function installRequestDropdownPositioning(){
var root=resolveRoot();
if(!root||root.dataset.lifeDropdownPositioning==="1"){
return;
}

installASBRPrecheckFloatingDropdownStyle();

root.dataset.lifeDropdownPositioning="1";

lifeRequestDropdownObserver=
new MutationObserver(function(mutations){
var shouldPosition=false;

mutations.forEach(function(mutation){
var target=mutation.target;

if(
mutation.type==="attributes"&&
target&&
target.classList&&
(
target.classList.contains("search-drop")||
target.classList.contains("stock-drop")||
target.classList.contains("branch-receipt-employee-results")||
target.id==="asbr-employee-drop"||
target.id==="asbr-cluster-head-drop"
)
){
shouldPosition=true;
}

if(
mutation.type==="childList"&&
target&&
(
target.closest&&
target.closest(
".search-drop,.stock-drop,"+
".branch-receipt-employee-results,"+
"#asbr-employee-drop,"+
"#asbr-cluster-head-drop"
)
)
){
shouldPosition=true;
}
}
);

if(shouldPosition){
lifeScheduleRequestDropdownPosition();
}
}
);

lifeRequestDropdownObserver.observe(
root,
{
subtree:true,
childList:true,
attributes:true,
attributeFilter:["class"]
}
);

window.addEventListener(
"resize",
lifeScheduleRequestDropdownPosition
);

window.addEventListener(
"scroll",
lifeScheduleRequestDropdownPosition,
true
);

lifeScheduleRequestDropdownPosition();
}

