function installMonthlyIndentScrollHandoff(){

var page=byId(
"page-monthly-indent"
);

if(!page){
return;
}

if(
page.dataset.scrollHandoffInstalled===
"1"
){
return;
}

page.dataset.scrollHandoffInstalled=
"1";

page.addEventListener(
"wheel",
function(event){

var target=
event.target;

if(
!target||
typeof target.closest!=="function"
){
return;
}

var scroller=
target.closest(
".bulk-monthly-indent-table-scroll"
);

if(!scroller){
return;
}

var scrollTop=
Number(scroller.scrollTop)||0;

var clientHeight=
Number(scroller.clientHeight)||0;

var scrollHeight=
Number(scroller.scrollHeight)||0;

var atTop=
scrollTop<=1;

var atBottom=
(
scrollTop+
clientHeight
)>=(
scrollHeight-2
);

if(
event.deltaY>0&&
atBottom
){
event.preventDefault();

window.scrollBy({
top:event.deltaY,
left:0,
behavior:"auto"
});

return;
}

if(
event.deltaY<0&&
atTop
){
event.preventDefault();

window.scrollBy({
top:event.deltaY,
left:0,
behavior:"auto"
});
}
},
{
passive:false
}
);
}

