        "";

    var extractedBranch =
        extractBranchFromWarehouse(targetWarehouse);

    if (
        extractedBranch &&
        extractedBranch !== "No Branch"
    ) {
        return String(extractedBranch).trim();
    }

    return String(
        row.branch || "No Branch"
    ).trim();
}

function hoManagerReceiptTargetBranch(row) {
    row = row || {};

    var branch =
        stockEntryTargetBranchLabel(row);

    return String(
        branch || "No Branch"
    ).trim();
}

function hoManagerRowMatchesBranch(row, rowType) {
    var activeBranch =
        normalizeHOManagerBranchKey(
            hoManagerBranchFilter
        );

    if (activeBranch === "all") {
        return true;
    }

    var rowBranch =
        rowType === "receipt"
            ? hoManagerReceiptTargetBranch(row)
            : hoManagerRequestTargetBranch(row);

    return (
        normalizeHOManagerBranchKey(rowBranch) ===
        activeBranch
    );
}

function filterHOManagerRowsByBranch(
    rows,
    rowType
) {
    rows = Array.isArray(rows) ? rows : [];

    if (
        normalizeHOManagerBranchKey(
            hoManagerBranchFilter
        ) === "all"
    ) {
        return rows.slice();
    }

    return rows.filter(function (row) {
        return hoManagerRowMatchesBranch(
            row,
            rowType
        );
    });
}

function collectHOManagerBranchOptions() {
    var branchMap = Object.create(null);

    var excludedHOManagerBranchKeys = [
    "Head Office",
    "HO Central Stores",
    "Testing",
    "Testing Branch"
].map(function (value) {
    return normalizeHOManagerBranchKey(value);
});

function addBranch(branchName) {
    var label = String(
        branchName || ""
    ).trim();

    var key =
        normalizeHOManagerBranchKey(label);

    if (
        !label ||
        key === "all" ||
        label === "No Branch" ||
        label === "—" ||
        excludedHOManagerBranchKeys.indexOf(key) !== -1
    ) {
        return;
    }

    if (!branchMap[key]) {
        branchMap[key] = label;
    }
}

    /*
     * Include all Branch master records.
     */
    (Array.isArray(state.branches)
        ? state.branches
        : []
    ).forEach(function (branch) {
        addBranch(
            branch.branch ||
            branch.name
        );
    });

    /*
     * Include branches found in Material Requests.
     */
    (Array.isArray(state.requests)
        ? state.requests
        : []
    ).forEach(function (request) {
        addBranch(
            hoManagerRequestTargetBranch(
                request
            )
        );
    });

    /*
     * Include branches found in Stock Entries.
     */
    (
        typeof hoReceiptTrackingRows !==
            "undefined" &&
        Array.isArray(hoReceiptTrackingRows)
            ? hoReceiptTrackingRows
            : []
    ).forEach(function (stockEntry) {
        addBranch(
            hoManagerReceiptTargetBranch(
                stockEntry
            )
        );
    });

    return Object.keys(branchMap)
        .map(function (key) {
            return {
                key: key,
                label: branchMap[key]
            };
        })
        .sort(function (left, right) {
            return left.label.localeCompare(
                right.label
            );
        });
}

function getHOManagerActiveBranchLabel() {
    var activeKey =
        normalizeHOManagerBranchKey(
            hoManagerBranchFilter
        );

    if (activeKey === "all") {
        return "All Branches";
    }

    var options =
        collectHOManagerBranchOptions();

    var selected = options.find(
        function (option) {
            return option.key === activeKey;
        }
    );

    return selected
        ? selected.label
        : "Selected Branch";
}

function buildHOManagerBranchFilter() {
