}

function moveHOManagerBranchFilterToHeader() {
    var refreshButton =
        byId("ho-refresh-all-btn");

    var approvalArea =
        byId("ho-approval-area");

    if (!refreshButton || !approvalArea) {
        return;
    }

    /*
     * Always select the filter created by the current
     * renderHOApproval() call. The previous filter may
     * already be in the header and has the same ID.
     */
    var filterBar =
        approvalArea.querySelector(
            ".ho-manager-branch-filter-bar"
        );

    if (!filterBar) {
        return;
    }

    var headerRow =
        refreshButton.parentElement;

    if (!headerRow) {
        return;
    }

    /*
     * Remove filters moved into the header by older renders.
     */
    var previousHeaderFilters =
        headerRow.querySelectorAll(
            ".ho-manager-branch-filter-bar"
        );

    Array.prototype.forEach.call(
        previousHeaderFilters,
        function (previousFilter) {
            if (
                previousFilter !== filterBar &&
                previousFilter.parentNode
            ) {
                previousFilter.parentNode.removeChild(
                    previousFilter
                );
            }
        }
    );

    headerRow.classList.add(
        "ho-manager-top-row-with-filter"
    );

    filterBar.classList.add(
        "ho-manager-branch-filter-bar--header"
    );

    headerRow.insertBefore(
        filterBar,
        refreshButton
    );
}

