/* =========================================================
   REQUESTS & APPROVALS — LOCAL LIST FILTERS
   ---------------------------------------------------------
   Pending Approval and Approved / Pending Stock Release each
   keep their own independent filters:
   1. Branch / Target Warehouse
   2. Request Date From
   3. Request Date To
   4. Required By
   5. Request Type
   ========================================================= */
var hoPendingApprovalFilters = {
    targetWarehouse: "all",
    requestDateFrom: "",
    requestDateTo: "",
    requiredBy: "",
    requestType: "all"
};

var hoApprovedReleaseFilters = {
    targetWarehouse: "all",
    requestDateFrom: "",
    requestDateTo: "",
    requiredBy: "",
    requestType: "all"
};

function normalizeHOPendingFilterText(value) {
    return String(value || "")
        .trim()
        .toLowerCase();
}

function hoPendingTargetWarehouse(row) {
    row = row || {};

    return String(
        row.set_warehouse ||
        row.target_warehouse ||
        row.warehouse ||
        ""
    ).trim();
}

function hoPendingTargetWarehouseLabel(value) {
    var raw = String(value || "").trim();

    if (!raw) {
        return "No Target Warehouse";
    }

    if (typeof window.lifeWarehouseDisplayName === "function") {
        return window.lifeWarehouseDisplayName(raw) || raw;
    }

    return raw
        .replace(/\s*-\s*LSACPL\s*$/i, "")
        .trim();
}

function hoPendingRequiredByValue(row) {
    var raw = String(
        row && (
            row.schedule_date ||
            row.required_by ||
            row.requiredBy ||
            ""
        ) || ""
    ).trim();

    return raw ? raw.slice(0, 10) : "";
}

function hoRequestDateValue(row) {
    var raw = String(
        row && (
            row.creation ||
            row.transaction_date ||
            row.request_date ||
            row.submittedOn ||
            ""
        ) || ""
    ).trim();

    return raw ? raw.slice(0, 10) : "";
}

function collectHOPendingTargetWarehouseOptions(rows) {
    var map = Object.create(null);

    (Array.isArray(rows) ? rows : []).forEach(function (row) {
        var warehouse = hoPendingTargetWarehouse(row);
        var key = normalizeHOPendingFilterText(warehouse);

        if (!warehouse || !key) {
            return;
        }

        if (!map[key]) {
            map[key] = {
                value: warehouse,
                label: hoPendingTargetWarehouseLabel(warehouse)
            };
        }
    });

    return Object.keys(map)
        .map(function (key) {
            return map[key];
        })
        .sort(function (left, right) {
            return left.label.localeCompare(right.label);
        });
}

function collectHOPendingRequestTypeOptions(rows) {
    var map = Object.create(null);

    function addType(label) {
        label = String(label || "").trim();

        var key =
            normalizeHOPendingFilterText(
                label
            );

        if (!label || !key) {
            return;
        }

        if (!map[key]) {
            map[key] = label;
        }
    }

    /*
     * Keep the standard request types visible even when the
     * currently loaded list does not contain one of them.
     */
    [
        "Monthly Indent Request (General)",
        "Consumable Request",
        "Advance Booking Material Request"
    ].forEach(addType);

    /*
     * Add any additional type actually returned by ERPNext.
     */
    (Array.isArray(rows) ? rows : []).forEach(function (row) {
        addType(
            requestDisplayType(
                row
            )
        );
    });

    var preferredOrder = {
        "monthly indent request (general)": 1,
        "consumable request": 2,
        "advance booking material request": 3,
        "advance material request": 3
    };

    return Object.keys(map)
        .map(function (key) {
            return map[key];
        })
        .sort(function (left, right) {
            var leftKey =
                normalizeHOPendingFilterText(
                    left
                );

            var rightKey =
                normalizeHOPendingFilterText(
                    right
                );

            var leftOrder =
                preferredOrder[
                    leftKey
                ] || 99;

            var rightOrder =
                preferredOrder[
                    rightKey
                ] || 99;

            if (
                leftOrder !==
                rightOrder
            ) {
                return (
                    leftOrder -
                    rightOrder
                );
            }

            return left.localeCompare(
                right
            );
        });
}

function hoRequestLocalFiltersActive(filters) {
    filters = filters || {};

    return (
        normalizeHOPendingFilterText(
            filters.targetWarehouse
        ) !== "all" ||
        !!String(filters.requestDateFrom || "").trim() ||
        !!String(filters.requestDateTo || "").trim() ||
        !!String(filters.requiredBy || "").trim() ||
        normalizeHOPendingFilterText(
            filters.requestType
        ) !== "all"
    );
}

function filterHORequestRowsByLocalFilters(rows, filters) {
    rows = Array.isArray(rows) ? rows : [];
    filters = filters || {};

    var targetWarehouse =
        normalizeHOPendingFilterText(
            filters.targetWarehouse
        );

    var requestDateFrom =
        String(
            filters.requestDateFrom || ""
        ).trim();

    var requestDateTo =
        String(
            filters.requestDateTo || ""
        ).trim();

    var requiredBy =
        String(
            filters.requiredBy || ""
        ).trim();

    var requestType =
        normalizeHOPendingFilterText(
            filters.requestType
        );

    return rows.filter(function (row) {
        if (
            targetWarehouse !== "all" &&
            normalizeHOPendingFilterText(
                hoPendingTargetWarehouse(row)
            ) !== targetWarehouse
        ) {
            return false;
        }

        var requestDate =
            hoRequestDateValue(row);

        if (
            requestDateFrom &&
            (
                !requestDate ||
                requestDate < requestDateFrom
            )
        ) {
            return false;
        }

        if (
            requestDateTo &&
            (
                !requestDate ||
                requestDate > requestDateTo
            )
        ) {
            return false;
        }

        if (
            requiredBy &&
            hoPendingRequiredByValue(row) !== requiredBy
        ) {
            return false;
        }

        if (
            requestType !== "all" &&
            normalizeHOPendingFilterText(
                requestDisplayType(row)
            ) !== requestType
        ) {
            return false;
        }

        return true;
    });
}

function buildHORequestLocalFilters(rows, options) {
    rows = Array.isArray(rows) ? rows : [];
    options = options || {};

    var filters =
        options.filters || {};

    var prefix =
        String(
            options.prefix || "ho-request"
        ).trim();

    var setterName =
        String(
            options.setterName || ""
        ).trim();

    var resetName =
        String(
            options.resetName || ""
        ).trim();

    var warehouseOptions =
        '<option value="all">All Branches / Target Warehouses</option>';

    collectHOPendingTargetWarehouseOptions(rows)
        .forEach(function (option) {
            var selected =
                normalizeHOPendingFilterText(
                    option.value
                ) ===
                normalizeHOPendingFilterText(
                    filters.targetWarehouse
                );

            warehouseOptions +=
                '<option value="' +
                escAttr(option.value) +
                '"' +
                (selected ? " selected" : "") +
                '>' +
                escapeHtml(option.label) +
                '</option>';
        });

    var requestTypeOptions =
        '<option value="all">All Request Types</option>';

    collectHOPendingRequestTypeOptions(rows)
        .forEach(function (typeLabel) {
            var selected =
                normalizeHOPendingFilterText(
                    typeLabel
                ) ===
                normalizeHOPendingFilterText(
                    filters.requestType
                );

            requestTypeOptions +=
                '<option value="' +
                escAttr(typeLabel) +
                '"' +
                (selected ? " selected" : "") +
                '>' +
                escapeHtml(typeLabel) +
                '</option>';
        });

    return (
        '<div class="ho-pending-filter-shell" style="box-sizing:border-box;width:100%;padding:16px 28px 18px">' +
        '<div class="ho-pending-filter-bar" style="box-sizing:border-box;width:100%;margin:0">' +

            '<div class="ho-pending-filter-field ho-pending-filter-warehouse">' +
                '<label for="' + escAttr(prefix) + '-target-warehouse-filter">' +
                    'Branch / Target Warehouse' +
                '</label>' +
                '<select id="' + escAttr(prefix) + '-target-warehouse-filter" ' +
                    'onchange="' + escAttr(setterName) + '(\'targetWarehouse\',this.value)">' +
                    warehouseOptions +
                '</select>' +
            '</div>' +

            '<div class="ho-pending-filter-field">' +
                '<label for="' + escAttr(prefix) + '-request-date-from-filter">' +
                    'Request Date From' +
                '</label>' +
                '<input id="' + escAttr(prefix) + '-request-date-from-filter" type="date" ' +
                    'value="' +
                    escAttr(filters.requestDateFrom || "") +
                    '" onchange="' + escAttr(setterName) + '(\'requestDateFrom\',this.value)">' +
            '</div>' +

            '<div class="ho-pending-filter-field">' +
                '<label for="' + escAttr(prefix) + '-request-date-to-filter">' +
                    'Request Date To' +
                '</label>' +
                '<input id="' + escAttr(prefix) + '-request-date-to-filter" type="date" ' +
                    'value="' +
                    escAttr(filters.requestDateTo || "") +
                    '" onchange="' + escAttr(setterName) + '(\'requestDateTo\',this.value)">' +
            '</div>' +

            '<div class="ho-pending-filter-field">' +
                '<label for="' + escAttr(prefix) + '-required-by-filter">' +
                    'Required By' +
                '</label>' +
                '<input id="' + escAttr(prefix) + '-required-by-filter" type="date" ' +
                    'value="' +
                    escAttr(filters.requiredBy || "") +
                    '" onchange="' + escAttr(setterName) + '(\'requiredBy\',this.value)">' +
            '</div>' +

            '<div class="ho-pending-filter-field">' +
                '<label for="' + escAttr(prefix) + '-request-type-filter">' +
                    'Request Type' +
                '</label>' +
                '<select id="' + escAttr(prefix) + '-request-type-filter" ' +
                    'onchange="' + escAttr(setterName) + '(\'requestType\',this.value)">' +
                    requestTypeOptions +
                '</select>' +
            '</div>' +

            '<div class="ho-pending-filter-actions">' +
                '<button type="button" class="btn btn-gy btn-sm" ' +
                    'onclick="' + escAttr(resetName) + '()">' +
                    '↺ Reset Filters' +
                '</button>' +
            '</div>' +

        '</div>' +
        '</div>'
    );
}

function hoPendingApprovalFiltersActive() {
    return hoRequestLocalFiltersActive(
        hoPendingApprovalFilters
    );
}

function filterHOPendingApprovalRows(rows) {
    return filterHORequestRowsByLocalFilters(
        rows,
        hoPendingApprovalFilters
    );
}

function buildHOPendingApprovalFilters(rows) {
    return buildHORequestLocalFilters(
        rows,
        {
            filters: hoPendingApprovalFilters,
            prefix: "ho-pending",
            setterName: "setHOPendingApprovalFilter",
            resetName: "resetHOPendingApprovalFilters"
        }
    );
}

function setHOPendingApprovalFilter(filterName, value) {
    var name = String(filterName || "").trim();

    var allowedFilters = [
        "targetWarehouse",
        "clientSearch",
        "itemSearch",
        "requestDateFrom",
        "requestDateTo",
        "requiredBy",
        "requestType"
    ];

    if (allowedFilters.indexOf(name) === -1) {
        return;
    }

    /*
     * Always update the stored filter immediately.
     */
    hoPendingApprovalFilters[name] =
        String(
            value === null ||
            value === undefined
                ? ""
                : value
        );

    state.hoPendingPage = 1;

    /*
     * Text fields:
     * don't rebuild entire Pending section
     * for every single keyboard event.
     */
    if (
        name === "clientSearch" ||
        name === "itemSearch"
    ) {
        clearTimeout(
            hoPendingTextFilterTimer
        );

        var activeElement =
            document.activeElement;

        var activeId =
            activeElement &&
            activeElement.id
                ? activeElement.id
                : "";

        var cursorPosition = null;

        try {
            if (
                activeElement &&
                typeof activeElement.selectionStart ===
                    "number"
            ) {
                cursorPosition =
                    activeElement.selectionStart;
            }
        } catch (ignore) {}

        hoPendingTextFilterTimer =
            setTimeout(function () {

                renderHOApproval();

                /*
                 * Restore the field after render.
                 */
                if (activeId) {
                    var input =
                        document.getElementById(
                            activeId
                        );

                    if (input) {
                        try {
                            input.focus({
                                preventScroll: true
                            });
                        } catch (error) {
                            input.focus();
                        }

                        if (
                            cursorPosition !== null &&
                            typeof input.setSelectionRange ===
                                "function"
                        ) {
                            try {
                                var len =
                                    String(
                                        input.value || ""
                                    ).length;

                                var pos =
                                    Math.min(
                                        cursorPosition,
                                        len
                                    );

                                input.setSelectionRange(
                                    pos,
                                    pos
                                );
                            } catch (ignoreCursor) {}
                        }
                    }
                }

            }, 180);

        return;
    }

    /*
     * Select/date fields can render immediately.
     */
    renderHOApproval();
}

function resetHOPendingApprovalFilters() {
