/* =========================================================
   ORIGINAL HO STATUS-GROUP FILTER
   ========================================================= */

function hoManagerRows(group) {
    var rows =
        Array.isArray(
            state.requests
        )
            ? state.requests
            : [];

    /*
     * Requests & Approvals must show every Material Request type
     * in every status group. Client-linked-only filtering belongs
     * only to Sent Material / Session Tracking.
     */
    return rows.filter(function (row) {
        return (
            hoManagerStatusGroup(
                row
            ) ===
            String(group || "").trim()
        );
    });
}
function hoManagerItems(row){
if(row&&Array.isArray(row.items)&&row.items.length){
return row.items;
}
if(row&&Array.isArray(row._home_items)){
return row._home_items;
}
return[];
}
function hoManagerPageData(rows,requestedPage){
var pageSize=Math.max(1,num(state.hoPageSize,10));
var totalRecords=rows.length;
var totalPages=Math.max(1,Math.ceil(totalRecords/pageSize));
var currentPage=Math.min(totalPages,Math.max(1,num(requestedPage,1)));
var start=(currentPage-1)*pageSize;
return{
rows:rows.slice(start,start+pageSize),currentPage:currentPage,totalPages:totalPages,totalRecords:totalRecords,firstRecord:totalRecords?start+1:0,lastRecord:totalRecords?Math.min(start+pageSize,totalRecords):0}
;
}
function buildHOManagerPagination(listType,data){
if(!data||data.totalPages<=1){
return"";
}
var startPage=Math.max(1,data.currentPage-2);
var endPage=Math.min(data.totalPages,startPage+4);
startPage=Math.max(1,endPage-4);
var buttons="";
var page;
for(page=startPage;
