var toggle=byId("ho-"+key+"-toggle");
var content=byId("ho-"+key+"-content");
var chevron=byId("ho-"+key+"-chevron");
if(toggle){
toggle.setAttribute("aria-expanded",expanded?"true":"false");
toggle.classList.toggle("expanded",expanded);
}
if(content){
content.hidden=!expanded;
}
if(chevron){
chevron.textContent=expanded?"▾":"▸";
}
}
function toggleHOSection(section){
var key=normalizeHOSectionKey(section);
if(!key){
return;
}
if(!state.hoSectionExpanded){
state.hoSectionExpanded={
pending:false,approved:false,completed:false,receipts:false}
;
}
state.hoSectionExpanded[key]=!state.hoSectionExpanded[key];
updateHOSectionToggleUI(key);
if(key==="completed"&&state.hoSectionExpanded[key]){
var completedList=byId("ho-completed-tracking-list");
if(completedList&&completedList.dataset.completedTrackingLoaded!=="1"&&completedList.dataset.completedTrackingLoaded!=="loading"&&typeof renderHOCompletedTracking==="function"){
renderHOCompletedTracking().catch(showError);
