function materialAdjustmentLoadMasters(
forceReload
){

if(
materialAdjustmentMasters.loaded&&
!forceReload
){
return Promise.resolve(
materialAdjustmentMasters
);
}

if(
materialAdjustmentMasters.loading&&
!forceReload
){
return materialAdjustmentMasters.loading;
}

var company=
String(
(
materialAdjustmentFormState&&
materialAdjustmentFormState.company
)||
state.company||
COMPANY_FALLBACK||
""
).trim();

var warehousePromise;

if(
Array.isArray(state.warehouses)&&
state.warehouses.length&&
!forceReload
){
warehousePromise=
Promise.resolve(
state.warehouses.slice()
);
}
else{
warehousePromise=
materialAdjustmentSafeList(
"Warehouse",
[
"name",
"warehouse_name",
"company",
"is_group",
"disabled"
],
[
["company","=",company],
["is_group","=",0],
["disabled","=",0]
],
{
order_by:"warehouse_name asc",
limit_page_length:5000
}
);
}

materialAdjustmentMasters.loading=
warehousePromise
.then(function(rows){

materialAdjustmentMasters.warehouses=
(Array.isArray(rows)?rows:[])
.filter(function(row){
return(
row&&
String(
row.name||
row.warehouse_name||
""
).trim()&&
num(row.is_group,0)!==1&&
num(row.disabled,0)!==1
);
});

materialAdjustmentMasters.loaded=true;
materialAdjustmentMasters.loading=null;

return materialAdjustmentMasters;
})
.catch(function(error){
materialAdjustmentMasters.loading=null;
throw error;
});

return materialAdjustmentMasters.loading;
}


function materialAdjustmentIsMainStore(
name
){

name=
String(
name||
""
).trim();

if(!name){
return false;
}

/*
 * User requirement:
 * Source warehouse names containing "Main".
 */
return(
/(^|[\s\-_])main([\s\-_]|$)/i
.test(name)
);
}


function materialAdjustmentIsSubStore(
name
){

name=
String(
name||
""
).trim();

if(!name){
return false;
}

/*
 * User requirement:
 * Target warehouse names containing "Sub".
 */
return(
/(^|[\s\-_])sub([\s\-_]|$)/i
.test(name)
);
}


function materialAdjustmentBranchKey(
value
){

if(
typeof lifeRequestBranchLookupKey===
"function"
){
return lifeRequestBranchLookupKey(
value
);
}

return String(
value||
""
)
.toLowerCase()
.replace(/\s*-\s*lsacpl\s*$/i,"")
.replace(/\bbranch\b/gi,"")
.replace(/\bmain\b/gi,"")
.replace(/\bsub\b/gi,"")
.replace(/\bstores?\b/gi,"")
.replace(/\bwarehouses?\b/gi,"")
.replace(/[^a-z0-9]+/g,"")
.trim();
}


function materialAdjustmentCurrentBranchKey(){

var candidates=[
window.__lifeIntegratedStockBranchName,
state.branch,
state.employee&&state.employee.branch
];

for(
var index=0;
index<candidates.length;
index+=1
){
var key=
materialAdjustmentBranchKey(
candidates[index]
);

if(key){
return key;
}
}

return"";
}


function materialAdjustmentGetMainWarehouses(){

var rows=
(materialAdjustmentMasters.warehouses||[])
.filter(function(warehouse){

var name=
String(
warehouse&&(
warehouse.name||
warehouse.warehouse_name
)||
""
).trim();

return(
name&&
materialAdjustmentIsMainStore(name)&&
!materialAdjustmentIsSubStore(name)
);
});

/*
 * For a normal Branch login, keep this feature inside that branch.
 * System/Stock Manager testing can still use the server-permitted
 * warehouse list when no branch context is available.
 */
var branchKey=
materialAdjustmentCurrentBranchKey();

var hostRole=
String(
window.__lifeIntegratedStockRole||
""
).trim().toLowerCase();

if(
branchKey&&
hostRole==="branch"
){
var branchRows=
rows.filter(function(warehouse){

var name=
String(
warehouse.name||
warehouse.warehouse_name||
""
).trim();

var warehouseKey=
materialAdjustmentBranchKey(
name
);

return(
warehouseKey===branchKey||
warehouseKey.indexOf(branchKey)>=0||
branchKey.indexOf(warehouseKey)>=0
);
});

if(branchRows.length){
rows=branchRows;
}
}

return rows
.slice()
.sort(function(left,right){

var leftName=
String(
left.name||
left.warehouse_name||
""
);

var rightName=
String(
right.name||
right.warehouse_name||
""
);

return leftName.localeCompare(
rightName,
undefined,
{
numeric:true,
sensitivity:"base"
}
);
});
}


function materialAdjustmentGetSubWarehouses(){

return(
materialAdjustmentMasters.warehouses||
[]
)
.filter(function(warehouse){

var name=
String(
warehouse&&(
warehouse.name||
warehouse.warehouse_name
)||
""
).trim();

return(
name&&
materialAdjustmentIsSubStore(name)
);
})
.slice()
.sort(function(left,right){

var leftName=
String(
left.name||
left.warehouse_name||
""
);

var rightName=
String(
right.name||
right.warehouse_name||
""
);

return leftName.localeCompare(
rightName,
undefined,
{
numeric:true,
sensitivity:"base"
}
);
});
}


function materialAdjustmentResolveSubWarehouse(
sourceWarehouse
){

sourceWarehouse=
String(
sourceWarehouse||
""
).trim();

if(!sourceWarehouse){
return"";
}

var sourceKey=
materialAdjustmentBranchKey(
sourceWarehouse
);

if(!sourceKey){
return"";
}

var candidates=
materialAdjustmentGetSubWarehouses();

var exact=
candidates.find(function(warehouse){

var name=
String(
warehouse.name||
warehouse.warehouse_name||
""
).trim();

return(
materialAdjustmentBranchKey(name)===
sourceKey
);
});

if(exact){
return String(
exact.name||
exact.warehouse_name||
""
).trim();
}

/*
 * Compatibility for spelling differences such as
 * Himayatnagar/Himayathnagar.
 */
var contained=
candidates.find(function(warehouse){

var name=
String(
warehouse.name||
warehouse.warehouse_name||
""
).trim();

var targetKey=
materialAdjustmentBranchKey(
name
);

return(
targetKey&&
(
targetKey===sourceKey||
targetKey.indexOf(sourceKey)>=0||
sourceKey.indexOf(targetKey)>=0
)
);
});

return contained
?String(
contained.name||
contained.warehouse_name||
""
).trim()
:"";
}


