                escAttr(
                    name
                ) +
                '"' +

                (
                    name === selected
                        ? " selected"
                        : ""
                ) +

            '>' +

                escapeHtml(
                    label ||
                    name
                ) +

            '</option>';
    });


    return html;
}

function materialAdjustmentNormalizeQty(
value,
fallback,
maxValue
){

var fallbackNumber=
Number(fallback);

if(
!isFinite(fallbackNumber)||
fallbackNumber<=0
){
fallbackNumber=1;
}

var quantity=
Number(value);

if(
!isFinite(quantity)||
quantity<=0
){
quantity=fallbackNumber;
}

var maximum=
Number(maxValue);

if(
isFinite(maximum)&&
maximum>0
){
quantity=
Math.min(
quantity,
maximum
);
}

return(
Math.round(
quantity*
1000000
)/
1000000
);
}


