function materialAdjustmentWireSelectedItems(){

    materialAdjustmentQueryAll(
        '#material-adjustment-stock-list ' +
        '.material-adjustment-qty'
    )
    .forEach(function(input){


        input.addEventListener(
            "input",
            function(){

                var index =
                    num(
                        input.getAttribute(
                            "data-index"
                        ),
                        -1
                    );


                if(
                    index < 0 ||
                    !materialAdjustmentFormState ||
                    !materialAdjustmentFormState.rows[index]
                ){
                    return;
                }


                var row =
                    materialAdjustmentFormState
                        .rows[index];


                var available =
                    Math.max(
                        0,
                        Number(
                            row.available_qty ||
                            0
                        )
                    );


                var entered =
                    Number(
                        input.value
                    );


                if(
                    !isFinite(
                        entered
                    )
                ){
                    return;
                }


                if(
                    entered >
                    available
                ){

                    entered =
                        available;


                    input.value =
                        String(
                            entered
                        );
                }


                if(
                    entered > 0
                ){

                    row.qty =
                        materialAdjustmentNormalizeQty(
                            entered,
                            row.qty ||
                            available ||
                            1,
                            available ||
                            undefined
                        );
                }
            }
        );


        input.addEventListener(
            "blur",
            function(){

                var index =
                    num(
                        input.getAttribute(
                            "data-index"
                        ),
                        -1
                    );


                if(
                    index < 0 ||
                    !materialAdjustmentFormState ||
                    !materialAdjustmentFormState.rows[index]
                ){
                    return;
                }


                var row =
                    materialAdjustmentFormState
                        .rows[index];


                var available =
                    Math.max(
                        0,
                        Number(
                            row.available_qty ||
                            0
                        )
                    );


                row.qty =
                    materialAdjustmentNormalizeQty(
                        input.value,
                        row.qty ||
                        available ||
                        1,
                        available ||
                        undefined
                    );


                input.value =
                    String(
                        row.qty
                    );
            }
        );
    });


    materialAdjustmentQueryAll(
        '#material-adjustment-stock-list ' +
        '[data-remove-material-adjustment-stock]'
    )
    .forEach(function(button){


        button.addEventListener(
            "click",
            function(){

                var index =
                    num(
                        button.getAttribute(
                            "data-remove-material-adjustment-stock"
                        ),
                        -1
                    );


                if(
                    !materialAdjustmentFormState ||
                    index < 0 ||
                    index >=
                        materialAdjustmentFormState.rows.length
                ){
                    return;
                }


                materialAdjustmentFormState
                    .rows
                    .splice(
                        index,
                        1
                    );


                materialAdjustmentRenderSelectedItems();
            }
        );
    });
}


