async function materialAdjustmentLoadSourceStock(
sourceWarehouse
){

sourceWarehouse=
String(
sourceWarehouse||
""
).trim();

if(
!materialAdjustmentFormState
){
materialAdjustmentResetState();
}

materialAdjustmentFormState
.rows=
[];

materialAdjustmentFormState
.load_error=
"";

if(!sourceWarehouse){
materialAdjustmentFormState
.loading_stock=
false;

materialAdjustmentRenderForm();

return[];
}

materialAdjustmentFormState
.loading_stock=
true;

materialAdjustmentRenderForm();

try{

var today=
(
window.frappe&&
frappe.datetime&&
typeof frappe.datetime.get_today===
"function"
)
?frappe.datetime.get_today()
:isoToday();

var company=
String(
materialAdjustmentFormState.company||
state.company||
COMPANY_FALLBACK||
""
).trim();

var reportData=
await window.LifeStockGateway.invoke(
"frappe.desk.query_report.run",
{
report_name:
"Stock Balance",

filters:{
company:company,
from_date:today,
to_date:today,
warehouse:[
sourceWarehouse
],
valuation_field_type:
"Currency",
ignore_closing_balance:0,
include_zero_stock_items:0,
show_variant_attributes:0,
show_stock_ageing_data:0,
show_dimension_wise_stock:0
},

ignore_prepared_report:1,
are_default_filters:0
}
);

var reportRows=
reportData&&
Array.isArray(
reportData.result
)
?reportData.result
:[];

var qtyByItem=
Object.create(null);

reportRows
.forEach(function(row){

if(
!row||
!row.item_code
){
return;
}

var warehouse=
String(
row.warehouse||
""
).trim();

if(
warehouse&&
warehouse.toLowerCase()!==
sourceWarehouse.toLowerCase()
){
return;
}

var quantity=
Number(
row.bal_qty
);

if(
!isFinite(quantity)||
quantity<=0
){
return;
}

var itemCode=
String(
row.item_code||
""
).trim();

if(!itemCode){
return;
}

if(
!qtyByItem[
itemCode
]
){
qtyByItem[
itemCode
]={
item_code:itemCode,
item_name:String(
row.item_name||
itemCode
),
item_group:String(
row.item_group||
""
),
stock_uom:String(
row.stock_uom||
row.uom||
"Nos"
),
available_qty:0
};
}

qtyByItem[
itemCode
].available_qty+=
quantity;
});

var itemCodes=
Object.keys(
qtyByItem
);

if(!itemCodes.length){
materialAdjustmentFormState
.rows=
[];

return[];
}

var itemMap=
await materialAdjustmentFetchSelectedItems(
itemCodes
);

var rows=[];

itemCodes
.forEach(function(itemCode){

var stock=
qtyByItem[
itemCode
];

var item=
itemMap[
itemCode
];

if(!item){
return;
}

var available=
Math.max(
0,
Number(
stock.available_qty||
0
)
);

if(
!isFinite(available)||
available<=0
){
return;
}

rows.push({
item_code:String(
item.item_code||
item.name||
itemCode
).trim(),

item_name:String(
item.item_name||
stock.item_name||
itemCode
),

item_group:String(
item.item_group||
stock.item_group||
"Item"
),

stock_uom:String(
item.stock_uom||
stock.stock_uom||
"Nos"
),

available_qty:
available,

qty:
materialAdjustmentNormalizeQty(
available,
available,
available
)
});
});

rows.sort(function(
left,
right
){

return String(
left.item_name||
left.item_code
)
.localeCompare(
String(
right.item_name||
right.item_code
),
undefined,
{
numeric:true,
sensitivity:"base"
}
);
});

materialAdjustmentFormState
.rows=
rows;

return rows;
}
catch(error){

materialAdjustmentFormState
.rows=
[];

materialAdjustmentFormState
.load_error=
String(
error&&error.message
?error.message
:error||
"Unable to load stock."
);

throw error;
}
finally{

materialAdjustmentFormState
.loading_stock=
false;

materialAdjustmentRenderForm();
}
}


async function materialAdjustmentValidateSourceStock(
sourceWarehouse,
rows
){

var itemCodes=
rows.map(function(row){
return row.item_code;
});

var stockRows=
await loadStockBalanceRows(
itemCodes
);

var sourceKey=
String(
sourceWarehouse||
""
)
.trim()
.toLowerCase();

var availability=
Object.create(null);

stockRows
.forEach(function(row){

if(
String(
row.warehouse||
""
)
.trim()
.toLowerCase()!==
sourceKey
){
return;
}

var code=
String(
row.item_code||
""
).trim();

if(!code){
return;
}

var usableQty=
Number(
row.available_qty!==undefined
?row.available_qty
:row.actual_qty
);

if(
!isFinite(usableQty)
){
usableQty=0;
}

availability[
code
]=
Object.prototype.hasOwnProperty.call(
availability,
code
)
?Math.max(
availability[
code
],
usableQty
)
:usableQty;
});

var shortages=[];

rows
.forEach(function(row){

var available=
Object.prototype.hasOwnProperty.call(
availability,
row.item_code
)
?Number(
availability[
row.item_code
]||
0
)
:0;

if(
Number(
row.qty
)>
available+
0.000001
){
shortages.push(
row.item_code+
": transfer "+
formatStockQty(
row.qty
)+
", usable "+
formatStockQty(
available
)
);
}
});

if(shortages.length){
throw new Error(
"Insufficient usable stock in "+
sourceWarehouse+
":\n"+
shortages.join(
"\n"
)
);
}
}


