function materialAdjustmentShowError(
    error
){

    var message =
        String(
            error &&
            error.message
                ? error.message
                : (
                    error ||
                    "Unable to submit Stock Adjustment."
                )
        );


    void 0;


    var errorBox =
        materialAdjustmentById(
            "material-adjustment-error"
        );


    if(errorBox){

        errorBox.style.display =
            "block";


        errorBox.innerHTML =
            "<strong>Unable to continue</strong><br>" +
            escapeHtml(
                message
            )
            .replace(
                /\n/g,
                "<br>"
            );


        var body =
            materialAdjustmentById(
                "life-stock-adjustment-modal-body"
            );


        if(
            body &&
            typeof body.scrollTo ===
                "function"
        ){

            body.scrollTo({
                top:0,
                behavior:"smooth"
            });
        }


        return;
    }


    /*
     * Last resort only.
     */
    if(
        window.frappe &&
        typeof frappe.msgprint ===
            "function"
    ){

        if(
            typeof window.__lifeRaiseFrappeOverlays ===
            "function"
        ){

            window.__lifeRaiseFrappeOverlays();
        }


        frappe.msgprint({
            title:
                "Stock Adjustment",

            indicator:
                "red",

            message:
                escapeHtml(
                    message
                )
                .replace(
                    /\n/g,
                    "<br>"
                )
        });


        if(
            typeof window.__lifeRaiseFrappeOverlays ===
            "function"
        ){

            setTimeout(
                window.__lifeRaiseFrappeOverlays,
                0
            );

            setTimeout(
                window.__lifeRaiseFrappeOverlays,
                100
            );
        }
    }
}


function materialAdjustmentSetSaving(
