function materialAdjustmentWireForm(){

    var sourceSelect =
        materialAdjustmentById(
            "material-adjustment-source"
        );


    var targetSelect =
        materialAdjustmentById(
            "material-adjustment-target"
        );


    /*
     * SOURCE CHANGE
     */
    if(sourceSelect){

        sourceSelect.addEventListener(
            "change",
            async function(){

                if(
                    !materialAdjustmentFormState
                ){
                    return;
                }


                /*
                 * Preserve remarks.
                 */
                var remarksField =
                    materialAdjustmentById(
                        "material-adjustment-remarks"
                    );


                materialAdjustmentFormState
                    .remarks =
                    String(
                        remarksField
                            ? remarksField.value
                            : (
                                materialAdjustmentFormState
                                    .remarks ||
                                ""
                            )
                    );


                /*
                 * New Source.
                 */
                materialAdjustmentFormState
                    .source_warehouse =
                    String(
                        sourceSelect.value ||
                        ""
                    ).trim();


                /*
                 * Do NOT automatically choose Target.
                 *
                 * Preserve selected Target if user already chose one.
                 */
                if(targetSelect){

                    materialAdjustmentFormState
                        .target_warehouse =
                        String(
                            targetSelect.value ||
                            ""
                        ).trim();
                }


                /*
                 * Clear old source Items.
                 */
                materialAdjustmentFormState
                    .rows =
                    [];


                materialAdjustmentFormState
                    .load_error =
                    "";


                if(
                    !materialAdjustmentFormState
                        .source_warehouse
                ){

                    materialAdjustmentRenderForm();

                    return;
                }


                try{

                    /*
                     * Items depend only on Source Warehouse.
                     * Target selection does not affect stock loading.
                     */
                    await materialAdjustmentLoadSourceStock(
                        materialAdjustmentFormState
                            .source_warehouse
                    );

                }
                catch(error){

                    materialAdjustmentShowError(
                        error
                    );
                }
            }
        );
    }


    /*
     * TARGET CHANGE
     */
    if(targetSelect){

        targetSelect.addEventListener(
            "change",
            function(){

                if(
                    !materialAdjustmentFormState
                ){
                    return;
                }


                materialAdjustmentFormState
                    .target_warehouse =
                    String(
                        targetSelect.value ||
                        ""
                    ).trim();


                /*
                 * Update Transfer Route and submit state.
                 * No need to reload source stock.
                 */
                materialAdjustmentCollectState();

                materialAdjustmentRenderForm();
            }
        );
    }


    /*
     * ITEM QTY + REMOVE
     */
    materialAdjustmentWireSelectedItems();
}


