    );
}

if(
!materialAdjustmentIsSubStore(
targetWarehouse
)
){
throw new Error(
"Target Warehouse must contain 'Sub'."
);
}

if(
sourceWarehouse===
targetWarehouse
){
throw new Error(
"Source Warehouse and Target Warehouse must be different."
);
}



if(!costCenter){
throw new Error(
"The ERP cost center default could not be resolved."
);
}

if(!remarks){
throw new Error(
"Reason / Remarks is mandatory."
);
}

if(!rows.length){
throw new Error(
"There are no Items selected for transfer."
);
}

var seen=
Object.create(null);

rows
.forEach(function(
row,
index
){

if(
!isFinite(
Number(
row.qty
)
)||
Number(
row.qty
)<=0
){
throw new Error(
"Enter a valid Transfer Qty greater than zero in item row "+
(index+1)+
"."
);
}

if(
Number(
row.qty
)>
Number(
row.available_qty
)+
0.000001
){
throw new Error(
row.item_code+
": Transfer Qty cannot exceed Available Qty "+
formatStockQty(
row.available_qty
)+
"."
);
}

if(
seen[
row.item_code
]
){
throw new Error(
"Item "+
row.item_code+
" appears more than once."
);
}

seen[
row.item_code
]=
true;
});

materialAdjustmentSetSaving(
true
);

var itemCodes=
rows.map(function(row){
return row.item_code;
});

var itemMap=
await materialAdjustmentFetchSelectedItems(
itemCodes
);

rows
.forEach(function(
row,
index
){

var item=
itemMap[
row.item_code
];

if(!item){
throw new Error(
"Item "+
row.item_code+
" is disabled, non-stock, belongs to Assets/Services, or is no longer available."
);
}

row.item_code=
String(
item.item_code||
item.name||
row.item_code
).trim();

row.stock_uom=
String(
item.stock_uom||
row.stock_uom||
"Nos"
);

row.item_name=
String(
item.item_name||
row.item_name||
row.item_code
);

if(!row.item_code){
throw new Error(
"A valid Item Code is required in row "+
(index+1)+
"."
);
}
});

/*
 * Recheck live stock immediately before Stock Entry submission.
 */
await materialAdjustmentValidateSourceStock(
sourceWarehouse,
rows
);

var stockEntryItems=
rows.map(function(row){

var stockUom=
String(
row.stock_uom||
"Nos"
);

return{
item_code:
row.item_code,

qty:
Number(
row.qty
),

uom:
stockUom,

stock_uom:
stockUom,

conversion_factor:
1,

cost_center:
costCenter,

s_warehouse:
sourceWarehouse,

t_warehouse:
targetWarehouse
};
});

var stockEntryDoc={
doctype:"Stock Entry",
docstatus:0,
naming_series:"MAT-STE-.YYYY.-",
stock_entry_type:type,
purpose:type,
company:company,
cost_center:costCenter,
from_warehouse:sourceWarehouse,
to_warehouse:targetWarehouse,
remarks:remarks,
items:stockEntryItems
};

/*
 * Keep the existing submission architecture.
 * No new API action is required.
 */
var submitted=
await call(
"frappe.client.submit",
{
doc:
stockEntryDoc
}
);

if(
!submitted||
!submitted.name||
num(
submitted.docstatus,
0
)!==1
){
throw new Error(
"ERPNext did not return a submitted Stock Entry."
);
}

materialAdjustmentCloseModal();

materialAdjustmentFormState=
null;

lifeShowApiSuccess(
"Material Adjustment Submitted",
"Stock Entry "+
submitted.name+
" transferred "+
rows.length+
" Item"+
(
rows.length===1
?""
:"s"
)+
" from "+
sourceWarehouse+
" to "+
targetWarehouse+
" successfully.",
"Stock Entry",
submitted.name
);

if(
typeof refreshAfterMaterialRequestChange===
"function"
){
try{
await refreshAfterMaterialRequestChange({
stockChanged:true,
refreshReceiptTracking:false,
delayedRefresh:false
});
}
catch(refreshError){
void 0;
}
}

try{
await renderBranchReceiving();
}
catch(receiptRefreshError){
void 0;
}

}
catch(error){

materialAdjustmentShowError(
error
);

}
finally{

materialAdjustmentSetSaving(
false
);

}
}


