function scheduleHOVisibleRequestTitleHydration(rows) {
    rows =
        Array.isArray(rows)
            ? rows
            : [];

    if (
        state.hoVisibleRequestTitleHydrationRunning
    ) {
        return;
    }

    /*
     * Hydrate whenever full Material Request data
     * has NOT been loaded yet.
     *
     * Do NOT depend on title being blank.
     * A lightweight list row can already contain
     * title while still having no item rows.
     */
    var rowsToHydrate =
        rows.filter(function (row) {
            return !!(
                row &&
                row.name &&
                !row._homeHydrated
            );
        });

    if (!rowsToHydrate.length) {
        return;
    }

    state.hoVisibleRequestTitleHydrationRunning =
        true;

    hydrateHomeRequestData(
        rowsToHydrate
    )
    .then(function () {

        state.hoVisibleRequestTitleHydrationRunning =
            false;

        /*
         * Repaint after items, qty and title
         * are populated.
         */
        if (
            state.currentPage ===
            "ho-approval"
        ) {
            renderHOApproval();
        }
    })
    .catch(function (error) {

        state.hoVisibleRequestTitleHydrationRunning =
            false;

        void 0;
    });
}

