function getHOCardKey(requestId,mode){
return String(mode||"pending")+"::"+String(requestId||"");
}
function shortHOText(value,maxLength){
var textValue=String(value||"").replace(/\s+/g," ").trim();
if(!textValue){
return"—";
}
var limit=Math.max(20,num(maxLength,120));
if(textValue.length<=limit){
return textValue;
}
return textValue.slice(0,limit-1).trim()+"…";
}
function toggleHOCardExpand(requestId,mode){
requestId=String(requestId||"");
mode=String(mode||"pending");
if(!state.hoCardExpanded){
state.hoCardExpanded={
}
;
}
var key=getHOCardKey(requestId,mode);
var expanded=!state.hoCardExpanded[key];
state.hoCardExpanded[key]=expanded;
var body=byId("ho-card-body-"+mode+"-"+requestId);
var button=byId("ho-card-toggle-"+mode+"-"+requestId);
var card=byId("ho-request-card-"+mode+"-"+requestId);
if(body){
body.style.display=expanded?"block":"none";
}
if(button){
button.innerHTML=expanded?"▾ Collapse":"▸ Expand";
button.setAttribute("aria-expanded",expanded?"true":"false");
}
if(card){
card.classList.toggle("is-expanded",expanded);
}
}

function hoRequestTypePillClass(request){
    var kind=
        branchRequestTypeKind(
            request
