async function hoCompletedResolveRemoteSessionAudit(
rows
){
rows=
Array.isArray(
rows
)
?rows
:[];

/*
 * Appointment / Session caches are scoped to the current page.
 * No hidden page is pre-hydrated.
 */
ssrFallbackSessionCache=
Object.create(null);

ssrHistoricalAppointmentCache=
Object.create(null);

ssrHistoricalTherapyPlanCache=
Object.create(null);

/*
 * A page starts with an empty session-batch queue. The individual
 * loadSSRAppointmentExecution calls below are still parallel, but
 * their Therapy Session queries are coalesced automatically.
 */
if(ssrSessionLookupBatchTimer){

window.clearTimeout(
ssrSessionLookupBatchTimer
);

ssrSessionLookupBatchTimer=null;
}

ssrSessionLookupBatchQueue=[];

for(
var start=0;
start<rows.length;
start+=6
){

var batch=
rows.slice(
start,
start+6
);

await Promise.all(
batch.map(
async function(row){

if(
!lifeIsClientLinkedMaterialRequest(
row.request
)||
!hoCompletedRequestIsSpecial(
row.request
)
){
return;
}

try{

row.execution=
await loadSSRAppointmentExecution(
row.request,
{
sentDate:
row.sentDate,

receiptDate:
row.receiptDate
}
);

}
catch(error){

void 0;

row.execution={
linked:false,
status_key:"not_linked",
status_label:
"Appointment Not Linked",
appointment:null,
session:null,
error:error,
match_type:"none",
match_basis:
"Session lookup failed",
sent_date:
row.sentDate,
receipt_date:
row.receiptDate
};

}

}
)
);

}

return rows;
}

async function loadHOCompletedRemotePage(
page
){
page=
Math.max(
1,
num(
page,
1
)
);

/*
 * Going back to a page already opened is instant.
 */
if(
hoCompletedRemotePages[
page
]
){
return hoCompletedRemotePages[
page
];
}

if(
!hoCompletedRemoteNextInput[
page
]
){
if(page===1){
hoCompletedRemoteNextInput[1]={
offset:0,
carry:[]
};
}
else{
/*
 * Direct jumping is not exposed in the pager, but if another code
 * path asks for Page N, build only the preceding page needed to
 * obtain its cursor.
 */
await loadHOCompletedRemotePage(
page-1
);
}
}

var input=
hoCompletedRemoteInputClone(
hoCompletedRemoteNextInput[
page
]
);

var offset=
input.offset;

var candidates=
input.carry.slice();

var targetCount=
Math.max(
1,
num(
hoCompletedTrackingPageSize,
10
)
)+1;

var reachedBackendEnd=false;

/*
 * Read small backend chunks only until we have:
 *
 *   10 visible requests + 1 look-ahead request
 *
 * The one look-ahead record is enough to know whether Next should
 * remain enabled.
 */
while(
candidates.length<
targetCount&&
!reachedBackendEnd
){

var headers=
await hoCompletedFetchSentHeaderChunk(
offset,
HO_COMPLETED_REMOTE_SCAN_SIZE
);

headers=
Array.isArray(
headers
)
?headers
:[];

offset+=
headers.length;

if(
headers.length<
HO_COMPLETED_REMOTE_SCAN_SIZE
){
reachedBackendEnd=true;
}

if(!headers.length){
break;
}

var sentHeaders=
headers.filter(
hoCompletedSentStockEntry
);

if(!sentHeaders.length){
continue;
}

/*
 * Child items identify the linked Material Request, so only the
 * Stock Entries from THIS small backend chunk are fully loaded.
 */
var stockEntries=
await hoCompletedLoadDocuments(
STOCK_ENTRY_DOCTYPE,
sentHeaders.map(function(row){
return row.name;
}),
6
);

stockEntries=
stockEntries.filter(
hoCompletedSentStockEntry
);

var chunkCandidates=
await hoCompletedCandidatesFromStockEntries(
stockEntries
);

chunkCandidates.forEach(function(candidate){

var key=
hoCompletedRemoteCandidateKey(
candidate
);

if(
!key||
hoCompletedRemoteSeenRequestIds[
key
]
){
return;
}

hoCompletedRemoteSeenRequestIds[
key
]=true;

candidates.push(
candidate
);

});

}

var pageCandidates=
candidates.slice(
0,
hoCompletedTrackingPageSize
);

var carry=
candidates.slice(
hoCompletedTrackingPageSize
);

var hasNext=
carry.length>0||
!reachedBackendEnd;

/*
 * Combine split Stock Entries only for the request IDs that will
 * actually be rendered on this page.
 */
pageCandidates=
await hoCompletedLoadAllSentEntriesForRequests(
pageCandidates
);

var rows=
pageCandidates
.map(function(candidate){

return hoCompletedBuildRemoteAuditRow(
candidate.request,
candidate.requestId,
candidate.stockEntries
);

})
.filter(Boolean)
.sort(function(left,right){

return String(
right.lastSentDate||
right.sentDate||
""
).localeCompare(
String(
left.lastSentDate||
left.sentDate||
""
)
);

});

/*
 * EXPENSIVE WORK IS PAGE-SCOPED:
 * Patient Appointment and Therapy Session resolution runs only for
 * the visible rows here.
 */
await hoCompletedResolveRemoteSessionAudit(
rows
);

var result={
page:page,
rows:rows,
hasPrevious:
page>1,
hasNext:
hasNext,
backendOffset:
offset,
carryCount:
carry.length
};

reconcileHOCompletedTrackingTotalFromPage(
result
);

hoCompletedRemotePages[
page
]=result;

if(hasNext){
hoCompletedRemoteNextInput[
page+1
]={
offset:offset,
carry:carry
};
}

return result;
}

