function hoReceiptTrackingState(stockEntry){
var docstatus=num(stockEntry&&stockEntry.docstatus,0);
if(docstatus===1){
return{
key:"received",label:"Received / Submitted",cssClass:"p-green"}
;
}
return{
key:"pending",label:"Awaiting Branch Update",cssClass:"p-or"}
;
}
function hoReceiptTrackingRelevant(stockEntry){
if(!stockEntry||!stockEntry.name){
return false;
}
var purpose=String(stockEntry.purpose||stockEntry.stock_entry_type||"").trim();
if(purpose!=="Material Transfer"){
return false;
}
var docstatus=num(stockEntry.docstatus,0);
var workflowState=String(stockEntry.workflow_state||"").toLowerCase();
if(docstatus===0){
return workflowState.indexOf("pending receipt")>=0;
}
if(docstatus===1){
return!!(stockEntry.custom_received_by||stockEntry.custom_received_date);
}
return false;
}
async function loadHOReceiptTrackingRows() {

    if (
        !window.LifeStockGateway ||
        typeof window.LifeStockGateway.action !== "function"
    ) {
        throw new Error(
            "LIFE Stock API gateway is unavailable."
        );
    }

    var result =
        await window.LifeStockGateway.action(
            "list_ho_receipt_updates",
            {}
        );

    var rows =
        result &&
        Array.isArray(result.rows)
            ? result.rows
            : [];

    /*
     * Keep only records that belong in
     * Branch Stock Receipt Updates:
     *
     * 1. Draft + Pending Receipt
     * 2. Submitted + branch receipt completed
     */
    rows = rows.filter(
        hoReceiptTrackingRelevant
    );

    /*
     * Resolve Released By / employee display names.
     */
    await hydrateStockEntryDisplayNames(
        rows
    );

    var receivedIdentifiers =
        uniqueValues(
            rows.map(function (row) {
                return String(
                    row.custom_received_by || ""
                ).trim();
            })
        );

    var receivedNameMap =
        await resolvePersonDisplayNames(
            receivedIdentifiers
        );

    rows.forEach(function (row) {

        var receivedIdentifier =
            String(
                row.custom_received_by || ""
            ).trim();

        row._received_by_name =
            receivedIdentifier
                ? (
                    receivedNameMap[
                        receivedIdentifier
                    ] ||
                    receivedIdentifier
                )
                : "—";
    });

    /*
     * Pending receipts first.
     * Within each group show newest first.
     */
    return rows.sort(
        function (left, right) {

            var leftState =
                hoReceiptTrackingState(
                    left
                );

            var rightState =
                hoReceiptTrackingState(
                    right
                );

            if (
                leftState.key !==
                rightState.key
            ) {
                return leftState.key === "pending"
                    ? -1
                    : 1;
            }

            return String(
                right.custom_received_date ||
                right.modified ||
                right.creation ||
                ""
            ).localeCompare(
                String(
                    left.custom_received_date ||
                    left.modified ||
                    left.creation ||
                    ""
                )
            );
        }
    );
}
