hoRejectRequest = async function (id) {
    var requestId =
        String(
            id || ""
        ).trim();

    if (!requestId) {
        toast(
            "Material Request ID is missing.",
            "r"
        );
        return;
    }

    var remarksElement =
        byId(
            "ho-review-remark-" +
            requestId
        ) ||
        byId(
            "ho-remark-" +
            requestId
        );

    var remarks =
        remarksElement
            ? String(
                remarksElement.value || ""
            ).trim()
            : "";

    if (!remarks) {
        toast(
            "Enter Store Manager Remarks before rejecting.",
            "r"
        );
        return;
    }

    try {
        setBusy(
            true,
            "Rejecting request…"
        );

        /*
         * Reject on server first.
         */
        var result =
            await lifeRequireAPI()
                .rejectRequest({
                    request_name:
                        requestId,

                    remarks:
                        remarks
                });

        /*
         * ==================================================
         * IMMEDIATELY LOCK THIS REQUEST AS REJECTED
         * ==================================================
         *
         * Delayed Pending API responses must never be able
         * to put this request back into Pending.
         */
        lifeMarkRequestLocallyRejected(
            requestId
        );

        var rejectedRow = null;

        if (
            result &&
            result.request &&
            typeof result.request ===
                "object"
        ) {
            rejectedRow =
                result.request;
        }

        /*
         * Update existing local row.
         */
        var foundExisting = false;

        state.requests =
            (
                Array.isArray(
                    state.requests
                )
                    ? state.requests
                    : []
            ).map(function (row) {

                var rowId =
                    String(
                        row &&
                        (
                            row.name ||
                            row.id
                        ) ||
                        ""
                    ).trim();

                if (
                    rowId !==
                    requestId
                ) {
                    return row;
                }

                foundExisting = true;

                return lifeForceRejectedRequestRow(
                    Object.assign(
                        {},
                        row,
                        rejectedRow || {},
                        {
                            workflow_state:
                                "Rejected",

                            custom_stock_request_status:
                                "Rejected",

                            status:
                                "Rejected",

                            transfer_status:
                                ""
                        }
                    )
                );
            });

        /*
         * If the request was not in state.requests but the
         * server returned it, insert it as Rejected.
         */
        if (
            !foundExisting &&
            rejectedRow
        ) {
            state.requests.unshift(
                lifeForceRejectedRequestRow(
                    Object.assign(
                        {},
                        rejectedRow,
                        {
                            workflow_state:
                                "Rejected",

                            custom_stock_request_status:
                                "Rejected",

                            status:
                                "Rejected",

                            transfer_status:
                                ""
                        }
                    )
                )
            );
        }

        /*
         * Ensure no duplicates remain.
         */
        state.requests =
            lifeMergeUniqueMaterialRequestRows([
                state.requests
            ]);

        state.hoPendingPage = 1;

        /*
         * Close modal.
         */
        closeModal();

        /*
         * Immediate UI update.
         */
        if (
            state.currentPage ===
            "ho-approval"
        ) {
            renderHOApproval();
        }

        toast(
            (
                result &&
                result.message
            )
                ? result.message
                : (
                    "Request " +
                    requestId +
                    " rejected."
                ),
            "r"
        );

        /*
         * ==================================================
         * REFRESH FROM SERVER
         * ==================================================
         */
        try {
            await loadRequests();

            /*
             * Re-apply lock after every async loader has
             * completed/started.
             */
            state.requests =
                lifeProtectLocallyRejectedRows(
                    state.requests
                );

            if (
                state.currentPage ===
                "ho-approval"
            ) {
                renderHOApproval();
            }
        }
        catch (refreshError) {
            void 0;

            /*
             * Rejection succeeded already, so keep local UI
             * correct even when refresh fails.
             */
            state.requests =
                lifeProtectLocallyRejectedRows(
                    state.requests
                );

            if (
                state.currentPage ===
                "ho-approval"
            ) {
                renderHOApproval();
            }
        }
    }
    catch (error) {
        showError(error);
    }
    finally {
        setBusy(false);
    }
};

