/* =====================================================================
   LIFE STOCK RECEIPT ADJUSTMENT WORKFLOW
   - Branch enters usable, missing and damaged quantities per item.
   - Clean receipts use the existing immediate receipt API.
   - Discrepancies create/update LIFE Stock Receipt Adjustment Request.
   - Stock Manager reviews every state in a separate filtered list.
   - Approval submits the full original transfer and then posts one reverse
     Material Transfer for Missing + Damaged back to the source warehouse.
   ===================================================================== */
(function installLifeReceiptAdjustmentWorkflow(){
"use strict";

if(window.__lifeReceiptAdjustmentWorkflowInstalled){
return;
}
window.__lifeReceiptAdjustmentWorkflowInstalled=true;

var LIFE_RA_DOCTYPE="LIFE Stock Receipt Adjustment Request";
var LIFE_RA_ITEM_DOCTYPE="LIFE Stock Receipt Adjustment Item";
var LIFE_RA_PENDING="Pending Stock Manager Approval";
var LIFE_RA_CORRECTION="Correction Requested";
var LIFE_RA_APPROVED="Approved";
var LIFE_RA_REJECTED="Rejected";
var LIFE_RA_COMPLETED="Adjustment Completed";
var LIFE_RA_TOLERANCE=0.0001;

/*
 * Manager-role cache scoped to this receipt-adjustment module.
 * Do not depend on loadLoggedInUserRoles() or loggedInUserHasRole(),
 * because those helpers belong to another private IIFE on this page.
 */
var lifeRAManagerRoles=[];
var lifeRAManagerRolesLoaded=false;
var lifeRAManagerRolesPromise=null;

function lifeRANormalizeRole(value){
return String(value||"").trim().toLowerCase();
}

function lifeRAAppendRole(target,value){
var role=String(
value&&typeof value==="object"
?(value.role||value.role_name||value.name||"")
:(value||"")
).trim();
if(!role){return;}
var normalized=lifeRANormalizeRole(role);
var exists=target.some(function(existing){
return lifeRANormalizeRole(existing)===normalized;
});
if(!exists){target.push(role);}
}

function lifeRACollectClientRoles(){
var roles=[];
try{
if(window.frappe&&Array.isArray(frappe.user_roles)){
frappe.user_roles.forEach(function(role){lifeRAAppendRole(roles,role);});
}
}catch(ignoreUserRoles){}
try{
if(window.frappe&&frappe.boot&&frappe.boot.user&&Array.isArray(frappe.boot.user.roles)){
frappe.boot.user.roles.forEach(function(role){lifeRAAppendRole(roles,role);});
}
}catch(ignoreBootRoles){}
try{
if(Array.isArray(window.user_roles)){
window.user_roles.forEach(function(role){lifeRAAppendRole(roles,role);});
}
}catch(ignoreWindowRoles){}
return roles;
}

async function lifeRALoadManagerRoles(force){
if(!force&&lifeRAManagerRolesLoaded){
return lifeRAManagerRoles.slice();
}
if(!force&&lifeRAManagerRolesPromise){
return lifeRAManagerRolesPromise;
}
lifeRAManagerRolesPromise=(async function(){
var roles=lifeRACollectClientRoles();
var sessionUser=String(
window.frappe&&frappe.session&&frappe.session.user
?frappe.session.user
:""
).trim();
if(sessionUser.toLowerCase()==="administrator"){
lifeRAAppendRole(roles,"System Manager");
}
try{
var context=await lifeRequireAPI().getContext();
var contextRoles=context&&Array.isArray(context.roles)?context.roles:[];
contextRoles.forEach(function(role){lifeRAAppendRole(roles,role);});
}catch(contextError){
void 0;
try{
if(sessionUser){
var userDoc=await getDoc("User",sessionUser);
var userRoles=userDoc&&Array.isArray(userDoc.roles)?userDoc.roles:[];
userRoles.forEach(function(role){lifeRAAppendRole(roles,role);});
}
}catch(userRoleError){
void 0;
}
}
lifeRAManagerRoles=roles.slice();
lifeRAManagerRolesLoaded=true;
lifeRAManagerRolesPromise=null;
return lifeRAManagerRoles.slice();
})();
return lifeRAManagerRolesPromise;
}

function lifeRAHasCachedRole(roleName){
var required=lifeRANormalizeRole(roleName);
if(!required){return false;}
var roles=lifeRAManagerRolesLoaded
?lifeRAManagerRoles
:lifeRACollectClientRoles();
return roles.some(function(role){
return lifeRANormalizeRole(role)===required;
});
}

var lifeRAOriginalLoadPendingReceiptStockEntries=loadPendingReceiptStockEntries;
var lifeRAOriginalStockEntryReceiptDisplayState=stockEntryReceiptDisplayState;
var lifeRAOriginalCanApproveStockEntryReceipt=canApproveStockEntryReceipt;
var lifeRAOriginalRefreshAllHOManagerTables=refreshAllHOManagerTables;
var lifeRAOriginalLoadHOReceiptTrackingRows=loadHOReceiptTrackingRows;
var lifeRAOriginalHOReceiptTrackingState=hoReceiptTrackingState;

var lifeRAListState={
rows:[],
loaded:false,
loading:false,
page:1,
pageSize:10,
search:"",
status:"",
branch:"",
sourceWarehouse:"",
reportedBy:""
};

function lifeRANumber(value,fallback){
var parsed=Number(value);
return isFinite(parsed)?parsed:Number(fallback||0);
}

function lifeRAAlmostEqual(left,right){
return Math.abs(lifeRANumber(left,0)-lifeRANumber(right,0))<=LIFE_RA_TOLERANCE;
}

function lifeRAUser(){
return String(frappe&&frappe.session&&frappe.session.user||state.currentUser||"").trim();
}

function lifeRAHasManagerAccess(){
var sessionUser=String(
window.frappe&&frappe.session&&frappe.session.user
?frappe.session.user
:(state.currentUser||"")
).trim().toLowerCase();

if(sessionUser==="administrator"){
return true;
}

return!!(
lifeRAHasCachedRole("System Manager")||
lifeRAHasCachedRole("Stock Manager")||
(typeof stockReceiptOverrideAllowed==="function"&&stockReceiptOverrideAllowed())
);
}

async function lifeRASetFields(doctype,name,values){
var keys=Object.keys(values||{});
for(var index=0;index<keys.length;index+=1){
var fieldname=keys[index];
await setValue(doctype,name,fieldname,values[fieldname]);
}
}

