function lifeRAStatusLabel(status){
var value=String(status||"Draft").trim();
return value||"Draft";
}

function lifeRAStatusClass(status){
var value=lifeRAStatusLabel(status).toLowerCase();
if(value.indexOf("completed")>=0){return"p-green";}
if(value.indexOf("approved")>=0){return"p-blue";}
if(value.indexOf("correction")>=0){return"p-gold";}
if(value.indexOf("rejected")>=0){return"p-red";}
if(value.indexOf("pending")>=0){return"p-or";}
return"p-gy";
}

function lifeRARequestEditable(adjustment){
if(!adjustment||!adjustment.name){
return true;
}
return lifeRAStatusLabel(adjustment.status)===LIFE_RA_CORRECTION;
}

loadPendingReceiptStockEntries=async function(){
var rows=await lifeRAOriginalLoadPendingReceiptStockEntries();
rows=Array.isArray(rows)?rows:[];
var names=rows.map(function(row){return String(row&&row.name||"").trim();}).filter(Boolean);
if(!names.length){
return rows;
}
try{
var adjustments=await getList(
LIFE_RA_DOCTYPE,
["name","status","stock_entry","reported_by","reported_by_name","reported_on","stock_manager_remarks","modified"],
[["stock_entry","in",names]],
{order_by:"modified desc",limit_page_length:500}
);
var adjustmentByStockEntry=Object.create(null);
(adjustments||[]).forEach(function(adjustment){
var key=String(adjustment.stock_entry||"").trim();
if(key&&!adjustmentByStockEntry[key]){
adjustmentByStockEntry[key]=adjustment;
}
});
rows.forEach(function(row){
row._receipt_adjustment_summary=adjustmentByStockEntry[String(row.name||"").trim()]||null;
});
return rows.filter(function(row){
var adjustment=row._receipt_adjustment_summary;
var status=lifeRAStatusLabel(adjustment&&adjustment.status);
return status!==LIFE_RA_COMPLETED&&status!==LIFE_RA_APPROVED;
});
}
catch(error){
void 0;
return rows;
}
};

stockEntryReceiptDisplayState=function(stockEntry){
var adjustment=stockEntry&&(stockEntry._receipt_adjustment||stockEntry._receipt_adjustment_summary);
if(adjustment&&adjustment.status){
return lifeRAStatusLabel(adjustment.status);
}
return lifeRAOriginalStockEntryReceiptDisplayState(stockEntry);
};

canApproveStockEntryReceipt=function(stockEntry){
if(!lifeRAOriginalCanApproveStockEntryReceipt(stockEntry)){
return false;
}
var adjustment=stockEntry&&(stockEntry._receipt_adjustment||stockEntry._receipt_adjustment_summary);
return lifeRARequestEditable(adjustment);
};

function lifeRAItemAdjustmentMap(adjustment){
var map=Object.create(null);
var itemMap=Object.create(null);
var rows=adjustment&&Array.isArray(adjustment.adjustment_items)?adjustment.adjustment_items:[];
rows.forEach(function(row){
var detail=String(row.stock_entry_detail||"").trim();
var itemCode=String(row.item_code||"").trim();
if(detail){map[detail]=row;}
if(itemCode&&!itemMap[itemCode]){itemMap[itemCode]=row;}
});
return{byDetail:map,byItem:itemMap};
}

function lifeRAResolveItemAdjustment(item,adjustmentMap){
var detail=String(item&&item.name||"").trim();
var itemCode=String(item&&item.item_code||"").trim();
return adjustmentMap.byDetail[detail]||adjustmentMap.byItem[itemCode]||null;
}

function lifeRAExistingQty(item,adjustmentRow,fieldname,fallback){
if(adjustmentRow&&adjustmentRow[fieldname]!==undefined&&adjustmentRow[fieldname]!==null&&String(adjustmentRow[fieldname]).trim()!==""){
return lifeRANumber(adjustmentRow[fieldname],fallback);
}
var customField="custom_"+fieldname;
if(item&&item[customField]!==undefined&&item[customField]!==null&&String(item[customField]).trim()!==""){
return lifeRANumber(item[customField],fallback);
}
return fallback;
}

