function lifeRAReadRowNumber(row,kind){
var input=row.querySelector('[data-life-ra-kind="'+kind+'"]');
var raw=String(input&&input.value||"").trim();
return raw===""?null:Number(raw);
}

function lifeRAUpdateBranchTotals(card){
if(!card){return;}
var totals={released:0,received:0,missing:0,damaged:0};
Array.prototype.forEach.call(card.querySelectorAll(".branch-receipt-item-row"),function(row){
totals.released+=lifeRANumber(row.getAttribute("data-released-qty"),0);
["received","missing","damaged"].forEach(function(kind){
var value=lifeRAReadRowNumber(row,kind);
if(value!==null&&isFinite(value)){totals[kind]+=Math.max(0,value);}
});
});
var returnQty=totals.missing+totals.damaged;
var wrap=card.querySelector("[data-life-ra-totals]");
if(wrap){
wrap.innerHTML='<div><span>Released</span><strong>'+escapeHtml(formatStockQty(totals.released))+'</strong></div><div><span>Received / Usable</span><strong>'+escapeHtml(formatStockQty(totals.received))+'</strong></div><div><span>Missing</span><strong>'+escapeHtml(formatStockQty(totals.missing))+'</strong></div><div><span>Damaged</span><strong>'+escapeHtml(formatStockQty(totals.damaged))+'</strong></div><div><span>Return to Source</span><strong>'+escapeHtml(formatStockQty(returnQty))+'</strong></div>';
}
}

