var damaged=lifeRAReadRowNumber(row,"damaged");
var returnNode=row.querySelector("[data-life-ra-return]");
var statusNode=row.querySelector("[data-life-ra-row-status]");
var returnQty=Math.max(0,lifeRANumber(missing,0))+Math.max(0,lifeRANumber(damaged,0));
if(returnNode){returnNode.textContent=formatStockQty(returnQty);}
var complete=received!==null&&missing!==null&&damaged!==null&&[received,missing,damaged].every(function(value){return isFinite(value)&&value>=0;});
var accounted=lifeRANumber(received,0)+lifeRANumber(missing,0)+lifeRANumber(damaged,0);
var label="Needs entry";
var css="p-gy";
if(complete&&lifeRAAlmostEqual(accounted,released)){
if(returnQty>0){label="Discrepancy";css="p-gold";}else{label="Fully received";css="p-green";}
}else if(complete){label="Not balanced";css="p-red";}
if(statusNode){statusNode.className="pill "+css;statusNode.textContent=label;}
lifeRAUpdateBranchTotals(row.closest(".life-ra-branch-form"));
}

