collectBranchReceiptPayload=function(stockEntryName){
var card=byId("branch-receive-card-"+stockEntryName);
if(!card){throw new Error("The receipt form is unavailable. Refresh and try again.");}
var selectedEmployee=branchReceiptSelectedEmployee;
var selectedEmployeeId=String((byId("branch-receipt-employee-id")||{}).value||"").trim();
if(!selectedEmployee||!selectedEmployee.name||!selectedEmployeeId||selectedEmployee.name!==selectedEmployeeId){
throw new Error("Search and select the active employee who received the stock.");
}
if(String(selectedEmployee.status||"").toLowerCase()!=="active"){
throw new Error("Only an active employee can be selected as Received By.");
}
if(!branchReceiptReceivingBranch){
throw new Error("The receiving branch could not be resolved. Refresh the page and open the receipt again.");
}
if(!branchReceiptEmployeeMatchesReceivingBranch(selectedEmployee)){
throw new Error(
"Selected employee belongs to "+
String(selectedEmployee.branch||"another branch")+
". Please select an active employee from "+
String(branchReceiptReceivingBranch)+
"."
);
}
var rows=Array.prototype.slice.call(card.querySelectorAll(".branch-receipt-item-row"));
if(!rows.length){throw new Error("No Stock Entry Detail rows were found.");}
var hasDiscrepancy=false;
var items=rows.map(function(row){
var released=Math.max(0,lifeRANumber(row.getAttribute("data-released-qty"),0));
var received=lifeRAReadRowNumber(row,"received");
var missing=lifeRAReadRowNumber(row,"missing");
var damaged=lifeRAReadRowNumber(row,"damaged");
var itemCode=String((row.querySelector("[data-life-ra-item-code]")||{}).value||"Material");
var itemName=String((row.querySelector("[data-life-ra-item-name]")||{}).value||itemCode);
var rowName=String((row.querySelector("[data-life-ra-row-name]")||{}).value||"");
var remarks=String((row.querySelector(".branch-receipt-row-remarks")||{}).value||"").trim();
if(received===null){throw new Error("Enter Received / Usable Qty for "+itemCode+".");}
if(missing===null){missing=0;}
if(damaged===null){damaged=0;}
if(![received,missing,damaged].every(function(value){return isFinite(value)&&value>=0;})){
throw new Error("All quantities for "+itemCode+" must be zero or greater.");
}
var accounted=received+missing+damaged;
if(!lifeRAAlmostEqual(accounted,released)){
throw new Error("For "+itemCode+", Received + Missing + Damaged must equal Released Qty "+formatStockQty(released)+". Current total: "+formatStockQty(accounted)+".");
}
var discrepancy=missing>0||damaged>0;
if(discrepancy&&!remarks){throw new Error("Enter row remarks for the missing or damaged quantity of "+itemCode+".");}
hasDiscrepancy=hasDiscrepancy||discrepancy;
return{row_name:rowName,item_code:itemCode,item_name:itemName,released_qty:released,received_qty:received,missing_qty:missing,damaged_qty:damaged,return_to_source_qty:missing+damaged,discrepancy_remarks:remarks};
});
var remarksElement=byId("branch-receipt-remarks-"+stockEntryName);
return{
stock_entry:stockEntryName,
received_by:selectedEmployee.name,
received_by_name:selectedEmployee.employee_name||selectedEmployee.name,
received_date:nowDateTime(),
receipt_remarks:String(remarksElement&&remarksElement.value||"").trim(),
existing_adjustment_request:String(card.getAttribute("data-adjustment-request")||""),
existing_adjustment_status:String(card.getAttribute("data-adjustment-status")||""),
has_discrepancy:hasDiscrepancy,
items:items
};
};

buildBranchReceiptConfirmation=function(payload){
payload=payload||{};
var items=Array.isArray(payload.items)?payload.items:[];
var totals={released:0,received:0,missing:0,damaged:0};
var rows=items.map(function(item){
["released","received","missing","damaged"].forEach(function(key){
totals[key]+=lifeRANumber(item[key+"_qty"],0);
});
return '<tr><td>'+escapeHtml(item.item_name||item.item_code||"Material")+'</td><td class="life-ra-number-cell">'+escapeHtml(formatStockQty(item.released_qty))+'</td><td class="life-ra-number-cell">'+escapeHtml(formatStockQty(item.received_qty))+'</td><td class="life-ra-number-cell">'+escapeHtml(formatStockQty(item.missing_qty))+'</td><td class="life-ra-number-cell">'+escapeHtml(formatStockQty(item.damaged_qty))+'</td><td class="life-ra-number-cell">'+escapeHtml(formatStockQty(item.return_to_source_qty))+'</td></tr>';
}).join("");
var discrepancy=!!payload.has_discrepancy;
var heading=discrepancy?"Create Stock Receipt Adjustment Request":"Confirm Full Usable Receipt";
var explanation=discrepancy
?"The original Stock Entry will remain Draft until approval. On approval, ERPNext submits the full original transfer and then creates one reverse Material Transfer for Missing + Damaged back to the source warehouse."
:"No missing or damaged quantity was reported. The existing receipt process will submit the Stock Entry immediately.";
var html='<div class="branch-receipt-confirmation life-ra-confirmation"><div class="notice '+(discrepancy?'notice-orange':'notice-green')+'"><strong>'+escapeHtml(heading)+'</strong><br>'+escapeHtml(explanation)+'</div><div class="branch-receipt-confirm-table-wrap"><table class="branch-receipt-confirm-table"><thead><tr><th>Material</th><th>Released</th><th>Received</th><th>Missing</th><th>Damaged</th><th>Return</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="life-ra-confirm-total">Released '+escapeHtml(formatStockQty(totals.released))+' · Received '+escapeHtml(formatStockQty(totals.received))+' · Return to Source '+escapeHtml(formatStockQty(totals.missing+totals.damaged))+'</div><div class="branch-receipt-confirm-person"><strong>Received By:</strong> '+escapeHtml(payload.received_by_name||payload.received_by||"—")+'</div></div>';
return{html:html,plainText:heading+"? "+explanation};
};

async function lifeRACreateOrUpdateRequest(payload){
var result=await lifeRequireAPI().call("submit_receipt_adjustment",payload||{});
var request=result&&result.adjustment_request;
if(!request||!request.name){
throw new Error("ERPNext did not return the receipt adjustment request ID.");
}
return request;
}

applyBranchReceipt=async function(payload){
try{
if(payload.has_discrepancy){
setBusy(true,"Creating Stock Receipt Adjustment Request…");
var adjustment=await lifeRACreateOrUpdateRequest(payload);
lifeStockIssueInvalidate();
closeModal();
await refreshAfterMaterialRequestChange({stockChanged:false,refreshReceiptTracking:true,delayedRefresh:false});
await lifeStockIssueRefreshCards(true);
lifeShowApiSuccess("Adjustment Request Submitted","Adjustment request "+adjustment.name+" is pending Stock Manager approval. No original or reverse warehouse movement has been posted.",LIFE_RA_DOCTYPE,adjustment.name);
}else{
setBusy(true,"Saving receipt quantities and submitting Stock Entry…");
var result=await lifeRequireAPI().confirmBranchReceipt(payload);
await refreshAfterMaterialRequestChange({stockChanged:true,refreshReceiptTracking:true,delayedRefresh:false});
lifeShowApiSuccess("Receipt Approved",result.message,"Stock Entry",result.stock_entry&&result.stock_entry.name);
}
}
catch(error){showError(error);}
finally{setBusy(false);}
};

confirmBranchReceipt=async function(stockEntryName){
try{
var payload=collectBranchReceiptPayload(stockEntryName);
var confirmation=buildBranchReceiptConfirmation(payload);
if(window.frappe&&typeof frappe.confirm==="function"){
raiseActiveFrappeConfirmation();
frappe.confirm(confirmation.html,function(){
cleanupLifeConfirmationLayer();
Promise.resolve(applyBranchReceipt(payload)).catch(showError);
},function(){cleanupLifeConfirmationLayer();});
raiseActiveFrappeConfirmation();
window.setTimeout(raiseActiveFrappeConfirmation,50);
window.setTimeout(raiseActiveFrappeConfirmation,150);
return;
}
if(window.confirm(confirmation.plainText)){await applyBranchReceipt(payload);}
}
catch(error){cleanupLifeConfirmationLayer();showError(error);}
};

