return lifeTableNormalize([row.name,row.stock_entry,row.material_request,row.target_branch,row.source_warehouse,row.target_warehouse,reporter,row.status,row.stock_manager_remarks,row.submitted_stock_entry].join(" ")).indexOf(query)>=0;
