/* =====================================================================
   DAMAGED + MISSING STOCK — SHARED DASHBOARD COUNTS AND REGISTER MODALS

   Both dashboard cards use the exact same parent data source as the
   working Requests & Approvals list. Counts are calculated client-side
   from parent totals. Item details are loaded from readable parent
   documents only when a register modal is opened.
   ===================================================================== */

var LIFE_STOCK_ISSUE_PARENT_FIELDS=[
"name","creation","modified","status","stock_entry","material_request",
"source_warehouse","target_warehouse","target_branch",
"reported_by","reported_by_name","reported_on",
"total_released_qty","total_received_qty","total_missing_qty",
"total_damaged_qty","total_return_to_source_qty",
"stock_manager_remarks","approved_by","approved_on",
"submitted_stock_entry"
];

var LIFE_STOCK_ISSUE_CACHE={
parents:[],
parentsLoaded:false,
parentsPromise:null,
cardsPromise:null,
cardRefreshSequence:0,
damagedRows:[],
damagedLoaded:false,
damagedPromise:null,
missingRows:[],
missingLoaded:false,
missingPromise:null,
opening:""
};

var LIFE_STOCK_ISSUE_FILTERS={
damaged:{search:"",status:"",location:"",source:""},
missing:{search:"",status:"",location:"",source:""}
};

function lifeStockIssueKind(kind){
return String(kind||"").toLowerCase()==="missing"?"missing":"damaged";
}

function lifeStockIssueIsActiveStatus(status){
var normalized=lifeRAStatusLabel(status);
return normalized!==LIFE_RA_COMPLETED&&normalized!==LIFE_RA_REJECTED;
}

function lifeStockIssueWithTimeout(promise,timeoutMs,message){
return new Promise(function(resolve,reject){
var finished=false;
var timer=window.setTimeout(function(){
if(finished){return;}
finished=true;
reject(new Error(message||"Stock issue data request timed out."));
},Math.max(1000,lifeRANumber(timeoutMs,10000)));

Promise.resolve(promise).then(function(value){
if(finished){return;}
finished=true;
window.clearTimeout(timer);
resolve(value);
}).catch(function(error){
if(finished){return;}
finished=true;
window.clearTimeout(timer);
reject(error);
});
});
}

async function lifeStockIssueLoadParents(force){
if(!force&&LIFE_STOCK_ISSUE_CACHE.parentsLoaded){
return LIFE_STOCK_ISSUE_CACHE.parents.slice();
}

/* Reuse the already working Requests & Approvals rows immediately. */
if(
!force&&
typeof lifeRAListState!=="undefined"&&
lifeRAListState.loaded&&
Array.isArray(lifeRAListState.rows)
){
LIFE_STOCK_ISSUE_CACHE.parents=lifeRAListState.rows.slice();
LIFE_STOCK_ISSUE_CACHE.parentsLoaded=true;
return LIFE_STOCK_ISSUE_CACHE.parents.slice();
}

if(LIFE_STOCK_ISSUE_CACHE.parentsPromise){
return LIFE_STOCK_ISSUE_CACHE.parentsPromise;
}

LIFE_STOCK_ISSUE_CACHE.parentsPromise=(async function(){
try{
var rows=await getList(
LIFE_RA_DOCTYPE,
LIFE_STOCK_ISSUE_PARENT_FIELDS,
[],
{
order_by:"reported_on desc, modified desc",
limit_page_length:1000
}
);

LIFE_STOCK_ISSUE_CACHE.parents=Array.isArray(rows)?rows:[];
LIFE_STOCK_ISSUE_CACHE.parentsLoaded=true;

/* Keep the working Requests & Approvals list and cards on one source. */
if(typeof lifeRAListState!=="undefined"){
lifeRAListState.rows=LIFE_STOCK_ISSUE_CACHE.parents.slice();
}

return LIFE_STOCK_ISSUE_CACHE.parents.slice();
}
catch(error){
LIFE_STOCK_ISSUE_CACHE.parentsLoaded=false;
throw error;
}
finally{
LIFE_STOCK_ISSUE_CACHE.parentsPromise=null;
}
}());

return LIFE_STOCK_ISSUE_CACHE.parentsPromise;
}

function lifeStockIssueParentQty(parent,kind){
kind=lifeStockIssueKind(kind);
return lifeRANumber(
kind==="missing"
?parent&&parent.total_missing_qty
:parent&&parent.total_damaged_qty,
0
);
}

function lifeStockIssueRelevantParents(parents,kind){
return (parents||[]).filter(function(parent){
return lifeStockIssueParentQty(parent,kind)>0;
});
}

function lifeStockIssueParentSummary(parents,kind){
kind=lifeStockIssueKind(kind);
var relevant=lifeStockIssueRelevantParents(parents,kind);
var active=relevant.filter(function(parent){
return lifeStockIssueIsActiveStatus(parent.status);
});
var total=active.reduce(function(sum,parent){
return sum+lifeStockIssueParentQty(parent,kind);
},0);
var locations={};

active.forEach(function(parent){
var location=
kind==="missing"
?(parent.target_branch||parent.target_warehouse||"")
:(parent.target_warehouse||parent.target_branch||"");
if(location){locations[location]=true;}
});

return{
qty:total,
locationCount:Object.keys(locations).length,
activeRequests:active.length,
allRequests:relevant.length
};
}

function lifeStockIssueCardNodes(kind){
kind=lifeStockIssueKind(kind);
var card=byId(kind==="missing"?"ls-card-missing":"ls-card-damaged");
return{
card:card,
value:card?card.querySelector(".tv"):null,
subtitle:card?card.querySelector(".ts"):null
};
}

function lifeStockIssuePaintCard(kind,summary,error){
kind=lifeStockIssueKind(kind);
var nodes=lifeStockIssueCardNodes(kind);
if(!nodes.card){return;}

var emptyClass=kind==="missing"
?"life-missing-stock-empty"
:"life-damaged-stock-empty";

if(error){
if(nodes.value){nodes.value.textContent="!";}
if(nodes.subtitle){nodes.subtitle.textContent="Unable to load · click to retry";}
nodes.card.classList.add(emptyClass);
nodes.card.title=error&&error.message?error.message:String(error||"Unable to load");
return;
}

if(nodes.value){nodes.value.textContent=formatStockQty(summary.qty);}
if(nodes.subtitle){
var locationWord=kind==="missing"?"branch":"warehouse";
nodes.subtitle.textContent=
summary.locationCount+" "+locationWord+
(summary.locationCount===1?"":"es")+
" · "+summary.activeRequests+" active request"+
(summary.activeRequests===1?"":"s");
}
nodes.card.classList.toggle(emptyClass,summary.qty<=0);
nodes.card.title=
summary.allRequests+" recorded request"+
(summary.allRequests===1?"":"s")+
" with "+kind+" quantity";
}

function lifeStockIssueKnownParents(){
if(LIFE_STOCK_ISSUE_CACHE.parentsLoaded){
return LIFE_STOCK_ISSUE_CACHE.parents.slice();
}
if(
typeof lifeRAListState!=="undefined"&&
lifeRAListState.loaded&&
Array.isArray(lifeRAListState.rows)
){
return lifeRAListState.rows.slice();
}
return null;
}

function lifeStockIssuePaintBothCards(parents){
parents=Array.isArray(parents)?parents:[];
lifeStockIssuePaintCard(
"damaged",
lifeStockIssueParentSummary(parents,"damaged")
);
lifeStockIssuePaintCard(
"missing",
lifeStockIssueParentSummary(parents,"missing")
);
}

async function lifeStockIssueRefreshCards(force){
var sequence=++LIFE_STOCK_ISSUE_CACHE.cardRefreshSequence;
var knownParents=lifeStockIssueKnownParents();

/* Never leave the cards showing Loading when usable list data is known. */
if(knownParents){
lifeStockIssuePaintBothCards(knownParents);
}else{
var damagedNodes=lifeStockIssueCardNodes("damaged");
var missingNodes=lifeStockIssueCardNodes("missing");
[damagedNodes,missingNodes].forEach(function(nodes){
if(nodes.value){nodes.value.textContent="…";}
if(nodes.subtitle){nodes.subtitle.textContent="Loading register totals…";}
});
}

if(LIFE_STOCK_ISSUE_CACHE.cardsPromise&&!force){
return LIFE_STOCK_ISSUE_CACHE.cardsPromise;
}

LIFE_STOCK_ISSUE_CACHE.cardsPromise=(async function(){
try{
var parents=await lifeStockIssueWithTimeout(
lifeStockIssueLoadParents(!!force),
6000,
"Damaged and missing stock totals took too long to load."
);

/* Always paint the currently mounted cards, even after a tab re-render. */
lifeStockIssuePaintBothCards(parents);
return parents;
}
catch(error){
var fallback=lifeStockIssueKnownParents();
if(fallback){
lifeStockIssuePaintBothCards(fallback);
return fallback;
}
lifeStockIssuePaintCard("damaged",null,error);
lifeStockIssuePaintCard("missing",null,error);
void 0;
return[];
}
finally{
if(sequence===LIFE_STOCK_ISSUE_CACHE.cardRefreshSequence||!LIFE_STOCK_ISSUE_CACHE.cardsPromise){
LIFE_STOCK_ISSUE_CACHE.cardsPromise=null;
}else{
LIFE_STOCK_ISSUE_CACHE.cardsPromise=null;
}
}
}());

return LIFE_STOCK_ISSUE_CACHE.cardsPromise;
}

function lifeStockIssueInvalidate(kind){
kind=kind?lifeStockIssueKind(kind):"";
LIFE_STOCK_ISSUE_CACHE.parentsLoaded=false;
LIFE_STOCK_ISSUE_CACHE.parentsPromise=null;
LIFE_STOCK_ISSUE_CACHE.cardsPromise=null;

if(!kind||kind==="damaged"){
LIFE_STOCK_ISSUE_CACHE.damagedLoaded=false;
LIFE_STOCK_ISSUE_CACHE.damagedPromise=null;
LIFE_STOCK_ISSUE_CACHE.damagedRows=[];
}
if(!kind||kind==="missing"){
LIFE_STOCK_ISSUE_CACHE.missingLoaded=false;
LIFE_STOCK_ISSUE_CACHE.missingPromise=null;
LIFE_STOCK_ISSUE_CACHE.missingRows=[];
}
}

async function lifeStockIssueLoadRows(kind,force){
kind=lifeStockIssueKind(kind);
var rowsKey=kind+"Rows";
var loadedKey=kind+"Loaded";
var promiseKey=kind+"Promise";

if(!force&&LIFE_STOCK_ISSUE_CACHE[loadedKey]){
return LIFE_STOCK_ISSUE_CACHE[rowsKey].slice();
}
if(LIFE_STOCK_ISSUE_CACHE[promiseKey]){
return LIFE_STOCK_ISSUE_CACHE[promiseKey];
}

LIFE_STOCK_ISSUE_CACHE[promiseKey]=(async function(){
try{
var parents=await lifeStockIssueLoadParents(!!force);
var relevant=lifeStockIssueRelevantParents(parents,kind);
var documents=[];
var batchSize=8;

for(var offset=0;offset<relevant.length;offset=offset+batchSize){
var batch=relevant.slice(offset,offset+batchSize);
var loaded=await Promise.all(batch.map(function(parent){
return getDoc(LIFE_RA_DOCTYPE,parent.name).catch(function(error){
void 0;
return null;
});
}));
documents=documents.concat(loaded);
}

var result=[];
documents.forEach(function(request){
if(!request){return;}
var items=Array.isArray(request.adjustment_items)
?request.adjustment_items
:[];

items.forEach(function(item){
var issueQty=lifeRANumber(
kind==="missing"?item.missing_qty:item.damaged_qty,
0
);
if(issueQty<=0){return;}

result.push({
kind:kind,
request:request.name||item.parent||"",
item_code:item.item_code||"",
item_name:item.item_name||item.item_code||"Material",
location:
kind==="missing"
?(request.target_branch||item.target_warehouse||request.target_warehouse||"")
:(item.target_warehouse||request.target_warehouse||request.target_branch||""),
branch:request.target_branch||"",
target_warehouse:item.target_warehouse||request.target_warehouse||"",
source_warehouse:item.source_warehouse||request.source_warehouse||"",
qty:issueQty,
remarks:item.discrepancy_remarks||"",
row_status:item.row_status||"",
status:lifeRAStatusLabel(request.status),
original_stock_entry:request.stock_entry||"",
reverse_stock_entry:request.submitted_stock_entry||"",
reported_on:request.reported_on||request.creation||"",
reported_by:request.reported_by_name||request.reported_by||""
});
});
});

LIFE_STOCK_ISSUE_CACHE[rowsKey]=result;
LIFE_STOCK_ISSUE_CACHE[loadedKey]=true;
return result.slice();
}
catch(error){
LIFE_STOCK_ISSUE_CACHE[loadedKey]=false;
throw error;
}
finally{
LIFE_STOCK_ISSUE_CACHE[promiseKey]=null;
}
}());

return LIFE_STOCK_ISSUE_CACHE[promiseKey];
}

function lifeStockIssueRows(kind){
kind=lifeStockIssueKind(kind);
return LIFE_STOCK_ISSUE_CACHE[kind+"Rows"]||[];
}

function lifeStockIssueSummary(rows){
var active=(rows||[]).filter(function(row){
return lifeStockIssueIsActiveStatus(row.status);
});
var total=active.reduce(function(sum,row){
return sum+lifeRANumber(row.qty,0);
},0);
var locations={};
active.forEach(function(row){
if(row.location){locations[row.location]=true;}
});
return{
qty:total,
locationCount:Object.keys(locations).length,
activeRows:active.length,
allRows:(rows||[]).length
};
}

function lifeStockIssueFilteredRows(kind){
kind=lifeStockIssueKind(kind);
var filters=LIFE_STOCK_ISSUE_FILTERS[kind];
var query=lifeTableNormalize(filters.search||"");

return lifeStockIssueRows(kind).filter(function(row){
if(filters.status&&row.status!==filters.status){return false;}
if(filters.location&&row.location!==filters.location){return false;}
if(filters.source&&row.source_warehouse!==filters.source){return false;}
if(!query){return true;}

return lifeTableNormalize([
row.location,row.branch,row.target_warehouse,row.source_warehouse,
row.item_code,row.item_name,row.request,row.status,row.row_status,
row.original_stock_entry,row.reverse_stock_entry,row.reported_by,row.remarks
].join(" ")).indexOf(query)>=0;
});
}

function lifeStockIssueOptions(values,selected,emptyLabel){
var unique={};
(values||[]).forEach(function(value){
value=String(value||"").trim();
if(value){unique[value]=true;}
});

return '<option value="">'+escapeHtml(emptyLabel)+'</option>'+
Object.keys(unique).sort().map(function(value){
return '<option value="'+escAttr(value)+'" '+
(value===selected?'selected':'')+'>'+
escapeHtml(stripCommonCompanySuffix(value))+
'</option>';
}).join("");
}

