function lifeStockIssueCardTarget(event){
var target=event&&event.target;
var card=target&&target.closest
?target.closest("#ls-card-damaged,#ls-card-missing")
:null;

if(!card&&event&&typeof event.composedPath==="function"){
var path=event.composedPath();
for(var index=0;index<path.length;index+=1){
var node=path[index];
if(node&&node.id&&(node.id==="ls-card-damaged"||node.id==="ls-card-missing")){
card=node;
break;
}
}
}
return card;
}

function lifeStockIssueOpenFromCard(card){
if(!card){return false;}
var kind=card.id==="ls-card-missing"?"missing":"damaged";
lifeStockIssueOpenRegister(kind,false).catch(function(error){
void 0;
});
return false;
}

function lifeStockIssueMountDashboardCards(forceRefresh){
var damaged=byId("ls-card-damaged");
var missing=byId("ls-card-missing");

if(!damaged&&!missing){
return false;
}

window.__lifeStockIssueMountedDamagedCard=damaged||null;
window.__lifeStockIssueMountedMissingCard=missing||null;

[damaged,missing].forEach(function(card){
if(!card){return;}
card.style.cursor="pointer";
card.setAttribute("role","button");
card.setAttribute("tabindex","0");
card.setAttribute("aria-haspopup","dialog");
/* The permanent capture handler owns clicks; remove render-time handlers. */
card.onclick=null;
});

var known=lifeStockIssueKnownParents();
if(known){lifeStockIssuePaintBothCards(known);}

lifeStockIssueRefreshCards(!!forceRefresh).catch(function(error){
void 0;
});
return true;
}

function lifeStockIssueInstallPermanentCardHandling(){
if(window.__lifeStockIssuePermanentCardHandlingInstalled){
lifeStockIssueMountDashboardCards(false);
return;
}
window.__lifeStockIssuePermanentCardHandlingInstalled=true;

/* Capture phase guarantees the first click is handled before tab/root handlers. */
document.addEventListener("click",function(event){
var card=lifeStockIssueCardTarget(event);
if(!card){return;}
event.preventDefault();
event.stopPropagation();
if(typeof event.stopImmediatePropagation==="function"){
event.stopImmediatePropagation();
}
lifeStockIssueOpenFromCard(card);
},true);

document.addEventListener("keydown",function(event){
if(event.key!=="Enter"&&event.key!==" "){return;}
var card=lifeStockIssueCardTarget(event);
if(!card){return;}
event.preventDefault();
event.stopPropagation();
lifeStockIssueOpenFromCard(card);
},true);

var observeRoot=document.getElementById("life-stock-root")||document.body;
if(observeRoot&&window.MutationObserver){
var observer=new MutationObserver(function(){
var damaged=byId("ls-card-damaged");
var missing=byId("ls-card-missing");

var changed=
damaged!==window.__lifeStockIssueMountedDamagedCard||
missing!==window.__lifeStockIssueMountedMissingCard;

if(changed&&(damaged||missing)){
window.setTimeout(function(){
lifeStockIssueMountDashboardCards(false);
},0);
}
});
observer.observe(observeRoot,{childList:true,subtree:true});
window.__lifeStockIssueCardObserver=observer;
}

/* Cover initial render and async tab/view changes. */
window.setTimeout(function(){lifeStockIssueMountDashboardCards(false);},0);
window.setTimeout(function(){lifeStockIssueMountDashboardCards(false);},250);
window.setTimeout(function(){lifeStockIssueMountDashboardCards(false);},1000);
}

