kind,
'<div class="life-stock-issue-loading">'+
'<div class="notice notice-red" style="width:min(700px,94%)">'+
'<strong>Unable to load '+escapeHtml(kind)+' stock details.</strong><br>'+
escapeHtml(
error&&error.message
?error.message
:String(error)
)+
