async function lifeRAApproveRequest(name){
try{
if(!lifeRAHasManagerAccess()){throw new Error("Only Stock Manager or System Manager can approve receipt adjustments.");}
var remarks=lifeRAManagerRemarks(false);
if(!window.confirm("Approve "+name+"? ERPNext will submit the full original transfer and create a reverse Material Transfer for Missing + Damaged.")){return;}
setBusy(true,"Submitting original transfer and posting reverse Material Transfer…");
var result=await lifeRequireAPI().call("approve_receipt_adjustment",{
request_name:name,
remarks:remarks
});
var request=result&&result.adjustment_request;
var original=result&&result.original_stock_entry;
var reverseEntry=result&&result.adjustment_stock_entry;
closeModal();
await renderHOReceiptAdjustments();
await lifeStockIssueRefreshCards(false);
await refreshAfterMaterialRequestChange({stockChanged:true,refreshReceiptTracking:true,refreshCompletedTracking:true,delayedRefresh:false});
lifeShowApiSuccess(
"Receipt Adjustment Completed",
result&&result.message?result.message:("Original Stock Entry "+(original&&original.name||"—")+" and reverse Material Transfer "+(reverseEntry&&reverseEntry.name||"—")+" were posted."),
LIFE_RA_DOCTYPE,
request&&request.name?request.name:name
);
}
catch(error){showError(error);}
finally{setBusy(false);}
}

