"use strict";

    function lifeHOISODate(date) {
        var year = date.getFullYear();
        var month = String(date.getMonth() + 1).padStart(2, "0");
        var day = String(date.getDate()).padStart(2, "0");
        return year + "-" + month + "-" + day;
    }

    function lifeHOCurrentWeek() {
        var today = new Date();
        today.setHours(0, 0, 0, 0);
        var day = today.getDay();
        var offset = day === 0 ? 6 : day - 1;
        var monday = new Date(today);
        monday.setDate(today.getDate() - offset);
        var sunday = new Date(monday);
        sunday.setDate(monday.getDate() + 6);
        return { from: lifeHOISODate(monday), to: lifeHOISODate(sunday) };
    }

    function lifeHONormalize(value) {
        return String(value || "").trim().toLowerCase();
    }

    function lifeHOEnsureFilterShape(filters) {
        var week = lifeHOCurrentWeek();
        filters = filters || {};
        if (filters.targetWarehouse === undefined) filters.targetWarehouse = "all";
        if (filters.clientSearch === undefined) filters.clientSearch = "";
        if (filters.itemSearch === undefined) filters.itemSearch = "";
        if (!filters.requestDateFrom) filters.requestDateFrom = week.from;
        if (!filters.requestDateTo) filters.requestDateTo = week.to;
        if (filters.requiredBy === undefined) filters.requiredBy = "";
        if (filters.requestType === undefined) filters.requestType = "all";
        return filters;
    }

    hoPendingApprovalFilters = lifeHOEnsureFilterShape(hoPendingApprovalFilters);
    hoApprovedReleaseFilters = lifeHOEnsureFilterShape(hoApprovedReleaseFilters);

    function lifeHOClientText(row) {
        row = row || {};
        return [
            row.custom_client_name,
            row.custom_new_client_name,
            row.client_name,
            row.patient_name,
            row.patient,
            row.customer_name,
            row.customer,
            row.custom_client,
            row.custom_patient
        ].filter(Boolean).join(" ").toLowerCase();
    }

    function lifeHOItems(row) {

    row = row || {};


    /*
     * Full Material Request documents loaded by
     * hydrateHomeRequestData() are stored in _home_items.
     *
     * IMPORTANT:
     * _home_items must be checked before returning [].
     */
    var items =
        row.items ||
        row.material_request_items ||
        row.item_rows ||
        row._items ||
        row._home_items ||
        [];


    return Array.isArray(items)
        ? items
        : [];
}

    function lifeHOItemText(row) {
        row = row || {};
        var values = [
            row.item_code,
            row.item_name,
            row.description,
            row.custom_item_code,
            row.custom_item_name,
            row.custom_therapy_id
        ];
        lifeHOItems(row).forEach(function (item) {
            item = item || {};
            values.push(
                item.item_code,
                item.item_name,
                item.description,
                item.custom_item_code,
                item.custom_item_name,
                item.uom,
                item.stock_uom
            );
        });
        return values.filter(Boolean).join(" ").toLowerCase();
    }

    filterHORequestRowsByLocalFilters = function (rows, filters) {
        rows = Array.isArray(rows) ? rows : [];
        filters = lifeHOEnsureFilterShape(filters);

        var warehouse = lifeHONormalize(filters.targetWarehouse);
        var client = lifeHONormalize(filters.clientSearch);
        var item = lifeHONormalize(filters.itemSearch);
        var fromDate = String(filters.requestDateFrom || "").trim();
        var toDate = String(filters.requestDateTo || "").trim();
        var requiredBy = String(filters.requiredBy || "").trim();
        var requestType = lifeHONormalize(filters.requestType);

        return rows.filter(function (row) {
            if (
                warehouse !== "all" &&
                lifeHONormalize(hoPendingTargetWarehouse(row)) !== warehouse
            ) return false;

            if (client && lifeHOClientText(row).indexOf(client) === -1) {
                return false;
            }

            if (item && lifeHOItemText(row).indexOf(item) === -1) {
                return false;
            }

            var requestDate = hoRequestDateValue(row);
            if (fromDate && (!requestDate || requestDate < fromDate)) {
                return false;
            }
            if (toDate && (!requestDate || requestDate > toDate)) {
                return false;
            }
            if (requiredBy && hoPendingRequiredByValue(row) !== requiredBy) {
                return false;
            }
            if (
                requestType !== "all" &&
                lifeHONormalize(requestDisplayType(row)) !== requestType
            ) return false;

            return true;
        });
    };

    hoRequestLocalFiltersActive = function (filters) {
        filters = filters || {};
        return (
            lifeHONormalize(filters.targetWarehouse) !== "all" ||
            !!String(filters.clientSearch || "").trim() ||
            !!String(filters.itemSearch || "").trim() ||
            !!String(filters.requestDateFrom || "").trim() ||
            !!String(filters.requestDateTo || "").trim() ||
            !!String(filters.requiredBy || "").trim() ||
            lifeHONormalize(filters.requestType) !== "all"
        );
    };

    buildHORequestLocalFilters = function (rows, options) {
        rows = Array.isArray(rows) ? rows : [];
        options = options || {};

        var filters = lifeHOEnsureFilterShape(options.filters);
        var prefix = String(options.prefix || "ho-request").trim();
        var setter = String(options.setterName || "").trim();
        var resetter = String(options.resetName || "").trim();
        var exporter = String(options.exportName || "").trim();

        var warehouses = '<option value="all">All Branches / Target Warehouses</option>';
        collectHOPendingTargetWarehouseOptions(rows).forEach(function (option) {
            var selected =
                lifeHONormalize(option.value) === lifeHONormalize(filters.targetWarehouse);
            warehouses +=
                '<option value="' + escAttr(option.value) + '"' +
                (selected ? " selected" : "") + ">" +
                escapeHtml(option.label) + "</option>";
        });

        var types = '<option value="all">All Request Types</option>';
        collectHOPendingRequestTypeOptions(rows).forEach(function (label) {
            var selected =
                lifeHONormalize(label) === lifeHONormalize(filters.requestType);
            types +=
                '<option value="' + escAttr(label) + '"' +
                (selected ? " selected" : "") + ">" +
                escapeHtml(label) + "</option>";
        });

        var exportButton = exporter
            ? '<button type="button" class="btn btn-gr btn-sm" onclick="' +
              escAttr(exporter) + '()">⬇ Export Filtered</button>'
            : "";

        function field(label, idSuffix, control) {
            return '<div class="ho-pending-filter-field">' +
                '<label for="' + escAttr(prefix) + "-" + idSuffix + '">' +
                label + "</label>" + control + "</div>";
        }

        return '<div class="ho-pending-filter-shell">' +
            '<div class="ho-pending-filter-bar">' +

            field(
                "Branch / Target Warehouse",
                "warehouse",
                '<select id="' + escAttr(prefix) + '-warehouse" onchange="' +
                escAttr(setter) + '(\'targetWarehouse\',this.value)">' +
                warehouses + "</select>"
            ) +

            field(
                "Client Name",
                "client",
                '<input id="' + escAttr(prefix) + '-client" ' +
                'type="search" ' +
                'autocomplete="off" ' +
                'placeholder="Search client name..." ' +
                'value="' + escAttr(filters.clientSearch || "") + '" ' +
                'oninput="' +
                escAttr(setter) +
                '(\'clientSearch\',this.value)">'
            )+

            field(
                "Item",
                "item",
                '<input id="' + escAttr(prefix) + '-item" ' +
                'type="search" ' +
                'autocomplete="off" ' +
                'placeholder="Search item or code..." ' +
                'value="' + escAttr(filters.itemSearch || "") + '" ' +
                'oninput="' +
                escAttr(setter) +
                '(\'itemSearch\',this.value)">'
            ) +

            field(
                "Request Date From",
                "from",
                '<input id="' + escAttr(prefix) + '-from" type="date" value="' +
                escAttr(filters.requestDateFrom || "") + '" onchange="' +
                escAttr(setter) + '(\'requestDateFrom\',this.value)">'
            ) +

            field(
                "Request Date To",
                "to",
                '<input id="' + escAttr(prefix) + '-to" type="date" value="' +
                escAttr(filters.requestDateTo || "") + '" onchange="' +
                escAttr(setter) + '(\'requestDateTo\',this.value)">'
            ) +

            field(
                "Required By",
                "required",
                '<input id="' + escAttr(prefix) + '-required" type="date" value="' +
                escAttr(filters.requiredBy || "") + '" onchange="' +
                escAttr(setter) + '(\'requiredBy\',this.value)">'
            ) +

            field(
                "Request Type",
                "type",
                '<select id="' + escAttr(prefix) + '-type" onchange="' +
                escAttr(setter) + '(\'requestType\',this.value)">' +
                types + "</select>"
            ) +

            '<div class="ho-pending-filter-actions">' +
            exportButton +
            '<button type="button" class="btn btn-gy btn-sm" onclick="' +
            escAttr(resetter) + '()">↺ Reset Filters</button>' +
            "</div></div></div>";
    };

    buildHOPendingApprovalFilters = function (rows) {
        return buildHORequestLocalFilters(rows, {
            filters: hoPendingApprovalFilters,
            prefix: "ho-pending",
            setterName: "setHOPendingApprovalFilter",
            resetName: "resetHOPendingApprovalFilters",
            exportName: "exportHOPendingApprovalRequests"
        });
    };

    buildHOApprovedReleaseFilters = function (rows) {
        return buildHORequestLocalFilters(rows, {
            filters: hoApprovedReleaseFilters,
            prefix: "ho-approved",
            setterName: "setHOApprovedReleaseFilter",
            resetName: "resetHOApprovedReleaseFilters",
            exportName: ""
        });
    };

    var pendingTimer = null;
    var approvedTimer = null;
    var allowed = [
        "targetWarehouse", "clientSearch", "itemSearch",
        "requestDateFrom", "requestDateTo", "requiredBy", "requestType"
    ];

    var LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE = null;


async function lifeEnsurePendingRowsHydratedForItemSearch(
    rows
){

    rows =
        Array.isArray(rows)
            ? rows
            : [];


    var itemSearch =
        String(
            hoPendingApprovalFilters &&
            hoPendingApprovalFilters.itemSearch ||
            ""
        ).trim();


    /*
     * No item search = no need to load all Material Request
     * child rows.
     */
    if(!itemSearch){
        return;
    }


    var rowsToHydrate =
        rows.filter(
            function(row){

                return !!(
                    row &&
                    row.name &&
                    !row._homeHydrated
                );
            }
        );


    if(!rowsToHydrate.length){
        return;
    }


    /*
     * Prevent duplicate hydration when the user types:
     * c -> co -> cos -> cosm...
     */
    if(
        LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE
    ){

        await LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE;

        return;
    }


    LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE =
        hydrateHomeRequestData(
            rowsToHydrate
        );


    try{

        await LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE;

    }
    finally{

        LIFE_HO_PENDING_ITEM_HYDRATE_PROMISE =
            null;
    }
}

    async function lifeRefreshHOPendingFilteredResults(){

    var section =
        document.getElementById(
            "ho-pending-section"
        );


    if(!section){
        return;
    }


    var requestList =
        section.querySelector(
            ".card-body.ho-request-list"
        );


    if(!requestList){
        return;
    }


    /*
     * ============================================================
     * ALL PENDING REQUESTS
     * ============================================================
     */

    var allPending =
        hoManagerRows(
            "pending"
        );


    /*
     * Apply common Stock Manager branch filter first.
     *
     * This means we only hydrate requests that can actually
     * belong to the active branch scope.
     */
    var branchFiltered =
        filterHOManagerRowsByBranch(
            allPending,
            "request"
        );


    /*
     * ============================================================
     * CRITICAL ITEM SEARCH FIX
     * ============================================================
     *
     * Material Request list rows are lightweight and normally
     * don't contain the complete child `items` table.
     *
     * The old code filtered by item BEFORE loading those items.
     * Therefore records on other pages incorrectly disappeared.
     *
     * When Item Search is active, hydrate ALL branch candidates
     * before running the item filter.
     * ============================================================
     */

    var itemSearch =
        String(
            hoPendingApprovalFilters &&
            hoPendingApprovalFilters.itemSearch ||
            ""
        ).trim();


    if(itemSearch){

        /*
         * Give user feedback while the first complete item index
         * is being prepared.
         */
        var needsHydration =
            branchFiltered.some(
                function(row){

                    return !!(
                        row &&
                        row.name &&
                        !row._homeHydrated
                    );
                }
            );


        if(needsHydration){

            requestList.innerHTML =
                '<div class="ho-empty-state">' +
                    '⏳ Searching all pending request items…' +
                '</div>';
        }


        try{

            await lifeEnsurePendingRowsHydratedForItemSearch(
                branchFiltered
            );

        }
        catch(error){

            void 0;
        }
    }


    /*
     * ============================================================
     * NOW APPLY ALL FILTERS
     * ============================================================
     */

    var pending =
        filterHOPendingApprovalRows(
            branchFiltered
        );


    /*
     * Always restart from page 1 after text filtering.
     */
    state.hoPendingPage =
        Math.max(
            1,
            Number(
                state.hoPendingPage ||
                1
            )
        );


    var pendingPage =
        hoManagerPageData(
            pending,
            state.hoPendingPage
        );


    state.hoPendingPage =
        pendingPage.currentPage;


    /*
     * ============================================================
     * RENDER CARDS
     * ============================================================
     */

    requestList.innerHTML =
        pendingPage.rows.length

            ? pendingPage.rows
                .map(
                    buildHOPendingCard
                )
                .join("")

            : (
                '<div class="ho-empty-state">' +

                    (
                        hoPendingApprovalFiltersActive()

                            ? "No pending requests match the selected filters."

                            : "No pending requests."
                    ) +

                "</div>"
            );


    /*
     * ============================================================
     * PAGINATION
     * ============================================================
     */

    var existingPagination =
        section.querySelector(
            ".ho-pagination-wrap"
        );


    var paginationHtml =
        buildHOManagerPagination(
            "pending",
            pendingPage
        );


    if(existingPagination){

        if(paginationHtml){

            var holder =
                document.createElement(
                    "div"
                );


            holder.innerHTML =
                paginationHtml;


            var replacement =
                holder.firstElementChild;


            if(replacement){

                existingPagination.replaceWith(
                    replacement
                );
            }

        }
        else{

            existingPagination.remove();
        }

    }
    else if(paginationHtml){

        requestList.insertAdjacentHTML(
            "afterend",
            paginationHtml
        );
    }


    /*
     * ============================================================
     * UPDATE TITLE COUNT
     * ============================================================
     */

    var title =
        section.querySelector(
            ".ho-collapsible-title"
        );


    if(title){

        var countText =
            (
                normalizeHOManagerBranchKey(
                    hoManagerBranchFilter
                ) === "all" &&
                !hoPendingApprovalFiltersActive()
            )

                ? String(
                    pending.length
                )

                : (
                    String(
                        pending.length
                    ) +
                    " of " +
                    String(
                        allPending.length
                    )
                );


        var chevron =
            title.querySelector(
                ".ho-section-chevron"
            );


        if(chevron){

            while(
                chevron.nextSibling
            ){

                title.removeChild(
                    chevron.nextSibling
                );
            }


            title.appendChild(
                document.createTextNode(
                    " Pending Approval Requests — " +
                    countText
                )
            );
        }
    }


    /*
     * ============================================================
     * HYDRATE CURRENT PAGE FOR NORMAL DISPLAY
     * ============================================================
     *
     * If item search was active, these rows are already hydrated.
     * If item search is blank, continue the previous lightweight
     * behavior and hydrate only visible rows.
     * ============================================================
     */

    var rowsToHydrate =
        pendingPage.rows.filter(
            function(row){

                return !!(
                    row &&
                    row.name &&
                    !row._homeHydrated
                );
            }
        );


    if(!rowsToHydrate.length){
        return;
    }


    try{

        await hydrateHomeRequestData(
            rowsToHydrate
        );


        /*
         * Re-render only cards.
         * Do NOT rebuild filter inputs because user may be typing.
         */
        var latestPending =
            filterHOPendingApprovalRows(
                filterHOManagerRowsByBranch(
                    hoManagerRows(
                        "pending"
                    ),
                    "request"
                )
            );


        var latestPage =
            hoManagerPageData(
                latestPending,
                state.hoPendingPage
            );


        state.hoPendingPage =
            latestPage.currentPage;


        requestList.innerHTML =
            latestPage.rows.length

                ? latestPage.rows
                    .map(
                        buildHOPendingCard
                    )
                    .join("")

                : (
                    '<div class="ho-empty-state">' +
                        'No pending requests match the selected filters.' +
                    '</div>'
                );

    }
    catch(error){

        void 0;
    }
}

    window.setHOPendingApprovalFilter =
setHOPendingApprovalFilter =
function (name, value) {
    name =
        String(
            name || ""
        ).trim();

    if (
        allowed.indexOf(
            name
        ) === -1
    ) {
        return;
    }

    /*
     * Save current filter value.
     *
     * Do not trim while typing because that can
     * interfere with the actual value/cursor.
     */
    hoPendingApprovalFilters[name] =
        value === null ||
        value === undefined
            ? ""
            : String(value);

    state.hoPendingPage = 1;

    /*
     * Client Name + Item:
     *
     * NEVER use renderHOApproval() here.
     * That destroys and recreates the input field.
     */
    if (
        name === "clientSearch" ||
        name === "itemSearch"
    ) {
        clearTimeout(
            pendingTimer
        );

        pendingTimer =
            setTimeout(
                function () {
                    lifeRefreshHOPendingFilteredResults();
                },
                220
            );

        return;
    }

    /*
     * Dropdown/date fields do not need continuous
     * keyboard focus, so normal complete render is OK.
     */
    renderHOApproval();
};

    window.setHOApprovedReleaseFilter = setHOApprovedReleaseFilter =
        function (name, value) {
            name = String(name || "").trim();
            if (allowed.indexOf(name) === -1) return;
            hoApprovedReleaseFilters[name] = String(value || "").trim();
            state.hoApprovedPage = 1;

            if (name === "clientSearch" || name === "itemSearch") {
                clearTimeout(approvedTimer);
                approvedTimer = setTimeout(renderHOApproval, 350);
            } else {
                renderHOApproval();
            }
        };

    window.resetHOPendingApprovalFilters = resetHOPendingApprovalFilters =
        function () {
            var week = lifeHOCurrentWeek();
            hoPendingApprovalFilters = {
                targetWarehouse: "all",
                clientSearch: "",
                itemSearch: "",
                requestDateFrom: week.from,
                requestDateTo: week.to,
                requiredBy: "",
                requestType: "all"
            };
            state.hoPendingPage = 1;
            renderHOApproval();
        };

    window.resetHOApprovedReleaseFilters = resetHOApprovedReleaseFilters =
        function () {
            var week = lifeHOCurrentWeek();
            hoApprovedReleaseFilters = {
                targetWarehouse: "all",
                clientSearch: "",
                itemSearch: "",
                requestDateFrom: week.from,
                requestDateTo: week.to,
                requiredBy: "",
                requestType: "all"
            };
            state.hoApprovedPage = 1;
            renderHOApproval();
        };

    function csvValue(value) {
        return '"' + String(value == null ? "" : value).replace(/"/g, '""') + '"';
    }

    function clientLabel(row) {
        row = row || {};
        return row.custom_client_name || row.custom_new_client_name ||
            row.client_name || row.patient_name || row.patient ||
            row.customer_name || row.customer || "—";
    }

    function itemLabels(row) {
        var items = lifeHOItems(row);
        if (items.length) {
            return items.map(function (item) {
                item = item || {};
                var label = item.item_name || item.item_code || item.description || "Item";
                var code = item.item_code && item.item_code !== label
                    ? " (" + item.item_code + ")" : "";
                var qty = item.qty != null ? " - Qty: " + item.qty : "";
                return label + code + qty;
            }).join("; ");
        }
        row = row || {};
        return row.item_name || row.item_code || row.description ||
            row.custom_item_name || "—";
    }

    window.exportHOPendingApprovalRequests = function () {
        var allRows = hoManagerRows("pending");
        var branchRows = filterHOManagerRowsByBranch(allRows, "request");
        var rows = filterHOPendingApprovalRows(branchRows);

        if (!rows.length) {
            toast("No pending approval requests match the selected filters.", "o");
            return;
        }

        var csv = [[
            "Request ID", "Request Type", "Branch", "Target Warehouse",
            "Client Name", "Items", "Request Date", "Required By",
            "Requested By", "Priority", "Status"
        ].map(csvValue).join(",")];

        rows.forEach(function (row) {
            row = row || {};
            var branch = extractBranchFromWarehouse(
                row.set_warehouse || row.target_warehouse || ""
            ) || row.branch || "—";
            var requester = row._requested_by_name ||
                row.custom_material_request_by || row.owner || "—";

            csv.push([
                row.name || row.id || "",
                requestDisplayType(row),
                branch,
                hoPendingTargetWarehouseLabel(hoPendingTargetWarehouse(row)),
                clientLabel(row),
                itemLabels(row),
                hoRequestDateValue(row),
                hoPendingRequiredByValue(row),
                requester,
                priorityLabel(row.custom_priority),
                getRequestDisplayStatus(row) ||
                    row.workflow_state || row.status || "Pending"
            ].map(csvValue).join(","));
        });

        var blob = new Blob(["\uFEFF" + csv.join("\r\n")], {
            type: "text/csv;charset=utf-8;"
        });
        var url = URL.createObjectURL(blob);
        var link = document.createElement("a");
        link.href = url;
        link.download = "Pending_Approval_Requests_" +
            lifeHOISODate(new Date()) + ".csv";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        toast(rows.length + " filtered request(s) exported.", "g");
    };

