/* LIFE HO COMPLETE EXPORT PATCH — START */

(function installHOCompleteRequestExport() {
    "use strict";

    /* ---------------------------------------------------------
       Use only actual Material Request item rows for item search.
       --------------------------------------------------------- */

    lifeHOItems = function (request) {
        request = request || {};

        if (
            typeof hoManagerItems === "function"
        ) {
            var managerItems =
                hoManagerItems(request);

            if (
                Array.isArray(managerItems) &&
                managerItems.length
            ) {
                return managerItems;
            }
        }

        if (Array.isArray(request.items)) {
            return request.items;
        }

        if (
            Array.isArray(
                request.material_request_items
            )
        ) {
            return request.material_request_items;
        }

        return [];
    };

    lifeHOItemText = function (request) {
        return lifeHOItems(request)
            .map(function (item) {
                item = item || {};

                return [
                    item.item_code,
                    item.item_name,
                    item.description
                ]
                    .filter(Boolean)
                    .join(" ");
            })
            .join(" ")
            .toLowerCase();
    };

    /* ---------------------------------------------------------
       Add Excel and PDF buttons after every approval render.
       --------------------------------------------------------- */

    function installHOExportButtons() {
        var pendingSection =
            document.getElementById(
                "ho-pending-section"
            );

        if (!pendingSection) {
            return;
        }

        var actions =
            pendingSection.querySelector(
                ".ho-pending-filter-actions"
            );

        if (!actions) {
            return;
        }

        /*
         * Remove all previous export buttons first.
         */
        [
            "ho-export-filtered-pdf",
            "ho-export-filtered-excel"
        ].forEach(function (buttonId) {
            var existing =
                document.getElementById(
                    buttonId
                );

            if (existing) {
                existing.remove();
            }
        });

        /*
         * Remove the old single Export Filtered button.
         */
        var oldExportButtons =
            actions.querySelectorAll(
                '[onclick*="exportHOPendingApprovalRequests"],' +
                '[onclick*="exportHOFilteredRequestsPDF"],' +
                '[onclick*="exportHOFilteredRequestsExcel"]'
            );

        Array.prototype.forEach.call(
            oldExportButtons,
            function (button) {
                button.remove();
            }
        );

        /*
         * Add only the Excel button.
         */
        var excelButton =
            document.createElement("button");

        excelButton.type = "button";
        excelButton.id =
            "ho-export-filtered-excel";

        excelButton.className =
            "btn btn-gr btn-sm ho-filter-excel-btn";

        excelButton.innerHTML =
            "📊 Export Excel";

        excelButton.onclick = function () {
            exportHOFilteredRequestsExcel();
        };

        var resetButton =
            actions.querySelector(
                '[onclick*="resetHOPendingApprovalFilters"]'
            );

        if (resetButton) {
            resetButton.classList.add(
                "ho-filter-reset-btn"
            );

            actions.insertBefore(
                excelButton,
                resetButton
            );
        } else {
            actions.appendChild(
                excelButton
            );
        }
    }


    var previousRenderHOApproval =
        renderHOApproval;

    renderHOApproval = function () {
        var result =
            previousRenderHOApproval.apply(
                this,
                arguments
            );

        window.setTimeout(
            installHOExportButtons,
            0
        );

        return result;
    };

    /* ---------------------------------------------------------
       Filtered request source
       --------------------------------------------------------- */

    function getHOFilteredPendingRequests() {
        var allPending =
            hoManagerRows("pending");

        var branchFiltered =
            filterHOManagerRowsByBranch(
                allPending,
                "request"
            );

        return filterHOPendingApprovalRows(
            branchFiltered
        );
    }

    function hoRequestId(request) {
        return String(
            request &&
            (
                request.name ||
                request.id
            ) ||
            ""
        ).trim();
    }

    /* ---------------------------------------------------------
       Load the complete Material Request documents.
       Five requests are loaded together to avoid server overload.
       --------------------------------------------------------- */

    async function loadCompleteHORequests(rows) {
        rows = Array.isArray(rows)
            ? rows
            : [];

        var completed = [];
        var batchSize = 5;
        var start = 0;

        for (
            start = 0;
            start < rows.length;
            start += batchSize
        ) {
            var batch =
                rows.slice(
                    start,
                    start + batchSize
                );

            var results =
                await Promise.all(
                    batch.map(
                        async function (cachedRow) {
                            var requestId =
                                hoRequestId(
                                    cachedRow
                                );

                            if (!requestId) {
                                return cachedRow;
                            }

                            try {
                                var response =
                                    await lifeRequireAPI()
                                        .getRequest(
                                            requestId
                                        );

                                var fullRequest =
                                    response &&
                                    response.request
                                        ? response.request
                                        : null;

                                if (!fullRequest) {
                                    return cachedRow;
                                }

                                if (
                                    !fullRequest
                                        ._requested_by_name &&
                                    cachedRow
                                        ._requested_by_name
                                ) {
                                    fullRequest
                                        ._requested_by_name =
                                        cachedRow
                                            ._requested_by_name;
                                }

                                if (
                                    !fullRequest.branch &&
                                    cachedRow.branch
                                ) {
                                    fullRequest.branch =
                                        cachedRow.branch;
                                }

                                return fullRequest;
                            } catch (error) {
                                void 0;

                                return cachedRow;
                            }
                        }
                    )
                );

            completed =
                completed.concat(results);
        }

        return completed;
    }

    /* ---------------------------------------------------------
       Client and request detail helpers
       --------------------------------------------------------- */

    function exportText(value) {
        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            return "";
        }

        return String(value)
            .replace(/\s+/g, " ")
            .trim();
    }

    function exportClientName(request) {
        request = request || {};

        return (
            request.custom_client_name ||
            request.custom_new_client_name ||
            request.custom_expected_client_name ||
            request.client_name ||
            request.patient_name ||
            request.patient ||
            request.customer_name ||
            request.customer ||
            (
                typeof getHomeClientLabel ===
                    "function"
                    ? getHomeClientLabel(request)
                    : ""
            ) ||
            ""
        );
    }

    function exportClientId(request) {
        request = request || {};

        return (
            request.custom_client ||
            request.custom_patient ||
            request.patient ||
            request.customer ||
            request.custom_client_id ||
            ""
        );
    }

    function requestBranch(request) {
        request = request || {};

        return (
            extractBranchFromWarehouse(
                request.set_warehouse
            ) ||
            request.branch ||
            ""
        );
    }

    function requestStatus(request) {
        request = request || {};

        return (
            getRequestDisplayStatus(request) ||
            request.workflow_state ||
            request.status ||
            ""
        );
    }

    function requestRemarks(request) {
        request = request || {};

        return (
            request.custom_reasonjustification ||
            request.custom_additional_notes ||
            request.remarks ||
            ""
        );
    }

    function requestAppointment(request) {
        request = request || {};

        return (
            request.custom_appointment ||
            request.custom_patient_appointment ||
            request.patient_appointment ||
            request.appointment ||
            ""
        );
    }

    function requestTherapy(request) {
        request = request || {};

        return (
            request.custom_therapy_id ||
            request.custom_therapy_plan ||
            request.therapy_plan ||
            request.custom_expected_treatment_category ||
            ""
        );
    }

    /* ---------------------------------------------------------
       Convert complete requests into one row per requested item.
       --------------------------------------------------------- */

    function buildHOCompleteExportRows(requests) {
        var rows = [];

        (Array.isArray(requests)
            ? requests
            : []
        ).forEach(function (request) {
            request = request || {};

            var items =
                lifeHOItems(request);

            if (!items.length) {
                items = [{}];
            }

            items.forEach(
                function (item, itemIndex) {
                    item = item || {};

                    rows.push({
                        request_id:
                            hoRequestId(request),

                        request_type:
                            requestDisplayType(
                                request
                            ),

                        title:
                            getHORequestDisplayTitle(
                                request
                            ),

                        status:
                            requestStatus(request),

                        workflow_state:
                            request.workflow_state ||
                            "",

                        priority:
                            priorityLabel(
                                request.custom_priority
                            ),

                        request_date:
                            request.creation ||
                            request.transaction_date ||
                            request.request_date ||
                            "",

                        required_by:
                            request.schedule_date ||
                            "",

                        requested_by:
                            request
                                ._requested_by_name ||
                            request
                                .custom_material_request_by ||
                            request.owner ||
                            "",

                        owner:
                            request.owner ||
                            "",

                        branch:
                            requestBranch(request),

                        source_warehouse:
                            stripCommonCompanySuffix(
                                item.from_warehouse ||
                                request.set_from_warehouse ||
                                ""
                            ),

                        target_warehouse:
                            stripCommonCompanySuffix(
                                item.warehouse ||
                                request.set_warehouse ||
                                ""
                            ),

                        client_name:
                            exportClientName(request),

                        client_id:
                            exportClientId(request),

                        therapy_plan:
                            requestTherapy(request),

                        appointment:
                            requestAppointment(request),

                        item_number:
                            itemIndex + 1,

                        item_code:
                            item.item_code ||
                            "",

                        item_name:
                            item.item_name ||
                            item.item_code ||
                            "",

                        description:
                            item.description ||
                            "",

                        requested_qty:
                            item.qty !== undefined
                                ? item.qty
                                : "",

                        uom:
                            item.uom ||
                            item.stock_uom ||
                            "",

                        item_required_by:
                            item.schedule_date ||
                            request.schedule_date ||
                            "",

                        item_source_warehouse:
                            stripCommonCompanySuffix(
                                item.from_warehouse ||
                                request.set_from_warehouse ||
                                ""
                            ),

                        item_target_warehouse:
                            stripCommonCompanySuffix(
                                item.warehouse ||
                                request.set_warehouse ||
                                ""
                            ),

                        stock_qty:
                            item.stock_qty !== undefined
                                ? item.stock_qty
                                : "",

                        conversion_factor:
                            item.conversion_factor !==
                                undefined
                                ? item.conversion_factor
                                : "",

                        remarks:
                            requestRemarks(request),

                        additional_notes:
                            request.custom_additional_notes ||
                            "",

                        reason:
                            request.custom_reasonjustification ||
                            ""
                    });
                }
            );
        });

        return rows;
    }

    var exportColumns = [
        ["Request ID", "request_id"],
        ["Request Type", "request_type"],
        ["Request Title", "title"],
        ["Status", "status"],
        ["Workflow State", "workflow_state"],
        ["Priority", "priority"],
        ["Request Date & Time", "request_date"],
