    function excelXmlEscape(value) {
        return exportText(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&apos;");
    }

    function downloadBlob(
        content,
        mimeType,
        filename
    ) {
        var blob = new Blob(
            [content],
            {
                type: mimeType
            }
        );

        var url =
            window.URL.createObjectURL(
                blob
            );

        var link =
            document.createElement("a");

        link.href = url;
        link.download = filename;

        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        window.URL.revokeObjectURL(url);
    }

    /* ---------------------------------------------------------
       Excel export
       --------------------------------------------------------- */

    window.exportHOFilteredRequestsExcel =
        async function () {
            var filtered =
                getHOFilteredPendingRequests();

            if (!filtered.length) {
                toast(
                    "No pending requests match the selected filters.",
                    "o"
                );

                return;
            }

            try {
                toast(
                    "Preparing complete Excel export…",
                    "b"
                );

                var completeRequests =
                    await loadCompleteHORequests(
                        filtered
                    );

                var rows =
                    buildHOCompleteExportRows(
                        completeRequests
                    );

                var xml =
                    '<?xml version="1.0"?>' +
                    '<?mso-application progid="Excel.Sheet"?>' +
                    '<Workbook ' +
                    'xmlns="urn:schemas-microsoft-com:office:spreadsheet" ' +
                    'xmlns:o="urn:schemas-microsoft-com:office:office" ' +
                    'xmlns:x="urn:schemas-microsoft-com:office:excel" ' +
                    'xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">' +

                    '<Styles>' +
                    '<Style ss:ID="Header">' +
                    '<Font ss:Bold="1" ss:Color="#FFFFFF"/>' +
                    '<Interior ss:Color="#176B2C" ss:Pattern="Solid"/>' +
                    '<Alignment ss:Vertical="Center" ss:WrapText="1"/>' +
                    '</Style>' +

                    '<Style ss:ID="Cell">' +
                    '<Alignment ss:Vertical="Top" ss:WrapText="1"/>' +
                    '</Style>' +
                    '</Styles>' +

                    '<Worksheet ss:Name="Pending Requests">' +
                    '<Table>';

                xml += "<Row>";

                exportColumns.forEach(
                    function (column) {
                        xml +=
                            '<Cell ss:StyleID="Header">' +
                            '<Data ss:Type="String">' +
                            excelXmlEscape(
                                column[0]
                            ) +
                            "</Data></Cell>";
                    }
                );

                xml += "</Row>";

                rows.forEach(function (row) {
                    xml += "<Row>";

                    exportColumns.forEach(
                        function (column) {
                            var value =
                                row[column[1]];

                            var isNumber =
                                [
                                    "item_number",
                                    "requested_qty",
                                    "stock_qty",
                                    "conversion_factor"
                                ].indexOf(
                                    column[1]
                                ) !== -1 &&
                                value !== "" &&
                                !isNaN(
                                    Number(value)
                                );

                            xml +=
                                '<Cell ss:StyleID="Cell">' +
                                '<Data ss:Type="' +
                                (
                                    isNumber
                                        ? "Number"
                                        : "String"
                                ) +
                                '">' +
                                excelXmlEscape(value) +
                                "</Data></Cell>";
                        }
                    );

                    xml += "</Row>";
                });

                xml +=
                    "</Table>" +
                    "</Worksheet>" +
                    "</Workbook>";

                downloadBlob(
                    xml,
                    "application/vnd.ms-excel;charset=utf-8;",
                    "Pending_Material_Requests_" +
                    lifeHOISODate(
                        new Date()
                    ) +
                    ".xls"
                );

                toast(
                    filtered.length +
                    " request(s), " +
                    rows.length +
                    " material row(s) exported to Excel.",
                    "g"
                );
            } catch (error) {
                void 0;

                toast(
                    error &&
                    error.message
                        ? error.message
                        : "Excel export failed.",
                    "r"
                );
            }
        };

