function lifeSessionBranchKey(value){return String(value||'').toLowerCase().replace(/main store|sub store|branch|warehouse/g,'').replace(/[^a-z0-9]/g,'').replace('banjarahills','banjara').replace('banjarahill','banjara').replace('himayatnagar','himayathnagar').replace('dilsukhnagar','dilsukhnagar');}
