    function lifeSessionRowMatchesCheapFilters(row) {
        var client = lifeSessionClient(row);
        var branch = lifeSessionBranch(row);
        var material = lifeSessionMaterial(row);
        var request = row && row.request ? row.request : {};

        /*
         * Fast filters only. These fields are already available from the
         * Stock Entry + Material Request and do NOT require Appointment /
