            appointmentFixed
        ) {
            return false;
        }

        var execution =
            lifeSessionExecution(row);

        if (
            lifeSessionTableFilters.execution !== "all" &&
            execution.key !== lifeSessionTableFilters.execution
        ) {
            return false;
        }

        return true;
    }

    function lifeSessionRowMatchesFilters(row) {
