    async function lifeFetchSessionSourcePage() {
        /*
         * FAST MODAL SOURCE PAGE
         * ----------------------
         * Build one small request page from released Stock Entries without
         * resolving Appointment / Therapy Session. That expensive work is
         * performed only AFTER the visible table has rendered.
         */
        var targetCount =
            Math.max(
                1,
                Number(LIFE_SESSION_BACKEND_PAGE_SIZE) || 10
            );

        var candidates =
            Array.isArray(lifeSessionSourceState.carry)
                ? lifeSessionSourceState.carry.slice()
                : [];

        while (
            candidates.length < targetCount &&
            !lifeSessionSourceState.sourceEnded
        ) {
            var headers =
                await hoCompletedFetchSentHeaderChunk(
                    lifeSessionSourceState.backendOffset,
                    Math.max(
                        targetCount,
                        typeof HO_COMPLETED_REMOTE_SCAN_SIZE !== "undefined"
                            ? Number(HO_COMPLETED_REMOTE_SCAN_SIZE) || 15
                            : 15
                    )
                );

            headers =
                Array.isArray(headers)
                    ? headers
                    : [];

            lifeSessionSourceState.backendOffset +=
                headers.length;

            if (
                !headers.length ||
                headers.length <
                    Math.max(
                        targetCount,
                        typeof HO_COMPLETED_REMOTE_SCAN_SIZE !== "undefined"
                            ? Number(HO_COMPLETED_REMOTE_SCAN_SIZE) || 15
                            : 15
                    )
            ) {
                lifeSessionSourceState.sourceEnded = true;
            }

            if (!headers.length) {
                break;
            }

            var sentHeaders =
                headers.filter(
                    hoCompletedSentStockEntry
                );

            if (!sentHeaders.length) {
                continue;
            }

            var stockEntries =
                await hoCompletedLoadDocuments(
                    STOCK_ENTRY_DOCTYPE,
                    sentHeaders.map(function (row) {
                        return row.name;
                    }),
                    6
                );

            stockEntries =
                stockEntries.filter(
                    hoCompletedSentStockEntry
                );

            var savedBranch =
                typeof hoManagerBranchFilter !== "undefined"
                    ? hoManagerBranchFilter
                    : "all";

            var chunkCandidates = [];

            try {
                if (
                    typeof hoManagerBranchFilter !== "undefined"
                ) {
                    hoManagerBranchFilter = "all";
                }

                chunkCandidates =
                    await hoCompletedCandidatesFromStockEntries(
                        stockEntries
                    );
            }
            finally {
                if (
                    typeof hoManagerBranchFilter !== "undefined"
                ) {
                    hoManagerBranchFilter = savedBranch;
                }
            }

            chunkCandidates.forEach(function (candidate) {
                var key =
                    hoCompletedRemoteCandidateKey(
                        candidate
                    );

                if (
                    !key ||
                    lifeSessionSourceState.seenRequestIds[key]
                ) {
                    return;
                }

                lifeSessionSourceState.seenRequestIds[key] = true;
                candidates.push(candidate);
            });
        }

        var pageCandidates =
            candidates.slice(
                0,
                targetCount
            );

        lifeSessionSourceState.carry =
            candidates.slice(
                targetCount
            );

        if (pageCandidates.length) {
            pageCandidates =
                await hoCompletedLoadAllSentEntriesForRequests(
                    pageCandidates
                );
        }

        var rows =
            pageCandidates
                .map(function (candidate) {
                    var row =
                        hoCompletedBuildRemoteAuditRow(
                            candidate.request,
                            candidate.requestId,
                            candidate.stockEntries
                        );

                    if (row) {
                        row._lifeSessionHydrated = false;
