            lifeSessionSourceState.carry.length > 0 ||
            !lifeSessionSourceState.sourceEnded;

        return {
            rows: rows,
            hasNext: hasNext
        };
    }

    async function lifeFetchSessionBackendPage(){
var index=lifeSessionRemoteState.backendPage;
while(lifeSessionSourcePages.length<=index){
if(!lifeSessionSourceLoading){lifeSessionSourceLoading=lifePromiseTimeout(lifeFetchSessionSourcePage(),60000,'Client stock scan').then(function(result){lifeSessionSourcePages.push(result);return result;}).finally(function(){lifeSessionSourceLoading=null;});}
await lifeSessionSourceLoading;
}
return lifeSessionSourcePages[index];
}

async function lifeHydrateSessionRows(rows) {
        rows =
            Array.isArray(rows)
                ? rows
                : [];

        var pendingRows =
            rows.filter(function (row) {
                return (
                    row &&
                    row._lifeSessionHydrated !== true
                );
            });

        if (!pendingRows.length) {
            return rows;
        }

        await hoCompletedResolveRemoteSessionAudit(
            pendingRows
        );

        pendingRows.forEach(function (row) {
            row._lifeSessionHydrated = true;
        });

        return rows;
    }

    async function lifeHydrateVisibleSessionPage() {
        var rows =
            Array.isArray(lifeSessionRemoteState.currentRows)
                ? lifeSessionRemoteState.currentRows.slice()
                : [];

        if (!rows.length) {
            return;
        }

        var signature =
            lifeSessionRemoteState.signature;

        var page =
            lifeSessionPage;

        var requestIds =
            rows.map(function (row) {
                return String(
                    row &&
                    (
                        row.requestId ||
                        row.request && row.request.name
                    ) ||
                    ""
                );
            }).join("|");

        try {
            await lifeHydrateSessionRows(
                rows
            );
        }
        catch (error) {
            void 0;
            return;
        }

        if (
            signature !== lifeSessionRemoteState.signature ||
            page !== lifeSessionPage
        ) {
            return;
        }

        var currentIds =
            (lifeSessionRemoteState.currentRows || [])
                .map(function (row) {
                    return String(
                        row &&
                        (
                            row.requestId ||
                            row.request && row.request.name
                        ) ||
                        ""
                    );
