    async function lifeSessionScanNextBackendPage() {
 var generation=lifeSessionGeneration;
        lifeSessionEnsureFilterState();

        if (
            lifeSessionRemoteState.reachedEnd
        ) {
            return false;
        }

        var nextPage =
            lifeSessionRemoteState.backendPage + 1;

        if (
            nextPage >
            LIFE_SESSION_TRACKING_MAX_BACKEND_PAGES
        ) {
            throw new Error(
                "Client Stock & Session Tracking stopped after " +
                LIFE_SESSION_TRACKING_MAX_BACKEND_PAGES +
                " backend pages for safety."
            );
        }

        var result =
            await lifeFetchSessionBackendPage();
 if(generation!==lifeSessionGeneration)return false;

        var rows =
            result &&
            Array.isArray(result.rows)
                ? result.rows
                : [];

        var cheapRows =
            rows.filter(
                lifeSessionRowMatchesCheapFilters
            );

        /*
         * Appointment / Execution filters require resolved session data.
         * Only when the user actually selects one of those filters do we
         * pay that cost during scanning.
         */
        if (
            cheapRows.length &&
            lifeSessionAdvancedFiltersActive()
        ) {
            await lifeHydrateSessionRows(
                cheapRows
            );
        }

        if(generation!==lifeSessionGeneration)return false;
 cheapRows.forEach(function (row) {
            if (
                !lifeSessionAdvancedFiltersActive() ||
                lifeSessionRowMatchesAdvancedFilters(row)
            ) {
                if(!lifeSessionRemoteState.matchedRows.some(function(existing){return String(existing.requestId||existing.request.name)===String(row.requestId||row.request.name);}))lifeSessionRemoteState.matchedRows.push(row);
            }
        });

        lifeSessionRemoteState.backendPage =
            nextPage;

        if (
            !result ||
            result.hasNext !== true
        ) {
            lifeSessionRemoteState.reachedEnd =
                true;
        }

        return rows.length > 0;
    }

    async function lifeSessionEnsureMatchedCount(
    requiredCount
){

    var generation =
        lifeSessionGeneration;


    lifeSessionEnsureFilterState();


    requiredCount =
        Math.max(
            0,
            Number(
                requiredCount
            ) || 0
        );


    /*
     * Do not let one visible table page scan the entire history.
     *
     * Maximum backend pages to inspect for a normal screen load.
     * Export can still deliberately scan everything.
     */
    var maxPagesPerVisibleLoad =
        6;


    var scannedThisLoad =
        0;


    while(
        lifeSessionRemoteState.matchedRows.length <
            requiredCount &&
        !lifeSessionRemoteState.reachedEnd &&
        scannedThisLoad <
            maxPagesPerVisibleLoad
    ){

        await lifeSessionScanNextBackendPage();


        scannedThisLoad +=
            1;


        if(
            generation !==
            lifeSessionGeneration
        ){
            return;
        }


        lifeSessionRemoteState.currentRows =
            lifeSessionRemoteState
                .matchedRows
                .slice(
                    (
                        lifeSessionPage -
                        1
                    ) *
                    lifeSessionPageSize,

                    lifeSessionPage *
                    lifeSessionPageSize
                );


        lifeRefreshSessionModal();
    }
}

    /*
     * FINAL TABLE PAGINATION CONTRACT
     * -------------------------------
     * - Only the requested table page is rendered.
     * - Cheap stock/request filters are applied before session hydration.
     * - Appointment/Therapy Session data is hydrated only for the visible page
     *   unless Appointment/Execution itself is an active filter.
     * - Export is the only normal action that deliberately scans all remaining
     *   pages and hydrates all matching rows.
     */
    async function lifeLoadSessionTablePage(page) {
 var generation=lifeSessionGeneration;
        lifeSessionEnsureFilterState();
 generation=lifeSessionGeneration;
 if(lifeSessionTableFilters.sentFrom&&lifeSessionTableFilters.sentTo&&lifeSessionTableFilters.sentFrom>lifeSessionTableFilters.sentTo){lifeSessionRemoteState.isLoadingPage=false;lifeRefreshSessionModal();throw new Error("Stock Sent From must be on or before Stock Sent To.");}

        page =
            Math.max(
                1,
                Number(page) || 1
            );

        var start =
            (page - 1) *
            lifeSessionPageSize;

        var requiredCount =
            start +
            lifeSessionPageSize +
            1;

        lifeSessionRemoteState.isLoadingPage = true;
        lifeRefreshSessionModal();

        await lifeSessionEnsureMatchedCount(
            requiredCount
        );

        if(generation!==lifeSessionGeneration)return;
 var available =
            lifeSessionRemoteState.matchedRows.length;

        if (
            start >= available &&
            lifeSessionRemoteState.reachedEnd &&
            page > 1
        ) {
            page =
                Math.max(
                    1,
                    Math.ceil(
                        available /
                        lifeSessionPageSize
                    )
                );

            start =
                (page - 1) *
                lifeSessionPageSize;
        }

        lifeSessionPage = page;

        lifeSessionRemoteState.currentRows =
            lifeSessionRemoteState.matchedRows.slice(
                start,
                start + lifeSessionPageSize
            );

        lifeSessionRemoteState.currentHasNext =
            (
                lifeSessionRemoteState.matchedRows.length >
                start + lifeSessionPageSize
            ) ||
            !lifeSessionRemoteState.reachedEnd;

        lifeSessionRemoteState.currentTotalKnown =
            lifeSessionRemoteState.reachedEnd;

        lifeSessionRemoteState.isLoadingPage = false;

        /*
         * IMPORTANT: render basic rows NOW. Do not wait for Therapy Session.
         */
        lifeRefreshSessionModal();

        /*
         * Default Appointment=All / Execution=All:
         * resolve visible status in the background and refresh the same rows.
         */
        if (
            !lifeSessionAdvancedFiltersActive()
