    async function lifeLoadAllFilteredSessionRowsForExport() {
        lifeSessionEnsureFilterState();

        while (
            !lifeSessionRemoteState.reachedEnd
        ) {
            await lifeSessionScanNextBackendPage();
        }

        var rows =
            lifeSessionRemoteState.matchedRows.slice();

        /*
         * Excel must contain final Appointment / Execution values for every
         * matching row, regardless of the visible table page. Hydrate in
         * controlled batches only when Export is explicitly requested.
         */
        for (
            var start = 0;
            start < rows.length;
            start += 6
        ) {
            await lifeHydrateSessionRows(
                rows.slice(
                    start,
                    start + 6
                )
            );
        }

        return rows;
    }

