                : [];

        branchMaster.forEach(function (branch) {
            var name =
                String(
                    branch && branch.name || ""
                ).trim();

            if (
                name &&
                name !== "Testing Branch"
            ) {
                map[name] = true;
            }
        });

        (lifeSessionRemoteState.matchedRows || [])
            .forEach(function (row) {
                var name =
                    lifeSessionBranch(row);

                if (
                    name &&
                    name !== "No Branch" &&
                    name !== "Testing Branch"
                ) {
                    map[name] = true;
                }
            });

        return Object.keys(map)
            .sort()
            .map(function (branch) {
                return (
                    '<option value="' +
                    escAttr(branch) +
                    '"' +
                    (
                        branch === lifeSessionTableFilters.branch
