    function lifeBindSessionTableFilters() {
        var mappings = [
            ["life-session-search", "search", "input"],
            ["life-session-branch", "branch", "change"],
            ["life-session-item", "item", "input"],
            ["life-session-from", "sentFrom", "change"],
            ["life-session-to", "sentTo", "change"],
            ["life-session-appointment", "appointment", "change"],
            ["life-session-execution", "execution", "change"]
        ];

        mappings.forEach(function (mapping) {
            var element =
                document.getElementById(
                    mapping[0]
                );

            if (!element) {
                return;
            }

            var timer = null;

            element.addEventListener(
                mapping[2],
                function () {
                    lifeSessionTableFilters[
                        mapping[1]
                    ] =
                        String(
                            element.value || ""
                        );

                    lifeSessionPage = 1;

                    var runReload =
                        function () {
                            lifeSessionResetRemoteState();

                            lifeSessionRemoteState.isLoadingPage = true;
                            lifeRefreshSessionModal();

                            lifeLoadSessionTablePage(1)
                                .catch(showError);
                        };

                    if (
                        mapping[2] === "input"
                    ) {
                        window.clearTimeout(timer);

                        timer =
                            window.setTimeout(
                                runReload,
                                400
                            );
                    }
                    else {
                        runReload();
                    }
                }
            );
        });
    }

    function lifeRefreshSessionModal() {
        var modalBody =
            document.getElementById(
                "modal-body"
            );

        if (!modalBody) {
            return;
        }

        var activeElement =
            document.activeElement;

        var activeId =
            activeElement &&
            activeElement.id
                ? activeElement.id
                : "";

        var cursorStart =
            activeElement &&
            typeof activeElement.selectionStart ===
                "number"
                ? activeElement.selectionStart
                : null;

        var cursorEnd =
            activeElement &&
            typeof activeElement.selectionEnd ===
                "number"
                ? activeElement.selectionEnd
                : null;

        modalBody.innerHTML =
            lifeSessionTableHTML();

        lifeBindSessionTableFilters();

        if (activeId) {
            var restored =
                document.getElementById(
                    activeId
                );

            if (restored) {
                restored.focus();

                if (
                    cursorStart !== null &&
                    typeof restored.setSelectionRange ===
                        "function"
                ) {
                    try {
                        restored.setSelectionRange(
                            cursorStart,
                            cursorEnd
                        );
                    }
                    catch (ignore) {}
                }
            }
        }
    }

    window.lifeGoToSessionPage =
    async function (page) {
        var requestedPage =
            Math.max(
                1,
                Number(page) || 1
            );

        if (
            requestedPage ===
            lifeSessionPage
        ) {
            return;
        }

        try {
            lifeSessionRemoteState.isLoadingPage = true;
            lifeRefreshSessionModal();

            await lifeLoadSessionTablePage(
                requestedPage
            );

            var tableWrap =
                document.querySelector(
                    ".life-session-table-wrap"
                );

            if (tableWrap) {
                tableWrap.scrollTop = 0;
            }
        }
        catch (error) {
            showError(error);
        }
    };

    window.lifeSetSessionPageSize =
    async function (size) {
        var parsed =
            Number(size);

        if (
            [10, 25, 50, 100]
                .indexOf(parsed) === -1
        ) {
            parsed = 25;
        }

        lifeSessionPageSize =
            parsed;

        lifeSessionPage = 1;

        try {
            lifeSessionRemoteState.isLoadingPage = true;
            lifeRefreshSessionModal();

            await lifeLoadSessionTablePage(
                1
            );
        }
        catch (error) {
            showError(error);
        }
    };

