                "Stock Sent",
                "Appointment Fixed",
                "Appointment ID",
                "Appointment Date & Time",
                "Execution Status",
                "Therapy Session",
                "Material Request"
            ];

            function csv(value) {
                return (
                    '"' +
                    String(
                        value === null ||
                        value === undefined
                            ? ""
                            : value
                    )
                        .replace(/"/g, '""') +
                    '"'
                );
            }

            var content = [
                headers
                    .map(csv)
                    .join(",")
            ];

            rows.forEach(function (row) {
                var request =
                    row.request || {};

                var session =
                    lifeSessionRecord(row);

                var appointmentName =
                    lifeSessionAppointmentName(row);

                var execution =
                    lifeSessionExecution(row);

                content.push(
                    [
