                        session &&
                        session.name ||
                        "",
                        row.requestId ||
                        request.name ||
                        ""
                    ]
                        .map(csv)
                        .join(",")
                );
            });

            var blob =
                new Blob(
                    [
                        "\uFEFF" +
                        content.join("\r\n")
                    ],
                    {
                        type:
                            "text/csv;charset=utf-8;"
                    }
                );

            var url =
                window.URL
                    .createObjectURL(
                        blob
                    );

            var link =
                document.createElement(
                    "a"
                );

            link.href = url;

            link.download =
