             * Export may have discovered the real total. Restore the table
             * page the user was viewing without reloading all rows visually.
             */
            lifeSessionPage =
                savedPage;

            await lifeLoadSessionTablePage(
                savedPage
            );
        }
        catch (error) {
            lifeSessionPage =
                savedPage;

            showError(error);
