    function lifeLoadSheetJS() {
        if (
            window.XLSX &&
            window.XLSX.utils
        ) {
            return Promise.resolve(
                window.XLSX
            );
        }

        if (window.lifeSheetJSLoading) {
            return window.lifeSheetJSLoading;
        }

        var sources = [
            "/assets/frappe/js/lib/xlsx.full.min.js",
            "/assets/frappe/js/lib/xlsx/xlsx.full.min.js",
            "/assets/frappe/js/lib/xlsx/xlsx.min.js",
            "https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"
        ];

        window.lifeSheetJSLoading =
            new Promise(function (
                resolve,
                reject
            ) {
                var sourceIndex = 0;

                function tryNextSource() {
                    if (
                        window.XLSX &&
                        window.XLSX.utils
                    ) {
                        resolve(window.XLSX);
                        return;
                    }

                    if (
                        sourceIndex >=
                        sources.length
                    ) {
                        reject(
                            new Error(
                                "Excel library could not be loaded. Check browser Content Security Policy or internet access."
                            )
                        );

                        return;
                    }

                    var source =
                        sources[sourceIndex];

                    sourceIndex =
                        sourceIndex + 1;

                    var script =
                        document.createElement(
                            "script"
                        );

                    script.src = source;
                    script.async = true;

                    script.onload =
                    function () {
                        if (
                            window.XLSX &&
                            window.XLSX.utils
                        ) {
                            resolve(
                                window.XLSX
                            );
                        } else {
                            script.remove();
                            tryNextSource();
                        }
                    };

                    script.onerror =
                    function () {
                        script.remove();
                        tryNextSource();
                    };

                    document.head.appendChild(
                        script
                    );
                }

                tryNextSource();
            });

        return window.lifeSheetJSLoading;
    }


    async function lifeDownloadTrueXLSX(
        title,
        fileName,
        rows
    ) {
        rows = Array.isArray(rows)
            ? rows
            : [];

        if (!rows.length) {
            throw new Error(
                "No records match the current filters."
            );
        }

        lifeUpdateExcelLoading(
            "Loading the Excel generator…"
        );

        var XLSXLibrary =
            await lifeLoadSheetJS();

        lifeUpdateExcelLoading(
            "Creating Excel file with " +
            rows.length +
            " row(s)…"
        );

        var columns =
            Object.keys(rows[0]);

        var cleanRows =
            rows.map(function (row) {
                var cleanRow = {};

                columns.forEach(
                    function (column) {
                        var value =
                            row[column];

                        if (
                            value === null ||
                            value === undefined
                        ) {
                            value = "";
                        } else if (
                            typeof value ===
                            "object"
                        ) {
                            try {
                                value =
                                    JSON.stringify(
                                        value
                                    );
                            } catch (
                                conversionError
                            ) {
                                value =
                                    String(value);
                            }
                        }

                        cleanRow[column] =
                            value;
                    }
                );

                return cleanRow;
            });

        var worksheet =
            XLSXLibrary.utils.json_to_sheet(
                cleanRows,
                {
                    header: columns
                }
            );

        worksheet["!autofilter"] = {
            ref: worksheet["!ref"]
        };

        worksheet["!cols"] =
            columns.map(function (column) {
                var maximumLength =
                    Math.max(
                        String(column).length,
                        12
                    );

                cleanRows.forEach(
                    function (row) {
                        var valueLength =
                            String(
                                row[column] || ""
                            ).length;

                        maximumLength =
                            Math.max(
                                maximumLength,
                                Math.min(
                                    valueLength,
                                    45
                                )
                            );
                    }
                );

                return {
                    wch:
                        Math.min(
                            maximumLength + 2,
                            45
                        )
                };
            });

        var workbook =
            XLSXLibrary.utils.book_new();

        var safeSheetName =
            String(
                title ||
                "Stock Export"
            )
            .replace(
                /[\\\/\?\*\[\]:]/g,
                " "
            )
            .slice(0, 31);

        XLSXLibrary.utils.book_append_sheet(
            workbook,
            worksheet,
            safeSheetName
        );

        var safeFileName =
            String(
                fileName ||
                "Stock_Export"
            )
            .replace(
                /\.xlsx$/i,
                ""
            )
            .replace(
                /[^a-zA-Z0-9_-]+/g,
                "_"
            );

        XLSXLibrary.writeFile(
            workbook,
            safeFileName + ".xlsx",
            {
                compression: true,
                bookType: "xlsx"
            }
        );

        return true;
    }


    window.lifeExportApprovalSection =
    async function (section) {
        lifeShowExcelLoading(
            "Loading all records matching the current filters…"
        );

        try {
            /*
             Empty filters:
             lifeEPGetRows returns the complete section.

             Applied filters:
             lifeEPGetRows returns every matching record,
             not only the visible pagination page.
            */
            var rows =
                await lifeEPGetRows(
                    section
                );

            if (!rows.length) {
                toast(
                    "No records match the current filters.",
                    "o"
                );

                return false;
            }

            lifeUpdateExcelLoading(
                rows.length +
                " record(s) loaded. Building Excel file…"
            );

            var cleanTitle =
                lifeEPSectionTitle(
                    section
                );

            var cleanFileName =
                cleanTitle
                    .replace(
                        /[^a-z0-9]+/gi,
                        "_"
                    )
                    .replace(
                        /^_+|_+$/g,
                        ""
                    ) +
                "_" +
                new Date()
                    .toISOString()
                    .slice(0, 10);

            await lifeDownloadTrueXLSX(
                cleanTitle,
                cleanFileName,
                rows
            );

            toast(
                rows.length +
                " row(s) downloaded successfully.",
                "g"
            );
        } catch (error) {
            showError(error);
        } finally {
            lifeHideExcelLoading();
        }

        return false;
    };


