function bhraEnsure() {

    var page =
        document.getElementById(
            'page-ho-approval'
        );


    var area =
        document.getElementById(
            'ho-approval-area'
        );


    /*
     * The HO page markup can exist in the DOM even while the
     * logged-in dashboard is in Branch mode.
     *
     * Do not use DOM existence alone as permission/view evidence.
     */
    if(
        !page ||
        !area
    ){
        return;
    }


    /*
     * ============================================================
     * RESOLVE CURRENT DASHBOARD VIEW
     * ============================================================
     */

    var hostContext =
        (
            typeof synchronizeEmbeddedBranchFromHost ===
            "function"
        )
            ? synchronizeEmbeddedBranchFromHost()
            : null;


    var currentView =
        String(
            state &&
            state.currentView
                ? state.currentView
                : ""
        )
        .trim()
        .toLowerCase();


    var isHOView =
        currentView ===
        "ho";


    /*
     * Host role is stronger than stale local state.
     */
    if(
        hostContext &&
        hostContext.role
    ){

        var hostRole =
            String(
                hostContext.role
            )
            .trim()
            .toLowerCase();


        if(
            hostRole ===
            "branch"
        ){

            isHOView =
                false;
        }
        else if(
            hostRole === "ho" ||
            hostRole === "stock manager" ||
            hostRole === "stock_manager" ||
            hostRole === "manager"
        ){

            isHOView =
                true;
        }
    }


    /*
     * ============================================================
     * BRANCH USER GUARD
     * ============================================================
     *
     * Branch users must never initialize HO receipt tracking.
     *
     * The backend endpoint:
     *
     *   list_ho_receipt_updates
     *
     * intentionally requires Stock Manager / System Manager.
     */
    if(
        !isHOView
    ){

        /*
         * Clear any stale HO-receipt state left from a previous
         * view/session without making an HO API call.
         */
        BHRA.receiptStarted =
            false;


        BHRA.receiptReady =
            false;


        BHRA.receiptBusy =
            false;


        BHRA.receiptError =
            "";


        return;
    }


    /*
     * ============================================================
     * HO VIEW STARTS HERE
     * ============================================================
     */

    if(
        page.dataset.bhraView !==
        BHRA.view
    ){

        page.dataset.bhraView =
            BHRA.view;
    }


    /*
     * ============================================================
     * TOP TAB BAR
     * ============================================================
     */

    var bar =
        document.getElementById(
            'bhra-tabs'
        );


    if(
        !bar
    ){

        bar =
            document.createElement(
                'nav'
            );


        bar.id =
            'bhra-tabs';


        bar.setAttribute(
            'aria-label',
            'Requests and Approvals sections'
        );


        bar.innerHTML =

            '<button data-bhra-view="overview">' +
                'Overview' +
            '</button>' +

            BHRA_SECTIONS
            .map(
                function(c){

                    return (
                        '<button data-bhra-view="' +
                            c[0] +
                        '">' +

                            c[1] +

                        '</button>'
                    );
                }
            )
            .join('');


        var heading =
            page.querySelector(
                '.back-bar'
            );


        if(
            heading
        ){

            heading.after(
                bar
            );


            var title =
                heading.querySelector(
                    '.bbtitle'
                );


            if(
                title
            ){

                title.textContent =
                    'Requests & Approvals';
            }
        }
        else{

            page.insertBefore(
                bar,
                page.firstChild
            );
        }


        bar.onclick =
            function(e){

                var button =
                    e.target.closest(
                        '[data-bhra-view]'
                    );


                if(
                    button
                ){

                    bhraShow(
                        button.dataset.bhraView
                    );
                }
            };
    }


    /*
     * Mark active tab.
     */
    bar.querySelectorAll(
        'button'
    )
    .forEach(
        function(button){

            var active =
                button.dataset.bhraView ===
                BHRA.view;


            if(
                button.classList.contains(
                    'active'
                ) !== active
            ){

                button.classList.toggle(
                    'active',
                    active
                );
            }


            button.setAttribute(
                'aria-pressed',
                String(
                    active
                )
            );
        }
    );


    /*
     * ============================================================
     * SUMMARY
     * ============================================================
     */

    var summary =
        document.getElementById(
            'bhra-summary'
        );


    if(
        !summary
    ){

        summary =
            document.createElement(
                'div'
            );


        summary.id =
            'bhra-summary';


        bar.after(
            summary
        );


        summary.onclick =
            function(e){

                var button =
                    e.target.closest(
                        'button'
                    );


                if(
                    !button
                ){
                    return;
                }


                if(
                    button.dataset.bhraOpen
                ){

                    var key =
                        button.dataset.bhraOpen;


                    if(
                        key === 'rejected' ||
                        key === 'requirements'
                    ){

                        openHOTilePopup(
                            key
                        );
                    }
                    else{

                        bhraShow(
                            key
                        );
                    }
                }


                if(
                    button.dataset.bhraSummaryPrint
                ){

                    bhraPreview(
                        'Summary — ' +
                        button.dataset.bhraSummaryPrint,

                        BHRA.summaryData[
                            button.dataset.bhraSummaryPrint
                        ]
                    );
                }


                if(
                    button.dataset.bhraSummaryExport
                ){

                    lifeDownloadTrueXLSX(
                        'Branch summary',

                        'Branch_summary_' +
                        button.dataset.bhraSummaryExport,

                        BHRA.summaryData[
                            button.dataset.bhraSummaryExport
                        ]
                    );
                }
            };
    }


    /*
     * ============================================================
     * BRANCH FILTER
     * ============================================================
     */

    var filter =
        document.getElementById(
            'ho-manager-branch-filter'
        );


    if(
        filter
    ){

        var wrap =
            filter.closest(
                '.ho-manager-branch-filter-bar'
            );


        var slot =
            document.getElementById(
                'bhra-branch-row'
            );


        if(
            !slot
        ){

            slot =
                document.createElement(
                    'div'
                );


            slot.id =
                'bhra-branch-row';


            summary.after(
                slot
            );
        }


        if(
            wrap &&
            wrap.parentNode !==
            slot
        ){

            slot.appendChild(
                wrap
            );
        }
    }


    /*
     * ============================================================
     * SEARCH CLIENT BUTTON
     * ============================================================
     */

    var nav =
        document.getElementById(
            'ls-ho-nav'
        );


    if(
        nav &&
        !document.getElementById(
            'bhra-client-nav'
        )
    ){

        var client =
            document.createElement(
                'button'
            );


        client.id =
            'bhra-client-nav';


        client.type =
            'button';


        client.className =
            'mnav';


        client.textContent =
            '⌕ Search Client';


        client.onclick =
    function(event){

        if(event){

            event.preventDefault();

            event.stopPropagation();
        }


        if(
            typeof showHoMode ===
            "function"
        ){

            showHoMode(
                1
            );
        }


        window.setTimeout(
            function(){

                if(
                    typeof window.lifeOpenSessionTrackingTable ===
                    "function"
                ){

                    window.lifeOpenSessionTrackingTable();
                }

            },
            250
        );
    };


        var main =
            nav.querySelector(
                '[data-hmode="1"]'
            );


        if(
            main
        ){

            main.childNodes.forEach(
                function(node){

                    if(
                        node.nodeType === 3 &&
                        node.textContent.trim()
                    ){

                        node.textContent =
                            '📥 Requests & Approvals ';
                    }
                }
            );


            main.after(
                client
            );


            main.addEventListener(
                'click',
                function(){

                    bhraShow(
                        'overview'
                    );
                }
            );
        }
        else{

            nav.appendChild(
                client
            );
        }
    }


    /*
     * ============================================================
     * MOVE SEARCH CLIENT TO HEADER TOOLBAR
     * ============================================================
     */

    var clientButton =
        document.getElementById(
            'bhra-client-nav'
        );


    var tools =
        document.getElementById(
            'inv-tools'
        );


    var toolbar =
        tools
            ? tools.querySelector(
                '.inv-toolbar'
            )
            : null;


    var howToUseButton =
        toolbar
            ? toolbar.querySelector(
                '[data-inv-tool="help"]'
            )
            : null;


    if(
        clientButton &&
        toolbar
    ){

        clientButton.classList.remove(
            'mnav'
        );


        clientButton.classList.add(
            'life-header-client-search'
        );


        if(
            howToUseButton
        ){

            if(
                clientButton.parentNode !==
                    toolbar ||
                clientButton.nextElementSibling !==
                    howToUseButton
            ){

                toolbar.insertBefore(
                    clientButton,
                    howToUseButton
                );
            }
        }
        else if(
            clientButton.parentNode !==
            toolbar
        ){

            toolbar.insertBefore(
                clientButton,
                toolbar.firstChild
            );
        }
    }


    /*
     * ============================================================
     * CLEAN OLD STOCK360 / CLIENT STACK
     * ============================================================
     */

    var oldStack =
        document.getElementById(
            'life-client-header-stack'
        );


    if(
        oldStack
    ){

        var stock360 =
            document.getElementById(
                'ls-header-stock360'
            );


        var headerMeta =
            document.querySelector(
                '#life-stock-root ' +
                '.life-stock-app-header__meta'
            );


        if(
            stock360 &&
            headerMeta &&
            stock360.parentNode ===
                oldStack
        ){

            headerMeta.insertBefore(
                stock360,
                headerMeta.firstChild
            );
        }


        if(
            oldStack.parentNode
        ){

            oldStack.parentNode.removeChild(
                oldStack
            );
        }
    }


    /*
     * ============================================================
     * SUMMARY
     * ============================================================
     */

    bhraSummary();


    /*
     * ============================================================
     * HO RECEIPT TRACKING
     * ============================================================
     *
     * We are already inside an explicit HO-view guard.
     * Therefore this API cannot be called from Branch mode.
     * ============================================================
     */

    var receiptList =
        document.getElementById(
            'ho-receipt-tracking-list'
        );


    if(
        !BHRA.receiptStarted &&
        receiptList &&
        typeof renderHOReceiptTracking ===
            'function'
    ){

        BHRA.receiptStarted =
            true;


        renderHOReceiptTracking()
            .then(
                function(){

                    BHRA.receiptReady =
                        receiptList.dataset
                            .receiptTrackingLoaded ===
                        '1';


                    if(
                        !BHRA.receiptReady
                    ){

                        BHRA.receiptError =
                            'Receipt data could not be loaded. ' +
                            'Use Refresh All to retry.';
                    }


                    /*
                     * Reconfirm view before doing additional
                     * HO receipt processing.
                     */
                    var stillHO =
                        String(
                            state.currentView ||
                            ""
                        )
                        .toLowerCase() ===
                        "ho";


                    if(
                        stillHO
                    ){

                        bhraHydrateReceipts();

                        bhraSummary();
                    }
                }
            )
            .catch(
                function(error){

                    /*
                     * Ignore stale async completion after switching
                     * from HO to Branch.
                     */
                    if(
                        String(
                            state.currentView ||
                            ""
                        )
                        .toLowerCase() !==
                        "ho"
                    ){

                        BHRA.receiptStarted =
                            false;

                        BHRA.receiptError =
                            "";

                        return;
                    }


                    BHRA.receiptError =
                        error &&
                        error.message
                            ? error.message
                            : String(
                                error
                            );


                    bhraSummary();
                }
            );
    }


    /*
     * Hydrate receipt item quantities only in HO view.
     */
    if(
        !BHRA.receiptBusy &&
        !BHRA.receiptError
    ){

        bhraHydrateReceipts();
    }
