function renderASBRClusterHeadResults(query){
    var drop = byId("asbr-cluster-head-drop");
    if (!drop) {
        return;
    }

    var normalizedQuery = normalizeASBRClusterHeadText(query);

    var filteredRows = asbrClusterHeadRows.filter(function(practitioner){
        if (!normalizedQuery) {
            return true;
        }
        var searchableText = normalizeASBRClusterHeadText(
            [
                practitioner.employee_name,
                practitioner.name,
                practitioner.designation,
                practitioner.branch,
                practitioner.employee_number
            ].filter(Boolean).join(" ")
        );
        return searchableText.indexOf(normalizedQuery) >= 0;
    });

    drop._rows = filteredRows;

    if (!filteredRows.length) {
        drop.innerHTML =
            '<div class="sd-item" style="cursor:default">' +
                '<div class="sd-av">🔍</div>' +
                '<div>' +
                    '<div class="sd-name">No matching Area Manager found</div>' +
