        return;
    }

    drop.innerHTML = filteredRows.map(function(practitioner, index){
        var practitionerName =
            practitioner.employee_name ||
            practitioner.name ||
            "";

        var metadata = [
            practitioner.employee_number
                ? "Employee: " + practitioner.employee_number
                : "",
            practitioner.branch
                ? "Branch: " + practitioner.branch
                : "",
            practitioner.name
        ].filter(Boolean).join(" · ");

        return (
            '<div ' +
                'class="sd-item" ' +
                'data-asbr-cluster-head-index="' + index + '" ' +
                'role="button" ' +
                'tabindex="0">' +
                '<div class="sd-av">' +
                    escapeHtml(initials(practitionerName)) +
                '</div>' +
                '<div style="min-width:0;flex:1">' +
                    '<div class="sd-name">' +
                        escapeHtml(practitionerName) +
