(function () {
  "use strict";

  if (window.__lifeStockAppHeaderInitialized) {
    return;
  }
  window.__lifeStockAppHeaderInitialized = true;

  function byId(id) {
    return document.getElementById(id);
  }

  function pad(value) {
    return String(value).padStart(2, "0");
  }

  function safeText(value, fallback) {
    var text = String(value || "").trim();
    return text || fallback || "—";
  }

  var headerUserCache = {
    user: "",
    name: "",
    loading: false,
    loaded: false
  };

  function currentUserId() {
    try {
      return window.frappe && frappe.session
        ? String(frappe.session.user || "").trim()
        : "";
    } catch (error) {
      return "";
    }
  }

  function usableFullName(value, user) {
    var name = String(value || "").trim();

    if (!name) {
      return "";
    }

    if (name === user || name.indexOf("@") !== -1) {
      return "";
    }

    return name;
  }

  function fullNameFromLoadedData(user) {
    var candidates = [];

    try {
      if (window.frappe && frappe.boot && frappe.boot.user) {
        candidates.push(
          frappe.boot.user.full_name,
          frappe.boot.user.fullname,
          frappe.boot.user.first_name
        );
      }
    } catch (error) {}

    try {
      if (
        window.frappe &&
        frappe.boot &&
        frappe.boot.user_info &&
        frappe.boot.user_info[user]
      ) {
        var bootInfo = frappe.boot.user_info[user] || {};
        candidates.push(
          bootInfo.full_name,
          bootInfo.fullname,
          bootInfo.first_name
        );
      }
    } catch (error) {}

    try {
      if (
        user &&
        window.frappe &&
        typeof frappe.user_info === "function"
      ) {
        var userInfo = frappe.user_info(user) || {};
        candidates.push(
          userInfo.full_name,
          userInfo.fullname,
          userInfo.first_name
        );
      }
    } catch (error) {}

    for (var index = 0; index < candidates.length; index++) {
      var name = usableFullName(candidates[index], user);
      if (name) {
        return name;
      }
    }

    return "";
  }

  function applyResolvedUserName(user, name) {
    var resolvedName = usableFullName(name, user);

    if (!resolvedName && user === "Administrator") {
      resolvedName = "Administrator";
    }

    if (!resolvedName) {
      resolvedName = "Logged-in User";
    }

    headerUserCache.user = user;
    headerUserCache.name = resolvedName;
    headerUserCache.loading = false;
    headerUserCache.loaded = true;

    var userNode = byId("ls-header-user");
    var avatarNode = byId("ls-header-avatar");

    if (userNode) {
      userNode.textContent = resolvedName;
      userNode.title = resolvedName;
    }

    if (avatarNode) {
      avatarNode.textContent = initials(resolvedName);
    }
  }

  function resolveUserFullName(user) {
    if (
      !user ||
      user === "Guest" ||
      headerUserCache.loading ||
      (
        headerUserCache.loaded &&
        headerUserCache.user === user
      )
    ) {
      return;
    }

    var loadedName = fullNameFromLoadedData(user);
    if (loadedName) {
      applyResolvedUserName(user, loadedName);
      return;
    }

    if (user === "Administrator") {
      applyResolvedUserName(user, "Administrator");
      return;
    }

    headerUserCache.loading = true;
    headerUserCache.user = user;

    if (
      !window.frappe ||
      typeof frappe.call !== "function"
    ) {
      applyResolvedUserName(user, "");
      return;
    }

    window.LifeStockGateway.compat({
      method: "frappe.client.get_value",
      args: {
        doctype: "User",
        filters: {
          name: user
        },
        fieldname: [
          "full_name",
          "first_name",
          "last_name"
        ]
      },
      callback: function (response) {
        var row =
          response &&
          response.message
            ? response.message
            : {};

        var fullName = String(row.full_name || "").trim();

        if (!fullName) {
          fullName = (
            String(row.first_name || "").trim() +
            " " +
            String(row.last_name || "").trim()
          ).trim();
        }

        applyResolvedUserName(user, fullName);
      },
      error: function () {
        applyResolvedUserName(user, "");
      }
    });
  }

  function userFullName() {
    var user = currentUserId();

    if (
      headerUserCache.user === user &&
      headerUserCache.name
    ) {
      return {
        user: user,
        name: headerUserCache.name
      };
    }

    var loadedName = fullNameFromLoadedData(user);

    if (loadedName) {
      headerUserCache.user = user;
      headerUserCache.name = loadedName;
      headerUserCache.loaded = true;
    } else {
      resolveUserFullName(user);
    }

    return {
      user: user,
      name:
        loadedName ||
        (
          user === "Administrator"
            ? "Administrator"
            : "Loading…"
        )
    };
  }

  function initials(name) {
    var parts = String(name || "")
      .trim()
      .split(/\s+/)
      .filter(Boolean);

    if (!parts.length) {
      return "U";
    }

    if (parts.length === 1) {
      return parts[0].slice(0, 2).toUpperCase();
    }

    return (
      parts[0].charAt(0) +
      parts[parts.length - 1].charAt(0)
    ).toUpperCase();
  }

  function currentView() {
    var hiddenView = byId("ls-view-select");
    var view = hiddenView ? String(hiddenView.value || "").trim() : "";
    var role = String(window.__lifeIntegratedStockRole || "").trim();
    var branch = String(window.__lifeIntegratedStockBranchName || "").trim();

    if (role === "ho" || view === "HO") {
      return {
        role: "STOCK MANAGER / HO",
        location: "Head Office · All Branches"
      };
    }

    if (role === "branch" || view) {
      return {
        role: "BRANCH STOCK USER",
        location: branch || view || "Branch"
      };
    }

    return {
      role: "RESOLVING ACCESS",
      location: "Loading location…"
    };
  }

  function updateClock() {
    var now = new Date();
    var months = [
      "Jan", "Feb", "Mar", "Apr", "May", "Jun",
      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ];

    var dateText =
      pad(now.getDate()) + "-" +
      months[now.getMonth()] + "-" +
      String(now.getFullYear()).slice(-2);

    var hours = now.getHours();
    var period = hours >= 12 ? "PM" : "AM";
    hours = hours % 12 || 12;

    var timeText =
      pad(hours) + ":" +
      pad(now.getMinutes()) + ":" +
      pad(now.getSeconds()) + " " +
      period;

    var dateNode = byId("ls-header-date");
    var timeNode = byId("ls-header-time");

    if (dateNode) {
      dateNode.textContent = dateText;
    }
    if (timeNode) {
      timeNode.textContent = timeText;
    }
  }

  function updateContext() {
    var person = userFullName();
    var view = currentView();

    var locationNode = byId("ls-header-location");
    var roleNode = byId("ls-header-role");
    var userNode = byId("ls-header-user");
    var avatarNode = byId("ls-header-avatar");

    if (locationNode) {
      locationNode.textContent = view.location;
      locationNode.title = view.location;
    }
    if (roleNode) {
      roleNode.textContent = view.role;
    }
    if (userNode) {
      userNode.textContent = person.name;
      userNode.title = person.name;
    }
    if (avatarNode) {
      avatarNode.textContent = initials(person.name);
    }
  }

  function updateHeader() {
    if (!byId("life-stock-app-header")) {
      return;
    }

    updateClock();
    updateContext();
  }

  function startHeader() {
    updateHeader();

    document.addEventListener("click", function (event) {
      if (event.target && event.target.closest(".mnav")) {
        setTimeout(updateContext, 0);
      }
    });

    window.setInterval(updateHeader, 1000);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startHeader, { once: true });
  } else {
    startHeader();
  }
})();

