  function getSalesCycleRange(offset) {
  var now = new Date();

  // if before 6th, current business cycle is previous month
  var baseMonth = now.getDate() < 6
    ? now.getMonth() - 1
    : now.getMonth();

  var start = new Date(now.getFullYear(), baseMonth + offset, 6);
  var end   = new Date(now.getFullYear(), baseMonth + offset + 1, 5);

  return { from: start, to: end };
}

