  function loadChartJS(cb) {
    if (window.Chart) return cb();

    var existing = document.querySelector('script[data-sai-chartjs="1"]');
    if (existing) {
      var tries = 0;
      var timer = setInterval(function () {
        tries++;
        if (window.Chart) {
          clearInterval(timer);
          cb();
        } else if (tries > 40) {
          clearInterval(timer);
          cb(new Error('Chart.js load timeout'));
        }
      }, 250);
      return;
    }

    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    s.async = true;
    s.setAttribute('data-sai-chartjs', '1');
    s.onload = function () { cb(); };
    s.onerror = function () { cb(new Error('Chart.js failed to load')); };
    document.head.appendChild(s);
  }

  function destroyChart(id) {
    try {
      if (!window.Chart) return;
      var el = byId(id);
      if (!el) return;
      var inst = window.Chart.getChart(el);
      if (inst) inst.destroy();
    } catch (e) {}
  }

  function mkChart(id, type, labels, datasets, options) {
    try {
      if (!window.Chart) return;
      var canvas = byId(id);
      if (!canvas) return;

      destroyChart(id);

      new window.Chart(canvas, {
        type: type,
        data: { labels: labels || [], datasets: datasets || [] },
        options: Object.assign({
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          plugins: { legend: { display: false } }
        }, options || {})
      });
    } catch (e) {
      void 0;
    }
  }

