  function saiItemBalanceReadNonNegativeNumber(rawValue) {
    var text = str(rawValue).replace(/,/g, '').trim();

    if (text === '') {
      return null;
    }

    var value = Number(text);

    if (!isFinite(value) || value < 0) {
      return null;
    }

    return value;
  }

  function saiItemBalanceFormatIndianInput(rawValue) {
    var raw = str(rawValue).trim();

    /*
     * Negative values are not permitted for this filter.
     */
    if (raw.indexOf('-') !== -1) {
      return '0';
    }

    /*
     * Remove existing commas and any character other than digits / decimal.
     */
    raw = raw
      .replace(/,/g, '')
      .replace(/[^\d.]/g, '');

    if (raw === '') {
      return '';
    }

    /*
     * Keep only the first decimal point and at most 2 decimal places.
     */
    var dotIndex = raw.indexOf('.');
    var hasDecimal = dotIndex !== -1;
    var integerPart = hasDecimal ? raw.slice(0, dotIndex) : raw;
    var decimalPart = hasDecimal
      ? raw.slice(dotIndex + 1).replace(/\./g, '').slice(0, 2)
      : '';

    if (integerPart === '') {
      integerPart = '0';
    }

    /*
     * Remove unnecessary leading zeroes while retaining one zero.
     */
    integerPart = integerPart.replace(/^0+(?=\d)/, '');

    /*
     * Indian number grouping:
     * 1,000
     * 10,000
     * 1,00,000
     * 10,00,000
     * 1,00,00,000
     */
    var groupedInteger = integerPart;

    if (integerPart.length > 3) {
      var lastThree = integerPart.slice(-3);
      var leading = integerPart.slice(0, -3);

      leading = leading.replace(
        /\B(?=(\d{2})+(?!\d))/g,
        ','
      );

      groupedInteger = leading + ',' + lastThree;
    }

    if (hasDecimal) {
      return groupedInteger + '.' + decimalPart;
    }

    return groupedInteger;
  }

  function saiItemBalanceFilterState() {
    var metricEl = byId('sai-item-balance-metric');
    var operatorEl = byId('sai-item-balance-operator');
    var valueEl = byId('sai-item-balance-filter-value');

    var metric = metricEl ? str(metricEl.value).trim() : 'value';
    if (metric !== 'qty' && metric !== 'value') {
      metric = 'value';
    }

    var operator = operatorEl ? str(operatorEl.value).trim() : '';
    var value = valueEl
      ? saiItemBalanceReadNonNegativeNumber(valueEl.value)
      : null;

    var validOperator = (
      operator === 'gt' ||
      operator === 'gte' ||
      operator === 'lt' ||
      operator === 'lte' ||
      operator === 'eq'
    );

    return {
      active: validOperator && value !== null,
      metric: metric,
      operator: validOperator ? operator : '',
      value: value === null ? 0 : value
    };
  }

  function saiItemBalanceMatches(balanceValue, filterState) {
    if (!filterState || !filterState.active) {
      return true;
    }

    var rowValue = Number(balanceValue);

    if (!isFinite(rowValue)) {
      rowValue = 0;
    }

    if (filterState.operator === 'gt') {
      return rowValue > filterState.value;
    }

    if (filterState.operator === 'gte') {
      return rowValue >= filterState.value;
    }

    if (filterState.operator === 'lt') {
      return rowValue < filterState.value;
    }

    if (filterState.operator === 'lte') {
      return rowValue <= filterState.value;
    }

    if (filterState.operator === 'eq') {
      return Math.abs(rowValue - filterState.value) < 0.005;
    }

    return true;
  }

  function saiItemBalanceFilterLabel(filterState) {
    var metricLabel =
      filterState && filterState.metric === 'qty'
        ? 'Balance Qty'
        : 'Balance Value';

    if (!filterState || !filterState.active) {
      return 'All ' + metricLabel;
    }

    var symbol = '';

    if (filterState.operator === 'gt') symbol = '>';
    else if (filterState.operator === 'gte') symbol = '>=';
    else if (filterState.operator === 'lt') symbol = '<';
    else if (filterState.operator === 'lte') symbol = '<=';
    else if (filterState.operator === 'eq') symbol = '=';

    return metricLabel + ' ' + symbol + ' ' +
      (
        filterState.metric === 'qty'
          ? fmtQty(filterState.value)
          : '₹' + fmtMoney2(filterState.value)
      );
  }

  function saiBuildItemBalanceRows(stockRows) {

    var map = {};


    (
        Array.isArray(stockRows)
            ? stockRows
            : []
    )
    .forEach(
        function(r){

            var key =
                str(
                    r.item_code ||
                    r.item_name
                ).trim();


            if(!key){
                return;
            }


            if(!map[key]){

                map[key] = {

                    item_code:
                        str(
                            r.item_code ||
                            key
                        ),

                    item_name:
                        str(
                            r.item_name ||
                            r.item_code ||
                            key
                        ),

                    uom:
                        str(
                            r.stock_uom ||
                            r.uom ||
                            r.uom_name ||
                            ''
                        ).trim(),

                    bal_qty:
                        0,

                    bal_val:
                        0,

                    val_rate:
                        0
                };
            }


            if(!map[key].uom){

                map[key].uom =
                    str(
                        r.stock_uom ||
                        r.uom ||
                        r.uom_name ||
                        ''
                    ).trim();
            }


            map[key].bal_qty +=
                num(
                    r.bal_qty
                );


            map[key].bal_val +=
                num(
                    r.bal_val
                );


            /*
             * Prefer the ERP valuation rate.
             */
            var rowRate =
                num(
                    r.val_rate ||
                    r.valuation_rate ||
                    r.selling_rate ||
                    r.price_list_rate
                );


            if(rowRate > 0){

                map[key].val_rate =
                    rowRate;
            }
        }
    );


    return Object.keys(
        map
    )
    .map(
        function(key){

            var row =
                map[key];


            /*
             * Reliable fallback:
             * total stock value / total qty
             */
            if(
                num(row.val_rate) <= 0 &&
                num(row.bal_qty) !== 0
            ){

                row.val_rate =
                    num(row.bal_val) /
                    num(row.bal_qty);
            }


            return row;
        }
    )
    .filter(
        function(row){

            return (
                num(row.bal_qty) !== 0 ||
                num(row.bal_val) !== 0
            );
        }
    )
    .sort(
        function(a,b){

            return (
                num(b.bal_val) -
                num(a.bal_val)
            );
        }
    );
}

