  function saiCsvCell(value) {
    var text = str(value === null || value === undefined ? '' : value);
    return '"' + text.replace(/"/g, '""') + '"';
  }

  /*
   * Microsoft Excel can open .csv files using the Windows ANSI codepage
   * even when the file contains a UTF-8 BOM. Characters such as ₹, —,
   * ▲ and ▼ can therefore appear as mojibake (â‚¹, â€” etc.).
   *
   * Keep CSV exports ASCII-safe:
   * - money cells become plain numeric INR values
   * - em/en dashes become blank / normal hyphen
   * - directional symbols become simple ASCII text
   *
   * Print output is unchanged and may continue to display ₹ normally.
   */
  function saiExcelAsciiText(value) {
    return str(value === null || value === undefined ? '' : value)
      .replace(/\u20B9/g, 'INR ')
      .replace(/[\u2014\u2013]/g, '-')
      .replace(/\u2192/g, '->')
      .replace(/\u2191|\u25B2/g, 'UP ')
      .replace(/\u2193|\u25BC/g, 'DOWN ')
      .replace(/\u2265/g, '>=')
      .replace(/\u2264/g, '<=')
      .replace(/\u00A0/g, ' ')
      .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function saiExcelNumericText(value) {
    var raw = str(value === null || value === undefined ? '' : value)
      .replace(/\u20B9/g, '')
      .replace(/\bINR\b/gi, '')
      .replace(/,/g, '')
      .replace(/\s+/g, '')
      .trim();

    if (!raw || raw === '-' || raw === '--') {
      return '';
    }

    /*
     * Values displayed in Lakhs (e.g. 13.44L) are kept as their visible
     * numeric lakh value rather than converted to rupees. The header still
     * says (₹L), so Excel receives 13.44 as a real number.
     */
    var lakhMatch = raw.match(/^(-?\d+(?:\.\d+)?)L$/i);
    if (lakhMatch) {
      return lakhMatch[1];
    }

    var percentMatch = raw.match(/^(-?\d+(?:\.\d+)?)%$/);
    if (percentMatch) {
      return percentMatch[1] + '%';
    }

    var numericMatch = raw.match(/^-?\d+(?:\.\d+)?$/);
    if (numericMatch) {
      return raw;
    }

    return saiExcelAsciiText(value);
  }

  function saiExcelHeaderIsNumeric(header) {
    var h = str(header).toLowerCase();

    return (
      /qty|quantity|count|sessions|units|age|days left|month/.test(h) ||
      /value|rate|revenue|stock|consumed|order|amount|paid|due|balance/.test(h) ||
      /₹|inr|\(₹/.test(str(header))
    );
  }

  function saiExcelSafeCell(value, header) {
    if (saiExcelHeaderIsNumeric(header)) {
      return saiExcelNumericText(value);
    }

    var text = saiExcelAsciiText(value);

    /*
     * Do not export placeholder dashes as data.
     */
    if (text === '-' || text === '--') {
      return '';
    }

    return text;
  }

  function saiExportItemBalanceExcel() {
    var rows = SAI_ITEM_BALANCE_STATE.renderedRows || [];

    if (!rows.length) {
      if (window.frappe && typeof frappe.show_alert === 'function') {
        frappe.show_alert({
          message: 'No Item-wise Stock Balance rows are available to export.',
          indicator: 'orange'
        }, 5);
      }
      else {
        window.alert('No Item-wise Stock Balance rows are available to export.');
      }

      return;
    }

    var filterState = saiItemBalanceFilterState();
    var scopeLabel = selectedWarehouse
      ? cleanBranchName(selectedWarehouse)
      : 'All Warehouses';

    var lines = [];

    // sep=, helps Microsoft Excel recognise the delimiter immediately.
