/**
 * UPDATED: Renders the Item-wise Balance Qty & Value table.
 * This function now fetches a list of disabled items first and filters
 * the stock data to ensure only enabled items are displayed.
 */
async function renderItemBalanceTable(stockRows) {
    var tbody = byId('sai-tb-item-balance');

    if (!tbody) {
        return;
    }

    // 1. Immediately show a loading state and clear previous data.
    tbody.innerHTML = emptyRow(4, 'Loading item details...');
    SAI_ITEM_BALANCE_STATE.sourceRows = [];
    SAI_ITEM_BALANCE_STATE.aggregatedRows = [];

    try {
        // 2. Fetch all disabled item codes from the 'Item' doctype.
        // We fetch all and create a lookup map for fast filtering.
        const disabledItemsResponse = await frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Item',
                filters: {
                    disabled: 1
                },
                fields: ['name'],
                limit_page_length: 0 // Fetch all disabled items
            }
        });

        if (disabledItemsResponse.exc) {
            throw new Error(disabledItemsResponse.exc);
        }

        const disabledItemCodes = new Set(
            (disabledItemsResponse.message || []).map(item => item.name)
        );

        // 3. Filter the stock rows to remove any item that is in our disabled set.
        const enabledStockRows = (stockRows || []).filter(function(row) {
            const itemCode = str(row.item_code);
            // Keep the row if its item code is NOT in the disabled set.
            return itemCode && !disabledItemCodes.has(itemCode);
        });

        // 4. Update the state with the filtered rows.
        SAI_ITEM_BALANCE_STATE.sourceRows = enabledStockRows;

        // 5. Rebuild the aggregated rows from the filtered data and render the table.
        SAI_ITEM_BALANCE_STATE.aggregatedRows =
            saiBuildItemBalanceRows(
                SAI_ITEM_BALANCE_STATE.sourceRows
            );

        // Re-apply any active filters and render the final table.
        saiBindItemBalanceTools();
        saiApplyItemBalanceFilter();

    } catch (error) {
        void 0;
        tbody.innerHTML = emptyRow(4, 'Error loading enabled items: ' + error.message);
        showErrorBox('Could not load the item balance table due to an error.');
    }
}

function pickNum(row, keys) {
  for (var i = 0; i < keys.length; i++) {
    var v = row[keys[i]];
    if (v !== undefined && v !== null && v !== '') return num(v);
  }
  return 0;
}


function saiVisibleDomTableRows(tbody) {
  if (!tbody) return [];

  return Array.prototype.slice.call(tbody.querySelectorAll('tr'))
    .filter(function (row) {
      if (!row || row.offsetParent === null) {
        return false;
      }

      var cells = row.querySelectorAll('td');
      if (!cells.length) {
        return false;
      }

      if (cells.length === 1 && cells[0].hasAttribute('colspan')) {
        return false;
      }

      return true;
    });
}

function saiDomTableMatrix(tbodyId) {
  var tbody = byId(tbodyId);
  if (!tbody) {
    return null;
  }

  var table = tbody.closest('table');
  if (!table) {
    return null;
  }

  var headerRow = table.querySelector('thead tr:not(.sai-filter-row)');
  if (!headerRow) {
    headerRow = table.querySelector('thead tr');
  }

  var headers = headerRow
    ? Array.prototype.slice.call(headerRow.children).map(function (cell) {
        return str(cell.textContent).replace(/\s*⇅\s*/g, '').trim();
      })
    : [];

  var rows = saiVisibleDomTableRows(tbody).map(function (row) {
    return Array.prototype.slice.call(row.children).map(function (cell) {
      return str(cell.textContent).replace(/\s+/g, ' ').trim();
    });
  });

  var footerRow = table.querySelector('tfoot tr');
  var footer = footerRow
    ? Array.prototype.slice.call(footerRow.children).map(function (cell) {
        return str(cell.textContent).replace(/\s+/g, ' ').trim();
      })
    : [];

  return {
    table: table,
    headers: headers,
    rows: rows,
    footer: footer
  };
}

