    saiNotifyNoRows('No visible table rows are available to export.');
    return;
  }

  var lines = ['sep=,'];

  (Array.isArray(metadataLines) ? metadataLines : []).forEach(function (line) {
    lines.push(saiCsvCell(saiExcelAsciiText(line)));
  });

  if (metadataLines && metadataLines.length) {
    lines.push('');
  }

  var safeHeaders = matrix.headers.map(function (header) {
    return saiExcelAsciiText(header)
      .replace(/₹/g, 'INR');
  });

  lines.push(safeHeaders.map(saiCsvCell).join(','));

  matrix.rows.forEach(function (row) {
    lines.push(
      row.map(function (cellValue, cellIndex) {
        return saiCsvCell(
          saiExcelSafeCell(
            cellValue,
            matrix.headers[cellIndex] || ''
          )
        );
      }).join(',')
    );
  });

  if (matrix.footer.length) {
    lines.push(
      matrix.footer.map(function (cellValue, cellIndex) {
        return saiCsvCell(
          saiExcelSafeCell(
            cellValue,
            matrix.headers[cellIndex] || ''
          )
        );
      }).join(',')
    );
  }

  var csv = '\uFEFF' + lines.join('\r\n');
  var blob = new Blob([csv], {
    type: 'text/csv;charset=utf-8;'
  });
  var url = URL.createObjectURL(blob);
  var link = document.createElement('a');

  var dateText;
  try {
    dateText = new Date().toISOString().slice(0, 10);
  }
  catch (error) {
    dateText = 'export';
  }

  link.href = url;
  link.download = str(fileBase || 'Stock_Intelligence_Table')
    .replace(/[^a-zA-Z0-9_-]+/g, '_') + '_' + dateText + '.csv';

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  window.setTimeout(function () {
    URL.revokeObjectURL(url);
  }, 1000);
}

