function saiLowStockFilterState() {
  var metricEl = byId('sai-low-stock-metric');
  var operatorEl = byId('sai-low-stock-operator');
  var valueEl = byId('sai-low-stock-filter-value');

  var metric = metricEl ? str(metricEl.value).trim() : 'value';
  if (metric !== 'qty' && metric !== 'value') {
    metric = 'value';
  }

  var operator = operatorEl ? str(operatorEl.value).trim() : '';
  var value = valueEl
    ? saiItemBalanceReadNonNegativeNumber(valueEl.value)
    : null;

  var validOperator = (
    operator === 'gt' ||
    operator === 'gte' ||
    operator === 'lt' ||
    operator === 'lte' ||
    operator === 'eq'
  );

  return {
    active: validOperator && value !== null,
    metric: metric,
    operator: validOperator ? operator : '',
    value: value === null ? 0 : value
  };
}

function saiLowStockFilterLabel(filterState) {
  var metricLabel =
    filterState && filterState.metric === 'qty'
      ? 'Balance Qty'
      : 'Balance Value';

  if (!filterState || !filterState.active) {
    return 'All ' + metricLabel;
  }

  var symbol = '';
  if (filterState.operator === 'gt') symbol = '>';
  else if (filterState.operator === 'gte') symbol = '>=';
  else if (filterState.operator === 'lt') symbol = '<';
  else if (filterState.operator === 'lte') symbol = '<=';
  else if (filterState.operator === 'eq') symbol = '=';

  return metricLabel + ' ' + symbol + ' ' +
    (
      filterState.metric === 'qty'
        ? fmtQty(filterState.value)
        : '₹' + fmtMoney2(filterState.value)
    );
}

function saiApplyLowStockFilter() {

    var tbody =
        byId(
            'sai-tb-low-stock'
        );


    if(!tbody){
        return;
    }


    var filterState =
        saiLowStockFilterState();


    var rows =
        (
            SAI_LOW_STOCK_STATE.sourceRows ||
            []
        )
        .filter(
            function(row){

                var target =
                    filterState.metric === 'qty'
                        ? row.bal_qty
                        : row.bal_val;


                return saiItemBalanceMatches(
                    target,
                    filterState
                );
            }
        );


    SAI_LOW_STOCK_STATE.renderedRows =
        rows.slice();


    if(!rows.length){

        tbody.innerHTML =
            emptyRow(
                7,
                filterState.active
                    ? 'No low stock items match the selected ' +
                      (
                          filterState.metric === 'qty'
                              ? 'Balance Qty'
                              : 'Balance Value'
                      ) +
                      ' filter'
                    : 'No low stock items found'
            );


        return;
    }


    tbody.innerHTML =
        rows.map(
            function(r){

                var qty =
                    num(
                        r.bal_qty
                    );


                var status;


                if(qty < 0){

                    status =
                        pill(
                            'Negative Stock',
                            'p-r'
                        );

                }
                else if(qty === 0){

                    status =
                        pill(
                            'Out of Stock',
                            'p-r'
                        );

                }
                else if(qty <= 3){

                    status =
                        pill(
                            'Critical',
                            'p-r'
                        );

                }
                else{

                    status =
                        pill(
                            'Low Stock',
                            'p-a'
                        );
                }


                var rate =
                    num(
                        r.val_rate ||
                        r.valuation_rate
                    );


                if(
                    rate <= 0 &&
                    qty !== 0
                ){

                    rate =
                        num(
                            r.bal_val
                        ) /
                        qty;
                }


                return (

                    '<tr>' +

                        '<td>' +
                            esc(
                                r.item_name ||
                                r.item_code
                            ) +
                        '</td>' +

                        '<td>' +
                            esc(
                                cleanBranchName(
                                    r.warehouse
                                )
                            ) +
                        '</td>' +

                        '<td class="nr">' +
                            fmtQty(
                                qty
                            ) +
                        '</td>' +

                        '<td>' +
                            esc(
                                r.stock_uom ||
                                r.uom ||
                                r.uom_name ||
                                ''
                            ) +
                        '</td>' +

                        '<td class="nr">' +
                            '₹' +
                            fmtMoney2(
                                rate
                            ) +
                        '</td>' +

                        '<td class="nr">' +
                            '₹' +
                            fmtMoney2(
                                r.bal_val
                            ) +
                        '</td>' +

                        '<td>' +
                            status +
                        '</td>' +

                    '</tr>'
                );
            }
        )
        .join('');


    window.setTimeout(
        function(){

            var table =
                tbody.closest(
                    'table'
                );


            if(!table){
                return;
            }


            var firstFilter =
                table.querySelector(
                    '.sai-filter-row .sai-column-filter'
                );


            if(firstFilter){

                try{

                    firstFilter.dispatchEvent(
                        new Event(
                            'input'
                        )
                    );

                }
                catch(error){

                }
            }
        },
        0
    );
}

