  function classifyAsset(asset) {
    var name = str(asset.asset_name).toLowerCase();

    if (
      name.indexOf('machine') > -1 ||
      name.indexOf('cryo') > -1 ||
      name.indexOf('lipo') > -1 ||
      name.indexOf('g5') > -1 ||
      name.indexOf('facial') > -1 ||
      name.indexOf('blanket') > -1 ||
      name.indexOf('stimulator') > -1 ||
      name.indexOf('motor') > -1 ||
      name.indexOf('chain') > -1
    ) return 'machinery';

    if (
      name.indexOf('mobile') > -1 ||
      name.indexOf('laptop') > -1 ||
      name.indexOf('desktop') > -1 ||
      name.indexOf('printer') > -1 ||
      name.indexOf('router') > -1 ||
      name.indexOf('air condition') > -1 ||
      name.indexOf('air conditioner') > -1 ||
      name.indexOf('fan') > -1 ||
      name.indexOf('battery') > -1
    ) return 'it';

    return 'infrastructure';
  }

