  function buildRevenueMap(rows) {
    var map = {};

    rows.forEach(function (r) {
      var key = str(r.item_name || r.item_code || '').trim();
      if (!key) return;

      if (!map[key]) {
        map[key] = { base: 0, gst: 0, total: 0 };
      }

      var base = num(r.item_total); // excluding GST
      var gst = num(r.tax_amount);
      var total = base + gst;

      map[key].base += base;
      map[key].gst += gst;
      map[key].total += total;
    });

    return map;
  }

  function findRevenueForTherapy(therapyName, revenueMap) {
    var exact = revenueMap[therapyName];
    if (exact) return exact;

    var t = normalizeText(therapyName);
    var keys = Object.keys(revenueMap);

    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var nk = normalizeText(k);
      if (nk === t || nk.indexOf(t) > -1 || t.indexOf(nk) > -1) {
        return revenueMap[k];
      }
    }

    return { base: 0, gst: 0, total: 0 };
  }

