  function saiDrillCellSortValue(cell,numeric){
    var text=String(cell&&cell.textContent||"")
      .replace(/\s+/g," ")
      .trim();

    if(numeric){
      var cleaned=text
        .replace(/₹/g,"")
        .replace(/,/g,"")
        .replace(/%/g,"")
        .replace(/L$/i,"")
        .trim();

      var numberValue=parseFloat(cleaned);
      if(isFinite(numberValue)){
        return numberValue;
      }
    }

    return text.toLowerCase();
  }

  function saiBindCurrentDrilldownTable(){
    var overlay=document.getElementById("sai-drilldown-modal-overlay");
    if(!overlay){
      return;
    }

    var modal=overlay.querySelector(".sai-drilldown-modal-shell");
    if(!modal){
      return;
    }

    var table=modal.querySelector(".sai-drill-table");
    var tbody=table?table.querySelector("tbody"):null;
    var search=modal.querySelector(".sai-drill-search");
    var clear=modal.querySelector(".sai-drill-search-clear");
    var rowCount=modal.querySelector(".sai-drill-row-count");

    if(!table||!tbody){
      return;
    }

    function updateVisibleCount(){
      var visible=Array.prototype.slice.call(tbody.rows).filter(function(row){
        return row.style.display!=="none";
      }).length;

      if(rowCount){
        rowCount.textContent=visible+" of "+tbody.rows.length+" rows";
      }
    }

    function applySearch(){
      var query=String(search&&search.value||"")
        .trim()
        .toLowerCase();

      Array.prototype.slice.call(tbody.rows).forEach(function(row){
        var haystack=String(row.textContent||"").toLowerCase();
        row.style.display=(!query||haystack.indexOf(query)!==-1)?"":"none";
      });

      if(clear){
        clear.style.visibility=query?"visible":"hidden";
      }

      updateVisibleCount();
    }

    if(search){
      search.addEventListener("input",applySearch);
    }

    if(clear){
      clear.style.visibility="hidden";
      clear.addEventListener("click",function(){
        if(search){
          search.value="";
          search.focus();
        }
        applySearch();
      });
    }

    Array.prototype.slice.call(table.querySelectorAll("th[data-sai-drill-sort]")).forEach(function(th){
      function sortColumn(){
        var index=parseInt(th.getAttribute("data-sai-drill-sort"),10);
        var isNumeric=th.classList.contains("nr");
        var direction=th.getAttribute("data-sai-sort-dir")==="asc"?"desc":"asc";

        Array.prototype.slice.call(table.querySelectorAll("th[data-sai-drill-sort]")).forEach(function(other){
          other.removeAttribute("data-sai-sort-dir");
          var indicator=other.querySelector(".sai-drill-sort-indicator");
          if(indicator){
            indicator.textContent="⇅";
          }
        });

        th.setAttribute("data-sai-sort-dir",direction);
        var activeIndicator=th.querySelector(".sai-drill-sort-indicator");
        if(activeIndicator){
          activeIndicator.textContent=direction==="asc"?"↑":"↓";
        }

        var rows=Array.prototype.slice.call(tbody.rows);

        rows.sort(function(a,b){
          var av=saiDrillCellSortValue(a.cells[index],isNumeric);
          var bv=saiDrillCellSortValue(b.cells[index],isNumeric);

          if(av<bv)return direction==="asc"?-1:1;
          if(av>bv)return direction==="asc"?1:-1;
          return 0;
        });

        rows.forEach(function(row){
          tbody.appendChild(row);
        });

        applySearch();
      }

      th.addEventListener("click",sortColumn);
      th.addEventListener("keydown",function(event){
        if(event.key==="Enter"||event.key===" "){
          event.preventDefault();
          sortColumn();
        }
      });
    });

    updateVisibleCount();

    if(search){
      window.setTimeout(function(){
        search.focus();
      },50);
    }
  }

