  function saiExportCurrentDrilldown(){
    var d=SAI_CURRENT_DRILLDOWN;
    if(!d||!d.rows||!d.rows.length){
      saiNotifyNoRows("No drill-down rows are available to export.");
      return;
    }

    var lines=["sep=,"];
    lines.push(saiCsvCell(saiExcelAsciiText(d.title)));
    (d.summary||[]).forEach(function(s){
      lines.push(
        saiCsvCell(saiExcelAsciiText(s.label))+","+
        saiCsvCell(saiExcelAsciiText(s.value))
      );
    });
    lines.push("");
    lines.push(d.headers.map(function(h){
      return saiCsvCell(saiExcelAsciiText(h.label));
    }).join(","));

    d.rows.forEach(function(row){
      lines.push(d.headers.map(function(h){
        var value=typeof h.exportGet==="function"
          ?h.exportGet(row)
          :(typeof h.get==="function"?h.get(row):row[h.key]);
        return saiCsvCell(saiExcelSafeCell(value,h.label));
      }).join(","));
    });

    var blob=new Blob(["\uFEFF"+lines.join("\r\n")],{type:"text/csv;charset=utf-8;"});
    var url=URL.createObjectURL(blob);
    var link=document.createElement("a");
    link.href=url;
    link.download=saiExcelAsciiText(d.title).replace(/[^a-zA-Z0-9]+/g,"_").replace(/^_+|_+$/g,"")+
      "_"+new Date().toISOString().slice(0,10)+".csv";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(function(){URL.revokeObjectURL(url);},1000);
  }


