  function saiBindDrilldownCards(){
    var root=root_element||document;

    if(!root||root.__saiDrilldownDelegated){
      return;
    }

    root.__saiDrilldownDelegated=true;

    function getDrillCard(target){
      if(!target){
        return null;
      }

      if(typeof target.closest==="function"){
        var card=target.closest("[data-sai-drill], .sai-branch-stock-card[data-sai-warehouse]");

        if(card&&root.contains(card)){
          return card;
        }
      }

      return null;
    }

    function activateCard(card){
      if(!card){
        return;
      }

      var warehouse=card.getAttribute("data-sai-warehouse")||"";

      if(warehouse){
        saiOpenDrilldown(
          "warehouse",
          warehouse
        );
        return;
      }

      var kind=card.getAttribute("data-sai-drill")||"";

      if(kind){
        saiOpenDrilldown(
          kind
        );
      }
    }

    root.addEventListener("click",function(event){
      var card=getDrillCard(event.target);

      if(!card){
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      try{
        activateCard(card);
      }
      catch(error){
        void 0;

        if(typeof showError==="function"){
          showError(error);
        }
        else if(window.frappe&&typeof frappe.show_alert==="function"){
          frappe.show_alert({
            message:
              "Unable to open card details: "+
              (error&&error.message?error.message:String(error)),
            indicator:"red"
          },7);
        }
      }
    });

    root.addEventListener("keydown",function(event){
      if(
        event.key!=="Enter"&&
        event.key!==" "
      ){
        return;
      }

      var card=getDrillCard(event.target);

      if(!card){
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      try{
        activateCard(card);
      }
      catch(error){
        void 0;

        if(typeof showError==="function"){
          showError(error);
        }
      }
    });
  }

  window.saiOpenDrilldown=saiOpenDrilldown;
  window.saiBindDrilldownCards=saiBindDrilldownCards;
  window.saiCloseDrilldownModal=saiCloseDrilldownModal;
  window.saiPrintCurrentDrilldown=saiPrintCurrentDrilldown;
  window.saiExportCurrentDrilldown=saiExportCurrentDrilldown;

  /*
   * Bind immediately to the permanent Stock Intelligence container.
   * The delegated handler works for both static KPI cards and branch
   * cards that are rebuilt later by renderBranchStockSummary().
   */
  saiBindDrilldownCards();

