  function setPageLoading(on, label) {
  var page = $('.sai');
  if (!page) return;

  var old = page.querySelector('.sai-loading-overlay');

  if (on) {
    page.classList.add('loading-state');

    if (!old) {
      var overlay = document.createElement('div');
      overlay.className = 'sai-loading-overlay';
      overlay.textContent = label || 'Updating data...';
      page.appendChild(overlay);
    } else {
      old.textContent = label || 'Updating data...';
    }
  } else {
    page.classList.remove('loading-state');
    if (old) old.remove();
  }
}

