function saiDateContext(){
var currentCycle=getSalesCycleRange(0);
var prevCycle=getSalesCycleRange(-1);
var olderCycle=getSalesCycleRange(-2);
var forecastCycle1=getSalesCycleRange(-3);
var forecastCycle2=getSalesCycleRange(-2);
var forecastCycle3=getSalesCycleRange(-1);

return{
currentCycle:currentCycle,
prevCycle:prevCycle,
olderCycle:olderCycle,
fromStr:formatDateInput(currentCycle.from),
toStr:formatDateInput(currentCycle.to),
prevFromStr:formatDateInput(prevCycle.from),
prevToStr:formatDateInput(prevCycle.to),
olderFromStr:formatDateInput(olderCycle.from),
olderToStr:formatDateInput(olderCycle.to),
fc1FromStr:formatDateInput(forecastCycle1.from),
fc1ToStr:formatDateInput(forecastCycle1.to),
fc2FromStr:formatDateInput(forecastCycle2.from),
fc2ToStr:formatDateInput(forecastCycle2.to),
fc3FromStr:formatDateInput(forecastCycle3.from),
fc3ToStr:formatDateInput(forecastCycle3.to),
ledgerFromStr:formatDateInput(getDateMonthsBack(4)),
ledgerToStr:formatDateInput(new Date())
};
}

function saiContextKey(context){
return[
context.fromStr,
context.toStr,
context.prevFromStr,
context.prevToStr,
context.fc1FromStr,
context.fc1ToStr,
context.fc2FromStr,
context.fc2ToStr,
context.fc3FromStr,
context.fc3ToStr
].join("|");
}

function saiServerPayload(context,phase,forceRefresh){
return{
phase:phase,
force_refresh:forceRefresh?1:0,
from_date:context.fromStr,
to_date:context.toStr,
prev_from_date:context.prevFromStr,
prev_to_date:context.prevToStr,
fc1_from_date:context.fc1FromStr,
fc1_to_date:context.fc1ToStr,
fc2_from_date:context.fc2FromStr,
fc2_to_date:context.fc2ToStr,
fc3_from_date:context.fc3FromStr,
fc3_to_date:context.fc3ToStr,
ledger_from_date:context.ledgerFromStr,
ledger_to_date:context.ledgerToStr
};
}

function saiApplyWarehouseRows(coreResult){
var data=coreResult&&coreResult.data?coreResult.data:{};
var rows=Array.isArray(data.warehouses)?data.warehouses:[];
if(!rows.length){
return;
}

var names=rows
.filter(isAllowedWarehouseForSelect)
.map(function(row){
return str(row.name).trim();
});

if(!canViewAllWarehouses){
names=userWarehouse?[userWarehouse]:[];
}

names=sortWarehousesForSelect(uniq(names));

if(selectedWarehouse&&names.indexOf(selectedWarehouse)===-1){
selectedWarehouse=canViewAllWarehouses?"":(userWarehouse||"");
}

renderWarehouseSelect(names);
}

function saiBuildRenderData(context,coreResult,trendsResult,clientFailures){
var core=coreResult&&coreResult.data?coreResult.data:{};
var trends=trendsResult&&trendsResult.data?trendsResult.data:{};
var failed=[];

if(coreResult&&Array.isArray(coreResult.failed)){
failed=failed.concat(coreResult.failed);
}
if(trendsResult&&Array.isArray(trendsResult.failed)){
failed=failed.concat(trendsResult.failed);
}
if(Array.isArray(clientFailures)){
failed=failed.concat(clientFailures);
}

return{
forecastStock1:[],
forecastStock2:[],
forecastStock3:[],
forecastLedger1:Array.isArray(trends.forecastLedger1)?trends.forecastLedger1:[],
forecastLedger2:Array.isArray(trends.forecastLedger2)?trends.forecastLedger2:[],
forecastLedger3:Array.isArray(trends.forecastLedger3)?trends.forecastLedger3:[],
fc1FromStr:context.fc1FromStr,
fc1ToStr:context.fc1ToStr,
fc2FromStr:context.fc2FromStr,
fc2ToStr:context.fc2ToStr,
fc3FromStr:context.fc3FromStr,
fc3ToStr:context.fc3ToStr,
fromStr:context.fromStr,
toStr:context.toStr,
cycleLabel:cycleLabel(context.currentCycle.from,context.currentCycle.to),
prevCycleLabel:cycleLabel(context.prevCycle.from,context.prevCycle.to),
olderCycleLabel:cycleLabel(context.olderCycle.from,context.olderCycle.to),
stockCurrent:extractReportRows(core.stockBalanceCurrent),
stockPrev:extractReportRows(trends.stockBalancePrevious),
stockOlder:[],
stockLedger4m:Array.isArray(core.stockLedger4m)?core.stockLedger4m:[],
projected:extractReportRows(core.stockProjected),
therapy:Array.isArray(trends.therapySessions)
?trends.therapySessions.filter(function(row){return num(row.docstatus)!==2;})
:[],
therapyPrev:Array.isArray(trends.therapySessionsPrev)
?trends.therapySessionsPrev.filter(function(row){return num(row.docstatus)!==2;})
:[],
therapyRevenue:extractReportRows(trends.therapyRevenue),
therapyRevenuePrev:extractReportRows(trends.therapyRevenuePrev),
assets:Array.isArray(core.assets)?core.assets:[],
batches:Array.isArray(core.batches)?core.batches:[],
failed:failed
};
}

function saiRenderCache(){
if(!SAI_CLIENT_CACHE.renderData){
return false;
}
renderAll(SAI_CLIENT_CACHE.renderData);
return true;
}

function loadAll(forceRefresh){
forceRefresh=!!forceRefresh;
var startTime=Date.now();
var context=saiDateContext();
var cacheKey=saiContextKey(context);
var cacheFresh=
!forceRefresh&&
SAI_CLIENT_CACHE.key===cacheKey&&
SAI_CLIENT_CACHE.renderData&&
(Date.now()-SAI_CLIENT_CACHE.loadedAt)<SAI_CLIENT_CACHE_TTL;

if(cacheFresh){
setLoading(false);
setPageLoading(false);
setTimestamp(
"Cached · "+
(selectedWarehouse?cleanBranchName(selectedWarehouse):"All Warehouses")
);
saiRenderCache();
return Promise.resolve(SAI_CLIENT_CACHE.renderData);
}

if(SAI_CLIENT_CACHE.loading&&!forceRefresh){
return SAI_CLIENT_CACHE.loading;
}

SAI_CLIENT_CACHE.key=cacheKey;
if(forceRefresh){
SAI_CLIENT_CACHE.core=null;
SAI_CLIENT_CACHE.trends=null;
SAI_CLIENT_CACHE.renderData=null;
SAI_CLIENT_CACHE.loadedAt=0;
}

setLoading(true);
var label="Updating "+(selectedWarehouse?cleanBranchName(selectedWarehouse):"All Warehouses")+"...";
setTimestamp(label);
setPageLoading(true,label);
clearErrorBox();

var failures=[];

var corePromise=window.LifeStockGateway.action(
"stock_intelligence",
saiServerPayload(context,"core",forceRefresh)
).then(function(result){
SAI_CLIENT_CACHE.core=result;
saiApplyWarehouseRows(result);
SAI_CLIENT_CACHE.renderData=saiBuildRenderData(
context,
SAI_CLIENT_CACHE.core,
SAI_CLIENT_CACHE.trends,
failures
);
renderAll(SAI_CLIENT_CACHE.renderData);
setPageLoading(false);
setTimestamp("Core stock loaded · completing analytics...");
return result;
}).catch(function(error){
var message="Core: "+(error&&error.message?error.message:String(error));
failures.push(message);
void 0;
return null;
});

var trendsPromise=window.LifeStockGateway.action(
"stock_intelligence",
saiServerPayload(context,"trends",forceRefresh)
).then(function(result){
SAI_CLIENT_CACHE.trends=result;
SAI_CLIENT_CACHE.renderData=saiBuildRenderData(
context,
SAI_CLIENT_CACHE.core,
SAI_CLIENT_CACHE.trends,
failures
);
renderAll(SAI_CLIENT_CACHE.renderData);
return result;
}).catch(function(error){
var message="Trends: "+(error&&error.message?error.message:String(error));
failures.push(message);
void 0;
return null;
});

SAI_CLIENT_CACHE.loading=Promise.all([
corePromise,
trendsPromise
]).then(function(){
if(!SAI_CLIENT_CACHE.core&&!SAI_CLIENT_CACHE.trends){
throw new Error(failures.join(" | ")||"Stock Intelligence could not be loaded.");
}

SAI_CLIENT_CACHE.renderData=saiBuildRenderData(
context,
SAI_CLIENT_CACHE.core,
SAI_CLIENT_CACHE.trends,
failures
);
SAI_CLIENT_CACHE.loadedAt=Date.now();
renderAll(SAI_CLIENT_CACHE.renderData);
setTimestamp(
"Updated · "+
(selectedWarehouse?cleanBranchName(selectedWarehouse):"All Warehouses")
);
return SAI_CLIENT_CACHE.renderData;
}).catch(function(error){
void 0;
renderFallback("Failed to load ERP data");
showErrorBox(
"Fatal load error: "+
(error&&error.message?error.message:"Unknown error")
);
