      // Forecast usage from previous 3 completed cycles
function addForecastLedgerValue(row, bucketKey) {
  var code = str(row.item_code);
  var group = str(row.item_group) || itemGroupByCode[code] || 'Unclassified';

  ensureForecastGroup(group);

  // Try every known ERPNext field for transaction quantity
  // Stock Ledger report uses different field names across versions:
  // v13: actual_qty (delta), v14/v15: qty or actual_qty
  // actual_qty in the *report* is the delta (negative = outward)
  // but in the *doctype* it's the running balance
  var txnQty =
    num(row.qty) ||                  // some versions
    num(row.actual_qty) ||           // report delta field (negative = outward)
    num(row.qty_after_transaction);  // fallback

  // If it's the running balance (always positive, large number),
  // we can't use it — skip rows where we can't determine direction
  // Instead, use the value fields directly (negative = outward)
  var rawValueDiff =
    num(row.stock_value_difference) ||
    num(row.value_difference)       ||
    num(row.stock_value_diff);

  // If value diff is negative, this is definitively an outward entry
  if (rawValueDiff < 0) {
    forecastByGroup[group][bucketKey] += Math.abs(rawValueDiff);
    return;
  }

  // Fallback: use outward qty × Item.valuation_rate
  if (txnQty < 0) {
    var rate =
      num(row.selling_rate)   ||
      num(row.price_list_rate)||
      num(row.valuation_rate) ||
      num(rateByItem[code]);
    var value = Math.abs(txnQty) * rate;
    if (value > 0) {
      forecastByGroup[group][bucketKey] += value;
    }
  }
}
