(function installLifeStockIntelligenceTableTools() {
  "use strict";

  var slot = document.getElementById("ls-stock-intelligence-slot");

  if (!slot || slot.__lifeSaiTableToolsInstalled) {
    return;
  }

  slot.__lifeSaiTableToolsInstalled = true;

  function cleanText(value) {
    return String(value || "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function numericValue(value) {
    var cleaned = cleanText(value)
      .replace(/[₹,%]/g, "")
      .replace(/\bL\b/gi, "")
      .replace(/,/g, "");

    var parsed = parseFloat(cleaned);
    return Number.isFinite(parsed) ? parsed : null;
  }

  function dateValue(value) {
    var text = cleanText(value);
    var match = text.match(/^(\d{1,2})-([A-Za-z]{3})-(\d{2,4})/);

    if (match) {
      var months = {
        jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
        jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
      };
      var year = parseInt(match[3], 10);
      if (year < 100) {
        year += 2000;
      }
      var month = months[String(match[2]).toLowerCase()];
      if (month !== undefined) {
        return new Date(year, month, parseInt(match[1], 10)).getTime();
      }
    }

    var parsed = Date.parse(text);
    return Number.isFinite(parsed) ? parsed : null;
  }

  function isSummaryRow(row) {
    return !!(
      row &&
      (
        row.classList.contains("tr") ||
        /^total\b/i.test(cleanText(row.textContent))
      )
    );
  }

  function compareValues(aText, bText, direction) {
    var aNumber = numericValue(aText);
    var bNumber = numericValue(bText);
    var result;

    if (aNumber !== null && bNumber !== null) {
      result = aNumber - bNumber;
    } else {
      var aDate = dateValue(aText);
      var bDate = dateValue(bText);

      if (aDate !== null && bDate !== null) {
        result = aDate - bDate;
      } else {
        result = cleanText(aText).localeCompare(
          cleanText(bText),
          undefined,
          { numeric: true, sensitivity: "base" }
        );
      }
    }

    return direction === "asc" ? result : -result;
  }

  function enhanceSorting(table) {
    if (table.__lifeSaiSortingBound) {
      return;
    }

    var headerRow = table.querySelector("thead tr:not(.sai-filter-row)");
    var tbody = table.querySelector("tbody");

    if (!headerRow || !tbody) {
      return;
    }

    table.__lifeSaiSortingBound = true;

    Array.prototype.forEach.call(
      headerRow.querySelectorAll("th"),
      function (header, columnIndex) {
        header.classList.add("sai-sortable-header");
        header.setAttribute("role", "button");
        header.setAttribute("tabindex", "0");

        var indicator = document.createElement("span");
        indicator.className = "sort-indicator";
        indicator.textContent = "⇅";
        header.appendChild(indicator);

        function sortColumn() {
          var nextDirection =
            header.getAttribute("data-sort-direction") === "asc"
              ? "desc"
              : "asc";

          Array.prototype.forEach.call(
            headerRow.querySelectorAll("th"),
            function (otherHeader) {
              otherHeader.removeAttribute("data-sort-direction");
              var otherIndicator = otherHeader.querySelector(".sort-indicator");
              if (otherIndicator) {
                otherIndicator.textContent = "⇅";
              }
            }
          );

          header.setAttribute("data-sort-direction", nextDirection);
          indicator.textContent = nextDirection === "asc" ? "▲" : "▼";

          var allRows = Array.prototype.slice.call(tbody.querySelectorAll("tr"));
          var summaryRows = allRows.filter(isSummaryRow);
          var dataRows = allRows.filter(function (row) {
            return !isSummaryRow(row);
          });

          dataRows.sort(function (rowA, rowB) {
            var cellA = rowA.children[columnIndex];
            var cellB = rowB.children[columnIndex];

            return compareValues(
              cellA ? cellA.textContent : "",
              cellB ? cellB.textContent : "",
              nextDirection
            );
          });

          dataRows.concat(summaryRows).forEach(function (row) {
            tbody.appendChild(row);
          });
        }

        header.addEventListener("click", sortColumn);
        header.addEventListener("keydown", function (event) {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            sortColumn();
          }
        });
      }
    );
  }

  function enhanceFiltering(table) {
    var thead = table.querySelector("thead");
    var headerRow = thead && thead.querySelector("tr:not(.sai-filter-row)");
    var tbody = table.querySelector("tbody");

    if (!thead || !headerRow || !tbody || thead.querySelector(".sai-filter-row")) {
      return;
    }

    var filterRow = document.createElement("tr");
    filterRow.className = "sai-filter-row";

    Array.prototype.forEach.call(
      headerRow.querySelectorAll("th"),
      function (_, columnIndex) {
        var cell = document.createElement("th");
        var input = document.createElement("input");

        input.type = "search";
        input.className = "sai-column-filter";
        input.placeholder = "Search…";
        input.setAttribute("aria-label", "Filter column " + (columnIndex + 1));

        input.addEventListener("click", function (event) {
          event.stopPropagation();
        });

        input.addEventListener("keydown", function (event) {
          event.stopPropagation();
        });

        input.addEventListener("input", function () {
          var filters = Array.prototype.map.call(
            filterRow.querySelectorAll("input"),
            function (filterInput) {
              return cleanText(filterInput.value).toLowerCase();
            }
          );

          Array.prototype.forEach.call(
