/* ================================================================
   GLOBAL NON-NEGATIVE NUMBER INPUT PROTECTION
   Prevents every numeric field on the Stock Management page from
   accepting a minus sign through typing, paste, drag/drop, spinner,
   or programmatic negative values. Works for dynamically rendered
   forms and modals as well.
   ================================================================ */
(function installLifeStockNonNegativeNumberGuard() {
  "use strict";

  if (window.__lifeStockNonNegativeNumberGuardInstalled) {
    return;
  }
  window.__lifeStockNonNegativeNumberGuardInstalled = true;

  function isProtectedNumericInput(element) {
    if (!element || element.tagName !== "INPUT") {
      return false;
    }

    var type = String(element.getAttribute("type") || "text").toLowerCase();
    var inputMode = String(element.getAttribute("inputmode") || "").toLowerCase();

    return (
      type === "number" ||
      inputMode === "numeric" ||
      inputMode === "decimal"
    );
  }

  function minimumAllowedValue(input) {
    var min = Number(input.getAttribute("min"));
    return Number.isFinite(min) && min >= 0 ? min : 0;
  }

  function normalizeNumericInput(input) {
    if (!isProtectedNumericInput(input)) {
      return;
    }

    if (String(input.getAttribute("type") || "").toLowerCase() === "number") {
      var declaredMin = Number(input.getAttribute("min"));
      if (!Number.isFinite(declaredMin) || declaredMin < 0) {
        input.setAttribute("min", "0");
      }
    }

    var rawValue = String(input.value == null ? "" : input.value);
    var numericValue = Number(rawValue);

    if (rawValue.indexOf("-") !== -1 || (rawValue !== "" && Number.isFinite(numericValue) && numericValue < 0)) {
      input.value = String(minimumAllowedValue(input));
      input.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  function normalizeAllNumericInputs(root) {
    if (!root) {
      return;
    }

    if (isProtectedNumericInput(root)) {
      normalizeNumericInput(root);
    }

    if (root.querySelectorAll) {
      Array.prototype.forEach.call(
        root.querySelectorAll('input[type="number"], input[inputmode="numeric"], input[inputmode="decimal"]'),
        normalizeNumericInput
      );
    }
  }

  document.addEventListener("keydown", function (event) {
    var input = event.target;
    if (!isProtectedNumericInput(input)) {
      return;
    }

    if (event.key === "-" || event.code === "NumpadSubtract" || event.key === "Subtract") {
      event.preventDefault();
      event.stopPropagation();
    }
  }, true);

  document.addEventListener("beforeinput", function (event) {
    var input = event.target;
    if (!isProtectedNumericInput(input)) {
      return;
    }

    if (String(event.data || "").indexOf("-") !== -1) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, true);

  document.addEventListener("paste", function (event) {
    var input = event.target;
    if (!isProtectedNumericInput(input)) {
      return;
    }

    var pastedText = event.clipboardData
      ? String(event.clipboardData.getData("text") || "")
      : "";

    if (pastedText.indexOf("-") !== -1) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, true);

  document.addEventListener("drop", function (event) {
    var input = event.target;
    if (!isProtectedNumericInput(input)) {
      return;
    }

    var droppedText = event.dataTransfer
      ? String(event.dataTransfer.getData("text") || "")
      : "";

    if (droppedText.indexOf("-") !== -1) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, true);

  document.addEventListener("input", function (event) {
    normalizeNumericInput(event.target);
  }, true);

  document.addEventListener("change", function (event) {
    normalizeNumericInput(event.target);
  }, true);

  var observer = new MutationObserver(function (mutations) {
    mutations.forEach(function (mutation) {
      Array.prototype.forEach.call(mutation.addedNodes || [], function (node) {
        if (node && node.nodeType === 1) {
          normalizeAllNumericInputs(node);
        }
      });
    });
  });

  function startGuard() {
    normalizeAllNumericInputs(document);
    observer.observe(document.documentElement || document.body, {
      childList: true,
      subtree: true
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startGuard, { once: true });
  } else {
    startGuard();
  }

