/* =========================================================================
   LIFE SSR TARGET WAREHOUSE — DOM LEVEL SAFETY GUARD
   -------------------------------------------------------------------------
   Why this exists:
   - ERPNext already resolves/submits the correct branch Main Store.
   - Browser debugging proves the Warehouse master query returns it.
   - The remaining issue is only the visible #ssr-target-warehouse control.
   - This guard works directly on the rendered DOM and does not depend on
     the Material Request IIFE's internal state/root/cache.

   Scope:
   - ONLY #ssr-target-warehouse (Consumable / Special Material Request)
   - Does NOT affect Monthly Indent, Advance Request, or other warehouse UI.
   ========================================================================= */
(function installLifeSSRTargetWarehouseDomGuard(){

    if (window.__lifeSSRTargetWarehouseDomGuardInstalled) {
        return;
    }
    window.__lifeSSRTargetWarehouseDomGuardInstalled = true;

    var COMPANY = "Life Slimming And Cosmetic Pvt Ltd";
    var lastBranch = "";
    var cachedRows = [];
    var loading = null;

    function clean(value) {
        return String(value == null ? "" : value).trim();
    }

    function branchKey(value) {
        return clean(value)
            .toLowerCase()
            .replace(/\s*-\s*lsacpl\s*$/i, "")
            .replace(/\bmain\s*stores?\b/gi, "")
            .replace(/\bsub\s*stores?\b/gi, "")
            .replace(/\bstores?\b/gi, "")
            .replace(/\bwarehouses?\b/gi, "")
            .replace(/\bbranch\b/gi, "")
            .replace(/[^a-z0-9]+/g, "");
    }

    function displayWarehouse(value) {
        var name = clean(value);

        if (/^Stores\s*-\s*LSACPL$/i.test(name)) {
            return "HO Main Stores";
        }

        return name
            .replace(/\s*-\s*LSACPL\s*$/i, "")
            .trim();
    }

    function currentBranch() {
        /*
         * The main Stock Dashboard already exposes the active branch.
         * Browser debugging confirmed this is populated correctly.
         */
        return clean(
            window.__lifeIntegratedStockBranchName ||
            ""
        );
    }

    function queryWarehouses() {
        var branch = currentBranch();
        var key = branchKey(branch);

        if (!branch || !key) {
            return Promise.resolve([]);
        }

        if (lastBranch === key && cachedRows.length) {
            return Promise.resolve(cachedRows.slice());
        }

        if (loading && lastBranch === key) {
            return loading;
        }

        lastBranch = key;

        loading = new Promise(function(resolve, reject) {
            if (!window.frappe || typeof frappe.call !== "function") {
                reject(new Error("frappe.call is unavailable."));
                return;
            }

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Warehouse",
                    fields: [
                        "name",
                        "warehouse_name",
                        "company",
                        "is_group",
                        "disabled"
                    ],
                    filters: [
                        ["company", "=", COMPANY],
                        ["is_group", "=", 0],
                        ["disabled", "=", 0]
                    ],
                    order_by: "name asc",
                    limit_page_length: 500
                },
                callback: function(r) {
                    var rows =
                        r && Array.isArray(r.message)
                            ? r.message
                            : [];

                    var matched = rows.filter(function(row) {
                        var name = clean(
                            row.name ||
                            row.warehouse_name
                        );

                        if (!name) {
                            return false;
                        }

                        if (!/main\s*store/i.test(name)) {
                            return false;
                        }

                        if (/^Stores\s*-\s*LSACPL$/i.test(name)) {
                            return false;
                        }

                        return branchKey(name) === key;
                    });

                    cachedRows = matched.slice();

                    resolve(matched);
                },
                error: function(err) {
                    reject(err);
                }
            });
        }).finally(function() {
            loading = null;
        });

        return loading;
    }

    function applyRows(select, rows) {
        if (!select || !document.documentElement.contains(select)) {
            return;
        }

        rows = Array.isArray(rows) ? rows : [];

        if (!rows.length) {
            return;
        }

        var current = clean(select.value);
        var html =
            '<option value="">— Select Target Warehouse —</option>';

        rows.forEach(function(row) {
            var name = clean(
                row.name ||
                row.warehouse_name
            );

            if (!name) {
                return;
            }

            html +=
                '<option value="' +
                name.replace(/&/g, "&amp;")
                    .replace(/"/g, "&quot;")
                    .replace(/</g, "&lt;")
                    .replace(/>/g, "&gt;") +
                '">' +
                displayWarehouse(name)
                    .replace(/&/g, "&amp;")
                    .replace(/</g, "&lt;")
                    .replace(/>/g, "&gt;") +
                '</option>';
        });

        select.innerHTML = html;

        var preferred =
            rows.length === 1
                ? clean(rows[0].name || rows[0].warehouse_name)
                : current;

        if (
            preferred &&
            Array.prototype.some.call(
                select.options,
                function(option) {
                    return option.value === preferred;
                }
            )
        ) {
            select.value = preferred;
        } else if (rows.length === 1) {
            select.value =
                clean(
                    rows[0].name ||
                    rows[0].warehouse_name
                );
        }

        /*
         * Fire change so the existing Material Request code synchronizes
         * its own state from the actual visible select.
         */
        try {
            select.dispatchEvent(
                new Event("change", {
                    bubbles: true
                })
            );
        } catch (e) {}


    }

    function ensureVisibleTarget() {
        var select =
            document.getElementById(
                "ssr-target-warehouse"
            );

        if (!select) {
            return;
        }

        queryWarehouses()
            .then(function(rows) {
                /*
                 * Re-fetch actual element in case the form was re-rendered
                 * while the async request was running.
                 */
                var liveSelect =
                    document.getElementById(
                        "ssr-target-warehouse"
                    );

                applyRows(
                    liveSelect,
                    rows
                );
            })
            .catch(function(error) {
                void 0;
            });
    }

    /*
     * Populate immediately if the form is already present.
     */
    ensureVisibleTarget();

    /*
     * Populate every time the SSR form is inserted/re-rendered.
     */
    var observer = new MutationObserver(function(mutations) {
        var needsRefresh = false;

        mutations.some(function(mutation) {
            if (
                mutation.type === "childList" &&
                mutation.addedNodes &&
                mutation.addedNodes.length
            ) {
                needsRefresh = true;
                return true;
            }

            return false;
        });

        if (needsRefresh) {
            window.clearTimeout(
                window.__lifeSSRTargetWarehouseDomGuardTimer
            );

            window.__lifeSSRTargetWarehouseDomGuardTimer =
                window.setTimeout(
                    ensureVisibleTarget,
                    80
                );
        }
    });

    observer.observe(
        document.documentElement,
        {
            childList: true,
            subtree: true
        }
    );

    /*
     * Also refresh immediately before user interacts with the field.
     */
    document.addEventListener(
        "mousedown",
        function(event) {
            var target = event.target;

            if (
                target &&
                target.id ===
                    "ssr-target-warehouse"
            ) {
                ensureVisibleTarget();
            }
        },
        true
    );

    document.addEventListener(
        "focusin",
        function(event) {
            var target = event.target;

            if (
                target &&
                target.id ===
                    "ssr-target-warehouse"
            ) {
                ensureVisibleTarget();
            }
        },
        true
    );

    /*
     * Expose one manual debug command too:
     * window.lifeRefreshSSRTargetWarehouse()
     */
    window.lifeRefreshSSRTargetWarehouse =
        ensureVisibleTarget;

})();

