   ============================================================ */

(function installBillingStockReceiptDeepLink() {

    "use strict";

    var handled = false;

    function getDeepLinkParams() {

        try {

            var params =
                new URLSearchParams(
                    window.location.search || ""
                );

            return {
                receipt:
                    params.get("receipt") === "1",

                stockEntry:
                    String(
                        params.get("stock_entry") || ""
                    ).trim()
            };

        } catch (error) {

            return {
                receipt: false,
                stockEntry: ""
            };
        }
    }


    function openReceiptSection() {

        var content =
            document.getElementById(
                "branch-home-receipts-content"
            );

        var toggle =
            document.getElementById(
                "branch-home-receipts-toggle"
            );

        var chevron =
            document.getElementById(
                "branch-home-receipts-chevron"
            );

        if (content) {
            content.hidden = false;
        }

        if (toggle) {
            toggle.setAttribute(
                "aria-expanded",
                "true"
            );
        }

        if (chevron) {
            chevron.textContent = "▾";
        }
    }


    async function openBillingReceiptDeepLink() {

        if (handled) {
            return;
        }

        var params =
            getDeepLinkParams();

        if (!params.receipt) {
            return;
        }

        /*
         * Wait until the Stock Dashboard application and
         * receipt functions are fully initialized.
         */
        if (
            typeof showPage !== "function" ||
            typeof renderBranchReceiving !== "function"
        ) {
            return;
        }

        handled = true;

        try {

            /*
             * Always take the branch user to the
             * Material Request Home page first.
             */
            showPage("home");

            /*
             * Expand:
             * Stock Received From HO Main Stores
             */
            openReceiptSection();

            /*
             * Refresh the pending Stock Entries.
             */
            await renderBranchReceiving();

            /*
             * If Billing passed an exact Stock Entry,
             * open its receipt popup immediately.
             */
            if (
                params.stockEntry &&
                typeof openBranchReceiptPopup === "function"
            ) {

                /*
                 * Small delay allows table/rendering to finish.
                 */
                setTimeout(function () {

                    try {

                        openBranchReceiptPopup(
                            params.stockEntry
                        );

                    } catch (error) {

                        void 0;
                    }

                }, 300);
            }

            /*
             * Scroll receipt area into view as a fallback.
             */
            var section =
                document.getElementById(
                    "branch-receiving-section"
                );

            if (section) {

                setTimeout(function () {

                    section.scrollIntoView({
                        behavior: "smooth",
                        block: "start"
                    });

                }, 100);
            }

        } catch (error) {

            handled = false;

            void 0;
        }
    }


    /*
     * The Stock Dashboard has asynchronous startup, so retry
     * briefly until its functions and user context are ready.
     */
    var tries = 0;

    var timer =
        setInterval(function () {

            tries++;

            openBillingReceiptDeepLink();

            if (
                handled ||
                tries >= 60
            ) {

                clearInterval(timer);
            }

        }, 250);


    /*
     * Also try once immediately.
     */
    openBillingReceiptDeepLink();

})();


