function lifeEnsureHeaderClientSearchButton(){

    var toolbar =
        document.querySelector(
            "#inv-tools .inv-toolbar"
        );


    if(!toolbar){
        return;
    }


    var button =
        document.getElementById(
            "bhra-client-nav"
        );


    if(!button){

        button =
            document.createElement(
                "button"
            );


        button.id =
            "bhra-client-nav";


        button.type =
            "button";
    }


    button.classList.remove(
        "mnav"
    );


    button.classList.add(
        "life-header-client-search"
    );


    button.textContent =
        "⌕ Search Client";


    button.title =
        "Search client stock and session history";


    button.setAttribute(
        "aria-label",
        "Search Client"
    );


    button.hidden =
        false;


    button.disabled =
        false;


    button.style.removeProperty(
        "display"
    );


    button.style.removeProperty(
        "pointer-events"
    );


    /*
     * ============================================================
     * CORRECT SEARCH CLIENT ACTION
     * ============================================================
     *
     * Client Stock & Session modal belongs to the Material Request
     * module.
     *
     * Therefore Requests & Approvals must be made visible FIRST,
     * otherwise the modal opens inside a hidden parent.
     */

    button.onclick =
        function(event){

            if(event){

                event.preventDefault();

                event.stopPropagation();
            }


            /*
             * Open HO Requests & Approvals.
             */
            if(
                typeof showHoMode ===
                "function"
            ){

                showHoMode(
                    1
                );
            }
            else{

                var requestsTab =
                    document.querySelector(
                        '#ls-ho-nav [data-hmode="1"]'
                    );


                if(requestsTab){

                    requestsTab.click();
                }
            }


            /*
             * Wait for Material Request module to be mounted and visible.
             */
            var attempt =
                0;


            var timer =
                window.setInterval(
                    function(){

                        attempt +=
                            1;


                        var moduleRoot =
                            document.getElementById(
                                "life-material-request-root"
                            );


                        var modal =
                            moduleRoot
                                ? moduleRoot.querySelector(
                                    "#modal"
                                )
                                : null;


                        var moduleVisible =
                            !!(
                                moduleRoot &&
                                moduleRoot.style.display !==
                                    "none" &&
                                moduleRoot.style.visibility !==
                                    "hidden"
                            );


                        if(
                            moduleVisible &&
                            modal &&
                            typeof window.lifeOpenSessionTrackingTable ===
                                "function"
                        ){

                            window.clearInterval(
                                timer
                            );


                            try{

                                var result =
                                    window.lifeOpenSessionTrackingTable();


                                if(
                                    result &&
                                    typeof result.catch ===
                                        "function"
                                ){

                                    result.catch(
                                        function(error){

                                            void 0;


                                            if(
                                                window.frappe &&
                                                frappe.msgprint
                                            ){

                                                frappe.msgprint({
                                                    title:
                                                        "Search Client",

                                                    indicator:
                                                        "red",

                                                    message:
                                                        "Unable to open Client Stock & Session Tracking.<br><br>" +
                                                        (
                                                            error &&
                                                            error.message
                                                                ? error.message
                                                                : String(
                                                                    error
                                                                )
                                                        )
                                                });
                                            }
                                        }
                                    );
                                }

                            }
                            catch(error){

                                void 0;


                                if(
                                    window.frappe &&
                                    frappe.msgprint
                                ){

                                    frappe.msgprint({
                                        title:
                                            "Search Client",

                                        indicator:
                                            "red",

                                        message:
                                            "Unable to open Client Stock & Session Tracking.<br><br>" +
                                            (
                                                error &&
                                                error.message
                                                    ? error.message
                                                    : String(
                                                        error
                                                    )
                                            )
                                    });
                                }
                            }


                            return;
                        }


                        /*
                         * Give mount process up to about 4 seconds.
                         */
                        if(
                            attempt >=
                            40
                        ){

                            window.clearInterval(
                                timer
                            );


                            void 0;


                            if(
                                window.frappe &&
                                frappe.msgprint
                            ){

                                frappe.msgprint({
                                    title:
                                        "Search Client",

                                    indicator:
                                        "orange",

                                    message:
                                        "Client Stock & Session Tracking could not open because the Requests & Approvals module is still loading. Please refresh and try again."
                                });
                            }
                        }

                    },
                    100
                );
        };


    /*
     * ============================================================
     * KEEP BUTTON BEFORE HOW TO USE
     * ============================================================
     */

    var howToUseButton =
        toolbar.querySelector(
            '[data-inv-tool="help"]'
        );


    if(howToUseButton){

        if(
            button.parentNode !==
                toolbar ||
            button.nextElementSibling !==
                howToUseButton
        ){

            toolbar.insertBefore(
                button,
                howToUseButton
            );
        }

    }
    else if(
        button.parentNode !==
        toolbar
    ){

        toolbar.insertBefore(
            button,
            toolbar.firstChild
        );
    }
}

